window.__D("text/zohar-hebrew-translation/c017",{"p":[[9522011672,"<p>רוֹעָה הַנֶּאֱמָן, עֶבֶד נֶאֱמָן, אֵלֶיךְ עֶבֶד עִבְרִי - (דבריםטו) הַעֲנֵיק תַּעֲנִיק לוֹ. הַעֲנֵיק - לוֹ, תַּעֲנִיק - לְבָנָיו, בַּדְּבָרִים הַגְּנוּזִים הַלָּלוּ. וּמִגָּרְנְךְ - גָּרְנָהּ שֶׁל הַתּוֹרָה שֶׁלְּךְ. וּמִיִּקְבְךְ - בְּגֹרֶן וְיֶקֶב הַכָּתוּב מְדַבֵּר, כְּמוֹ שֶׁבֵּאֲרוּ בַּעֲלֵי הַמִּשְׁנָה, בִּפְסֹלֶת גֹּרֶן וְיֶקֶב הַכָּתוּב מְדַבֵּר.</p>\n<p>יֶקֶ\"ב - יִ\"חוּד, קְ\"דֻשָּׁה, בְּ\"רָכָה שֶׁל הַקָּדוֹשׁ בָּרוּךְ הוּא. וְזוֹ הַשְּׁכִינָה, שֶׁהִיא בְּרָכָה שֶׁל הַקָּדוֹשׁ בָּרוּךְ הוּא מִיָּמִין, וְהִיא קְדֻשָּׁה מִשְּׂמֹאלוֹ, וְהִיא יִחוּדוֹ בָּאֶמְצַע, וְכָךְ עוֹלוֹת אוֹתִיּוֹתָיו שֶׁל הַקָּדוֹשׁ בָּרוּךְ הוּא יַבֹּ\"ק. כְּמוֹ זֶה הקב\"ה בְּחֶשְׁבּוֹן יַבּ\"ק.</p>\n<p>וּמִי שֶׁהוּא בָּקִ\"י בַּהֲלָכָה שֶׁלּוֹ, שֶׁהִיא הַשְּׁכִינָה - הַקָּדוֹשׁ בָּרוּךְ הוּא עִמּוֹ, שֶׁבִּשְׁבִילָהּ לֹא יָזוּז מִמֶּנּוּ לְעוֹלָם. שֶׁיֵּשׁ הֲלָכָה שֶׁהִיא נַעֲרָה שֶׁלָּהּ מִצַּד שֶׁל נַעַר, וּבִגְלָלָהּ נֶאֱמַר הֲלָכָה כִּפְלוֹנִי. אֲבָל הַהֲלָכָה שֶׁלְּךְ, רוֹעֶה הַנֶּאֱמָן, הִיא שֶׁנֶּאֱמַר בָּהּ הֲלָכָה לְמֹשֶׁה מִסִּינַי. מִפִּי הַגְּבוּרָה נָתַן לְךְ הַקָּדוֹשׁ בָּרוּךְ הוּא אֶת בִּתּוֹ.</p>\n<p>וְלָכֵן עַל הֲלָכוֹת אֲחֵרוֹת נֶאֱמַר, (משלי לא) רַבּוֹת בָּנוֹת עָשׂוּ חָיִל. עַל הֲלָכָה שֶׁלְּךְ נֶאֱמַר, וְאַתְּ עָלִית עַל כֻּלָּנָה. שֶׁהִתְגַּבַּרְתָּ עַל כֻּלָּם בִּגְבוּרָה. (שופטים ו) ה' עִמְּךְ גִּבּוֹר הֶחָיִל. נִתְקַן (נתחזק) בְּךְ וְהִשְׁלִים בִּנְיַן הַמֶּלֶךְ, וְהוּא בּוֹנֶה בִּנְיָנוֹ עַל פִּיךְ וְעַל יָדְךְ. אַשְׁרֶיךְ!</p>\n<p>פָּתַח הָרוֹעֶה הַנֶּאֱמָן וְאָמַר, (בראשית מח) הַמַּלְאָךְ הַגֹּאֵל אֹתִי מִכָּל רָע, שֶׁהִיא הַשְּׁכִינָה שֶׁנֶּאֱמַר בָּהּ (שמות יד) וַיִּסַּע מַלְאַךְ הָאֱלֹהִים. יְבָרֵךְ אֶתְכֶם בָּעוֹלָם הַבָּא, וְיִדְגּוּ לָרֹב בְּקֶרֶב הָאָרֶץ בָּעוֹלָם הַזֶּה. שֶׁתִּהְיֶה שְׁלִיטַתְכֶם בִּשְׁנֵי עוֹלָמוֹת שֶׁאַתֶּם חַיִּים. שֶׁמִּי שֶׁהוּא מֵהָעוֹלָם הַזֶּה נִקְרָא חַי, כַּכָּתוּב (משלי ג) עֵץ חַיִּים הִיא לַמַּחֲזִיקִים בָּהּ. חַיִּים שָׁם - חַיִּים כָּאן.</p>\n<p>מַה שֶּׁאֵינוֹ כָּךְ, מִי שֶׁהוּא מְלֻבָּשׁ בַּקְּלִפּוֹת הַלָּלוּ, שֶׁל עוֹר וּבָשָׂר וַעֲצָמוֹת וְגִידִים שֶׁל הַגּוּף הַשָּׁפָל, שֶׁהָרוּחַ מֵתָה שָׁם. מָה הַמֵּת לֹא רוֹאֶה וְלֹא שׁוֹמֵעַ וְלֹא מְדַבֵּר וְאֵין לוֹ תְּנוּעָה בְּכָל אֵיבָרָיו, כָּךְ הָרוּחַ לֹא רוֹאָה לְמַעְלָה מִמֶּנָּה, שֶׁנֶּאֱמַר עֲלֵיהֶם בַּתּוֹרָה, דַּע מַה לְמַעְלָה מִמְּךְ - עַיִן רוֹאָה וְאֹזֶן שׁוֹמַעַת, וְכָל מַעֲשֶׂיךְ בְּסֵפֶר נִכְתָּבִים.</p>\n<p>שֶׁכַּמָּה מַלְאָכִים הוֹלְכִים עִמּוֹ, שֶׁנֶּאֱמַר בָּהֶם (תהלים צא) כִּי מַלְאָכָיו יְצַוֶּה לָּךְ. וְאֵין לוֹ רְשׁוּת בַּגּוּף הַזֶּה לְהִסְתַּכֵּל בָּהֶם וְלִשְׁמֹעַ בְּקוֹלָם, שֶׁהֵם חַיּוֹת שֶׁל אֵשׁ, מְדַבְּרוֹת וּמְקַדְּשׁוֹת וּמְבָרְכוֹת וּמְיַחֲדוֹת אֶת הַקָּדוֹשׁ בָּרוּךְ הוּא עִם יִשְׂרָאֵל כְּאֶחָד, כָּל שֶׁכֵּן אֶת הַשְּׁכִינָה שֶׁהִיא עֲלֵיהֶם, כָּל שֶׁכֵּן הַקָּדוֹשׁ בָּרוּךְ הוּא שֶׁהוּא מֵעַל לִשְׁכִינָתוֹ, שֶׁבָּהּ הוּא מְקַבֵּל אֶת תְּפִלּוֹת יִשְׂרָאֵל.</p>\n<p>וּמִשּׁוּם הַחֲטָאִים הָיוּ מִתְלַבְּשִׁים בַּקְּלִפּוֹת הַלָּלוּ, כְּמוֹ שֶׁאָדָם שֶׁחֲטָאֵי אֲבוֹתֵיהֶם בִּידֵיהֶם. וְזֶהוּ שֶׁבֵּאֲרוּ בַּעֲלֵי הַמִּשְׁנָה, כְּשֶׁאוֹחֲזִים מַעֲשֵׂה אֲבוֹתֵיהֶם בִּידֵיהֶם. וּמִשּׁוּם הַקְּלִפּוֹת הַלָּלוּ שֶׁל הַחֲטָאִים, אָמַר הַכָּתוּב (ישעיה נט) כִּי אִם עֲונֹתֵיכֶם הָיוּ מַבְדִּלִים בֵּינֵכֶם לְבֵין אֱלֹהֵיכֶם. וּבִשְׁבִיל הַקְּלִפּוֹת הַלָּלוּ הַקָּדוֹשׁ בָּרוּךְ הוּא מִתְכַּסֶּה בְּכַמָּה כְנָפַיִם, שֶׁבָּהֶם נֶאֱמַר (שםו) בִּשְׁתַּיִם יְכַסֶּה פָנָיו וּבִשְׁתַּיִם יְכַסֶּה רַגְלָיו וְגוֹ'.</p>\n<p>לֶעָתִיד לָבא, (שם ל) וְלֹא יִכָּנֵף עוֹד מוֹרֶיךְ וְהָיוּ עֵינֶיךְ רֹאוֹת אֶת מוֹרֶיךְ. שֶׁאַתֶּם בָּעוֹלָם הַזֶּה, שֶׁאֵין לָכֶם קְלִפּוֹת וְעוֹרוֹת, יֵשׁ לָכֶם רְשׁוּת לְהִסְתַּכֵּל בִּבְנֵי הָעוֹלָם, וְלִבְנֵי הָעוֹלָם (אין) יֵשׁ רְשׁוּת לְהִסְתַּכֵּל בָּכֶם, וְלָכֵן עֲלֵיכֶם נֶאֱמַר שֶׁאַתֶּם חַיִּים, וְעוֹלַמְכֶם הוּא עוֹלַם הַחַיִּים. אֲבָל הָעוֹלָם הַשָּׁפָל הוּא עוֹלַם הַמֵּתִים, שֶׁכָּל אֱלָהוּת שֶׁל אֻמּוֹת הָעוֹלָם מִבִּלְעֲדֵי ה', כֻּלָּם מֵתִים.</p>"],[9522011673,"<p>אָמַר לוֹ רַבִּי שִׁמְעוֹן, (המנורה הקדושה) (רועה הגאמן), עִם כָּל זֶה שֶׁאַתָּה לֹא יָכוֹל לְהִסְתַּכֵּל בִּבְנֵי הָעוֹלָם הַבָּא בָּעֵינַיִם וְלֹא בְּמַלְאָכִים, כָּל שֶׁכֵּן בַּקָּדוֹשׁ- בָּרוּךְ-הוּא וּשְׁכִינָתוֹ, אֲבָל בְּעֵין הַשֵּׂכֶל שֶׁל לִבְּךְ אַתָּה רוֹאֶה אֶת כָּל בְּנֵי הָעוֹלָם הַבָּא, וּבַמַּלְאָכִים וּבַקָּדוֹשׁ בָּרוּךְ הוּא וּשְׁכִינָתוֹ שֶׁמַּקִּיפִים אוֹתְךְ. וּמִשּׁוּם זֶה אָמַר שְׁלֹמֹה, שֶׁכָּתוּב בּוֹ (מלכים א ה) וַיֶּחְכַּם מִכָּל הָאָדָם, (קהלת א) וְלִבִּי רָאָה הַרְבֵּה חָכְמָה וָדָעַת.</p>\n<p>אֲבָל בִּנְבוּאָה אֵין רְשׁוּת לְהִסְתַּכֵּל בּוֹ (כל שכן) נָבִיא בְּעֵין הַשֵּׂכֶל, אֶלָּא בָּעֵינַיִם, שֶׁהִיא מַרְאֶה וְחֶזְיוֹן הָעֵינַיִם. זֶהוּ שֶׁכָּתוּב בַּמַּרְאָה אֵלָיו אֶתְוַדָּע. וְעוֹד בְּחֶזְיוֹן לַיְלָה - מַרְאֶה בַּיּוֹם, חִזָּיוֹן בַּלַּיְלָה. וְהַכֹּל בָּעֵינַיִם, וְלֹא בְּעֵין הַשֵּׂכֶל שֶׁל הַלֵּב. וְהָעֵינַיִם הֵן שְׁנֵי סַרְסוּרֵי הַלֵּב, וּמִשַּׁמָּשִׁים שֶׁלּוֹ, וְהוּא מֶלֶךְ בֵּינֵיהֶם (אליהם), וְלָכֵן חָכָם עָדִיף מִנָּבִיא. וְכָךְ הֵם שְׁתֵּי הָאָזְנַיִם, שְׁנֵי שַׁמָּשֵׁי הַלֵּב.</p>\n<p>וּמִשּׁוּם זֶה פֵּרְשׁוּהָ רַבּוֹתֵינוּ, הַלֵּב רוֹאֶה וְהַלֵּב שׁוֹמֵעַ. וְלֹא עוֹד, אֶלָּא שֶׁנֶּאֱמַר בַּלֵּב, הַלֵּב מֵבִין, הַלֵּב יוֹדֵעַ. (שמות לא) וּבְלֵב כָּל חֲכַם לֵב נָתַתִּי חָכְמָה. הֲרֵי חָכְמָה וּתְבוּנָה וָדַעַת בַּלֵּב, שֶׁבָּהֶם נַעֲשׂוּ שָׁמַיִם וָאָרֶץ וּתְהוֹמוֹת, וּבָהֶם נַעֲשָׂה הַמִּשְׁכָּן. זֶהוּ שֶׁכָּתוּב (שם) וָאֲמַלֵּא אֹתוֹ רוּחַ אֱלֹהִים בְּחָכְמָה וּבִתְבוּנָה וּבְדַעַת. מַה שֶּׁאֵין כָּל זֶה בָּעֵינַיִם.</p>\n<p>וְרוֹעָה הַנֶּאֱמָן, מִי שֶׁכָּל זֶה בְּלִבּוֹ רוֹאֶה יוֹתֵר מִנָּבִיא, כָּל שֶׁכֵּן מַחֲשַׁבְתְּךְ שֶׁאֵין לָהּ סוֹף, וּבָהּ תִּסְתַּכֵּל בְּאוֹתוֹ שֶׁאֵין לוֹ סוֹף, מַה שֶּׁלֹּא הָיְתָה לְךְ רְשׁוּת בָּרִאשׁוֹנָה לְהִסְתַּכֵּל בָּעֵינַיִם. זֶהוּ שֶׁכָּתוּב (שם לג) וְרָאִיתָ אֶת אֲחֹרָי וּפָנַי לֹא יֵרָאוּ.</p>\n<p>טִפְּשֵׁי הַלֵּב הַלָּלוּ הֵם מֵתִים, וְעִוְרִים בַּקְּלִפּוֹת הַלָּלוּ. אֲבָל אֵלֶיךְ אֵינָם חֲשׁוּבִים לִכְלוּם, וְאֵינָם מַפְסִיקִים בֵּינְךְ לְבֵין הַקָּדוֹשׁ בָּרוּךְ הוּא וּשְׁכִינָתוֹ, וְכָל בְּנֵי הָעוֹלָם הַבָּא וְהַמַּלְאָכִים, שֶׁכָּךְ יִכָּנֵס אֵלֶיךְ בְּאוֹתָם חַלּוֹנוֹת שֶׁל הָעֵינַיִם וְהָאָזְנַיִם וְנִקְבֵי הַחֹטֶם וְהַפֶּה, כְּמוֹ מֶלֶךְ שֶׁנִּכְנָס בְּכִסּוּי לְחַדְרֵי חֲדָרִים לְדַבֵּר עִם בְּנוֹ. וּמִשּׁוּם זֶה מִתְפַּלְלִים יִשְׂרָאֵל בּוֹ בִּתְפִלָּתָם: אַתָּה חוֹפֵשׂ כָּל חַדְרֵי בָטֶן רוֹאֶה כְלָיוֹת וָלֵב וְאֵין כָּל דָּבָר נֶעְלָם מִמֶּךָּ.</p>\n<p>וְהַיְנוּ מַה שֶּׁאָמַר שְׁלֹמֹה, (שיר ב) מַשְׁגִּיחַ מִן הַחַלֹּנוֹת וְגוֹ'. וְאֵלֶּה הֵם הַחַלּוֹנוֹת שֶׁל עֵינַיִם וְאָזְנַיִם וְנִקְבֵי הַחֹטֶם וְהַפֶּה. בְּשִׁבְעַת הַנְּקָבִים הַלָּלוּ עוֹלָה הַנְּשָׁמָה בְּשִׁבְעָה מִינֵי בְשָׂמִים, וְכָךְ הַתְּפִלָּה עוֹלָה בְּשִׁבְעָה הַבְּשָׂמִים הַלָּלוּ, שֶׁהֵם: (שם ד) נֵרְדְּ וְכַרְכֹּם קָנֶה וְקִנָּמוֹן עִם כָּל עֲצֵי לְבוֹנָה מֹר וַאֲהָלוֹת עִם כָּל רָאשֵׁי בְשָׂמִים. בְּאוֹתוֹ זְמַן שֶׁכָּךְ הַתְּפִלָּה עוֹלָה, מְקֻטֶּרֶת מֹר וְכוּ'. הַקָּדוֹשׁ בָּרוּךְ הוּא שׁוֹאֵל עָלֶיהָ, (שםג) מִי זאת עֹלָה מִן הַמִּדְבָּר וְגוֹ', מְקֻטֶּרֶת מֹר וּלְבֹנָה וְגוֹ'. מִי זֹאת וַדַּאי, מִצַּד שֶׁל מִ\"י הִיא וַדַּאי בִּינָה, כְּלוּלָה מִשִּׁבְעָה מִינֵי בְשָׂמִים.</p>\n<p>וְזוֹ קְרִיאַת שְׁמַע, כְּלוּלָה מֵחֲמִשִּׁים שְׁעָרִים, שֶׁהֵם כ\"ה כ\"ה, כְּלוּלָה מִשֶּׁבַע בְּרָכוֹת, בַּשַּׁחַר - שְׁתַּיִם לְפָנֶיהָ וְאַחַת לְאַחֲרֶיהָ, וּבָעֶרֶב - שְׁתַּיִם לְפָנֶיהָ וּשְׁתַּיִם לְאַחֲרֶיהָ, וְהֵם: הַגְּדֻלָּה וְהַגְּבוּרָה וְהַתִּפְאֶרֶת וְהַנֵּצַח וְהַהוֹד, עַד לְךְ ה' הַמַּמְלָכָה, שֶׁהִיא מַלְכוּת, שֶׁהִיא כְּלוּלָה מִשְּׁלֹשָׁה בְשָׂמִים: מְקֻטֶּרֶת מֹר - זֶה כֶּתֶר, וּלְבוֹנָה - זוֹ חָכְמָה, מִכֹּל אַבְקַת רוֹכֵל - זוֹ בִּינָה. קוּם וְהַשְׁלֵם אֶת מִצְווֹת רִבּוֹנְךְ.</p>"],[9522011674,"<p>לֹא תִהְיֶה אַחֲרֵי רַבִּים לְרָעֹת וְגוֹ', אַחֲרֵי רַבִּים לְהַטֹּת. אַחֲרֵי רַבִּים לְהַטֹּת - אֵין רַבִּים פָּחוֹת מִשְּׁלֹשָׁה, וְאִם אֵין בֵּית דִּין בִּשְׁלֹשָׁה, אֵין לְהַטּוֹת אַחַר דִּינוֹ. בֵּית דִּין - שְׁכִינָה. בִּשְׁלֹשָׁה - שְׁלֹשׁ חַיּוֹת הַמֶּרְכָּבָה שֶׁלָּהּ, וְהִיא דִּין תּוֹרָה, דִּין אֱמֶת, הָעַמּוּד הָאֶמְצָעִי. וְכָל דַּיָּן שֶׁלֹּא דָן דִּין אֱמֶת לַאֲמִתּוֹ, זֶהוּ כְּאִלּוּ הִשְׁלִיט אֶת סמא\"ל בָּעוֹלָם. (דניאל ח) וְתַשְׁלֵךְ אֱמֶת אַרְצָה, וְהִפִּיל עִמָּהּ אֶת הַשְּׁכִינָה, וְיָקִים אֶת גֵּיהִנֹּם, בַּת הַזּוּג שֶׁל סמא\"ל עִם סמא\"ל. בַּמָּקוֹם שֶׁל דִּין הָאֱמֶת יָקִים שְׂפַת שֶׁקֶר. דִּין אֱמֶת - עַמּוּד הָאֶמְצָעִי. שְׂפַת שֶׁקֶר - גֵּיהִנֹּם וְסמא\"ל.</p>\n<p>וּמִשּׁוּם כָּךְ, כְּשֶׁדַּיָּן דָּן דִּין, גֵּיהִנֹּם פְּתוּחָה לְפָנָיו מִשְּׂמֹאלוֹ, בַּת זוּגוֹ שֶׁל סמא\"ל. וְחֶרֶב עַל צַוָּארוֹ, מַלְאַךְ הַמָּוֶת. סמא\"ל מֵאֲחוֹרָיו מֵעַל צַוָּארוֹ, וְגַן עֵדֶן פָּתוּחַ לִימִינוֹ, וְעֵץ הַחַיִּים פָּתוּחַ לְפָנָיו עַל רֹאשׁוֹ.</p>\n<p>אִם דָּן דִּין שֶׁקֶר, שׁוֹלֵט עָלָיו מַלְאַךְ הַמָּוֶת וְשׁוֹחֵט אוֹתוֹ, וְאַחַר כָּךְ שׂוֹרֵף אוֹתוֹ בַּגֵּיהִנֹּם. וְאִם דָּן דִּין אֱמֶת, הַקָּדוֹשׁ בָּרוּךְ הוּא יַכְנִיסוֹ לְגַן עֵדֶן וּמַטְעִים אוֹתוֹ מֵעֵץ הַחַיִּים, שֶׁכָּתוּב עָלָיו (בראשית ג) וְלָקַח גַּם מֵעֵץ הַחַיִּים וְאָכַל וָחַי לְעֹלָם. שֶׁנִּבְרָא בַּתּוֹרָה, שֶׁבָּהּ נֶאֱמַר (משלי ג) עֵץ חַיִּים הִיא לַמַּחֲזִיקִים בָּהּ. עֵץ חַיִּים - תִּפְאֶרֶת. חַיִּים שֶׁלּוֹ חָכְמָה וּבִינָה. חַיֵּי הַמֶּלֶךְ וַדַּאי.</p>\n<p>וּלְעוֹלָם דִּין הַמַּלְכוּת הוּא דִּין, וְהַדִּין בַּלֵּב, וְנֶאֱמַר בּוֹ הַלֵּב רוֹאֶה. וְלָכֵן אֵין לוֹ לַדַּיָּן אֶלָּא מַה שֶּׁעֵינָיו רוֹאוֹת. וְכָאן אֵין דַּיָּן אֶלָּא הַקָּדוֹשׁ בָּרוּךְ הוּא. מַה שֶּׁעֵינָיו רוֹאוֹת, כִּי ה' עֵינָיו מְשׁוֹטְטוֹת. עֵינָיו עַל דַּרְכֵי אִישׁ.</p>\n<p>וּבָהֶן מַשְׁגִּיחַ מִן הַחַלּוֹנוֹת בְּשִׁבְעַת נִקְבֵי הָאָדָם: בִּשְׁתֵּי עֵינַיִם, וּשְׁתֵּי אָזְנַיִם, וּשְׁנֵי נִקְבֵי הַחֹטֶם, וְהַפֶּה. הֲרֵי שֶׁבַע שֶׁל הָאֵם הָעֶלְיוֹנָה. וְכָךְ בְּמַעֲשָׂיו הִסְתַּכֵּל בְּשֶׁבַע מִצַּד הַשְּׁכִינָה הַתַּחְתּוֹנָה, בִּשְׁתֵּי יָדַיִם וְצַוָּאר - שָׁלֹשׁ, וְגוּף וּבְרִית - שְׁתַּיִם. הֲרֵי חָמֵשׁ. שְׁתֵּי רַגְלַיִם - הֲרֵי שֶׁבַע. י\"ה, יוֹ\"ד הֵ\"א - בְּשֶׁבַע אוֹתִיּוֹתָיו מִסְתַּכֵּל בְּשִׁבְעַת נִקְבֵי הָרֹאשׁ. נְקָבִים, עַל שֵׁם נְקֵבָה, שֶׁנְּקָבֶיהָ פְּתוּחוֹת לְקַבֵּל. ו\"ה, וָא\"ו הֵ\"א - בְּשֶׁבַע אוֹתִיּוֹתָיו מִסְתַּכֵּל בְּשִׁבְעָה הָאֵיבָרִים שֶׁלְּמַטָּה, שֶׁהֵם תִּקּוּן הַגּוּף, שֶׁבָּהֶם עֲשִׂיַּת הַמִּצְווֹת.</p>\n<p>אִשְׁתּוֹ דּוֹמָה לְגוּפוֹ, וְעַל שֵׁם הַמִּצְווֹת נִקְרְאוּ אֵיבָרִים. עַל שֵׁם הַשְּׁכִינָה - הַגּוּף. שֶׁמִּצַּד הָאַחֵר לְבוּשׁוֹ, שֶׁהֵם עוֹר וּבָשָׂר. זֶהוּ שֶׁכָּתוּב (איוב י) עוֹר וּבָשָׂר תַּלְבִּישֵׁנִי וּבַעֲצָמוֹת וְגִידִים תְּשּכְכֵנִי. בְּמָקוֹם שֶׁאֵין שְׁכִינָה, אוֹתוֹ הַגּוּף לֹא נִקְרָא אֶלָּא לְבוּשׁ שֶׁל אָדָם, שֶׁהוּא תּוֹרָה, (ויקרא יט) זֹאת הַתּוֹרָה אָדָם כִּי יָמוּת בְּאֹהֶל. (ישעיה מד) כְּתִפְאֶרֶת אָדָם לָשֶׁבֶת בָּיִת. וּבְמָקוֹם שֶׁשָּׁם מִצְוָה נִקְרָא גוּף שֶׁל אָדָם, כְּמוֹ גוּפֵי הֲלָכוֹת וּפִסְקֵי דִינִים.</p>\n<p>הַקָּדוֹשׁ בָּרוּךְ הוּא שׁוֹפֵט, הָעַמּוּד הָאֶמְצָעִי, מִצַּד שֶׁל הַבִּינָה, שֶׁהוּא יְדֹוָ\"ד. דַּיָּן מִצַּד הַמַּלְכוּת. שׁוֹטֵר הוּא שַׁלִּיט, (מצד של יוסף הצדיק משם) (בראשית מב) וְיוֹסֵף הוּא הַשַּׁלִּיט. וְכָל הַסְּפִירוֹת הָיוּ שׁוֹפְטִים מִצַּד שֶׁל הָאֵם הָעֶלְיוֹנָה (בינה), שֶׁתִּפְאֶרֶת שׁוֹפֵט. וְהֵם שׁוֹטְרִים מִצַּד הַמַּלְכוּת. שֶׁצַּדִּיק מִשָּׁם שׁוֹטֵר וּמוֹשֵׁל.</p>"],[9522011675,"<p>מִדְּבַר שֶׁקֶר תִּרְחָק וְנָקִי וְצַדִּיק אַל תַּהֲרֹג וְגוֹ'. מִצְוָה לְהַשְׁווֹת בַּעֲלֵי דִינִים וּלְהִתְרַחֵק מִדְּבַר שֶׁקֶר, שֶׁלֹּא יֹאמְרוּ מַשּׂוֹא פָנִים (יש בדבר), שֶׁהַקָּדוֹשׁ בָּרוּךְ הוּא נֶאֱמַר בּוֹ (דברים י) אֲשֶׁר לֹא יִשָּׂא פָּנִים. וְלֹ\"א יִקַּ\"ח שֹׁחַ\"ד - בְּסוֹפֵי תֵבוֹת אֶחָד. הַדַּיָּן הַזֶּה צָרִיךְ לִהְיוֹת כְּגָוֶן שֶׁל אֶחָד, שֶׁהוּא יְדוָ\"ד אֶחָד, שֶׁלֹּא יִקַּח שּחַד, שֶׁהוּא יִהְיֶה בִּדְיוֹקְנוֹ.</p>\n<p>וּבַדִּין לְהַשְׁווֹת שְׁנֵיהֶם כְּאֶחָד, וְלֹא יַטֶּה דִין לָזֶה יוֹתֵר מִזֶּה, אֶלָּא בְּמִשְׁקֹלֶת אַחַת עַד שֶׁיְּקַבְּלוּ הַדִּין. וְאַחַר כָּךְ כָּל אֶחָד נִדּוֹן לְפִי מַעֲשָׂיו.</p>\n<p>וּפֵרְשׁוּהָ בַּעֲלֵי הַמִּשְׁנָה, צַדִּיק - יֵצֶר הַטּוֹב שׁוֹפְטוֹ. רָשָׁע - יֵצֶר הָרָע שׁוֹפְטוֹ. בֵּינוֹנִי - זֶה וָזֶה שׁוֹפְטוֹ. מִי שֶׁהוּא מֵעֵץ הַחַיִּים אֵין לוֹ דִּין כְּלָל, אֵין לוֹ יֵצֶר הָרָע, וְזֶה צַדִּיק גָּמוּר, וְזֶה צַדִּיק וְטוֹב לוֹ. וְאֵין טוֹב אֶלָּא תּוֹרָה. זֶהוּ שֶׁכָּתוּב (משלי ד) כִּי לֶקַח טוֹב נָתַתִּי לָכֶם תּוֹרָתִי אַל תַּעֲזוֹבוּ. וְצַדִּיק וְרָע לוֹ, מִצַּד שֶׁל עֵץ הַדַּעַת טוֹב וָרָע. וְלָמָּה נִקְרָא צַדִּיק אַחֵר שֶׁרַע לוֹ, שֶׁהוּא יֵצֶר הָרָע? אֶלָּא מִשּׁוּם שֶׁטּוֹב שׁוֹלֵט עָלָיו נִקְרָא צַדִּיק וְרַע לוֹ, שֶׁאוֹתוֹ רַע הוּא תַּחַת רְשׁוּתוֹ. (כעבד תחת רבו).</p>\n<p>רָשָׁע וְטוֹב לוֹ, לָמָּה נִקְרָא רָשָׁע? מִשּׁוּם שֶׁהוּא הִתְעַלָּה לִהְיוֹת רֹאשׁ בַּיֵּצֶר הָרָע שֶׁלּוֹ, וְהַטּוֹב הוּא תַּחַת רְשׁוּתוֹ כְּמוֹ עֶבֶד תַּחַת רַבּוֹ. וְאַף עַל גַּב שֶׁרָשָׁע הוּא מַכְתִּיר אֶת הַצַּדִּיק, וְיָכוֹל צַדִּיק גָּמוּר לְהַעֲנִישׁ אוֹתוֹ, גַּם עֲנוֹשׁ לַצַּדִּיק לֹא טוֹב. מִשּׁוּם אוֹתוֹ טוֹב שֶׁהוּא תַּחַת רַגְלֵי הָרָשָׁע, אֵין לְהַעֲנִישׁוֹ, שֶׁאוּלַי יַחֲזֹר בִּתְשׁוּבָה וְיִתְגַּבֵּר עַל יִצְרוֹ, וְיִהְיֶה עָפָר תַּחַת רַגְלָיו.</p>\n<p>שֶׁמִּצַד שֶׁל רָשָׁע וְטוֹב לוֹ (שכינה) שׁוֹכֶבֶת, (רות ג) וַתְּגַל מַרְגְּלֹתָיו וַתִּשְׁכָּב. זֶהוּ (משלי ל) וְשִׁפְחָה כִּי תִירַשׁ גְּבִרְתָּהּ. (ומצד של צדיק גמור) שִׁפְחָה - יֵצֶר הָרָע נְקֵבָה. יֵצֶר הָרָע - זָכָר. בִּגְלָלוֹ נֶאֱמַר (ישעיה מב) וּכְבוֹדִי לְאַחֵר לֹא אֶתֵּן, (במדבר א) וְהַזָּר הַקָּרֵב יוּמָת.</p>\n<p>וּמִצַד שֶׁל צַדִּיק וְרַע לוֹ, שְׁכִינָה הִיא עֲטָרָה עַל רֹאשׁוֹ שֶׁל אָדָם, וְשִׁפְחָה - יֵצֶר הָרָע - נִכְנַעַת תַּחַת גְּבִרְתָּהּ. וּמִצַּד שֶׁל צַדִּיק גָּמוּר אֵין זָר וְאֵין יֵצֶר הָרָע. וּמִצַּד שֶׁל רָשָׁע גָּמוּר אֵין לוֹ חֵלֶק בַּשְּׁכִינָה, שֶׁאֵין חֵלֶק לָאָדָם בַּשְּׁכִינָה אֶלָּא מִצַּד הַטּוֹב.</p>\n<p>וְאֵין כָּל שְׁכִינָה שְׁקוּלוֹת, שֶׁהֲרֵי שְׁכִינָה שֶׁל עֵץ טוֹב וָרָע הִיא כִּסֵּא, אֲבָל שְׁכִינָה שֶׁל עֵץ הַחַיִּים, עָלֶיהָ נֶאֱמַר (תהלים ה) לֹא יְגֻרְךְ רָע. (אלא) מִשּׁוּם שֶׁנֶּאֱמַר בָּהּ וּמַלְכוּתוֹ בַּכֹּל מָשָׁלָה, מִי שֶׁפּוֹגֵם אֶת מְקוֹמוֹ נֶחְשָׁב כְּאִלּוּ עָשָׂה קָלוֹן לַגְּבִירָה. שֶׁקְּלוֹן הַגְּבִירָה הוּא מִי שֶׁמְּזַלְזֵל בִּמְקוֹמָהּ, וּקְלוֹן הַגְּבִירָה הוּא שֶׁל הַמֶּלֶךְ.</p>\n<p>כָּל שֶׁכֵּן מִי שֶׁמַּעֲבִיר אוֹתָהּ מִמְּקוֹמָהּ וְשָׂם שִׁפְחָה בִּמְקוֹמָהּ, שֶׁבְּכָל מָקוֹם שֶׁהוּא פּוֹגֵם, הַגְּבִירָה אֵינָהּ שְׁרוּיָה שָׁם, אֶלָּא שִׁפְחָה, שֶׁהִיא פְּגוּמָה, שׁוֹרָה בְּמָקוֹם פָּגוּם. וּפְגָם שֶׁל אָדָם שֶׁל חֲטָאָיו פּוֹגֵם בְּכָל אֵיבָרָיו, עַד שֶׁלֹּא מוֹצֵאת הַגְּבִירָה מָקוֹם לִשְׁרוֹת שָׁם, וְאֵין לוֹ תִּקּוּן עַד שֶׁיַּחֲזִירֶנָּה לְכָל אֵיבָרָיו.</p>"],[9522011676,"<p>אָמַר הַמְּנוֹרָה הַקְּדוֹשָׁה, רוֹעֶה הַנֶּאֱמָן, מִשּׁוּם זֶה אַתָּה מְתַקֵּן בַּחִבּוּר הַזֶּה שֶׁל רְמַ\"ח מִצווֹת לְהַמְלִיךְ אֶת הַקָּדוֹשׁ בָּרוּךְ הוּא עַל כָּל אֵיבְרֵי הַשְּׁכִינָה בְּכָל מִצְוָה וּמִצְוָה, וְאֵינְךְ חוֹשֵׁשׁ לִכְבוֹדְךְ. אַשְׁרֵי חֶלְקְךְ. שֶׁכְּמוֹ שֶׁאַתָּה מַמְלִיךְ אֶת הַקָּדוֹשׁ בָּרוּךְ הוּא בְּכָל אֵיבְרֵי הַשְּׁכִינָה, שֶׁהֵם בַּעֲלֵי מִדּוֹת שֶׁל כָּל יִשְׂרָאֵל, בַּעֲלֵי מִדּוֹת הֵם אֵיבְרֵי הַשְּׁכִינָה, כָּךְ עוֹשֶׂה הַקָּדוֹשׁ בָּרוּךְ הוּא לְהַשְׁרוֹת אֶת שְׁמוֹ עָלֶיךְ וְיַמְלִיךְ אוֹתְךְ עַל כָּל הַמַּחֲנוֹת הָעֶלְיוֹנִים וְהַתַּחְתּוֹנִים.</p>\n<p>קוּם רוֹעֶה הַנֶּאֱמָן לְסַדֵּר דִּינִים בְּהִלְכוֹת נְזִיקִין, בַּסִּדּוּר שֶׁל הַשֵּׁם הַזֶּה, הֲוָיָ\"ה, שֶׁהוּא (תהלים סח) רֶכֶב אֱלֹהִים רִבֹּתַיִם אַלְפֵי שִׁנְאָן, שֶׁהֵם שׁוֹר נֶשֶׁר אַרְיֵה אָדָם, שֶׁהֲרֵי מִצַּד הַיָּמִין, שֶׁשָּׁם יְדוָ\"ד, אַרְבַּע חַיּוֹת, כָּךְ הוּא סִדּוּרָם: אָדָם אַרְיֵה נֶשֶׁר שׁוֹר. וּכְפִי הַשִּׁנּוּיִים שֶׁמִּתְהַוִּים, כָּךְ הִיא תְּנוּעַת וְסִדּוּר הַחַיּוֹת. וְהַחַיּוֹת שֶׁל הַצַּד הָאַחֵר, שֶׁהֵם נְזִיקִין שֶׁל שְׂמֹאל, כָּךְ סִדּוּרָם: שִׁנְאָן. וּמִשּׁוּם זֶה הַהַתְחָלָה שֶׁלָּהֶם - הַשּׁוֹר - קָשׁוּר לְאַרְבָּעָה אֲבוֹת נְזִיקִין - הַשּׁוֹר וְהַבּוֹר וְהַמַּבְעֶה וְהַהֶבְעֵר, וְהַסִּיּוּם שֶׁלָּהֶם אָדָם, מוּעָד.</p>\n<p>קוּם הִתְעוֹרֵר בְּדִינִים. פָּתַח רוֹעֶה הַנֶּאֱמָן וְאָמַר, (שם כא) אֲדנָי שְׂפָתַי תִּפְתָּח וּפִי יַגִּיד תְּהִלָּתֶךְ. אֲדֹנָ\"י בְּהִפּוּךְ אוֹתִיּוֹת - דִּינָ\"א, וּמִשּׁוּם זֶה אָמְרוּ בַּעֲלֵי הַמִּשְׁנָה, דִּינָא דְמַלְכוּתָא דִּינָא. כָּל הַדִּינִים בַּשֵּׁם הַזֶּה נִדּוֹנוּ. (בה' בד') בְּד', בְּג'. בְּד' - שְׁכִינָה (בית דין בשלשה, בית דין שכינה בשלשה) כְּנֶגֶד שְׁלֹשֶׁת הָאָבוֹת. עַמּוּד הָאֶמְצָעִי, דַּיַּן אֱמֶת, וְהוּא דַּיָּן לָדוּן מִצַּד שֶׁל אֲדֹנָ\"י, שֶׁשָּׁם הוּא דַּיַּן אֱמֶת. וּמִצַּד שֶׁל שֵׁם אֱלֹהִים, שׁוֹפֵט. זֶהוּ שֶׁכָּתוּב (שם עה) כִּי אֱלֹהִים שּפֵט.</p>\n<p>וּמָהֵם הַדִּינִים? אֶחָד, לָדוּן בְּנִזְקֵי שׁוֹר. שֵׁנִי, לָדוּן בְּנִזְקֵי בוֹר. שְׁלִישִׁי, לָדוּן בְּנִזְקֵי אֵשׁ. רְבִיעִי, לָדוּן בְּנִזְקֵי אָדָם. וְאַחֲרֵיהֶם לָדוּן בְּדִינֵי אַרְבָּעָה שׁוֹמְרִים: שׁוֹמֵר חִנָּם, וְשׁוֹמֵר שָׂכָר, וְהַשּׁוֹאֵל, וְנוֹשֵׂא שָׂכָר. (והשוכר) כְּנֶגְדָּם אַרְבָּעָה דִּינִים: דִּין חֲלֻקַּת הַשֻּׁתָּפִים, דִּין חֲלֻקַּת קַרְקָעוֹת, דִּינֵי עֲבָדִים וּשְׁפָחוֹת, דִּינֵי תוֹבֵעַ וְנִתְבָּע בְּכַמָּה מִינֵי תְבִיעוֹת שֶׁל חִיּוּב מָמוֹן וְגָזֵל וַאֲבֵדָה, אוֹ שֶׁמַּזִּיק לַחֲבֵרוֹ וְהוֹרְגוֹ בְּאַחַת מֵאַרְבַּע מִיתוֹת בֵּית דִּין.</p>\n<p>אָדוֹן הוּא הַקָּדוֹשׁ בָּרוּךְ הוּא, בַּאדנָ\"י, לָדוּן בְּכָל מִינֵי דִינִים אֶת הַשִּׁפְחָה הָרָעָה כִּי תִירַשׁ גְּבִרְתָּהּ, שֶׁמִּמֶּנָּה כָּל הַנְּזָקִים נִמְצָאִים, שֶׁהֵם (כל) מַלְאֲכֵי חַבָּלָה, שֶׁמֵּהֶם נִשְׁמוֹת הָרְשָׁעִים, כְּמוֹ שֶׁבֵּאֲרוּ בַּעֲלֵי הַמִּשְׁנָה, נִשְׁמוֹת הָרְשָׁעִים הֵן הֵן הַמַּזִּיקִים שֶׁל הָעוֹלָם. אֵל אַחֵר, מַזִּיק, גַּזְלָן רָשָׁע. וּבַת זוּגוֹ סַם הַמָּוֶת.</p>\n<p>נֶזֶק שֶׁבֶת וּבשֶׁת וְרִפּוּי - לַשְּׁכִינָה וּבָנֶיהָ. שֶׁבֶת - שֶׁל בִּטּוּל תּוֹרָה שֶׁבִּטְּלָה אֶת בָּנֶיהָ. וְרִפּוּי - שֶׁגָּרְמָה לָהֶם שֶׁמִּתְרַפִּים מִדִּבְרֵי תוֹרָה. נֶזֶק - בְּכַמָּה נְזָקִים שֶׁל מַלְאֲכֵי חַבָּלָה, בַּעֲלֵי מַשְׁחִית אַף וְחֵמָה. וּבֹשֶׁת - שֶׁהָיוּ מְבַזִּים אֶת הַשְּׁכִינָה בְּכוֹכָבִים וּמַזָּלוֹת, הַשֶּׁקֶר שֶׁלָּהֶם, וְהָיוּ אוֹמְרִים אַיֵּה אֱלֹהֶיךְ. וְכַמָּה גְזֵלוֹת מֵהַשִּׁפְחָה הָרָעָה, שֶׁנֶּאֱמַר בָּהּ (ישעיה ג) גְּזֵלַת הֶעָנִי בְּבָתֵּיכֶם.</p>\n<p>כַּמָּה בְרָכוֹת גּוֹזֶלֶת אֶת הַשְּׁכִינָה הַשִּׁפְחָה הָרָעָה; בְּכֹבֶד הַמַּס, וּבְכֹבֶד שֶׁל כַּמָּה דִינִים מְשֻׁנִּים עַל בָּנֶיהָ, וְכַמָּה קָרְבָּנוֹת שֶׁל בֵּית הַמִּקְדָּשׁ שֶׁבִּטְּלָה לַגְּבִירָה. וּבֹשֶׁת שֶׁל הַגְּבִירָה שֶׁנִּשְׁאֲרָה עֲרֻמָּה מֵאַרְבָּעָה בִּגְדֵי זָהָב שֶׁמְּאִירִים מֵאַרְבָּעָה טוּרֵי אֶבֶן בִּשְׁתֵּים עֶשְׂרֵה אֲבָנִים מַרְגָּלִיּוֹת. מְעִיל בְּכַמָּה זַגִּים וְרִמּוֹנִים. וְאַרְבָּעָה בִּגְדֵי לָבָן שֶׁבָּהֶם הָיְתָה הַגְּבִירָה מִתְקַשֶּׁטֶת לִפְנֵי הַמֶּלֶךְ. זֶהוּ שֶׁכָּתוּב (בראשית ט) וּרְאִיתִיהָ לִזְכֹּר בְּרִית עוֹלָם. וְגוֹזֶלֶת אֶת גְּבִרְתָּהּ כַּמָּה מַאַכְלֵי הַקָּרְבָּנוֹת.</p>\n<p>שׁוֹר מוּעָד בַּעְלָהּ, נִכְנָס לְבֵית הַמֶּלֶךְ רִבּוֹנוֹ בְּאַרְבָּעָה אֲבוֹת הַנְּזִיקִין שֶׁלּוֹ, (שהם (יחזקאלא) ופניהשור מהשמאול לארבּעתָּן) עון ומשחית אף וחמה, שכלם מועדים לקלקל. בגוף שלו הרביץ על הכלים, מזבח מנורה שלחן ושאר כלים. רבץ עליהם ושברם. ובשן שלו אכל כל הקרבנות של מאכלי השלחן, ואת השאר רמס ברגליו, (וּמָחק הכּל, והשאָר שהם אמוּרים וּפדָרים, שיָרי מנָחות, רָמסבּרגלָיו) ובקרנו הרג כהנים ולוים. הרס הכל, חלל ממלכה ושריה.</p>\n<p>הַבּוֹר נְקֵבָה רָעָה, לִילִית, בְּבֵיתָהּ, שֶׁהִיא בֵּית הַסֹּהַר, תָּפְסָה אֶת הַגְּבִירָה וּבָנֶיהָ, הַשִּׁפְחָה רָעָה, בַּגָּלוּת שֶׁלָּהּ, וְשָׂמָה אוֹתָהּ בְּכַמָּה שַׁלְשְׁלָאוֹת, וְאָסְרוּ לְבָנֶיהָ אֶת יְדֵיהֶם מְהֻדָּקִים לְאָחוֹר. (איכה א) הִיא יָשְׁבָה בַגּוֹיִם לֹא מָצְאָה מָנוֹחַ. וְלֹא עוֹד, אֶלָּא (שם) כָּל מְכַבְּדֶיהָ הִזִּילוּהָ כִּי רָאוּ עֶרְוָתָהּ גַּם הִיא נֶאֶנְחָה וַתָּשָׁב אָחוֹר.</p>\n<p>וְלֹא עוֹד, אֶלָּא זוֹנָה, שֶׁהִיא הֶבְעֵר, שֶׁהַיְנוּ אֵשׁ, וַיַּצֶּת אֵשׁ בְּצִיּוֹן. אַחַר כָּךְ קָם אָדָם בְּלִיַּעַ\"ל רָשָׁע, רְבִיעִי לַאֲבוֹת הַנְּזִיקִין, שֶׁנֶּאֱמַר בּוֹ אָדָם מוּעָד לְעוֹלָם, בֵּין עֵר בֵּין יָשֵׁן, וְשִׁלַּח אֶת בְּעִירֹה, וְאָכַל וְהִשְׁמִיד וְגָדַע כְּרָמִים וּפַרְדֵּסִים שֶׁל יְרוּשָׁלַיִם, וְכִלָּה הַכֹּל.</p>\n<p>רִבּוֹן הָעוֹלָם, אַתָּה אֱמֶת וְתוֹרָתְךְ אֱמֶת, נָתַתָּ לָנוּ מִצְוַת תְּפִלִּין, לְצַדִּיקִים גְּמוּרִים הוּא שָׂכָר כְּפִי מַעֲשֵׂיהֶם, פְּאֵר עַל רֹאשָׁם, וּמְשַׁמְּשִׁים אֶת אֲבוֹתֵיהֶם וְאִמָּם, כְּמוֹ שֶׁהַגּוּף שֶׁכָּל אֵיבָרָיו מְשַׁמְּשִׁים אֶת הָרֹאשׁ, כָּךְ הָאִשָּׁה מְשַׁמֶּשֶׁת אֶת בַּעְלָהּ.</p>\n<p>וְיִשִׁ מַלְאָכִים הַמְשַׁמְּשִׁים אֶת הַגּוּף, וּמַלְאָכִים הַמְשַׁמְּשִׁים אֶת הַנְּשָׁמָה. וּכְמוֹ שֶׁיֵּשׁ הַפְרָדָה בֵּין גּוּף וּנְשָׁמָה, כָּךְ יֵשׁ הַפְרָדָהּ בֵּין הַמַּלְאָכִים שֶׁל הַגּוּף לְבֵין הַמַּלְאָכִים שֶׁל הַנְּשָׁמָה. וְיֵשׁ נְשָׁמָה לִנְשָׁמָה, וּמַלְאָכִים לְמַלְאָכִים, (קהלת ה) כִּי גָבהַּ מֵעַל גָּבֹהַּ שֹׁמֵר וּגְבֹהִים עֲלֵיהֶם. וְאֵלֶּה שֶׁהֵם נְשָׁמָה לִנְשָׁמָה, כֻּלָּם אֶחָד. וְאַף עַל גַּב שֶׁדֶּרֶךְ מָשָׁל, הֵם כְּגוּף אֵצֶל הַנְּשָׁמָה אֵלֶּה לְאֵלֶּה, מִשּׁוּם שֶׁמְּקַבְּלִים אֵלֶּה מֵאֵלֶּה. כָּךְ הַשְּׁכִינָה (הגשמה), אַף עַל גַּב שֶׁהִיא כְּנֶגֶד שְׁאָר הָאוֹרוֹת שֶׁל הַבְּרִיאָה כִּנְשָׁמָה אֵצֶל הַגּוּף, כְּנֶגֶד הַקָּדוֹשׁ בָּרוּךְ הוּא הִיא חֲשׁוּבָה כְּגוּף, אֲבָל הַכֹּל אֶחָד. כָּאן גּוּף וּנְשָׁמָה הַכֹּל אֶחָד. מַה שֶּׁאֵין כָּךְ בָּאָדָם, שֶׁגּוּפוֹ וְנִשְׁמָתוֹ בְּפֵרוּד, זֶה חֹמֶר וְזֶה שֵׂכֶל, זֶה חַיִּים וְזֶה מָוֶת. אֲבָל הַקָּדוֹשׁ בָּרוּךְ הוּא חַיִּים וּשְׁכִינָתוֹ חַיִּים. זֶהוּ שֶׁכָּתוּב (משליג) עֵץ חַיִּים הִיא לַמַּחֲזִיקִים בָּהּ.</p>"],[9522011677,"<p>וְכָל אוֹתָם שֶׁרְשׁוּמִים בְּסִימָנֵי הַקָּדוֹשׁ בָּרוּךְ הוּא וּשְׁכִינָתוֹ, הֵם רְשׁוּמִים בִּימֵי הַחֹל בָּאוֹת שֶׁל הַתְּפִלִּין, בָּאוֹת שֶׁל הַמִּילָה, וּרְשׁוּמִים בְּזָכוֹר וְשָׁמוֹר בְּשַׁבָּת. רְשׁוּמִים בַּתּוֹרָה שֶׁבִּכְתָב שֶׁנִּתְּנָה מִיָּמִין, וּבַתּוֹרָה שֶׁבְּעַל פֶּה שֶׁנִּתְּנָה מִשְּׂמֹאל. וְהַקָּדוֹשׁ בָּרוּךְ הוּא זָכוֹר מִיָּמִין, וְשָׁמוֹר מִשְּׂמֹאל. וְהַשְּׁכִינָה זְכִירָה מִיָּמִין, וּשְׁמִירָה מִשְּׂמֹאל. הֵן תְּפִלִּין שֶׁל רֹאשׁ שֶׁל הָאָדָם, וּתְפִלִּין שֶׁל יָד. וְכָךְ שְׁכִינָה, תּוֹרַת ה' תְּמִימָה, וְהַמִּצְוָה שֶׁלּוֹ. וְזֶה מֵהַצַּד שֶׁל הָעַמּוּד הָאֶמְצָעִי, שֶׁהוּא כּוֹלֵל דִּין וְרַחֲמִים. זָכוֹר וְשָׁמוֹר. נִקְרֵאת הִיא זְכִירָה וּשְׁמִירָה. וּבְכָל הַמִּצְווֹת הִיא שְׁקוּלָה אֵלָיו בַּמַּדְרֵגָה.</p>\n<p>אֲבָל מִצַּד הַחֶסֶד - הַקָּדוֹשׁ בָּרוּךְ הוּא הוּא זָכוֹר, וְהַשְּׁכִינָה שָׁמוֹר. כְּמוֹ שֶׁבֵּאֲרוּהָ בַּעֲלֵי הַמִּשְׁנָה, זָכוֹר לְזָכָר, וְשָׁמוֹר לְכַלָּה. מִשּׁוּם שֶׁבְּיָמִין וּבִשְׂמֹאל הָעֲנָפִים מִתְפָּרְדִים, כְּמוֹ כַּנְפֵי רֵאָה שֶׁהֵן פְּרוּדוֹת מִלְמַעְלָה. כְּנֶגְדָּם חַיּוֹת, וּפְנֵיהֶם וְכַנְפֵיהֶם פְּרֻדוֹת מִלְמָעְלָה. וּכְנֶגֶד פְּתוּחוֹת שֶׁל סֵפֶר תּוֹרָה. לְמַטָּה שְׁנֵיהֶם בְּיִחוּד אֶחָד, כְּמוֹ סְתוּמוֹת שֶׁל סֵפֶר תּוֹרָה, שֶׁאֵין שָׁם פֵּרוּד. וּמִשּׁוּם כָּךְ בְּמָקוֹם שֶׁל יִחוּד, שֶׁהוּא גּוּף, דּוֹמֶה לְשִׁדְרָה שֶׁל לוּלָב. אִם נִפְרְצוּ אוֹ נִפְרְדוּ עָלָיו - פָּסוּל.</p>\n<p>בְּכַמָּה רִשּׁוּמִים רָשַׁם הַקָּדוֹשׁ בָּרוּךְ הוּא אֶת יִשְׂרָאֵל לְהִוָּדַע לַמַּלְאָכִים. אֵלּוּ מִיָּמִין, שֶׁתְּלוּיִים מֵהַקָּדוֹשׁ בָּרוּךְ הוּא, אוֹ אֵלּוּ מִשְּׂמֹאל, שֶׁתְּלוּיִים מֵהַשְּׁכִינָה, אוֹ אֵלּוּ שֶׁתְּלוּיִים מֵהַקָּדוֹשׁ בָּרוּךְ הוּא וּשְׁכִינָתוֹ בְּיִחוּד אֶחָד. וַדַּאי אֵלֶּה שֶׁיֵּשׁ בָּהֶם תּוֹרָה רְשׁוּמִים בְּחֶסֶד, וְאֵלֶּה שֶׁיֵּשׁ בָּהֶם מִצְוָה רְשׁוּמִים בִּגְבוּרָה, וְאֵלּוּ בַּעֲלֵי הַתְּפִלִּין וְאוֹת שַׁבָּת וְאוֹת בְּרִית רְשׁוּמִים בְּצַדִּיק.</p>\n<p>וְהַבְּהֵמוֹת, עַמֵּי הָאָרֶץ, הֵם רְשׁוּמִים בְּהַעֲבָרַת עָרְלָה וּפְרִיעָה. עוֹפוֹת - בְּזֶפֶק וּבְקֻרְקְבָן נִקְלָף, בְּהַעֲבָרַת הַזֶּפֶק וּקְלִפַּת הַקֻּרְקְבָן, הֵם רְשׁוּמִים בָּעוֹפוֹת לֶאֱכֹל. וּבְהֵמוֹת בִּשְׁנֵי סִימָנִים - מַעֲלַת גֵּרָה וּמַפְרֶסֶת פַּרְסָה. כֻּלָּם רְשׁוּמִים בִּשְׁנֵי סִימָנִים, כְּמוֹ עָרְלָה וּפְרִיעָה, שֶׁמָּעֳבָרִים מֵהָעָם הַקָּדוֹשׁ.</p>\n<p>אֲבָל תַּלְמִידֵי חֲכָמִים, כֻּלָּם רְשׁוּמִים מֵהֶם בַּכִּסֵּא. וּמֵהֶם בַּמַּלְאָכִים, בְּאַרְבַּע חַיּוֹת הַכִּסֵּא. מֵהֶם בַּכּוֹכָבִים וּבַמַּזָּלוֹת, וּמֵהֶם רְשׁוּמִים בַּמִּדּוֹת שֶׁהַקָּדוֹשׁ בָּרוּךְ הוּא נוֹדָע בָּהֶם. וְאוֹתָם שֶׁמִּתְעַסְּקִים בְּתוֹרָה וּמִצְווֹת לִשְׁמוֹ שֶׁל הַקָּדוֹשׁ בָּרוּךְ הוּא שֶׁלֹּא עַל מְנָת לְקַבֵּל פְּרָס, אֶלָּא כְּבֵן הַמְחֻיָּב בִּכְבוֹד אָבִיו וְאִמּוֹ, זֶה וַדַּאי נִקְשָׁר וְנִרְשָׁם בָּעַמּוּד הָאֶמְצָעִי וּשְׁכִינָתוֹ, כְּאִלּוּ בּוֹ הֵם הָיוּ אֶחָד. וּמִי שֶׁיֵּשׁ בּוֹ תּוֹרָה בְּלִי מִצְוָה אוֹ מִצְוָה בְּלִי תוֹרָה, כִּבְיָכוֹל כְּאִלּוּ הָיוּ בוֹ בְּפֵרוּד. אֲבָל בָּזֶה וְזֶה, כְּמוֹ אִילָן שֶׁעֲנָפִים נִפְרָדִים לְיָמִין וְלִשְׂמֹאל, וְהָאִילָן הַיִּחוּד שֶׁל שְׁנֵיהֶם בָּאֶמְצַע.</p>\n<p>הָרְשָׁעִים רְשׁוּמִים בְּלִי סִימָנֵי טָהֳרָה, אוֹתָם שֶׁאֵין לָהֶם תְּפִלִּין עַל הָרֹאשׁ וְהַזְּרוֹעַ, וְאוֹתָם שֶׁלֹּא רְשׁוּמִים בְּתוֹרָה וּמִצְווֹת, וְאֵלֶּה שֶׁלֹּא שׁוֹמְרִים זָכוֹר וְשָׁמוֹר, וְלֹא רְשׁוּמִים בִּתְכֵלֶת וְלָבָן שֶׁל צִיצִית. וְאֵלֶּה שֶׁלֹּא רְשׁוּמִים בַּסִּימָנִים הַלָּלוּ, שֶׁקֶץ הֵם לָכֶם, אֵינָם יִשְׂרָאֵל, אֶלָּא עַמֵּי הָאָרֶץ. מָה אֵלֶּה שֶׁקֶץ וְשֶׁרֶץ - אַף הֵם (כך) שֶׁקֶץ וְשֶׁרֶץ. כְּמוֹ שֶׁבֵּאֲרוּהָ בַּעֲלֵי הַמִּשְׁנָה, עַמֵּי הָאָרֶץ הֵם שֶׁרֶץ, וּנְשׁוֹתֵיהֶם שֶׁקֶץ. וְעַל בְּנוֹתֵיהֶם נֶאֱמַר, (דברים כז) אָרוּר שּכֵב עִם כָּל בְּהֵמָה.</p>\n<p>וּמִיתָתָם מִיתָה בְּגָלוּי, וְאֵין מִיתָה אֶלָּא עֹנִי, וּמִיתַת הָעֹנִי שֶׁלָּהֶם לֹא תִהְיֶה בְּכִסּוּי, כְּמוֹ עוֹפוֹת שֶׁדּוֹמִים לְבַעֲלֵי מִצְווֹת, אֶלָּא בְּגִלּוּי, לְעֵינֵי הָעָם, שֶׁעָנִי חָשׁוּב בְּמֵת. וְיֵשׁ עֹנִי בְּכִסּוּי מֵעֵינֵי בְּנֵי אָדָם. וְיֵשׁ עֲנִיּוּת לְעֵינֵי כֹל, כִּזְרִיקַת דַּם הַבְּהֵמָה, וּזְרִיקָתָהּ לְעֵינֵי כֹל, שֶׁשּׁוֹפְכִים דָּם לִפְנֵי הַכֹּל. כָּךְ הָעֲנִיִּים שֶׁדָּמָם נִשְׁפָּךְ בִּפְנֵיהֶם לְעֵינֵי בְּנֵי אָדָם וְנַעֲשִׂים לִירֻקִּים כְּמוֹ מֵתִים.</p>\n<p>וְאִם חוֹזְרִים בִּתְשׁוּבָה וְלֹא פוֹתְחִים פִּיהֶם לְהָטִיחַ דְּבָרִים כְּלַפֵּי מַעְלָה, וּמִיתָתָם בִּסְתִימַת פֶּה, כְּמוֹ בְּהֵמָה שֶׁהִיא מֵתָה וְאֵין לָהּ קוֹל וְדִבּוּר. וּבַוִּדּוּי כָּךְ הוּא יֹאמַר: אֵין לִי פֶּה לְהָשִׁיב, וְלֹא מֵצַח לְהָרִים רֹאשׁ. וְיִתְוַדֶּה, וּמְיַחֵד אֶת הַקָּדוֹשׁ בָּרוּךְ הוּא בְּכָל יוֹם לִהְיוֹת מִיתָתוֹ בְּאֶחָד. כְּמוֹ שְׁחִיטַת הַבְּהֵמָה בִּשְׁתֵּים עֶשְׂרֵה בְּדִיקוֹת סַכִּין, וּבְסַכִּין שֶׁהוּא אֶחָ\"ד.</p>\n<p>וּמְבָרֵךְ וּמְקַדֵּשׁ אֶת הַקָּדוֹשׁ בָּרוּךְ הוּא בְּכָל יוֹם בְּבָרְכוּ וּבִקְדֻשָּׁה, וּבְכָל אֲכִילָה וּשְׁתִיָּה שֶׁלּוֹ. כְּמוֹ שֶׁמְּבָרֵךְ הַכֹּהֵן: בָּרוּךְ אַתָּה - הֲרֵי בְּרָכָה. אֲשֶׁר קִדְּשָׁנוּ - הֲרֵי קְדֻשָּׁה. כְּשֶׁהָרוּחַ מְבָרֶכֶת אֶת הַקָּדוֹשׁ בָּרוּךְ הוּא בְּכָל יוֹם בְּבָרוּךְ, וּמְקַדֶּשֶׁת אוֹתוֹ בִּקְדֻשָּׁתוֹ וּמְיַחֶדֶת אוֹתוֹ בְּיִחוּד שֶׁהִיא שְׁכִינָתוֹ, הַקָּדוֹשׁ בָּרוּךְ הוּא יוֹרֵד עַל אוֹתָהּ רוּחַ בְּכַמָּה מַחֲנוֹת.</p>"],[9522011678,"<p>אֵלִיָּהוּ, וַדַּאי אָדָם שֶׁמְּבָרֵךְ וּמְקַדֵּשׁ וּמְיַחֵד אֶת הַגְּבִירָה, כַּמָּה מַחֲנוֹת שֶׁל הַגְּבִירָה עוֹלִים עִמּוֹ, וּמַחֲנוֹת הַמֶּלֶךְ יוֹרְדִים אֵלָיו. וְכֻלָּם כְּדֵי לְשָׁמְרוֹ, וּלְהוֹדִיעָהּ לְאוֹתָהּ רוּחַ כַּמָּה חִדּוּשִׁים וַעֲתִידוֹת בַּחֲלוֹמוֹת בִּנְבוּאָה, וְכַמָּה סְתָרִים, כְּמוֹ שֶׁיַּעֲקֹב שֶׁנֶּאֱמַר בּוֹ, (בראשית כח) וְהִנֵּה מַלְאֲכֵי אֱלֹהִים עֹלִים וְיֹרְדִים בּוֹ. וְעַל מַחֲנוֹת הַמֶּלֶךְ וְהַגְּבִירָה נֶאֱמַר (שם לב) וַיִּקְרָא שֵׁם הַמָּקוֹם הַהוּא מַחֲנָיִם. אֲבָל הַמֶּלֶךְ וְהַגְּבִירָה לֹא יוֹרְדִים לְשָׁם.</p>\n<p>אָמַר אֵלִיָּהוּ, רוֹעֶה הַנֶּאֱמָן, כָּךְ זֶה וַדַּאי, אֲבָל מִשּׁוּם שֶׁבְּכָל מִצְוָה וּמִצְוָה הָיְתָה הִשְׁתַּדְּלוּת שֶׁלְּךְ לְיַחֵד אֶת הַקָּדוֹשׁ בָּרוּךְ הוּא וּשְׁכִינָתוֹ בְּכָל הַמַּחֲנוֹת שֶׁלְּמַעְלָה וּלְמַטָּה, כָּךְ הַקָּדוֹשׁ בָּרוּךְ הוּא וּשְׁכִינָתוֹ וְכָל מַחֲנוֹתָיו מַעְלָה וּמַטָּה מִתְיַחֲדִים עִם רוּחֲךְ בְּכָל מִצְוָה וּמִצְוָה, כְּבֶן הַמֶּלֶךְ שֶׁהָאָב וְהָאֵם אוֹהֲבִים אוֹתוֹ וּמְנַשְּׁקִים אוֹתוֹ, וּמֵחֲבִיבוּת שֶׁלּוֹ אֵינָם מַאֲמִינִים לְמַחֲנוֹתֵיהֶם, אֶלָּא הֵם בְּגוּפָם שׁוֹמְרִים אוֹתוֹ.</p>\n<p>מִשּׁוּם שֶׁאוֹתָהּ הָרוּחַ שֶׁלְּךְ הִיא מִצַּד הָעַמּוּד הָאֶמְצָעִי, שֶׁהוּא ו' כּוֹלֵל אָב וָאֵם, שֶׁהֵם י\"ה. הַנֶּפֶשׁ שֶׁלְּךְ, בַּת יְחִידָה, מִצַּד הָאוֹת ה', הַשְּׁכִינָה הַתַּחְתּוֹנָה לֹא זָזָה מִמְּךְ. וּכְמוֹ שֶׁאַבָּא וְאִמָּא שׁוֹמְרִים אֶת הַבֵּן, כָּךְ שׁוֹמְרִים אֶת הַבַּת בְּמַחֲנוֹת עֶלְיוֹנִים, שֶׁהֵם מַחֲנַיִם. וּבַמַּחֲשָׁבָה הָעֶלְיוֹנָה עוֹלִים לְרוּחֲךְ, כְּמוֹ שֶׁבֵּאֲרוּהָ, יִשְׂרָאֵל עָלָה בְּמַחֲשָׁבָה. יוֹ\"ד הֵ\"א וָא\"ו הֵ\"א. וּמָתַי רוּחֲךְ עָלְתָה בְּמַחֲשָׁבָה? כְּשֶׁהִיא שְׁלֵמָה, וְנֶאֱמַר בָּהּ (תהלים קנ) כֹּל הַנְּשָׁמָה תְּהַלֵּל יָהּ. וּבַנֶּפֶשׁ שֶׁהִיא ה'.</p>\n<p>בְּרוּחַ ה' נֶאֱמַר, כֹּה אָמַר ה' מֵאַרְבַּע רוּחוֹת בּאִי הָרוּחַ. וְהֵם רוּחַ ה', רוּחַ חָכְמָה וּבִינָה, רוּחַ עֵצָה וּגְבוּרָה וְגוֹ'. שָׁלֵם בְּאַרְבַּע אוֹתִיּוֹת, עָלָה בְּמַחֲשָׁבָה, וְעִלַּת הָעִלּוֹת מְעַטְּרוֹ בְּכֶתֶר. בְּכָל הַכָּבוֹד הַזֶּה רוּחֲךְ עוֹלָה וְיוֹרֶדֶת כָּל לַיְלָה, וְכָל הַדְּבָרִים שֶׁהִתְגַּלּוּ (לך בחסד, ועליהם נאמר ואתם וכו') עַל כֶּתֶר (דברים ד) וְאַתֶּם הַדְּבֵקִים בַּה'. אַתֶּם, וְלֹא אֻמּוֹת עוֹבְדֵי כוֹכָבִים וּמַזָּלוֹת. וּמִשּׁוּם זֶה, (שמות כב) זבֵחַ לָאֱלֹהִים יָחֳרָם. אֱלֹהִים אֲחֵרִים. בִּלְתִּי לַה' לְבַדּוֹ.</p>\n<p>אַשְׁרֵי הָעָם הַקָּדוֹשׁ שֶׁנִּקְרְאוּ צֹאן שֶׁל הַקָּדוֹשׁ בָּרוּךְ הוּא, לְהַקְרִיב אֶת עַצְמָם קָרְבָּנוֹת לְפָנָיו, כְּמוֹ שֶׁנֶּאֱמַר (תהלים מד) כִּי עָלֶיךְ הֹרַגְנוּ כָל הַיּוֹם נֶחְשַׁבְנוּ כְּצֹאן טִבְחָה. וּמַקְרִיבִים אֶת עַצְמָם כְּמוֹ צֹאן, בְּתַעֲנִית. שֶׁמִּעוּט הַחֵלֶב וְהַדָּם שֶׁבַּתַּעֲנִית חָשׁוּב יוֹתֵר מִקָּרְבַּן בְּהֵמוֹת, שֶׁהָיָה מִתְמַעֵט הַדָּם וְהַחֵלֶב וְכָל אוֹתָם אֵמוּרִים וּפְדָרִים שֶׁנֶּאֱכָלִים כָּל הַלַּיְלָה.</p>\n<p>אַשְׁרֵיהֶם (ישראל) שֶׁמַּקְרִיבִים אֶת רוּחָם קָרְבָּנוֹת לִפְנֵי ה', וּבְכָל לַיְלָה וְלַיְלָה שֶׁרוּחָם הִיא הָעוֹלָה אֵלָיו, אִם מַעֲלֶה אוֹתָהּ בְּתוֹרָה וּמִצְוָה, בַּתּוֹרָה שֶׁהִיא עֶשֶׂר אֲמִירוֹת, שֶׁנִּתְּנוּ מֵהָאוֹת י' שֶׁבְּעֶשֶׂר דִּבְּרוֹת, מֵאוֹתִיּוֹת ה\"ה. (בו', בששה) בְּשֵׁשׁ חֻמְשֵׁי תוֹרָה בְּסֵפֶר, בְּרֵאשִׁית. חֲמִשָּׁה הֵם שֶׁנִּקְרְאוּ חֲמִשָּׁה חֻמְשֵׁי תוֹרָה. שִׁשִּׁי נִקְרָא סֵפֶר בְּרֵאשִׁית. וּבַמַּחֲשָׁבָה שֶׁהוּא יוֹ\"ד הֵ\"א וָא\"ו הֵ\"א, שֶׁנֶּאֱמַר בּוֹ יִשְׂרָאֵל עָלָה בְּמַחֲשָׁבָה. וּלְאֵיזֶה מָקוֹם עוֹלֶה? לְכֶתֶר שֶׁשָּׁם עִלַּת הָעִלּוֹת, מֻפְלָא וּמְכֻסֶּה.</p>\n<p>י' - קַדֶּשׁ לִי. ה' - וְהָיָה כִּי יְבִיאֲךְ. ו' - שְׁמַע יִשְׂרָאֵל. ה' - וְהָיָה אִם שָׁמוֹעַ. בַּמַּחֲשָׁבָה. לְקַשֵּׁר אוֹתָהּ בַּיָּד, שֶׁהַשְּׁכִינָה הִיא י\"ה וּכְלוּלָה מִמַּעֲשֶׂה שֶׁהִיא ה'. וְדִבּוּר שֶׁהִיא בִּינָה כְּלוּלָה ו' סְפִירוֹת. וּבַמַּחֲשָׁבָה, שֶׁהוּא יוֹ\"ד הֵ\"א וָא\"ו הֵ\"א, יְהֹוָ\"ה. י\"ד אוֹתִיּוֹת, כְּחֶשְׁבּוֹן יָד. וְנִרְמְזוּ בְּאַרְבַּע פָּרָשִׁיּוֹת, וּבֵית הַתְּפִלִּין א', וּשְׁתֵּי רְצוּעוֹת הָרֹאשׁ - שֶׁבַע. שֶׁשְּׁנֵי שִׁינִי\"ן תֵּשַׁע, וְקֶשֶׁר הָרְצוּעָה עֶשֶׂר. וְאַרְבַּע פָּרָשִׁיּוֹת הַיָּד - הֲרֵי י\"ד, יַד הַשְּׁכִינָה, יַד יְהֹוָ\"ה.</p>\n<p>בִּשְׁבִילָהּ נֶאֱמַר, (שם לא) בְּיָדְךְ אַפְקִיד רוּחִי וְגוֹ'. הָרוּחַ נִפְקְדָה לַיהֹוָ\"ה, וְהַקָּדוֹשׁ בָּרוּךְ הוּא יוֹרֵד אֵלָיו לְקַבְּלוֹ לַשְּׁכִינָה, וְשׁוֹמְרִים אוֹתוֹ הַקָּדוֹשׁ בָּרוּךְ הוּא וּשְׁכִינָתוֹ. וּמִי גוֹרֵם אֶת זֶה? מִי שֶׁבְּכָל מִצְוָה וּמִצְוָה מַעֲלֶה שְׁכִינָה אֶל הַקָּדוֹשׁ בָּרוּךְ הוּא.</p>\n<p>וְשִׁבְעִים תֵּבוֹת שֶׁל יַעַנְךְ ה' בְּיוֹם צָרָה, וּבַמָּה הִיא צוֹוַחַת? אֶלָּא וַדַּאי בְּיִשְׂרָאֵל יֵשׁ בַּעֲלֵי תוֹרָה, מַלְאָכִים, מִצַּד שֶׁל אַיֶּלֶת הַשַּׁחַר, שֶׁהִיא שְׁכִינָה. וּשְׁתֵּי דְרָגוֹת הֵן - בֹּקֶר וְשַׁחַר, וַעֲלֵיהֶן נֶאֱמַר (תהלים טז) נְעִמוֹת בִּימִינְךְ נֶצַח. בֹּקֶר שֶׁל אַבְרָהָם, שֶׁהוּא חֶסֶ\"ד, זֶה עוֹלֶה יוֹתֵר בְּיוֹם הַגְּאֻלָּה, אֲבָל הַשַּׁחַר מַקְדִּים לְיוֹם הַגְּאֻלָּה, וּמִיהוּ? נֶצַח, שֶׁשְּׁכִינָה מִצִּדּוֹ נִקְרֵאת אַיֶּלֶת הַשַּׁחַר.</p>\n<p>וּמִשּׁוּם כָּךְ, ל\"מ נֶצַח, שָׁם נֶצַ\"ח, שָׁם ל'\"'מ, שֶׁהֵם שִׁבְעִים הַקּוֹלוֹת שֶׁצּוֹוַחַת אַיֶּלֶת הַשַּׁחַר עַל בָּנֶיהָ, שֶׁהִתְחַזֵּק עֲלֵיהֶם הַקַּדְרוּת בַּגָּלוּת, שַׁחֲרוּת הַשַּׁחַר בְּשִׁבְעִים הַשָּׁנִים הָאַחֲרוֹנוֹת. (בשבעים) בְּאוֹתוֹ זְמַן יִתְקַיֵּם בְּיִשְׂרָאֵל, (ישעיה כו) כְּמוֹ הָרָה תַּקְרִיב לָלֶדֶת תָּחִיל תִּזְעַק בַּחֲבָלֶיהָ כֵּן הָיִינוּ מִפָּנֶיךְ ה'. וְעַל כֵּן נְקַוֶּה לָךְ ה' אֱלֹהֵינוּ:</p>"],[9522011679,"<p>וּבָהֶם הָאַיֶּלֶת מַכְנִיסָה רֹאשָׁהּ בֵּין בִּרְכֶּיהָ. הָרֹאשׁ הוּא צַדִּיק יְסוֹד עוֹלָם. בֵּין בִּרְכֶּיהָ שֶׁהֵם נֶצַח וְהוֹד. וְנִשְׁבַּע לָהּ בּוֹ לִפְדּוֹת אֶת בָּנֶיהָ בַּבֹּקֶר, שֶׁהִיא אַרְיֵה, בֹּקֶר יָמִין שֶׁל אַבָרָהָם, מָשִׁיחַ בֶּן דָּוִד שֶׁיּוֹצֵא מִיהוּדָה, שֶׁנֶּאֱמַר בּוֹ (בראשית מט) גּוּר אַרְיֵה יְהוּדָה. וּמִשּׁוּם זֶה (רות ג) חַי ה' שִׁכְבִי עַד הַבֹּקֶר.</p>\n<p>וּבָהּ (ישעיה סג) מוֹלִיךְ לִימִין מֹשֶׁה זְרוֹעַ תִּפְאַרְתּוֹ בּוֹקֵעַ מַיִם וְגוֹ'. מִשּׁוּם שֶׁתִּפְאֶרֶת הִיא דַּרְגַּת מֹשֶׁה, הַגּוּף, וְחֶסֶד זְרוֹעוֹ, וּמֹשֶׁה נִקְשַׁר בְּע\"ב שֶׁהוּא חֶסֶד, דַּרְגָּתוֹ שֶׁל אַבְרָהָם. שֶׁכָּךְ עוֹלֶה בְּחֶשְׁבּוֹן ח\"י - וו\"ו מִן וַיִּסַּע וַיָּבֹא וַיֵּט, שְׁלֹשֶׁת עַנְפֵי הָאָבוֹת. ש, שֶׁנִּקְשְׁרָה בַּש' שֶׁל מֹשֶׁה, שֶׁנֶּאֱמַר בָּהֶם (יחזקאל א) וּפְנֵי אַרְיֵה אֶל הַיָּמִין לְאַרְבַּעְתָּם וּפְנֵי שׁוֹר מֵהַשְּׂמֹאל וְגוֹ', וּפְנֵי נֶשֶׁר לְאַרְבַּעְתָּן. מ\"ה מִן מֹשֶׁה, וּדְמוּת פְּנֵיהֶם פְּנֵי אָדָם.</p>\n<p>בִּזְרוֹעַ שְׂמֹאל נֶאֱמַר שְׂמֹאל דּוֹחָה, וְיָמִין מְקָרֶבֶת. שֶׁאַף עַל גַּב שֶׁהִקְדִּים בְּתִשְׁרֵי, שֶׁבֵּאֲרוּהָ בּוֹ בַּעֲלֵי הַמִּשְׁנָה, בְּתִשְׁרֵי עֲתִידִים לְהִגָּאֵל - תִּהְיֶה דּוֹחָה, כְּדֵי שֶׁלֹּא יָמוּת מָשִׁיחַ בֶּן אֶפְרַיִם. דּוֹחֶה מִתִּשְׁרֵי שֶׁהִיא שְׂמֹאל, עַד שֶׁיִּקְרַב יָמִין, פֶּסַח זְרוֹעַ יָמִין. לְקַיֵּם בָּהּ (מיכה ז) כִּימֵי צֵאתְךְ מֵאֶרֶץ מִצְרָיִם אַרְאֶנּוּ נִפְלָאוֹת, וְזֶהוּ בְּנִיסָן נִגְאֲלוּ וּבְנִיסָן עֲתִידִין לְהִגָּאֵל, לְקַיֵּם בָּהֶם (ישעיה נד) וּבְחֶסֶד עוֹלָם רִחַמְתִּיךְ אָמַר גֹּאֲלֵךְ ה'.</p>\n<p>וְאַחַר כָּךְ כֻּלָּם נוֹטְלִים מִגְּבוּרָה, שֶׁמִּמֶּנָּה מָשִׁיחַ בֶּן אֶפְרַיִם, לִטֹּל נְקָמָה מִשּׂוֹנְאָיו. שֶׁכָּךְ צָרִיךְ לְנַקּוֹת אֶת הַתְּבוּאָה, שֶׁהֵם יִשְׂרָאֵל, בְּיָמִין, וְאַחַר כָּךְ לִשְׂרֹף אֶת הַקַּשׁ בִּשְׂמֹאל. זֶהוּ שֶׁכָּתוּב (עובדיה א) וְהָיָה בֵית יַעֲקֹב אֵשׁ וּבֵית יוֹסֵף לֶהָבָה וּבֵית עֵשָׂו לְקַשׁ וְדָלְקוּ בָהֶם וַאֲכָלוּם. וְכִנּוּס הַתְּבוּאָה זֶהוּ הָעַמּוּד הָאֶמְצָעִי, בּוֹ (בראשית כה) וַיֵּאָסֶף (אל עמיו). לְאֵיזֶה מָקוֹם? לַבַּיִת, זוֹ הַשְּׁכִינָה.</p>\n<p>אֲבָל בְּדַרְגַּת מָשִׁיחַ בֶּן יוֹסֵף הוּא רוֹמֵז, (במדברכה) עַתָּה יְלַחֲכוּ הַקָּהָל אֶת כָּל סְבִיבתֵינוּ כִּלְחֹךְ הַשּׁוֹר אֵת יֶרֶק הַשָּׂדֶה. שֶׁעֲלֵיהֶם נֶאֱמַר (תהלים צא) בִּפְרֹחַ רְשָׁעִים כְּמוֹ עֵשֶׂב וְגוֹ'. מִפֶּסַח וְעַד תִּשְׁרֵי תִּהְיֶה הַגְּאֻלָּה, שֶׁהוּא עַד. וּמִשָּׁם וְאֵילָךְ תִּהְיֶה הַשְׁמָדָתָם, לְהִשָּׁמְדָם (גאלה) עֲדֵי עַד. (ולאעדבכלל, אלאעדשמגיעלעד. משם ואילך להשמדם עדי עד) כְּשֶׁהִגִּיעוּ לְתִשְׁרֵי, שֶׁהוּא שׁוֹר, בּוֹ כִּלְחֹךְ הַשּׁוֹר.</p>\n<p>וּסְמִיכָתָם (של ישראל והנטיה שלהם בימין) שֶׁל יִשְׂרָאֵל בְּיָמִין, שֶׁהוּא אַרְיֵה. אֲבָל הַקִּימָה שֶׁלָּהֶם בְּגוּף הָאִילָן. וְזֶהוּ כָּל הַכּוֹרֵעַ כּוֹרֵעַ בְּבָרוּךְ, צַדִּיק. שֶׁנֶּאֱמַר בּוֹ בְּיוֹסֵף הַצַּדִּיק, (בראשית לז) וְהִנֵּה תְסֻבֶּינָה אֲלֻמֹּתֵיכֶם וַתִּשְׁתַּחֲוֶיןָ לַאֲלֻמָּתִי. וְזֶהוּ (רות ג) חַי ה' שִׁכְבִי עַד הַבֹּקֶר. וְכָל הַזּוֹקֵף זוֹקֵף בַּשֵּׁם - דַּרְגַּת מֹשֶׁה רַבֵּנוּ לְמַעְלָה. (ובמשה) וּמֹשֶׁה לְמַטָּה, בּוֹ יָקוּמוּ כָּל יִשְׂרָאֵל כְּמוֹ אֵיבָרִים שֶׁל הַגּוּף, שֶׁבּוֹ כֻּלָּם זְקוּפִים בַּעֲמִידָה. וּבָזֶה הוּא כָּל הַזּוֹקֵף זוֹקֵף בַּשֵּׁם, מִשּׁוּם שֶׁעָלָיו נֶאֱמַר (שמות לג) וָאֵדָעֲךְ בְּשֵׁם.</p>\n<p>יִהְיוּ מָשִׁיחַ בֶּן דָּוִד, שֶׁהוּא אַרְיֵה, מִימִינוֹ, וּמָשִׁיחַ בֶּן יוֹסֵף, שֶׁהוּא שׁוֹר, מִשְּׂמֹאל. מִיָּמִין אַבְרָהָם, מִשְּׂמֹאל יִצְחָק, וְהוּא הַנֶּשֶׁר בָּאֶמְצַע. הַשַּׁלְשֶׁלֶת שֶׁלָּהֶם מִצַּד שֶׁל יַעֲקֹב. ש' שֶׁל מֹשֶׁה, קְדֻשָּׁה לְךְ יְשַׁלֵּשׁוּ. מִצַּד שֶׁל אַרְיֵה שְׁלֹשֶׁת פְּנֵי הָאָבוֹת נִקְרְאוּ אֲרָיוֹת. בֹּקֶר. מִצַּד שֶׁל שְׂמֹאל נִקְרְאוּ פָרִים מְנַגְּחִים. וּמִצַּד הָאֶמְצַע נִקְרְאוּ נְשָׁרִים, וַעֲלֵיהֶם נֶאֱמַר (שמות יט) וָאֶשָּׂא אֶתְכֶם עַל כַּנְפֵי נְשָׁרִים וָאָבִא אֶתְכֶם אֵלָי. הֲרֵי הֵם ט'. עֲשִׂירִי וּרְבִיעִי אָדָם (מה שמו) שֶׁל מֹשֶׁה שֶׁרוֹכֵב עַל שָׁלֹשׁ חַיּוֹת.</p>\n<p>וְנֶאֱמַר בְּיִשְׂרָאֵל, (בראשית א) וְיִרְדּוּ בִדְגַת הַיָּם - הַמְמֻנִּים עַל הַיָּם בַּצַּד שֶׁל הַנָּחָשׁ, שֶׁהָיָה שָׂרָהּ שֶׁל מִצְרַיִם, שֶׁהִתְפַּשֵּׁט בַּגָּלוּת הָאַחֲרוֹנָה מִיָּם עַד יָם. וּבְעוֹף הַשָּׁמַיִם - עִרְבּוּבְיָה רָעָה. עֲמָלֵקִים, נְפִילִים, תַּעֲרֹבֶת שֶׁל כָּל הָאֻמּוֹת בְּכָל צַד בַּגָּלוּת הָאַחֲרוֹנָה, בֵּין בְּיִשְׂרָאֵל, בֵּין בְּיִשְׁמָעֵאל, בֵּין בְּעֵשָׂו. וּבַבְּהֵמָה - אֵלּוּ בְּנֵי עֵשָׂו שֶׁשִּׁלְטוֹנָם בְּכָל הָאָרֶץ.</p>\n<p>וְיִתְקַיִּםִ בַּמָּשִׁיחַ, (תהלים עב) וְיֵרְדְּ מִיָּם עַל יָם וּמִנָּהָר עַד אַפְסֵי אָרֶץ. וְכָךְ בִּשְׁנֵי מְשִׁיחִים, וְכָךְ בְּיִשְׂרָאֵל, וְהַכֹּל בִּזְכוּת מָ\"ה (שמו) שֶׁל מֹשֶׁה. וְיָבִיאוּ נֵס שֶׁל מָשִׁיחַ בֶּן דָּוִד מִיהוּדָה - אַרְיֵה רָשׁוּם עָלָיו, וְנֵס שֶׁל מָשִׁיחַ בֶּן יוֹסֵף - שׁוֹר רָשׁוּם עָלָיו. וְנֵס שֶׁל שִׁילֹה - אַרְיֵה לְיָמִין, שׁוֹר לִשְׂמֹאל, וְנֶשֶׁר בָּאֶמְצַע, וְאָדָם עַל כֻּלָּם. וְאַרְבַּע פָּנִים לְכָל אֶחָד, אַרְבָּעָה שְׁבָטִים שֶׁל שָׁלֹשׁ חַיּוֹת - שְׁנֵים עָשָׂר. וּלְאָדָם שֶׁהוּא מַה שְּׁמוֹ, בְּנֵי מֹשֶׁה, שֶׁבְּאוֹתוֹ זְמַן יִתְקַיֵּם בְּמֹשֶׁה (במדבר יד) וְאֶעֱשֶׂה אוֹתְךְ לְגוֹי גָּדוֹל וְעָצוּם מִמֶּנּוּ. בְּאוֹתוֹ זְמַן, (קהלת ג) מַ\"ה שֶּׁ\"הָיָה ה\"וּא שֶׁיִּהְיֶה, וַאֲשֶׁר לִהְיוֹת כְּבָר הָיָה.</p>\n<p>וְהָאֱלֹהִים יְבַקֵּשׁ אֶת נִרְדָּף - יִשְׂרָאֵל שֶׁנֶּאֱמַר בָּהֶם (יחזקאל לד) וְאַתֵּן צֹאנִי צֹאן מַרְעִיתִי אָדָם אַתֶּם, הָיוּ נִרְדָּפִים לִפְנֵי הָעֵרֶב רַב, זְאֵבִים רָעִים, הֲרֵי בִּנְיָמִין זְאֵב יִטְרַף אֲלֵיהֶם, שֶׁטּוֹרֵף אוֹתָם, וְיִתְקַיֵּם בְּאוֹתוֹ זְמַן - בַּבֹּקֶר יֹאכַל עַד, שֶׁהַיְנוּ עַד כִּי יָבא שִׁילֹה, וְזֶה בּקֶר שֶׁל אַבְרָהָם. (בראשית מט) וְלָעֶרֶב יְחַלֵּק שָׁלָל - זֶה עֶרֶב שֶׁל יִצְחָק, שֶׁשָּׁם שְׁנֵי מְשִׁיחִים. בְּאֶחָד יֹאכַל (הממון) הַמְמֻנֶּה שֶׁל אֻמּוֹת הָעוֹלָם, וּבְאֶחָד יְחַלֵּק לָהֶם לְיִשְׂרָאֵל.</p>\n<p>יִשְׂרָאֵל, שֶׁהֵם אַיֶּלֶת, נִרְדָּפִים לִפְנֵי הָרְשָׁעִים אֲרָיוֹת, וְיִתְעוֹרֵר נַפְתָּלִי, שֶׁהוּא אַיָּלָה שְׁלֻחָה הַנֹּתֵן אִמְרֵי שָׁפֶר. יִתְעוֹרֵר בַּיָּמִין, שֶׁהוּא אַרְיֵה, מָשִׁיחַ בֶּן דָּוִד, שֶׁנֶּאֱמַר בּוֹ גּוּר אַרְיֵה יְהוּדָה מִטֶּרֶף בְּנִי עָלִיתָ. וְיֶחֱזַק (ויחזר) עַל אֻמּוֹת הָעוֹלָם, כָּרַע שָׁכַב עֲלֵיהֶם לִטְרֹף אוֹתָם, מִי יְקִימֶנּוּ. בְּאוֹתוֹ זְמַן נִרְאֶה מִי הוּא אֱלוֹהַּ אַחֵר שֶׁיָּקִים אוֹתוֹ מִלִּטְרֹף עֲלֵיהֶם אוֹ אֻמָּה וְלָשׁוֹן.</p>\n<p>וְיִשְׂרָאֵל שֶׁהָיוּ כַּיּוֹנָה, נִרְדָּפִים לִפְנֵי נֶשֶׁר מִצַּד שֶׁל הָעוֹפוֹת שֶׁל אֻמּוֹת הָעוֹלָם. בְּאוֹתוֹ זְמַן יִתְעוֹרֵר נֶשֶׁר וְיִפְרֹשׂ כְּנָפָיו עַל עִרְבּוּבֵי הָאֻמּוֹת, וְעֵשָׂו וְיִשְׁמָעֵאל, שֶׁהֵם עֲמָלֵקִים, וְעִרְבּוּבְיָה רָעָה שֶׁל יִשְׂרָאֵל, וְטוֹרֵף אוֹתָם שֶׁלֹּא יִשָּׁאֵר אֶחָד מֵהֶם, לְקַיֵּם מַה שֶּׁנֶּאֱמַר בְּיִשְׂרָאֵל, (דברים לב) ה' בָּדָד יַנְחֶנּוּ וְאֵין עִמּוֹ אֵל נֵכָר.</p>\n<p>מִשָּׁם וְאֵילָךְ אֵין מְקַבְּלִים גֵּרִים, כְּמוֹ שֶׁבֵּאֲרוּהָ בַּעֲלֵי הַמִּשְׁנָה, אֵין מְקַבְּלִים גֵּרִים לִימוֹת הַמָּשִׁיחַ. וְאֻמּוֹת עוֹבְדֵי כוֹכָבִים וּמַזָּלוֹת שֶׁל הָעוֹלָם שֶׁיִּשָּׁאֲרוּ, יְעוֹרֵר הַקָּדוֹשׁ בָּרוּךְ הוּא חַיָּה שֶׁל אָדָם לִשְׁלֹט עֲלֵיהֶם, לְקַיֵּם בָּהֶם (ישעיה ס) כִּי הַגּוֹי וְהַמַּמְלָכָה אֲשֶׁר לֹא יַעַבְדוּךְ יאבֵדוּ. לְקַיֵּם בְּיִשְׂרָאֵל, (בראשית א) וְיִרְדּוּ בִדְגַת הַיָּם וְגוֹ'. (שם ט) וּמוֹרַאֲכֶם וְחִתְּכֶם וְגוֹ'.</p>\n<p>וּמִצַד שֶׁל תְּבוּאוֹת חֲמִשָּׁה מִינֵי לֶחֶם, שְׁבוּרִים מִכֻּלָּם, וְהֵם: חִטָּה, וּשְׂעוֹרָה, וְכֻסֶּמֶת, וְשִׁבֹּלֶת שׁוּעָל, וְשִׁיפוֹן. הִמְשִׁיל אוֹתָם לְיִשְׂרָאֵל, זֶהוּ שֶׁכָּתוּב (ירמיהכ) קֹדֶשׁ יִשְׂרָאֵל לַה' רֵאשִׁית תְּבוּאָתֹה, בְּה'. כְּשֶׁיֵּצְאוּ מֵהַגָּלוּת, כָּךְ יִהְיוּ שְׁבוּרִים, עַד שֶׁיִּתְבָּרֵר אֹכֶל מִתּוֹךְ פְּסֹלֶת, שֶׁהַיְנוּ קַשׁ, עֵרֶב רַב, עַד שֶׁיִּתְבָּרְרוּ וְיִוָּדְעוּ יִשְׂרָאֵל בֵּינֵיהֶם, כְּמוֹ בַּר שֶׁנִּבְרָר מִתּוֹךְ מוֹץ וָתֶבֶן.</p>\n<p>וְעַד שֶׁיִּתְבָּרְרוּ מֵהֶם, י', שֶׁהִיא מַעֲשֵׂר, לֹא שׁוֹרָה עַל ה', שֶׁהוּא לֶחֶם שֶׁל חֲמִשָּׁה מִינִים, לְקַיֵּם אֶת הַשְּׁבוּעָה (שמות יז) כִּי יָד עַל כֵּס יָ\"הּ. וּמִשּׁוּם כָּךְ מוֹץ וָתֶבֶן אֵינוֹ מְחֻיָּב בְּמַעֲשֵׂר עַד שֶׁיִּתְבָּרֵר. אַחַר שֶׁיִּתְבָּרֵר, מִתְכַּנְּסִים לְאוֹתוֹ מָקוֹם שֶׁנִּקְרָא יְרוּשָׁלַיִם, כְּמוֹ שֶׁאֶת הַחִטָּה, אַחַר שֶׁנִּבְרָר קַשׁ וָתֶבֶן, מַכְנִיסִים אוֹתָהּ לְאוֹצָר. כָּךְ יִתְכַּנְּסוּ יִשְׂרָאֵל, שֶׁהֵם בַּר, לִירוּשָׁלַיִם, שֶׁהִיא בְּנוּיָה עַל הַר ה', שֶׁנֶּאֱמַר בָּהּ (תהלים כד) מִי יַעֲלֶה בְהַר ה' וּמִי יָקוּם בִּמְקוֹם קָדְשׁוֹ נְקִי כַפַּיִם וּבַר לֵבָב. נָקִי כְּמוֹ בַּר, שֶׁהִיא תְבוּאָה כְּשֶׁנִּבְרֶרֶת מִתּוֹךְ פְּסֹלֶת. בְּאוֹתוֹ זְמַן - נַשְּׁקוּ בַר, כְּבַתְּחִלָּה, שֶׁנֶּאֱמַר בּוֹ (שיר א) יִשָּׁקֵנִי מִנְּשִׁיקוֹת פִּיהוּ. בַּר תַּרְגּוּם בֵּן. בְּאוֹתוֹ זְמַן שֶׁיִּהְיוּ נְקִיִּים כְּמוֹ בַּר מִתּוֹךְ קַשׁ וָתֶבֶן, שׁוֹרֶה שְׁמוֹ עֲלֵיהֶם, וְקוֹרֵא לָהֶם בְּנִי בְכֹרִי יִשְׂרָאֵל.</p>\n<p>וְכָךְ מִכָּל הָאִילָנוֹת אֵין שָׁבוּר כַּגֶּפֶן. בִּנְטִיעָתוֹ שָׁבוּר, בַּעֲנָבָיו שָׁבוּר, שֶׁהֵם כְּתוּשִׁים בֵּין הָרַגְלַיִם. וְכָךְ זַיִת, הַזֵּיתִים שֶׁלָּהּ כְּתוּשִׁים. בַּגָּלוּת נִמְשְׁלוּ יִשְׂרָאֵל לָהֶם, זֶהוּ שֶׁכָּתוּב (תהלים פ) גֶּפֶן מִמִּצְרַיִם תַּסִּיעַ. וְכֵן בַּגָּלוּת הָרְבִיעִית, (ישעיה ה) כִּי כֶרֶם ה' צְבָאוֹת בֵּית יִשְׂרָאֵל. וּכְמוֹ זֶה יִשְׂרָאֵל מְשׁוּלִים לְזַיִת, (ירמיה יא) זַיִת רַעֲנָן יְפֵה פְרִי תֹאַר. וּמִשּׁוּם כָּךְ (תהלים קכח) אֶשְׁתְּךְ כְּגֶפֶן פֹּרִיָּה בְּיַרְכְּתֵי בֵיתֶךְ בָּנֶיךְ כִּשְׁתִלֵי זֵיתִים. סָמוּךְ זֶה לָזֶה, מִשּׁוּם שֶׁהֵם שְׁבוּרִים בַּגָּלוּת.</p>\n<p>וְאַחַר שֶׁיִּהְיוּ נְקִיִּים מִתּוֹךְ פְּסֹלֶת, יִתְקַדְּשׁוּ לְבֵית הַמִּקְדָּשׁ בְּיַיִן לְנַסֵּךְ עַל גַּבֵּי הַמִּזְבֵּחַ, וְזֵיתִים לְהַדְלִיק מָאוֹר נֵרוֹת לַמְּנוֹרָה. וּמִי זוֹכֶה לָזֶה? יַיִן שֶׁלֹּא הִתְנַסֵּךְ לְכּוֹכָבִים וּמַזָּלוֹת. שֶׁעֵרֶב רַב הֵם יַיִן שֶׁהִתְנַסֵּךְ לְכוֹכָבִים וּמַזָּלוֹת, וּמֵהֶם מְשֻׁמָּדִים, מִינִים, אֶפִּיקוֹרְסִים, מְשֻׁמָּדִים לָעֲבֵרוֹת שֶׁבְּכָל הַתּוֹרָה כֻּלָּהּ.</p>\n<p>וְיִשְׂרָאֵל שֶׁנֶּאֱמַר בָּהֶם, וַיְּתְעָרְבוּ בַגּוֹיִם וַיִּלְמְדוּ מַעֲשֵׂיהֶם. עַד שֶׁיִּהְיוּ דְרוּכִים בֵּין רַגְלֵיהֶם, בַּגָּלוּת הֵם לֹא נִבְרְרוּ מֵהֶם. וּבִשְׁבִילָם אָמַר דָּוִד, עָלָיו הַשָּׁלוֹם, (שם מט) לָמָּה אִירָא בִּימֵי רָע עֲוֹן עֲקֵבַי יְסֻבֵּנִי. וַעֲלֵיהֶם אָמַר שְׁלֹמֹה (שיר השירים א) צְאִי לָךְ בְּעִקְבֵ\"י הַצּאן. בְּיַעֲקֹ\"ב. שֶׁעָלָיו נֶאֱמַר אֶל הַנָּחָשׁ הַקַּדְמוֹנִי שֶׁפִּתָּה אֶת חַוָּה, (בראשית ג) הוּא יְשׁוּפְךְ רֹאשׁ וְאַתָּה תְּשׁוּפֶנּוּ עָקֵב. אַחַר שֶׁיָּצְאוּ מִן הַגָּלוּת נִמְשָׁלִים לְתַפּוּחִים וּלְכָל הָרֵיחוֹת הַטּוֹבִים, כְּמוֹ שֶׁבִּיצִיאַת מִצְרַיִם, שֶׁכָּתוּב בָּהּ (שיר השירים ח) תַּחַת הַתַּפּוּחַ עוֹרַרְתִּיךְ.</p>"],[9522011680,"<p>הַמִּצְוָה שֶׁאַחַר זוֹ - לְהָבִיא בִּכּוּרִים, וְאַחֲרֶיהָ - לְהִתְוַדּוֹת עַל הַבִּכּוּרִים, וְאַחֲרֶיהָ - לְהִתְוַדּוֹת עַל הַמַּעֲשֵׂר. וּבַעֲלֵי הַמִּשְׁנָה מַקְשִׁים עַל הַמַּעֲשֵׂר, שֶׁאִם יִהְיֶה קֹדֶם לְקִיטָתוֹ, אוֹ אַחַר לְקִיטָתוֹ עִשּׂוּרוֹ, כְּמוֹ אֶתְרוֹג, שֶׁנֶּאֱמַר בּוֹ בְּאִילָן, הָלַךְ אַחַר חֲנָטָה. יֵשׁ מִי שֶׁאוֹמֵר אַחַר בִּשּׁוּל הַפֵּרוֹת. וְאֶתְרוֹג מִקְצָתוֹ דּוֹמֶה לְאִילָן וּמִקְצָתוֹ לִתְבוּאָה, שֶׁהֵם זְרָעִים, שֶׁנֶּאֱמַר בָּהֶם שֶׁלְּאַחַר לְקִיטָתוֹ עִשּׂוּרוֹ. שֶׁאִילָן אֵינוֹ אֶלָּא עַד אַחַר גְּמַר בִּשּׁוּלוֹ.</p>\n<p>וּמִשּׁוּם כָּךְ תִּקְּנוּ הַמּוֹצִיא מִמָּקוֹם שֶׁבִּשּׁוּלוֹ יָפֶה, לְהוֹצִיא פַּת שָׂרוּף, אֶלָּא מִמָּקוֹם שֶׁהוּא מֻטְעָם. וְכָךְ תְּבוּאָה, אַחַר לְקִיטָתוֹ הוּא כְּבִשּׁוּל פֵּרוֹת.</p>\n<p>וְיִשְׂרָאֵל מְשׁוּלִים לָאִילָן וְלַתְּבוּאָה, שֶׁנֶּאֱמַר בָּהֶם (שמות כג) רֵאשִׁית בִּכּוּרֵי אַדְמָתְךְ תָּבִיא בֵּית ה' אֱלֹהֶיךְ. וְכָךְ (דברים יח) רֵאשִׁית גֵּז צֹאנְךְ תִּתֶּן לוֹ, שֶׁהֵם יִשְׂרָאֵל, שֶׁנֶּאֱמַר בָּהֶם (יחזקאל לד) וְאַתֵּן צֹאנִי. וְכָךְ יִשְׂרָאֵל, קֹדֶשׁ (קדש ישראל) יִשְׂרָאֵל לַה' רֵאשִׁית תְּבוּאָתֹה, לְאַחַר לְקִיטָתוֹ מִן הַגָּלוּת - עִשּׂוּר. וְנִקְרְאוּ קֹדֶשׁ לַה'.</p>\n<p>וְיִשְׂרָאֵל נִקְרְאוּ אִילָן גָּדוֹל וְתַקִּיף וּבוֹ מָזוֹן לַכֹּל. בּוֹ תּוֹרָה, שֶׁהִיא מָזוֹן לְמַעְלָה. בּוֹ תְּפִלָּה, שֶׁהִיא מָזוֹן לְמַטָּה. וַאֲפִלּוּ לַמַּלְאָכִים אֵין מָזוֹן אֶלָּא בְּיִשְׂרָאֵל. שֶׁאִם יִשְׂרָאֵל לֹא יִתְעַסְּקוּ בַּתּוֹרָה, לֹא הָיָה יוֹרֵד לָהֶם מָזוֹן מִצַּד שֶׁל הַתּוֹרָה שֶׁנִּמְשְׁלָה לְעֵץ. זֶהוּ שֶׁכָּתוּב (משלי ג) עֵץ חַיִּים הִיא לַמַּחֲזִיקִים בָּהּ. וְלַפְּרִי, שֶׁהוּא מִצְוָה.</p>\n<p>וְכָךָ הַתּוֹרָה נִמְשְׁלָה לְמַיִם, וְאֵלֶּה לְאֵשׁ, וְלֹא הָיוּ יוֹרְדִים מַיִם מִלְמַעְלָה, וְחַמָּה שֶׁהִיא אֵשׁ, לֹא הָיְתָה יוֹרֶדֶת (מלמעלה) לְבַשֵּׁל אֶת פֵּרוֹת הָאִילָן, אֶלָּא בִּשְׁבִיל יִשְׂרָאֵל, וּמִשּׁוּם זֶה נֶאֱמַר בְּיִשְׂרָאֵל, (שיר ב) הַתְּאֵנָה חָנְטָה פַגֶּיהָ. אֵלּוּ בַּעֲלֵי מִצְווֹת. וְהַגְּפָנִים סְמָדַר נָתְנוּ רֵיחַ, כְּשֶׁפּוֹתְחִים בִּתְשׁוּבָה, וּמִיָּד נֶאֱמַר בְּיִשְׂרָאֵל, קוּמִי לָךְ רַעְיָתִי יָפָתִי וּלְכִי לָךְ, מִן הַגָּלוּת.</p>\n<p>וּמִשּׁוּם זֶה בָּאִילָן, שֶׁהוּא עֵץ הַחַיִּים, בַּתּוֹרָה, בְּאֵלּוּ שֶׁמִּשְׁתַּדְּלִים בָּהּ הוֹלְכִים אַחַר חֲנָטָה וּמְעַשְּׂרִים אוֹתוֹ, שֶׁשּׁוֹרֶה עֲלֵיהֶם יוֹ\"ד, שֶׁהִיא חָכְמָ\"ה, א' מִי', וּבָהּ מִתְכַּנְּסִים ה\"ה, שֶׁהֵם פֵּרוֹת הָאִילָן. וּמַהוּ הָאִילָן? ו'. אֲבָל שְׁאָר הָעָם, אַחַר לְקִיטָתוֹ מִן הַגָּלוּת - עִשּׂוּרוֹ, אוֹתָם צַדִּיקִים שֶׁנֶּאֱמַר בָּהֶם (ויקרא כג) וּלְקַחְתֶּם לָכֶם בַּיּוֹם הָרִאשׁוֹן פְּרִי עֵץ הָדָר. הָדָר בְּמַעֲשֵׂיהֶם, שֶׁאֲחוּזִים בְּבַעֲלֵי תוֹרָה וּמִצְווֹת, וְאַחַר לְקִיטָה הוֹלְכִים לְגַבֵּיהֶם (ולגבי זרעים של תבואה. ואחר חנטה הולכים אליהם) כְּאִילָן.</p>\n<p>וּמִשּׁוּם זֶה פֵּרְשׁוּהָ בְּמַסֶּכֶת קִדּוּשִׁין, בָּא לְהַשְׁמִיעֵנוּ שֶׁאֶתְרוֹג כְּיָרָק. מַה יָּרָק דַּרְכּוֹ לִגָּדֵל עַל כָּל מַיִם וּבִשְׁעַת לְקִיטָתוֹ עִשּׂוּרוֹ, אַף אֶתְרוֹג גַּם דַּרְכּוֹ לִגָּדֵל וְכוּ' וּמִצַּד שֶׁל הַחָכְמָה, אֵין מַיִם אֶלָּא תּוֹרָה. וּבְמָקוֹם אַחֵר לְמַעְלָה, וְזֶה שֶׁשָּׁנִינוּ, אֶתְרוֹג שָׁוֶה לָאִילָן בִּשְׁלֹשָׁה דְרָכִים., הֲרֵי אֶתְרוֹג אוֹחֵז שְׁנֵי צְדָדִים, וְאֶתְרוֹג הוּא דְּיוֹקַן הַלֵּב שֶׁאָחוּז לְמַעְלָה וְאָחוּז לְמַטָּה. אָחוּז לְמַעְלָה - הַלֵּב רוֹאֶה. אָחוּז לְמַטָּה - בְּדַעַת, כְּמוֹ שֶׁבֵּאֲרוּהָ, הַלֵּב יוֹדֵעַ. דַּעַת הִיא אִילָן, הַתּוֹרָה הַפְּרִי שֶׁלּוֹ. הָעֵינַיִם שֶׁהֵן הַמִּצְווֹת שֶׁבָּהֶן - הַלֵּב רוֹאֶה. (ע\"כ רעיא מהימנא)</p>"],[9522011681,"<p>וְאַנְשֵׁי קֹדֶשׁ תִּהְיוּן לִי וְגוֹ'. רַבִּי יְהוּדָה פָּתַח, (איוב כח) וְהַחָכְמָה מֵאַיִן תִּמָּצֵא וְאֵי זֶה מְקוֹם בִּינָה. אַשְׁרֵיהֶם יִשְׂרָאֵל שֶׁהַקָּדוֹשׁ בָּרוּךְ הוּא רוֹצֶה לְכַבְּדָם יוֹתֵר (בכבוד שלהם) מִכָּל שְׁאָר בְּנֵי הָעוֹלָם. בַּתְּחִלָּה אָמַר לָהֶם, (שמות יט) וְאַתֶּם תִּהְיוּ לִי מַמְלֶכֶת כֹּהֲנִים. לֹא זָזָה הָאַהֲבָה הָרַבָּה מֵהֶם עַד שֶׁקָּרָא לָהֶם וְגוֹי קָדוֹשׁ, שֶׁהוּא יוֹתֵר. לֹא זָזָה הָאַהֲבָה מֵהֶם עַד שֶׁקָּרָא לָהֶם (דברים יד) כִּי עַם קָדוֹשׁ אַתָּה. לֹא זָזָה הָאַהֲבָה מֵהֶם עַד שֶׁקָּרָא לָהֶם (שמות כב) וְאַנְשֵׁי קֹדֶשׁ תִּהְיוּן לִי, שֶׁהוּא יוֹתֵר מִן הַכֹּל.</p>\n<p>כָּתוּב וְהַחָכְמָה מֵאַיִן תִּמָּצֵא. הַתּוֹרָה יָצְאָה מֵחָכְמָה, מִמָּקוֹם שֶׁנִּקְרָא קֹדֶשׁ, וְהַחָכְמָה יָצְאָה מִמָּקוֹם שֶׁנִּקְרָא קֹדֶשׁ הַקְּדָשִׁים. רַבִּי יִצְחָק אָמַר, וְכֵן יוֹבֵל נִקְרָא קֹדֶשׁ, שֶׁכָּתוּב (ויקרא כה) יוֹבֵל הִיא קֹדֶשׁ תִּהְיֶה לָכֶם. וְיִשְׂרָאֵל כְּלוּלִים מֵהֶם. זֶהוּ שֶׁכָּתוּב וְאַנְשֵׁי קֹדֶשׁ תִּהְיוּן לִי.</p>\n<p>בַּתְּחִלָּה קָדוֹשׁ, וְעַכְשָׁו קֹדֶשׁ. מַה בֵּין זֶה לָזֶה? אָמַר רַבִּי יוֹסֵי, זֶה לְמַעְלָה וְזֶה לְמַטָּה. וְזֶה לֹא כָּךְ, שֶׁכָּתוּב (ישעיה ד) וְהָיָה הַנִּשְׁאָר בְּצִיּוֹן וְהַנּוֹתָר בִּירוּשָׁלם קָדוֹשׁ יֵאָמֶר לוֹ. בְּמָקוֹם זֶה נִקְרָא קָדוֹשׁ, וּלְמַעְלָה לְמַעְלָה קֹדֶשׁ.</p>\n<p>רַבִּי אַבָּא הָיָה הוֹלֵךְ בַּדֶּרֶךְ, וְהָיוּ הוֹלְכִים עִמּוֹ רַבִּי יוֹסֵי וְרַבִּי חִיָּיא. אָמַר רַבִּי חִיָּיא, וְאַנְשֵׁי קֹדֶשׁ תִּהְיוּן לִי, מִנַּיִן לָנוּ? אָמַר לוֹ, הֲרֵי רַבִּי יוֹסֵי וְכָל הַחֲבֵרִים יָפֶה אָמְרוּ, וְכָךְ זֶה. מִנַּיִן לָנוּ? שֶׁכָּתוּב (ירמיהב) קֹדֶשׁ יִשְׂרָאֵל לַה' רֵאשִׁית תְּבוּאָתֹה. רֵאשִׁית, וַדַּאי חָכְמָה נִקְרֵאת רֵאשִׁית, שֶׁכָּתוּב (תהליםקיא) רֵאשִׁית חָכְמָה יִרְאַת ה'.</p>\n<p>וּמִשּׁוּם שֶׁיִּשְׂרָאֵל נִקְרְאוּ קֹדֶשׁ (ישראל) בִּשְׁלֵמוּת הַכֹּל, כָּתוּב (שמות כב) וּבָשָׂר בַּשָּׂדֶה טְרֵפָה לֹא תֹאכֵלוּ, שֶׁהֲרֵי יִשְׂרָאֵל, שֶׁהֵם שְׁלֵמִים עַל הַכֹּל, לֹא יוֹנְקִים מִצַּד הַדִּין הַקָּשֶׁה. לַכֶּלֶב תַּשְׁלִכוּן אֹתוֹ, לַכֶּלֶב וַדַּאי, שֶׁהוּא הַדִּין הֶחָצוּף הֶחָזָק עַל הַכֹּל. כֵּיוָן שֶׁהַדִּין הַקָּשֶׁה שָׁרוּי עָלָיו וְהִטִּיל בּוֹ זֻהֲמָה, אָסוּר לָהֶם לְאוֹתָם שֶׁנִּקְרָאִים קֹדֶשׁ. אֶלָּא לַכֶּלֶב תַּשְׁלִכוּן אֹתוֹ וַדַּאי, שֶׁהוּא הַדִּין הֶחָצוּף, דִּין הַקָּשֶׁה יוֹתֵר מִן הַכֹּל, שֶׁכָּתוּב (ישעיה כו) וְהַכְּלָבִים עַזֵּי נֶפֶשׁ.</p>\n<p>בֹּא וּרְאֵה, כְּשֶׁנִּזְכְּרָה נְבֵלָה בַּתּוֹרָה, כָּתוּב בְּיִשְׂרָאל קָדוֹשׁ, וְלֹא קֹדֶשׁ. כָּאן כָּתוּב וְאַנְשֵׁי קֹדֶשׁ תִּהְיוּן לִי וּבָשָׂר בַּשָּׂדֶה טְרֵפָה לֹא תֹאכֵלוּ. וְשָׁם בִּנְבֵלָה כָּתוּב (דברים יד) לֹא תֹאכְלוּ כָל נְבֵלָה לַגֵּר אֲשֶׁר בִּשְׁעָרֶיךְ תִּתְּנֶנָּה וְגוֹ', כִּי עַם קָדוֹשׁ אַתָּה. קָדוֹשׁ וְלֹא קֹדֶשׁ, שֶׁהֲרֵי נְבֵלָה מִצַּד שֶׁל יִשְׂרָאֵל נֶעֶשְׂתָה, שֶׁלֹּא פוֹסֵל אֶת זֶה אֶלָּא יִשְׂרָאֵל. וְרַבִּים הַגְּוָנִים יֵשׁ בָּהּ בִּנְבֵלָה, כְּמוֹ שֶׁבֵּאַרְנוּ.</p>\n<p>אָמַר רַבִּי שִׁמְעוֹן, כָּתוּב כָּאן וְאַנְשֵׁי קֹדֶשׁ תִּהְיוּן לִי, וְכָתוּב שָׁם, כִּי עַם קָדוֹשׁ אַתָּה לַה' אֱלֹהֶיךְ. לַה' אֱלֹהֶיךְ? לִי הָיָה צָרִיךְ לִהְיוֹת! אֶלָּא שָׁם (כאן) לְמַעְלָה לְמַעְלָה, וְכָאן (ושם) הַשְּׁכִינָה. וְכָתוּב (ישעיה ד) וְהָיָה הַנִּשְׁאָר בְּצִיּוֹן וְהַנּוֹתָר בִּירוּשָׁ לם קָדוֹשׁ יֵאָמֶר לוֹ, וְלֹא קֹדֶשׁ. בְּכָאן קָדוֹשׁ וּלְמַעְלָה קֹדֶשׁ. כָּתוּב קֹדֶשׁ יִשְׂרָאֵל לַה' רֵאשִׁית תְּבוּאָתֹה, בְּהֵ\"א, כְּמוֹ שֶׁבֵּאַרְנוּ. וְעַל כָּךְ אַנְשֵׁי קֹדֶשׁ תִּהְיוּן לִי וַדַּאי.</p>\n<p>רַבִּי יִצְחָק הָיָה יוֹשֵׁב לִפְנֵי רַבִּי שִׁמְעוֹן. אָמַר לוֹ, הֲרֵי כָּתוּב קֹדֶשׁ יִשְׂרָאֵל לַה'. בְּסוֹף הַפָּסוּק כָּתוּב כָּל אֹכְלָיו יֶאְשָׁמוּ, מַה זֶּה אוֹמֵר? אָמַר לוֹ רַבִּי שִׁמְעוֹן, יָפֶה אָמַר, כָּל אֹכְלָיו יֶאְשָׁמוּ - הַיְנוּ שֶׁכָּתוּב וְאִישׁ כִּי יֹאכַל קֹדֶשׁ בִּשְׁגָגָה וְכוּ'. וְכָתוּב וְכָל זָר לֹא יֹאכַל קֹדֶשׁ. וּמִשּׁוּם שֶׁיִּשְׂרָאֵל נִקְרְאוּ קֹדֶשׁ, כָּתוּב כָּל אֹכְלָיו יֶאְשָׁמוּ. בָּא רַבִּי יִצְחָק וְנָשַׁק יָדוֹ וְאָמַר, אִם לֹא בָאתִי לְכָאן אֶלָּא לִשְׁמֹעַ דָּבָר זֶה - מַסְפִּיק.</p>\n<p>אָמַר לוֹ, רַבִּי, הֲרֵי שָׁנִינוּ שֶׁקֹּדֶשׁ יוֹתֵר לְמַעְלָה מִקָּדוֹשׁ. אִם כָּךְ, הֲרֵי כָּתוּב (ישעיה ו) קָדוֹשׁ קָדוֹשׁ קָדוֹשׁ ה' צְבָאוֹת, וְזוֹ שְׁלֵמוּת הַכֹּל? אָמַר לוֹ, בּא וּרְאֵה, כְּשֶׁמִּתְחַבְּרִים כְּאֶחָד, כֻּלָּם נַעֲשִׂים בַּיִת אֶחָד, וְהַבַּיִת הַזֶּה נִקְרָא קֹדֶשׁ. הַכְּלָל שֶׁל הַכֹּל קָדוֹשׁ, וּמִשּׁוּם כָּךְ קֹדֶשׁ. הוּא כְּלָל שֶׁהַכֹּל נִכְלָל בּוֹ. וּכְשֶׁנִּכְלֶלֶת בְּיִשְׂרָאֵל הָאֱמוּנָה הַשְּׁלֵמָה, הֵם נִקְרָאִים קֹדֶשׁ, הַכְּלָל שֶׁל הַכֹּל, שֶׁכָּתוּב קֹדֶשׁ יִשְׂרָאֵל לַה'. וּמִשּׁוּם כָּךְ, וְאַנְשֵׁי קֹדֶשׁ תִּהְיוּן לִי.</p>\n<p>לִגְיוֹן אֶחָד שָׁאַל אֶת רַבִּי אַבָּא וְאָמַר לוֹ, לֹא כָתוּב וּבָשָׂר בַּשָּׂדֶה טְרֵפָה לֹא תֹאכֵלוּ?! אִם כָּךְ, מַהוּ שֶׁכָּתוּב (תהלים קיא) טֶרֶף נָתַן לִירֵאָיו? טֶרֶף נָתַן לַכְּלָבִים הָיָה צָרִיךְ לִהְיוֹת! לָמָּה נָתַן לִירֵאָיו? אָמַר לוֹ, רֵיקָא, הַאִם כָּתוּב טְרֵפָה נָתַן לִירֵאָיו?! טֶרֶף כָּתוּב! וְאִם תֹּאמַר, טֶרֶף כְּמוֹ טְרֵפָה, נָתַן לִירֵאָיו וַדַּאי, שֶׁדָּבָר זֶה לֹא נָתְנוּ לְהִזָּהֵר בּוֹ אֶלָּא לְאוֹתָם יִרְאֵי שְׁמוֹ וִירֵאִים מִמֶּנּוּ. מִשּׁוּם זֶה דָּבָר זֶה לֹא נָתַן לָכֶם, שֶׁהֲרֵי יָדַע שֶׁאֵינְכֶם יְרֵאִים מִמֶּנּוּ וְלֹא שׁוֹמְרִים מִצְווֹתָיו, וּמִשּׁוּם דָּבָר זֶה חֻמְרָה שֶׁל הַתּוֹרָה וְצָרִיךְ לְהִזָּהֵר בָּהּ. נָתַן לִירֵאָיו, נָתַן לִירֵאָיו וַדַּאי, וְלֹא לַאֲחֵרִים. וְכָל חֻמְרוֹת הַתּוֹרָה לֹא נְתָנָם הַקָּדוֹשׁ בָּרוּךְ הוּא אֶלָּא לְאוֹתָם יִרְאֵי חֵטְא, לְאוֹתָם יִרְאֵי מִצְווֹתָיו וְלֹא לָכֶם.</p>\n<p>שָׁנָה רַבִּי אֶלְעָזָר, כָּתוּב (קדש ישראל, וכתוב ואנשי וכו') וְאַנְשֵׁי קֹדֶשׁ תִּהְיוּן לִי. מַה זֶּה וְאַנְשֵׁי, וְאַחֲרָיו קֹדֶשׁ? אֶלָּא וְאַנְשֵׁי קֹדֶשׁ וַדַּאי. שֶׁשָּׁנִינוּ, לֹא יָצְאוּ יִשְׂרָאֵל לַחֵרוּת אֶלָּא מִצַּד הַיּוֹבֵל. אַחַר שֶׁיָּצְאוּ לַחֵרוּת, לָקַח אוֹתָם הַיּוֹבֵל הַזֶּה בִּכְנָפָיו, וְנִקְרְאוּ אֲנָשִׁים שֶׁלּוֹ, בָּנִים שֶׁלּוֹ. וְכָתוּב בּוֹ בַּיּוֹבֵל, (ויקרא כה) יוֹבֵל הִיא קֹדֶשׁ תִּהְיֶה לָכֶם, קֹדֶשׁ וַדַּאי, לָכֶם וַדַּאי. וּמִשּׁוּם כָּךְ, וְאַנְשֵׁי קֹדֶשׁ תִּהְיוּן לִי, אַנְשֵׁי קֹדֶשׁ וַדַּאי, אֲנָשִׁים שֶׁלּוֹ מַמָּשׁ.</p>\n<p>וְהַקָּדוֹשׁ בָּרוּךְ הוּא אָמַר אֶת זֶה, וְעַל זֶה זָכוּ יִשְׂרָאֵל לְהִקָּרֵא אַחִים לַקָּדוֹשׁ-בָּרוּךְ-הוּא, שֶׁכָּתוּב (תהלים קכב) לְמַעַן אַחַי וְרֵעָי וְגוֹ'. אַחַר כָּךְ נִקְרְאוּ קֹדֶשׁ מַמָּשׁ, שֶׁכָּתוּב (ירמיה ב) קֹדֶשׁ יִשְׂרָאֵל לַה' רֵאשִׁית תְּבוּאָתֹה. קֹדֶשׁ וְלֹא אַנְשֵׁי קֹדֶשׁ. מִשּׁוּם כָּךְ כָּל אֹכְלָיו יֶאְשָׁמוּ, וְכָתוּב (ויקרא כב) וְכָל זָר לֹא יֹאכַל קֹדֶשׁ. (שם) וְאִישׁ כִּי יֹאכַל קֹדֶשׁ בִּשְׁגָגָה.</p>\n<p>שָׁנִינוּ, יִשְׂרָאֵל נִקְרְאוּ קֹדֶשׁ, וּמִשּׁוּם שֶׁהֵם קֹדֶשׁ אָסוּר לְאָדָם לִקְרֹא לַחֲבֵרוֹ בְּשֵׁם גְּנַאי וְלֹא לְכַנּוֹת שֵׁם לַחֲבֵרוֹ, וְעָנְשׁוֹ גָּדוֹל, וְכָל שֶׁכֵּן בִּדְבָרִים אֲחֵרִים. שָׁנִינוּ, כָּתוּב (תהלים לד) נְצֹר לְשׁוֹנְךְ מֵרָע וְגוֹ'. מַהוּ מֵרָע? שֶׁבִּגְלַל לָשׁוֹן הָרָע מַחֲלוֹת יוֹרְדוֹת לָעוֹלָם.</p>\n<p>אָמַר רַבִּי יוֹסֵי, כָּל מִי שֶׁקּוֹרֵא לַחֲבֵרוֹ בְּשֵׁם שֶׁאֵין בּוֹ וּמְגַנֶּה אוֹתוֹ, נִתְפָּס בְּמַה שֶּׁאֵין בּוֹ. שֶׁאָמַר רַבִּי חִיָּא אָמַר רַבִּי חִזְקִיָּה, כָּל מִי שֶׁקּוֹרֵא לַחֲבֵרוֹ רָשָׁע, מוֹרִידִים אוֹתוֹ לַגֵּיהִנֹּם, וְיוֹרְדִים לוֹ לִלְחָיָיו, פְּרָט לְאוֹתָם חֲצוּפִים שֶׁל הַתּוֹרָה שֶׁמֻּתָּר לָאָדָם לִקְרֹא לָהֶם רָשָׁע.</p>\n<p>אוֹתוֹ אִישׁ שֶׁקִּלֵּל אֶת חֲבֵרוֹ, עָבַר רַבִּי יֵיסָא, אָמַר לוֹ, כְּמוֹ רָשָׁע עָשִׂיתָ. בָּא לִפְנֵי רַבִּי יְהוּדָה. אָמַר לוֹ, רָשָׁע לֹא אָמַרְתִּי לוֹ, אֶלָּא כְּרָשָׁע, שֶׁמַּרְאֵה דְבָרָיו כְּרָשָׁע, וְלֹא אָמַרְתִּי שֶׁהוּא רָשָׁע. בָּא רַבִּי יְהוּדָה וְשָׁאַל לַמַּעֲשֶׂה לִפְנֵי רַבִּי אֶלְעָזָר. אָמַר לוֹ, וַדַּאי שֶׁלֹּא הִתְחַיֵּב. מִנַּיִן לָנוּ? שֶׁכָּתוּב (איכהב) הָיָה ה' כְּאוֹיֵב, וְלֹא אוֹיֵב. שֶׁאִם לֹא כָּךְ, לֹא נִשְׁאַר מִיִּשְׂרָאֵל גְּזָעִים בָּעוֹלָם. כְּמוֹ זֶה, (שם א) הָיְתָה כְּאַלְמָנָה, וְלֹא אַלְמָנָה. כְּאַלְמָנָה שֶׁהָלַךְ בַּעְלָהּ לְעֵבֶר הַיָּם וּמְחַכָּה לוֹ.</p>\n<p>אָמַר רַבִּי חִיָּיא, וּמִכָּאן מַשְׁמָע? מִשָּׁם מַשְׁמָע, שֶׁהוּא עִקַּר הַכֹּל, שֶׁכָּתוּב (יחזקאל א) וְעַל דְּמוּת הַכִּסֵּא דְּמוּת כְּמַרְאֵה אָדָם. כְּמַרְאֵה אָדָם, וְלֹא מַרְאֵה אָדָם. אָמַר רַבִּי יִצְחָק, כָּתוּב כְּתַפּוּחַ בַּעֲצֵי הַיַּעַר וְגוֹ'. כְּתַפּוּחַ, וְלֹא תַפּוּחַ. כְּתַפּוּחַ, שֶׁנִּפְרָד בִּגְוָנָיו, וּבִגְוָנִים אָחוּז הַדָּבָר. אָמַר רַבִּי יְהוּדָה, אִלּוּ לֹא בָאתָ לְכָאן אֶלָּא לִשְׁמֹעַ הַדְּבָרִים הַלָּלוּ - דַּי.</p>\n<p>שָׁנִינוּ, כָּתוּב (זכריהיב) וְהָיָה הַנִּכְשָׁל בָּהֶם בַּיּוֹם הַהוּא כְּדָוִד. כְּדָוִד, וְלֹא דָוִד. כְּדָוִד שֶׁאָמַר וְהִנֵּה בְעָנְיִי הֲכִינוֹתִי לְבֵית ה'. וְכָתוּב (תהלים פו) כִּי עָנִי וְאֶבְיוֹן אָנִי. וְהוּא הָיָה מֶלֶךְ עַל מְלָכִים וְהָיָה קוֹרֵא לְעַצְמוֹ כָּךְ. אָמַר רַבִּי אַבָּא, אַשְׁרֵיהֶם יִשְׂרָאֵל שֶׁהַקָּדוֹשׁ בָּרוּךְ הוּא לֹא קָרָא לָהֶם כְּקֹדֶשׁ, אֶלָּא קֹדֶשׁ מַמָּשׁ, שֶׁכָּתוּב קֹדֶשׁ יִשְׂרָאֵל לַה', וּמִשּׁוּם כָּךְ כָּל אֹכְלָיו יֶאְשָׁמוּ וְגוֹ'.</p>"],[9522011682,"<p>שָׁנִינוּ, אָמַר רַבִּי יוֹסֵי, מָה רָאָה הַקָּדוֹשׁ בָּרוּךְ הוּא לָתֵת דִּינִים לְיִשְׂרָאֵל אַחַר עֶשֶׂר הָאֲמִירוֹת? אֶלָּא כָּךְ שָׁנִינוּ, מִצַּד הַגְּבוּרָה נִתְּנָה תּוֹרָה לְיִשְׂרָאֵל, מִשּׁוּם כָּךְ צָרִיךְ לָתֵת שָׁלוֹם בֵּינֵיהֶם כְּדֵי שֶׁהַתּוֹרָה תִּהְיֶה שְׁמוּרָה מִכָּל צְדָדֶיהָ. שֶׁאָמַר רַבִּי אַבָּא אָמַר רַבִּי יִצְחָק, אֵין הָעוֹלָם מִתְקַיֵּם אֶלָּא עַל דִּין, שֶׁאִלְמָלֵא הַדִּין לֹא יַעֲמֹד, וּמִשּׁוּם כָּךְ הָעוֹלָם נִבְרָא בְדִין וְהִתְקַיֵּם.</p>\n<p>שָׁנִינוּ, רַבִּי אַבָּא, כָּתוּב (ירמיה כא) דִּינוּ לַבּקֶר מִשְׁפָּט. וְכִי לַבֹּקֶר וְלֹא בְּכָל הַיּוֹם? אֶלָּא לַבּקֶר, טֶרֶם שֶׁיֹּאכְלוּ הַדַּיָּנִים וְלֹא יִשְׁתּוּ, שֶׁכָּל מִי שֶׁדָּן דִּין אַחַר שֶׁאָכַל וְשָׁתָה, אֵינוֹ דִּין אֱמֶת, שֶׁכָּתוּב (ויקראיט) לֹא תֹאכְלוּ עַל הַדָּם. מַה זֶּה עַל הַדָּם? אַזְהָרָה לְדַיָּנִים שֶׁלֹּא יֹאכְלוּ עַד שֶׁדָּנִים דִּין. שֶׁכָּל מִי שֶׁדָּן דִּין אַחַר שֶׁאָכַל וְשָׁתָה, כְּאִלּוּ חִיֵּב אֶת דַּם חֲבֵרוֹ לְאַחֵר, שֶׁהֲרֵי דָּמוֹ מַמָּשׁ נָתַן לְאַחֵר. זֶה בְּמָמוֹן, כָּל שֶׁכֵּן בְּדִינֵי נְפָשׁוֹת שֶׁצְּרִיכִים הַדַּיָּנִים לְהִשָּׁמֵר שֶׁלֹּא לָדוּן דִּין אֶלָּא קֹדֶם שֶׁאָכְלוּ וְשָׁתוּ, וְעַל זֶה כָתוּב דִּינוֹ לַבֹּקֶר מִשְׁפָּט, וְכָתוּב (ירמיה ט) אֲנִי ה' עֹשֶׂה חֶסֶד וּמִשְׁפָּט וּצְדָקָה בָּאָרֶץ כִּי בְאֵלֶּה חָפַצְתִּי נְאֻם ה'.</p>\n<p>שָׁנִינוּ, אָמַר רַבִּי יְהוּדָה, מִי שֶׁמְּשַׁקֵּר בַּדִּין, מְשַׁקֵּר בְּתִקּוּנֵי הַמֶּלֶךְ. מָהֵם תִּקּוּנֵי הַמֶּלֶךְ? אוֹתָם שֶׁנֶּאֱמַר, שֶׁכָּתוּב עֹשֶׂה חֶסֶד מִשְׁפָּט וּצְדָקָה בָּאָרֶץ. וְכָתוּב כִּי בְאֵלֶּה חָפַצְתִּי נְאֻם ה'. וְהַכֹּל תָּלוּי זֶה בָּזֶה (והלא בזה תלוי). רַבִּי יוֹסֵי אָמַר, אֵלֶּה הֵם תִּקּוּנֵי הַכִּסֵּא, שֶׁכָּתוּב (תהלים פט) צֶדֶק וּמִשְׁפָּט מְכוֹן כִּסְאֶךְ. וְכָתוּב (ישעיה טז) וְהוּכַן בַּחֶסֶד כִּסֵּא.</p>"],[9522011683,"<p>וּבְכֹל אֲשֶׁר אָמַרְתִּי אֲלֵיכֶם תִּשָּׁמֵרוּ וְגוֹ'. מַה זֶּה תִּשָּׁמֵרוּ? תִּשְׁמֹרוּ הָיָה צָרִיךְ לִהְיוֹת! אֶלָּא תִּשָּׁמֵרוּ וַדַּאי. מַה זֶּה אֲשֶׁר אָמַרְתִּי אֲלֵיכֶם? כְּלוֹמַר שֶׁהִזְהַרְתִּיכֶם עַל מַאֲמַר עֲבוֹדָתִי. תִּשָּׁמֵרוּ, שֶׁלֹּא יַגִּיעַ אֲלֵיכֶם שׁוּם רַע. תִּשָּׁמֵרוּ מֵאוֹתָהּ שְׁמִירָה וּנְטִירָה שֶׁלִּי בִּלְבַד. וְשֵׁם אֱלֹהִים אֲחֵרִים לֹא תַזְכִּירוּ - לֹא תַזְכִּירוּ כְּמוֹ שֶׁבֵּאַרְנוּ. דָּבָר אַחֵר וְשֵׁם אֱלֹהִים לֹא תַזְכִּירוּ - כְּלוֹמַר לֹא תְסַבְּבוּ, שֶׁתִּפְּלוּ בֵּין הָעַמִּים בְּאֶרֶץ אַחֶרֶת, וִיקֻיַּם בָּכֶם מַה שֶּׁכָּתוּב (דברים כח) וְעָבַדְתָּ שָּׁם אֱלֹהִים אֲחֵרִים וְגוֹ'.</p>\n<p>דָּבָר אַחֵר וּבְכֹל אֲשֶׁר אָמַרְתִּי אֲלֵיכֶם תִּשָּׁמֵרוּ - רַבִּי יְהוּדָה פָּתַח, (תהלים פא) שְׁמַע עַמִּי וְאָעִידָה בָּךְ וְגוֹ', לֹא יִהְיֶה בְךְ אֵל זָר וְגוֹ'. אָנֹכִי ה' אֱלֹהֶיךְ הַמַּעַלְךְ מֵאֶרֶץ מִצְרָיִם וְגוֹ'. הַפְּסוּקִים הַלָּלוּ אֲמָרָם דָּוִד בְּרוּחַ הַקֹּדֶשׁ, וְיֵשׁ לְהִתְבּוֹנֵן בָּהֶם. שְׁמַע עַמִּי - בְּכַמָּה מְקוֹמוֹת הִזְהִירָה הַתּוֹרָה אֶת הָאָדָם, בְּכַמָּה מְקוֹמוֹת מַזְהִיר הַקָּדוֹשׁ בָּרוּךְ הוּא אֶת הָאָדָם, וְהַכֹּל לְתוֹעֶלֶת הָאָדָם כְּדֵי שֶׁיִּשְׁמֹר אֶת מִצְווֹת הַתּוֹרָה. שֶׁכָּל מִי שֶׁיִּשְׁמֹר אֶת מִצְווֹת הַתּוֹרָה וּמִשְׁתַּדֵּל בָּהּ, כְּמִי שֶׁמִּשְׁתַּדֵּל בַּשֵּׁם הַקָּדוֹשׁ.</p>\n<p>שֶׁשָּׁנִינוּ, כָּל הַתּוֹרָה הִיא שְׁמוֹ שֶׁל הַקָּדוֹשׁ בָּרוּךְ הוּא, וּמִי שֶׁמִּשְׁתַּדֵּל בָּהּ כְּמִי שֶׁמִּשְׁתַּדֵּל בַּשֵּׁם הַקָּדוֹשׁ, מִשּׁוּם שֶׁכָּל הַתּוֹרָה הִיא שֵׁם קָדוֹשׁ אֶחָד, שֵׁם עֶלְיוֹן, שֵׁם שֶׁכּוֹלֵל אֶת כָּל הַשֵּׁמוֹת, וּמִי שֶׁגּוֹרֵעַ מִמֶּנָּה אוֹת אַחַת כְּאִלּוּ עָשָׂה פְּגָם בַּשֵּׁם הַקָּדוֹשׁ. שָׁנִינוּ, וְשֵׁם אֱלֹהִים אֲחֵרִים לֹא תַזְכִּירוּ - לֹא תוֹסִיף עַל הַתּוֹרָה וְלֹא תִגְרַע מִמֶּנָּה. רַבִּי חִיָּיא אָמַר, וְשֵׁם אֱלֹהִים אֲחֵרִים - זֶה מִי שֶׁמִּתְעַסֵּק בִּסְפָרִים אֲחֵרִים שֶׁאֵינָם מִצַּד הַתּוֹרָה. לֹא יִשָּׁמַע עַל פִּיךְ - שֶׁאָסוּר אֲפִלּוּ לְהַזְכִּירָם וְלִלְמֹד מֵהֶם טַעַם, כָּל שֶׁכֵּן עַל הַתּוֹרָה.</p>\n<p>רַבִּי יְהוּדָה שׁוֹנֶה כָּךְ, מָה הַטַּעַם כָּתוּב וְשֵׁם אֱלֹהִים אֲחֵרִים, וְסוֹמֵךְ לוֹ אֶת חַג הַמַּצּוֹת תִּשְׁמֹר? אֶלָּא מִי שֶׁמִּי שֶׁלֹּא שׁוֹמֵר אֶת זֶה, כְּמִי שֶׁלֹּא שׁוֹמֵר אֶת אֱמוּנַת הַקָּדוֹשׁ בָּרוּךְ הוּא. מָה הַטַּעַם? מִשּׁוּם שֶׁבּוֹ הַדָּבָר אָחוּז. אָמַר רַבִּי יִצְחָק, וְכֵן בְּכָל שְׁאָר הַחַגִּים וְהַזְּמַנִּים, שֶׁהֲרֵי כֻּלָּם אֲחוּזִים בַּשֵּׁם הַקָּדוֹשׁ הָעֶלְיוֹן. וְעַל זֶה שָׁנִינוּ, מַה שֶּׁכָּתוּב שָׁלֹשׁ פְּעָמִים בַּשָּׁנָה, מִשּׁוּם שֶׁבָּהֶם תְּלוּיָה הָאֱמוּנָה.</p>"],[9522011684,"<p>יֵרָאֶה כָּל זְכוּרְךְ, לָמָּה כָּל זְכוּרְךְ? אָמַר רַבִּי אֶלְעָזָר, כָּל זְכוּרְךְ מַמָּשׁ, מִשּׁוּם שֶׁנּוֹטְלִים בְּרָכָה מֵהַמַּעְיָן שֶׁל הַנַּחַל. מִכָּאן שָׁנִינוּ, כָּל בֶּן יִשְׂרָאֵל שֶׁנִּמּוֹל, צָרִיךְ לְהֵרָאוֹת לִפְנֵי הַמֶּלֶךְ הַקָּדוֹשׁ, מִשּׁוּם שֶׁנּוֹטֵל בְּרָכָה מִמַּבּוּעַ הַנַּחַל. זֶהוּ שֶׁכָּתוּב כְּבִרְכַּת ה' אֱלֹהֶיךְ אֲשֶׁר נָתַן לָךְ. וְכָתוּב אֶל פְּנֵי הָאָדן ה', כְּמוֹ שֶׁבֵּאַרְנוּ, שֶׁמִּשָּׁם מְרִיקִים בְּרָכוֹת וְנוֹטְלִים בְּרָכָה. אַשְׁרֵי חֶלְקָם שֶׁל יִשְׂרָאֵל מִכָּל שְׁאָר הָעַמִּים.</p>\n<p>פַּעַם אַחַת עָלוּ יִשְׂרָאֵל לָחֹג אֶת הֶחָג, וְהִתְעָרְבוּ עוֹבְדֵי עֲבוֹדַת כּוֹכָבִים וּמַזָּלוֹת עִמָּם, וְאוֹתָהּ שָׁנָה לֹא נִמְצְאָה בְּרָכָה בָּעוֹלָם. בָּאוּ וְשָׁאֲלוּ אֶת רַב הַמְנוּנָא סָבָא. אָמַר לָהֶם, רְאִיתֶם בַּתְּחִלָּה סִימָן לָזֶה? אָמְרוּ לוֹ, רָאִינוּ סִימָן, שֶׁכְּשֶׁשַּׁבְנוּ מִשָּׁם כָּל הַדְּרָכִים הָיוּ סְתוּמִים מִמַּיִם, וְעָנָן וַחֲשֵׁכָה נִמְצְאוּ, שֶׁלֹּא יָכְלוּ לָלֶכֶת כָּל אוֹתָם שֶׁעָלוּ לְשָׁם. וְעוֹד, בְּשָׁעָה שֶׁנִּכְנַסְנוּ לְהֵרָאוֹת, פְּנֵי הַשָּׁמַיִם נֶחְשְׁכוּ וְרָגְזוּ. (נחרד וראה) אָמַר לָהֶם, וַדַּאי אוֹ שֶׁיֵּשׁ בָּכֶם אֲנָשִׁים לֹא נִמּוֹלִים, אוֹ עוֹבְדֵי עֲבוֹדַת כּוֹכָבִים וּמַזָּלוֹת עָלוּ עִמָּכֶם, שֶׁהֲרֵי לֹא הִתְבָּרְכוּ בְּאוֹתָה שָׁעָה, פְּרָט לְאוֹתָם יִשְׂרְאֵלִים שֶׁנִּמּוֹלוּ, וּבָאוֹת הַקְּדוֹשָׁה הַזּוֹ מִסְתַּכֵּל הַקָּדוֹשׁ בָּרוּךְ הוּא וּמְבָרֵךְ אוֹתָם.</p>\n<p>לַשָּׁנָה הָאַחֶרֶת עָלוּ, וְעָלוּ אוֹתָם עוֹבְדֵי עֲבוֹדַת כּוֹכָבִים וּמַזָּלוֹת, שֶׁהִתְעָרְבוּ עִמָּם כְּשֶׁהָיוּ אוֹכְלִים קָרְבָּנוֹת וְהָיוּ שְׂמֵחִים. וְרָאוּ אֶת אוֹתָם עוֹבְדֵי עֲבוֹדַת כּוֹכָבִים וּמַזָּלוֹת שֶׁדְּפוּסָם בְּקִשְׁרֵיהֶם לְקֶשֶׁר הַכֹּתֶל. הִשְׁגִּיחוּ בָהֶם שֶׁכֻּלָּם מְבָרְכִים וְהֵם לֹא בֵרְכוּ. בָּאוּ וְאָמְרוּ אֶת הַדָּבָר לְבֵית הַדִּין. בָּאוּ וְשָׁאֲלוּ אוֹתָם. אָמְרוּ, זֶה שֶׁאֲכַלְתֶּם, הַחֵלֶק שֶׁלָּכֶם אֵיזֶה קָרְבָּן הָיָה? לֹא הָיָה בְיָדָם. בָּדְקוּ וּמָצְאוּ שֶׁהֵם עוֹבְדֵי עֲבוֹדַת כּוֹכָבִים וּמַזָּלוֹת וְהָרְגוּ אוֹתָם. אָמְרוּ, בָּרוּךְ הָרַחֲמָן שֶׁהִצִּיל אֶת עַמּוֹ, שֶׁוַּדַּאי אֵין בְּרָכָה שְׁרוּיָה אֶלָּא רַק בְּיִשְׂרָאֵל, הַזֶּרַע הַקָּדוֹשׁ, בְּנֵי הָאֱמוּנָה, בְּנֵי הָאֱמֶת. וְאוֹתָהּ הַשָּׁנָה נִמְצְאָה בְּרָכָה בָּעוֹלָם בִּשְׁלֵמוּת. פָּתְחוּ וְאָמְרוּ, (תהלים קמ) אַךְ צַדִּיקִים יוֹדוּ לִשְׁמֶךְ וְגוֹ'.</p>\n<p>רַבִּי חִיָּיא אָמַר, בִּזְכוּת יִשְׂרָאֵל מְהוּלִים, נִכְנָעִים שׂוֹנְאֵיהֶם תַּחְתֵּיהֶם וְיוֹרְשִׁים נַחֲלָתָם. בֹּא וּרְאֵה מַה כָּתוּב, יֵרָאֶה כָּל זְכוּרְךְ. וְכָתוּב אַחֲרָיו, כִּי אוֹרִישׁ גּוֹיִם מִפָּנֶיךְ וְהִרְחַבְתִּי אֶת גְּבֻלֶךְ. שֶׁהַקָּדוֹשׁ בָּרוּךְ הוּא עוֹקֵר דַּיָּרִים מִמְּקוֹמָם וּמוֹשִׁיב דַּיָּרִים לִמְקוֹמָם, וּמִשּׁוּם כָּךְ, (שמות לד) יֵרָאֶה כָּל זְכוּרְךְ אֶת פְּנֵי הָאָדֹן ה'. רַבִּי יְהוּדָה אָמַר, הָאָדוֹן, כְּמוֹ שֶׁכָּתוּב (ישעיה י) הִנֵּה הָאָדוֹן ה' צְבָאוֹת מְסָעֵף פֻּארָה וְגוֹ', וְיָצָא חֹטֶר וְגוֹ'. וְהַכֹּל אֶחָד, מְעַקֵּר דַּיָּרִים וּמוֹשִׁיב דַּיָּרִים. רַבִּי יִצְחָק אָמַר, יֵשׁ אָדוֹן וְיֵשׁ אָדוֹן, וְהַכֹּל בְּאֶחָד תָּלוּי.</p>"],[9522011685,"<p>רַבִּי יְהוּדָה אָמַר, אֲדנָי - אָלֶ\"ף דָּלֶי\"ת נוּ\"ן יוֹ\"ד, הַקָּדוֹשׁ בָּרוּךְ הוּא נִקְרָא, וְאוֹתוֹ שֶׁנִּקְרָא כְּמוֹ שֶׁהוּא כָּתוּב, וּמִיהוּ? רַבִּי יוֹסֵי אוֹמֵר, מַרְאֹת אֱלֹהִים. מַרְאַת כָּתוּב. וּמַהוּ מַרְאַת? שְׁלֵמוּת הַכֹּל - יוֹ\"ד הֵ\"א וָא\"ו הֵ\"א. (מראת הוא א'כו') מַרְאַת לָמָּה הוּא אָלֶ\"ף דָּלֶ\"ת נוּ\"ן יוֹ\"ד? זֶה נִקְרָא כִּכְתָבוֹ, וְזֶה לֹא נִקְרָא כִּכְתָבוֹ, וּמִשּׁוּם כָּךְ בָּזֶה נִקְרָא, וְעַל כָּךְ מַרְאַת אֱלֹהִים כָּתוּב.</p>\n<p>רַבִּי יְהוּדָה אָמַר, לִפְעָמִים עֶלְיוֹנִים שֶׁנִּקְרְאוּ בְּשֵׁם תַּחְתּוֹנִים, וְלִפְעָמִים תַּחְתּוֹנִים נִקְרָאִים בְּשֵׁם הָעֶלְיוֹנִים. הָאָדן ה' - בְּשֵׁם עֶלְיוֹן הוּא אֲדנָי, וַהֲרֵי בֵּאַרְנוּ הַדְּבָרִים. וּבִגְוָנִים רַבִּים נִתְפָּרְשׁוּ הַדְּבָרִים, וְהַכֹּל אֶחָד. בָּרוּךְ הָרַחֲמָן וּבָרוּךְ שְׁמוֹ לְעוֹלָם וּלְעוֹלְמֵי עוֹלָמִים.</p>"],[9522011686,"<p>הִנֵּה אָנֹכִי שֹׁלֵחַ מַלְאָךְ לְפָנֶיךְ וְגוֹ'. רַבִּי יִצְחָק פָּתַח, (שיר א) יִשָּׁקֵנִי מִנְּשִׁיקוֹת פִּיהוּ וְגוֹ'. אָמְרָה כְּנֶסֶת יִשְׂרָאֵל, יִשָּׁקֵנִי מִנְּשִׁיקוֹת פִּיהוּ. מָה הַטַּעַם יִשָּׁקֵנִי? יֹאהֲבֵנִי הָיָה צָרִיךְ לִהְיוֹת! לָמָּה יִשָּׁקֵנִי? אֶלָּא כָּךְ שָׁנִינוּ, מַה נְּשִׁיקוֹת שֶׁל דְּבֵקוּת שֶׁל רוּחַ בְּרוּחַ, שֶׁבִּגְלַל כָּךְ נְשִׁיקָה בַּפֶּה, שֶׁהֲרֵי הַפֶּה הוּא הַמּוֹצִיא וְהַמָּקוֹר שֶׁל הָרוּחַ, וְלָכֵן נְשִׁיקוֹת בַּפֶּה בַּחֲבִיבוּת, וּדְבֵקִים רוּחַ בְּרוּחַ, שֶׁלֹּא נִפְרָדִים זֶה מִזֶּה.</p>\n<p>וְלָכֵן מִי שֶׁמּוֹצִיא נִשְׁמָתוֹ בִּנְשִׁיקָה, נִדְבָּק בְּרוּחַ אַחֶרֶת, בְּרוּחַ שֶׁלֹּא נִפְרֶדֶת מִמֶּנּוּ. וְהַיְנוּ נִקְרָא נְשִׁיקָה. וְעַל זֶה אָמְרָה כְּנֶסֶת יִשְׂרָאֵל יִשָּׁקֵנִי מִנְּשִׁיקוֹת פִּיהוּ, לְהַדְבִּיק רוּחַ בְּרוּחַ, שֶׁלֹּא יִפָּרֵד זֶה מִזֶּה.</p>\n<p>כִּי טוֹבִים דֹּדֶיךְ מִיָּיִן. מָה עוֹשֶׂה כָּאן יַיִן? וַהֲרֵי כָּתוּב (ישעיה כח) וְגַם אֵלֶּה בְּיַיִן שָׁגוּ וְגוֹ', וְכָתוּב (ויקרא י) יַיִן וְשֵׁכָר אַל תֵּשְׁתְּ אַתָּה וּבָנֶיךְ. מָה הַטַּעַם כָּאן יַיִן? רַבִּי חִיָּיא אָמַר, מִיֵּינָהּ שֶׁל תּוֹרָה. רַבִּי חִזְקִיָּה אָמַר, זֶה שֶׁכָּתוּב (תהלים קד) וְיַיִן יְשַׂמַּח לְבַב אֱנוֹשׁ. וְעַל זֶה כָּתוּב כִּי טוֹבִים דֹּדֶיךְ מִיָּיִן, לְחֶדְוַת הַלֵּב. מִיָּיִן - שֶׁמְּשַׂמְּחֵנִי יוֹתֵר מֵהַכֹּל.</p>\n<p>רַבִּי יְהוּדָה אָמַר, כָּתוּב (בראשית כט) וַיִּשַּׁק יַעֲקֹב לְרָחֵל וַיִּשָּׂא אֶת קוֹלוֹ וַיֵּבְךָּ. לָמָּה בָכָה? אֶלָּא בִּדְבֵקוּת הָרוּחַ בָּהּ לֹא יָכֹל הַלֵּב לִסְבֹּל, וּבָכָה. וְאִם תֹּאמַר, הֲרֵי כָּתוּב וַיִּשָּׁקֵהוּ וַיִּבְכּוּ? שָׁנִינוּ, לָמָּה נָקוּד עַל וַיִּשָּׁקֵהוּ? אֶלָּא שֶׁלֹּא נִדְבְּקָה בּוֹ רוּחַ כְּלָל, וְעַל זֶה כָּתוּב וְנַעְתָּרוֹת נְשִׁיקוֹת שׂוֹנֵא. מַה זֶּה (משלי כז) וְנַעְתָּרוֹת נְשִׁיקוֹת שׂוֹנֵא? אֶלָּא מִי שֶׁנּוֹשֵׁק בַּחֲבִיבוּת, מַדְבִּיק רוּחוֹ בְּרוּחוֹ בִּדְבֵקוּת הַחֲבִיבוּת, וּמִי שֶׁלֹּא נוֹשֵׁק בַּחֲבִיבוּת, זֶה לֹא בִּדְבֵקוּת, אֶלָּא וְנַעְתָּרוֹת. מַה זֶּה נַעְתָּרוֹת? גַּסּוּת, שֶׁלֹּא דָבְקָה רוּחוֹ בְּאוֹתָהּ נְשִׁיקָה וְלֹא נִדְבַּק בּוֹ כְּלָל. וּמִשּׁוּם כָּךְ כָּתוּב, יִשָּׁקֵהוּ מִנְּשִׁיקוֹת פִּיהוּ, שֶׁהִיא דְבֵקוּת רוּחַ בְּרוּחַ.</p>\n<p>שָׁנִינוּ, כָּל זְמַן שֶׁהַקָּדוֹשׁ בָּרוּךְ הוּא הוֹלֵךְ עִם יִשְׂרָאֵל, כִּבְיָכוֹל נִדְבֶּקֶת רוּחַ בְּרוּחַ, וְעַל זֶה כָּתוּב (דברים ד) וְאַתֶּם הַדְּבֵקִים בַּה', בְּכָל אוֹתָם גּוֹנֵי הַדְּבֵקוּת, וְלֹא נִפְרָדִים זֶה מִזֶּה. בְּשָׁעָה שֶׁנֶּאֱמַר הִנֵּה אָנֹכִי שֹׁלֵחַ מַלְאָךְ לְפָנֶיךְ, יָדַע מֹשֶׁה שֶׁזּוֹ פְּרִישָׁה. אָמַר, (שמות לג) אִם אֵין פָּנֶיךְ הֹלְכִים אַל תַּעֲלֵנוּ מִזֶּה.</p>"],[9522011687,"<p>רַבִּי אַבָּא אָמַר, מַה כָּתוּב לְמַעְלָה מִזֶּה? (שם לד) רֵאשִׁית בִּכּוּרֵי אַדְמָתְךְ תָּבִיא בֵּית ה' אֱלֹהֶיךְ לֹא תְבַשֵּׁל גְּדִי בַּחֲלֵב אִמּוֹ. מַה זֶּה אוֹמֵר? אֶלָּא שֶׁלֹּא לְעָרֵב דָּבָר תַּחְתּוֹן בְּעֶלְיוֹן, שֶׁלֹּא יָנַק הַצַּד הַחִיצוֹן מֵהַצַּד הַפְּנִימִי. מַה בֵּין זֶה לָזֶה? זֶה שֶׁבַּחוּץ מִצַּד הַטֻּמְאָה, וְזֶה שֶׁלְּפָנִים בְּצַד הַקְּדֻשָּׁה. מִי הִיא אִמּוֹ? זוֹ כְּנֶסֶת יִשְׂרָאֵל שֶׁנִּקְרֵאת אֵם. בַּחֲלֵב אִמּוֹ - שֶׁלֹּא יוֹנֵק מִצַּד זֶה מִי שֶׁלֹּא צָרִיךְ.</p>\n<p>וְכָאן כָּתוּב, הִנֵּה אָנֹכִי שֹׁלֵחַ מַלְאָךְ לְפָנֶיךְ. אָמַר מֹשֶׁה, הֲרֵי קִבַּלְתִּי בִּטָּחוֹן מִמְּךְ שֶׁלֹּא תִפָּרֵד מֵעִמָּנוּ, וַדַּאי אִם אֵין פָּנֶיךְ הֹלְכִים אַל תַּעֲלֵנוּ מִזֶּה. וּבַמֶּה יִוָּדַע אֵפוֹא וְגוֹ'.</p>\n<p>אָמַר רַבִּי אֶלְעָזָר, דָּבָר זֶה לֹא אָמַר הַקָּדוֹשׁ בָּרוּךְ הוּא אֶלָּא בְּאַהֲבַת יִשְׂרָאֵל וּלְהִתְפַּיֵּס עִמָּם. לְמֶלֶךְ שֶׁהָיָה רוֹצֶה לֶלֶכֶת עִם בְּנוֹ, וְלֹא רָצָה לַעֲזֹב אוֹתוֹ. בָּא בְנוֹ וּפָחַד לְבַקֵּשׁ מֵהַמֶּלֶךְ שֶׁיֵּלֵךְ עִמּוֹ. הִקְדִּים הַמֶּלֶךְ וְאָמַר, הֲרֵי לִגְיוֹנֵר פְּלוֹנִי יֵלֵךְ עִמְּךְ לִשְׁמָרְךְ בַּדֶּרֶךְ. לְאַחַר מִכֵּן אָמַר, הִשָּׁמֵר לְךְ מִמֶּנּוּ (בדרך), שֶׁהֲרֵי אֵינוֹ גֶבֶר שָׁלֵם. אָמַר בְּנוֹ, אִם כָּךְ, אוֹ שֶׁאֲנִי אֵשֵׁב כָּאן, אוֹ שֶׁאַתָּה תֵּלֵךְ עִמִּי וְלֹא אֶפָּרֵד מִמְּךְ. כָּךְ הַקָּדוֹשׁ בָּרוּךְ הוּא, בַּתְּחִלָּה אָמַר, הִנֵּה אָנֹכִי שֹׁלֵחַ מַלְאָךְ לְפָנֶיךְ לִשְׁמָרְךְ בַּדָּרֶךְ. וְאַחַר כָּךְ אָמַר, הִשָּׁמֶר מִפָּנָיו וְגוֹ'. בְּאוֹתָהּ שָׁעָה אָמַר מֹשֶׁה, אִם אֵין פָּנֶיךְ הֹלְכִים וְגוֹ'.</p>\n<p>בָּא רַבִּי שִׁמְעוֹן, מָצָא אוֹתָם בָּזֶה. אָמַר, אֶלְעָזָר בְּנִי, יָפֶה אָמַרְתָּ, אֲבָל בֹּא וּרְאֵה, בַּמָּקוֹם הַזֶּה לֹא אָמַר מֹשֶׁה דָּבָר וְלֹא הֵשִׁיב דָּבָר כְּנֶגְדּוֹ, מָה הַטַּעַם? מִשּׁוּם שֶׁכָּאן לֹא נִמְצֵאת פְּרִישָׁה מִמֶּנּוּ, וַהֲרֵי בֵּאַרְנוּ דָבָר זֶה לַחֲבֵרִים. וְיֵשׁ שׁוֹנִים לְהֵפֶךְ, וְלֹא כָּךְ פֵּרְשׁוּהָ הָרִאשׁוֹנִים. וּכְשֶׁיִּסְתַּכְּלוּ הַדְּבָרִים, הַכֹּל יָפֶה, וְכֻלָּם אָמְרוּ הַטְּעָמִים שֶׁלָּהֶם בְּדָבָר אֶחָד.</p>\n<p>מָתַי הֵשִׁיב מֹשֶׁה? בִּזְמַן שֶׁאָמַר וְשָׁלַחְתִּי לְפָנֶיךְ מַלְאָךְ. וְכָתוּב, כִּי יֵלֵךְ מַלְאָכִי לְפָנֶיךְ. סָתַם וְלֹא פֵרַשׁ אֶת הַדָּבָר. וְעַל כֵּן כָּתוּב כָּאן, כִּי אִם שָׁמוֹעַ תִּשְׁמַע בְּקֹלוֹ וְעָשִׂיתָ כֹּל אֲשֶׁר אֲדַבֵּר. אֲשֶׁר אֲדַבֵּר דַּוְקָא. וְכָתוּב, וְאָיַבְתִּי אֶת אֹיְבֶיךְ וְצַרְתִּי אֶת צֹרֲרֶיךְ, וְהַכֹּל תָּלוּי בּוֹ.</p>\n<p>רַבִּי יְהוּדָה אָמַר, אִם תֹּאמַר שֶׁשְּׁנֵיהֶם מַמָּשׁ מַלְאָךְ - מֹשֶׁה לֹא הֵשִׁיב עֲלֵיהֶם, שֶׁלֹּא רָאָה מָקוֹם. וּמָתַי הֵשִׁיב? בִּזְמַן שֶׁכָּתוּב אִם אֵין פָּנֶיךְ הֹלְכִים אַל תַּעֲלֵנוּ וְגוֹ'. אָמַר רַבִּי שִׁמְעוֹן, כְּלָל שֶׁל הַכֹּל - מֹשֶׁה לֹא רָצָה מַלְאָךְ. שֶׁהֲרֵי כָּתוּב, (שמות לד) וַיֹּאמֶר אִם נָא מָצָאתִי חֵן בְּעֵינֶיךְ אֲדנָי יֵלֵךְ נָא אֲדנָי בְּקִרְבֵּנוּ.</p>"],[9522011688,"<p>אָמַר רַבִּי יְהוּדָה, זֶה שֶׁאָמַר רַבִּי אַבָּא, שֶׁכָּתוּב לֹא תְבַשֵּׁל גְּדִי בַּחֲלֵב אִמּוֹ, בַּחֲלֵב הָאֵם הָיָה צָרִיךְ לִהְיוֹת! מַה זֶּה אִמּוֹ? וְאִם תֹּאמַר, כְּנֶסֶת יִשְׂרָאֵל אִמּוֹ שֶׁמִּצַּד הַטֻּמְאָה - לֹא כָּךְ! שֶׁהֲרֵי שָׁמַעְתִּי שֶׁאָמַר רַבִּי שִׁמְעוֹן, כְּנֶסֶת יִשְׂרָאֵל הָאֵם הַקְּדוֹשָׁה נֶאֶחְזָה בַּחֵלֶק שֶׁל יִשְׂרָאֵל, שֶׁכָּתוּב (דברים לב) כִּי חֵלֶק ה' עַמּוֹ.</p>\n<p>אָמַר רַבִּי שִׁמְעוֹן, יָפֶה אָמַרְתָּ, וְזֶה שֶׁל רַבִּי אַבָּא יָפֶה, וְהַכֹּל תָּלוּי זֶה בָּזֶה. בּא וּרְאֵה, הָאֵם נֶאֶחְזָה לָהֶם לְמַעְלָה לְצַד זֶה וּלְצַד זֶה, וּשְׁנַיִם הֵם - אֶחָד לְיָמִין וְאֶחָד לִשְׂמֹאל. וּמִשּׁוּם כָּךְ, מֵהֶם לְיָמִין וּמֵהֶם לִשְׂמֹאל, וְכֻלָּם תְּלוּיִים בָּאֵם הַזֹּאת, הָאֵם הַקְּדוֹשָׁה, וְנֶאֱחָזִים בָּהּ.</p>\n<p>מָתַי הֵם נֶאֱחָזִים בָּהּ? בְּשָׁעָה שֶׁהָאֵם הַזּוֹ יוֹנֶקֶת מִן הַצַּד הָאַחֵר וְהַמִּקְדָּשׁ נִטְמָא, וְהַנָּחָשׁ הֶחָזָק מַתְחִיל לְהִתְגַּלּוֹת, וְאָז הַגְּדִי יוֹנֵק מֵחֲלֵב אִמּוֹ, וּמִתְעוֹרְרִים הַדִּינִים. וְעַל זֶה יִשְׂרָאֵל מַקְדִּימִים וּמְבִיאִים בִּכּוּרִים. וּבְשָׁעָה שֶׁהֵם מְבִיאִים אוֹתָם, צְרִיכִים לוֹמַר וְלִפְתֹּחַ בְּלָבָן, שֶׁרָצָה בִּכְשָׁפָיו אֵלּוּ לִשְׁלֹט בְּיַעֲקֹב וּבְזֶרַע הַקֹּדֶשׁ, וְלֹא נִתְּנוּ בְיָדוֹ וְלֹא נִמְסְרוּ יִשְׂרָאֵל לְצַד זֶה. וְעַל זֶה כָּתוּב, רֵאשִׁית בִּכּוּרֵי אַדְמָתְךְ וְגוֹ', לֹא תְבַשֵּׁל גְּדִי בַּחֲלֵב אִמּוֹ. וְלֹא יוֹנֵק אוֹתוֹ הַצַּד מֵחֲלֵב אִמּוֹ, שֶׁהֲרֵי לֹא נִטְמָא הַמִּקְדָּשׁ, וְהַדִּינִים לֹא מִתְעוֹרְרִים.</p>\n<p>מִשּׁוּם כָּךְ לֹא יֹאכַל בָּשָׂר בְּחָלָב כָּל זֶרַע הַקֹּדֶשׁ, וְכָל מִי שֶׁבָּא מֵהַצַּד הַזֶּה, שֶׁלֹּא יִתֵּן מָקוֹם לְמִי שֶׁלֹּא צָרִיךְ, שֶׁהֲרֵי בְּמַעֲשֶׂה תָּלוּי הַדָּבָר, בְּמַעֲשֶׂה שֶׁלְּמַטָּה לְעוֹרֵר לְמַעְלָה. אַשְׁרֵיהֶם יִשְׂרָאֵל מִכָּל הָעַמִּים עוֹבְדֵי עֲבוֹדַת כּוֹכָבִים וּמַזָּלוֹת, שֶׁרִבּוֹנָם קוֹרֵא עֲלֵיהֶם, (שם יד) וּבְךְ בָּחַר ה' לִהְיוֹת לוֹ לְעַם סְגֻלָּה. וְכָתוּב (שם) כִּי עַם קָדוֹשׁ אַתָּה לַה' אֱלֹהֶיךְ. וְכָתוּב (שם) בָּנִים אַתֶּם לַה' אֱלֹהֵיכֶם וְגוֹ'.</p>\n<p>בֹּא וּרְאֵה, בְּשָׁעָה שֶׁיִּשְׂרָאֵל לֹא הֻכְשְׁרוּ מַעֲשֵׂיהֶם, מַה כָּתוּב? (ישעיה ג) עַמִּי נֹגְשָׂיו מְעוֹלֵל וְנָשִׁים מָשְׁלוּ בוֹ. דַּוְקָא מָשְׁלוּ בוֹ, וַהֲרֵי בֵּאַרְנוּ הַדְּבָרִים בְּסוֹד סִפְרוֹ שֶׁל שְׁלֹמֹה הַמֶּלֶךְ, וְכָךְ מָצָאנוּ בוֹ. וְעוֹד מָצָאנוּ, שֶׁכָּל מִי שֶׁאוֹכֵל מַאֲכָל זֶה שֶׁהִתְחַבֵּר כְּאֶחָד, (או) בְּשָׁעָה אַחַת אוֹ בִּסְעוּדָה אַחַת, אַרְבָּעִים יוֹם נִרְאֶה גְדִי מְקֻלָּס בִּקְלִפָּתוֹ אֶל אוֹתָם שֶׁלְּמַעְלָה, וְסִיעָה טְמֵאָה מִתְקָרְבִים עִמּוֹ, וְגוֹרֵם לְעוֹרֵר דִּינִים בָּעוֹלָם, דִּינִים שֶׁאֵינָם קְדוֹשִׁים.</p>\n<p>וְאִם מוֹלִיד בֵּן בְּאוֹתָם יָמִים, מַלְוִים לוֹ נְשָׁמָה מֵהַצַּד הָאַחֵר, שֶׁלֹּא צָרִיךְ אוֹתוֹ. וְכָתוּב (ויקרא יא) וְהִתְקַדִּשְׁתֶּם וִהְיִיתֶם קְדֹשִׁים וְגוֹ'. בָּא לְהִטָּמֵא - מְטַמְּאִים אוֹתוֹ וַדַּאי, שֶׁכָּתוּב (שם) וְנִטְמֵתֶם בָּם. חָסֵר א'. טֻמְאָה אֲטוּמָה יוֹתֵר מִכֹּל, שֶׁאֵין רְשׁוּת לְהִטָּהֵר כָּךְ כְּמוֹ שְׁאָר מִינֵי הַטֻּמְאוֹת שֶׁנִּטְהָרוֹת. וְעוֹד, שֶׁפּוֹחֵד מֵחַיּוֹת רָעוֹת, שֶׁהֲרֵי בְעֵינֵיהֶם נִמְצָא גְדִי וְיָכוֹל לְהִנָּזֵק, שֶׁהֲרֵי צֶלֶם אָדָם הָעֳבַר מִמֶּנּוּ.</p>\n<p>רַבִּי יֵיסָא הִתִּיר לֶאֱכֹל תַּרְנְגוֹל בִּגְבִינָה אוֹ בְּחָלָב. אָמַר רַבִּי שִׁמְעוֹן, אָסוּר לְךְ, שֶׁלֹּא יִתֵּן אִישׁ פֶּתַח לַמִּינִים הָרָעִים. לֵךְ לֵךְ אוֹמְרִים לְנָזִיר, סָבִיב סָבִיב לַכֶּרֶם לֹא תִקְרַב. וַדַּאי אָסוּר לְךְ הוּא, שֶׁחֻמְרָה יֵשׁ בּוֹ כִּבְהֵמָה לִשְׁחִיטָה, וּמִי שֶׁמַּתִּיר אֶת זֶה מַה כָּתוּב? (עמוס ב) וַתַּשְׁקוּ אֶת הַנְּזִרִים יָיִן. מִי שֶׁמַּתִּיר אֶת זֶה, כְּמִי שֶׁמַּתִּיר אֶת זֶה. וְכָתוּב (דברים יד) לֹא תֹאכַל כָּל תּוֹעֵבָה. כָּל - לְהַכְלִיל הַכֹּל.</p>\n<p>שָׁנִינוּ, בַּמֶּה זָכוּ דָנִיֵּאל, חֲנַנְיָה, מִישָׁאֵל וַעֲזַרְיָה שֶׁנִּצְלוּ מֵאוֹתָם נִסְיוֹנוֹת? אֶלָּא מִשּׁוּם שֶׁלֹּא נִטְמְאוּ בְמַאַכְלֵיהֶם. אָמַר רַבִּי יְהוּדָה, כָּתוּב (דניאל א) וַיָּשֶׂם דָּנִיֵּאל עַל לִבּוֹ אֲשֶׁר לֹא יִתְגָּאַל בְּפַת בַּג הַמֶּלֶךְ וְגוֹ'. וְשָׁנִינוּ בְּסֵתֶר הַמִּשְׁנָה, מַאֲכַל אוֹתוֹ הָרָשָׁע, בָּשָׂר בְּחָלָב הָיָה וּגְבִינָה עִם בָּשָׂר, פְּרָט לְמַאֲכָלִים אֲחֵרִים, וְזֶה עָלָה לוֹ עַל שֻׁלְחָנוֹ בְּכָל יוֹם.</p>\n<p>וְדָנִיִּאִל שֶׁנִּשְׁמַר מִזֶּה, כְּשֶׁזְּרָקוּהוּ לְגֹב הָאֲרָיוֹת, הִשְׁתַּלֵּם בְּצֶלֶם רִבּוֹנוֹ, וְלֹא שִׁנָּה צַלְמוֹ לְצֶלֶם אַחֵר, וְלָכֵן פָּחֲדוּ מִמֶּנּוּ הָאֲרָיוֹת וְלֹא חִבְּלוּ בוֹ. וְאוֹתוֹ רָשָׁע, בְּשָׁעָה שֶׁהָעָבְרָה מִמֶּנּוּ מַלְכוּתוֹ וּמְדוֹרוֹ הָיָה עִם חַיּוֹת הַשָּׂדֶה, הָעֳבַר מִמֶּנּוּ צֶלֶם פָּנָיו, וּמֵאוֹתוֹ יוֹם לֹא נִרְאָה צַלְמוֹ צֶלֶם שֶׁל אָדָם, וְכָל בְּהֵמָה שֶׁבָּאָה, נִרְאָה לָהּ בְּצֶלֶם שֶׁל מִינָהּ וּנְקֵבָתָהּ, וְכֻלָּם הָיוּ בָאִים עָלָיו, וּבְכַמָּה פְעָמִים הָיוּ אוֹכְלוֹת אוֹתוֹ חַיּוֹת הַשָּׂדֶה זוּלַת נִגְזַר עָלָיו הָעֹנֶשׁ הַזֶּה, מִשּׁוּם שֶׁכָּתוּב (חבקוק א) וְהוּא בַּמְּלָכִים יִתְקַלָּס, מִשּׁוּם כָּךְ כֻּלָּם הִתְקַלְּסוּ בוֹ כָּל אוֹתוֹ זְמַן.</p>\n<p>בֹּא וּרְאֵה מַה כָּתוּב, וּמִקְצָת יָמִים עֲשָׂרָה נִרְאָה מַרְאֵיהֶם טוֹב (וגו') מִן כָּל הַיְלָדִים הָאֹכְלִים אֵת פַּת בַּג הַמֶּלֶךְ. נִרְאָה מַרְאֵיהֶם טוֹב - שֶׁצֶּלֶם רִבּוֹנָם לֹא זָז מֵהֶם, וּמֵאֲחֵרִים זָז. מִי גָרַם אֶת זֶה? מִשּׁוּם שֶׁלֹּא נִגְעֲלוּ בְּגִעוּלֵי מַאַכְלֵיהֶם. אַשְׁרֵי חֶלְקָם שֶׁל יִשְׂרָאֵל שֶׁכָּתוּב בָּהֶם, וְאַנְשֵׁי קֹדֶשׁ תִּהְיוּן לִי.</p>"],[9522011689,"<p>וְאֶל מֹשֶׁה אָמַר עֲלֵה אֶל ה' וְגוֹ'. וְאֶל מֹשֶׁה אָמַר - מִי אָמַר? זוֹ שְׁכִינָה. עֲלֵה אֶת ה', כַּכָּתוּב (שמות יט) וּמֹשֶׁה עָלָה אֶל הָאֱלֹהִים וְגוֹ'. (ויק, רא א, ליו ה') לָמָּה כָּל זֶה? לְקַיֵּם עִמָּם בְּרִית, כִּי הֲרֵי נִפְרְעוּ, מַה שֶּׁלֹּא יָצְאוּ כָּךְ מִמִּצְרַיִם, שֶׁנִּמּוֹלוּ וְלֹא נִפְרְעוּ, וְכָאן הֲרֵי נִפְרְעוּ וְנִכְנְסוּ בִּבְרִית הַקֹּדֶשׁ, שֶׁכָּתוּב שָׁם שָׂם לוֹ חֹקֶ וּמִשְׁפָּט. וְשָׁם נִסָּהוּ - בְּאוֹת הַקֹּדֶשׁ הַזּוֹ שֶׁנִּגְלְתָה בָהֶם, וְכָאן הִתְקַיְּמָה בָהֶם עַל יְדֵי מֹשֶׁה מִילַת הַבְּרִית, שֶׁכָּתוּב וַיִּקַּח מֹשֶׁה אֶת הַדָּם וַיִּזְרֹק עַל הָעָם וְגוֹ'.</p>\n<p>אָמַר רַבִּי יִצְחָק, מַה שֶׁכָּתוּב וַחֲצִי הַדָּם זָרַק עַל הַמִּזְבֵּחַ, בַּמִּזְבֵּחַ לֹא כָתוּב, אֶלָּא דַּוְקָא עַל הַמִּזְבֵּחַ. וְהִשְׁתַּחֲוִיתֶם מֵרָחֹק, מַהוּ מֵרָחֹק? כְּמוֹ שֶׁנֶּאֱמַר (ירמיה לא) מֵרָחוֹק ה' נִרְאָה לִי. וְכָתוּב (שמות ב) וַתֵּתַּצַּב אֲחֹתוֹ מֵרָחֹק. שָׁנָה רַבִּי אַבָּא, שֶׁעָמְדָה הַלְּבָנָה בִּפְגִימָתָהּ, וּבָהּ בְּשָׁעָה זָכוּ יִשְׂרָאֵל יוֹתֵר בְּחֵלֶק קָדוֹשׁ, וְגָזְרוּ בְּרִית קֹדֶשׁ עִם הַקָּדוֹשׁ בָּרוּךְ הוּא.</p>\n<p>וְאֶל מֹשֶׁה אָמַר עֲלֵה אֶל ה'. מָה הַטַּעַם? אָמְרָה לוֹ שְׁכִינָה, עֲלֵה לְמַעְלָה, שֶׁהֲרֵי אֲנִי וְיִשְׂרָאֵל נִשְׁתַּתֵּף כְּאֶחָד בִּשְׁלֵמוּת עַל יָדְךְ, מַה שֶּׁלֹּא הָיָה עַד כָּאן. מַה כָּתוּב? וַיִּקַּח מֹשֶׁה חֲצִי הַדָּם וְגוֹ'. חִלְּקוֹ לִשְׁנַיִם, חֲצִי הַדָּם זָרַק עַל הָעָם, וַחֲצִי הַדָּם זָרַק עַל הַמִּזְבֵּחַ, כְּמוֹ שֶׁבֵּאַרְנוּ. וְכָתוּב, וְהִנֵּה דַּם הַבְּרִית אֲשֶׁר כָּרַת ה' עִמָּכֶם. וַיָּשֶׂם בָּאַגָּנֹת, כָּתוּב בָּאַגָּנַת, חָסֵר וָא\"ו, כְּמוֹ שֶׁכָּתוּב (שיר השירים ז) שָׁרְרֵךְ אַגָּן הַסַּהַר אַל יֶחְסַר הַמָּזֶג.</p>\n<p>וְנִגַּשׁ מֹשֶׁה לְבַדּוֹ אֶל ה'. אַשְׁרֵי חֶלְקוֹ שֶׁל מֹשֶׁה שֶׁהוּא לְבַדּוֹ זָכָה לְמַה שֶּׁלֹּא זָכָה אָדָם אַחֵר. יִשְׂרָאֵל זָכוּ עַכְשָׁו מַה שֶּׁלֹּא זָכוּ עַד לְאוֹתָהּ שָׁעָה, וְאוֹתָהּ שָׁעָה הִתְקַיְּמוּ בְקִיּוּם עֶלְיוֹן קָדוֹשׁ, וּבְאוֹתָהּ שָׁעָה הִתְבַּשְּׂרוּ לִהְיוֹת הַמִּקְדָּשׁ בֵּינֵיהֶם, כְּמוֹ שֶׁנֶּאֱמַר (שמות כה) וְעָשׂוּ לִי מִקְדָּשׁ וְשָׁכַנְתִּי בְּתוֹכָם.</p>\n<p>וַיִּרְאוּ אֵת אֱלֹהֵי יִשְׂרָאֵל וְתַחַת רַגְלָיו כְּמַעֲשֵׂה לִבְנַת הַסַּפִּיר וְגוֹ'. רַבִּי יְהוּדָה פָּתַח, (שיר השירים ז) זֹאת קוֹמָתֵךְ דָּמְתָה לְתָמָר וְגוֹ'. כַּמָּה חֲבִיבָה כְּנֶסֶת יִשְׂרָאֵל לִפְנֵי הַקָּדוֹשׁ בָּרוּךְ הוּא, שֶׁלֹּא נִפְרֶדֶת מִמֶּנּוּ כַּתָּמָר הַזֶּה שֶׁלֹּא נִפְרָד הַזָּכָר מֵהַנְּקֵבָה לְעוֹלָמִים, וְלֹא עוֹלֶה זֶה בְּלִי זֶה. כָּךְ כְּנֶסֶת יִשְׂרָאֵל לֹא נִפְרֶדֶת מֵהַקָּדוֹשׁ בָּרוּךְ הוּא.</p>\n<p>בֹּא וּרְאֵה, בְּשָׁעָה שֶׁנָּדָב וַאֲבִיהוּא רָאוּ, וְשִׁבְעִים זְקֵנִים, מַה כָּתוּב בָּהֶם? וַיִּרְאוּ אֵת אֱלֹהֵי יִשְׂרָאֵל. שֶׁהִתְגַּלְּתָה עֲלֵיהֶם שְׁכִינָה. רַבִּי יְהוּדָה וְרַבִּי יוֹסֵי אוֹמְרִים, אֵת דַּוְקָא, וְזֶה אֵת הוּא מֵרָחוֹק. אֵת - לְהַכְלִיל אֶת מַה שֶּׁבְּתוֹכוֹ.</p>\n<p>רַבִּי יִצְחָק אָמַר, וַהֲרֵי כָּתוּב (יחזקאל י) הִיא הַחַיָּה אֲשֶׁר רָאִיתִי תַּחַת אֱלֹהֵי יִשְׂרָאֵל בִּנְהַר כְּבָר. מִי הַחַיָּה הַזּוֹ? אָמַר רַבִּי יוֹסֵי אָמַר רַבִּי חִיָּיא, חַיָּה קְטַנָּה. וְכִי יֵשׁ חַיָּה קְטַנָּה? כֵּן. חַיָּה קְטַנָּה, וְחַיָּה עֶלְיוֹנָה, וְחַיָּה קְטַנָּה שֶׁבַּקְּטַנּוֹת.</p>\n<p>וַיִּרְאוּ אֵת אֱלֹהֵי יִשְׂרָאֵל, דַּוְקָא, כְּמוֹ שֶׁאָמַרְנוּ. וְתַחַת רַגְלָיו כְּמַעֲשֵׂה לִבְנַת הַסַּפִּיר, כְּמַרְאֵה אֶבֶן טוֹבָה שֶׁעָתִיד הַקָּדוֹשׁ בָּרוּךְ הוּא לִבְנוֹת הַמִּקְדָּשׁ, שֶׁכָּתוּב (ישעיה נד) וִיסַדְתִּיךְ בַּסַּפִּירִים.</p>"],[9522011690,"<p>וְאֶל אֲצִילֵי בְּנֵי יִשְׂרָאֵל - זֶה נָדָב וַאֲבִיהוּא. לֹא שָׁלַח יָדוֹ - שֶׁהֶעֱלָה אוֹתָם לְאַחַר זְמַן, וְכָאן לֹא נֶעֶנְשׁוּ. רַבִּי יוֹסֵי אָמַר דָּבָר זֶה לְשִׁבְחָם, שֶׁכָּתוּב וַיֹּאכְלוּ וַיִּשְׁתּוּ, שֶׁזָּנוּ עֵינֵיהֶם מֵהָאוֹר הַזֶּה. רַבִּי יְהוּדָה אָמַר, אֲכִילָה וַדָּאִית אָכְלוּ וְזָנוּ עַצְמָם, וְכָאן נִקְשְׁרוּ לְמַעְלָה אִם לֹא שֶׁסָּטוּ דַרְכֵיהֶם אַחַר כָּךְ, כְּמוֹ שֶׁבֵּאַ רְנוּ.</p>\n<p>אָמַר רַבִּי אֶלְעָזָר, וַאֲפִלּוּ יִשְׂרָאֵל בְּאוֹתָהּ שָׁעָה הֻכְשְׁרוּ וְנִקְשְׁרָה בָהֶם שְׁכִינָה, וְהַבְּרִית הַזּוֹ וְכָל הַתּוֹרָה בִּזְמַן אֶחָד זֶה הָיָה, וְיִשְׂרָאֵל כְּאוֹתָהּ שָׁעָה לֹא רָאוּ לְעוֹלָמִים. וְלֶעָתִיד לָבֹא עָתִיד הַקָּדוֹשׁ בָּרוּךְ הוּא לְהִגָּלוֹת עַל בָּנָיו וּלְהַרְאוֹת אֶת כָּל כְּבוֹדוֹ עַיִן בְּעַיִן, שֶׁכָּתוּב (שם נב) כִּי עַיִן בְּעַיִן יִרְאוּ בְּשׁוּב ה' צִיּוֹן. וְכָתוּב (שם מ) וְנִגְלָה כְּבוֹד ה' וְרָאוּ כָל בָּשָׂר יַחְדָּו וְגוֹ'.</p>"],[9522011691,"<p>וַיְדַבֵּר ה' אֶל מֹשֶׁה לֵּאמֹר. דַּבֵּר אֶל בְּנֵי יִשְׂרָאֵל וְיִקְחוּ לִי תְּרוּמָה מֵאֵת כָּל אִישׁ אֲשֶׁר יִדְּבֶנּוּ לִבּוֹ וְגוֹ'. רַבִּי חִיָּיא פָּתַח, (תהליםקלה) כִּי יַעֲקֹב בָּחַר לוֹ יָהּ יִשְׂרָאֵל לִסְגֻלָּתוֹ. כַּמָּה חֲבִיבִים יִשְׂרָאֵל לִפְנֵי הַקָּדוֹשׁ בָּרוּךְ הוּא, שֶׁהִתְרַצָּה בָהֶם וְרָצָה לְהִדָּבֵק בָּהֶם וּלְהִתְקַשֵּׁר עִמָּם, וְעָשָׂה אוֹתָם עַם יְחִידִי בָּעוֹלָם, שֶׁכָּתוּב (שמואל ב ז) וּמִי כְעַמְּךְ כְּיִשְׂרָאֵל גּוֹי אֶחָד בָּאָרֶץ, וְהֵם הִתְרַצּוּ בוֹ וְהִתְקַשְּׁרוּ בוֹ. זֶהוּ שֶׁכָּתוּב כִּי יַעֲקֹב בָּחַר לוֹ יָהּ, וְכָתוּב (דברים לב) כִּי חֵלֶק ה' עַמּוֹ. וְנָתַן לִשְׁאָר הָעַמִּים שַׁלִּיטִים גְּדוֹלִים מְמֻנִּים עֲלֵיהֶם, וְהוּא נָטַל אֶת יִשְׂרָאֵל לְחֶלְקוֹ.</p>\n<p>רַבִּי שִׁמְעוֹן פָּתַח, (שיר השירים ו) מִי זאת הַנִּשְׁקָפָה כְּמוֹ שָׁחַר יָפָה כַלְּבָנָה בָּרָה כַּחַמָּה אֲיֻמָּה כַּנִּדְגָּלוֹת. מִי זאת - סוֹד שֶׁל שְׁנֵי עוֹלָמוֹת מְחֻבָּרִים כְּאֶחָד, וְזֶה הוּא עוֹלָם וְעוֹלָם. מִ\"י - הֲרֵי בֵּאַרְנוּהָ דַּרְגָּה עֶלְיוֹנָה לְמַעְלָה, רֵאשִׁית שֶׁעוֹמֶדֶת לִשְׁאֵלָה, וְנִקְרֵאת מִ\"י, כְּמוֹ שֶׁנֶּאֱמַר (ישעיה מ) שְׂאוּ מָרוֹם עֵינֵיכֶם וּרְאוּ מִי בָרָא אֵלֶּה. זֹא\"ת - דַּרְגָּה תַחְתּוֹנָה לְמַטָּה, עוֹלָם תַּחְתּוֹן. וּשְׁנֵיהֶם שְׁנֵי עוֹלָמוֹת בְּחִבּוּר אֶחָד, בְּקֶשֶׁר אֶחָד כְּאֶחָד.</p>\n<p>הַנִּשְׁקָפָה - כְּשֶׁמִּתְחַבְּרִים שְׁנֵיהֶם כְּאֶחָד. כְּמוֹ שָׁחַר - כְּשֶׁרוֹצֶה הַשַּׁחַר לְהָאִיר, וְאַחַר כָּךְ נָאוֹר כַּלְּבָנָה, כְּשֶׁמַּכֶּה (כשכונס) בּוֹ אוֹר הַשֶּׁמֶשׁ. וְאַחַר כָּךְ כַּשֶּׁמֶשׁ, כְּשֶׁעוֹמֶדֶת הַלְּבָנָה בִּשְׁלֵמוּת. אֲיֻמָּה - תַּקִּיפָה לְהָגֵן עַל הַכֹּל, שֶׁהֲרֵי אָז יֵשׁ לָהּ שְׁלֵמוּת וְתֹקֶף לַעֲשׂוֹת חַיִל.</p>\n<p>וְלוֹקַחַת חַיִל מֵהָעוֹלָם הָעֶלְיוֹן עַל יְדֵי יַעֲקֹב הַשָּׁלֵם, שֶׁחִבֵּר אוֹתָם כְּאֶחָד. חִבֵּר אוֹתָם כְּאֶחָד לְמַעְלָה, וְחִבֵּר אוֹתָם כְּאֶחָד לְמַטָּה, וּמִשָּׁם יָצְאוּ שְׁנֵים עָשָׂר שְׁבָטִים קְדוֹשִׁים כְּמוֹ שֶׁלְּמַעְלָה. יַעֲקֹב שֶׁהָיָה שָׁלֵם הִכְנִיס אַהֲבָה בִּשְׁנֵי עוֹלָמוֹת, כְּמוֹ שֶׁבֵּאַרְנוּ. שְׁאָר בְּנֵי אָדָם שֶׁעוֹשִׂים, כָּךְ מְגַלִּים עֲרָיוֹת לְמַעְלָה וּלְמַטָּה, גּוֹרְמִים יְרִיבוּת בִּשְׁנֵי עוֹלָמוֹת וְגוֹרְמִים פֵּרוּד. זֶהוּ שֶׁכָּתוּב (ויקרא יח) וְאִשָּׁה אֶל אֲחֹתָהּ לֹא תִקָּח לִצְרֹ\"ר, שֶׁנַּעֲשׂוֹת יְרִיבוֹת זוֹ לָזוֹ.</p>\n<p>וְאִם תֹּאמַר, (בראשית ל) וַתְּקַנֵּא רָחֵל בַּאֲחוֹתָהּ - כָּךְ הוּא וַדַּאי. שֶׁהֲרֵי כָּל תְּשׁוּקַת הָעוֹלָם הַתַּחְתּוֹן אֵינָהּ אֶלָּא כְּדֵי לִהְיוֹת כְּמוֹ הָעוֹלָם הָעֶלְיוֹן וְלִירַשׁ מְקוֹמוֹ. בְּמָקוֹם אַחֵר קִנְאַת סוֹפְרִים תַּרְבֶּה חָכְמָה, וְכָאן קִנְאַת סוֹפְרִים, מִשּׁוּם שֶׁיֵּשׁ סֵפֶר וְסֵפֶר, מַגְדִּילִים מְשִׁיכַת הַחָכְמָה (העליונה) אֲלֵיהֶם. (ועלזהיעקב השלים כו').</p>\n<p>וְעִם כָּל זֶה, אֲפִלּוּ יַעֲקֹב לֹא הִשְׁלִים אֲלֵיהֶם כָּרָאוּי. שְׁאָר בְּנֵי הָעוֹלָם גּוֹרְמִים יְרִיבוּת וְגוֹרְמִים פֵּרוּד וּמְגַלִּים עֲרָיוֹת שֶׁל הַכֹּל, עֲרָיוֹת שֶׁלְּמַעְלָה וּמַטָּה. וּבְסוֹד זֶה יֵשׁ אֶת סוֹד הָעֲרָיוֹת, עֲרָיוֹת שֶׁל אֵם וּבִתָּהּ, וְהַכֹּל בְּסוֹד אֶחָד. מִי זֹאת - נִקְרְאוּ אֲחָיוֹת, מִשּׁוּם שֶׁהֵן בְּאַהֲבָה וְאַחֲוָה וּבְחִבּוּר הָרָצוֹן. וְנִקְרָאוֹת אֵם וּבַת. מִי שֶׁמְּגַלֶּה אֶת עֶרְוָתָן, אֵין לוֹ חֵלֶק לָעוֹלָם הַבָּא וְאֵין לוֹ חֵלֶק בָּאֱמוּנָה.</p>\n<p>בֹּא וּרְאֵה, כִּי יַעֲקֹב בָּחַר לוֹ יָהּ - סוֹד עֶלְיוֹן לְמַעְלָה. כֵּיוָן שֶׁהֻשְׁלַם וְנִקְרָא יִשְׂרָאֵל, אָז לִסְגֻלָּתוֹ, נָטַל הַכֹּל בְּכָל הַצְּדָדִים, וְנָטַל לְמַעְלָה וְנָטַל לְמַטָּה, וְנִשְׁלַם בַּכֹּל.</p>"],[9522011692,"<p>אָמַר רַבִּי שִׁמְעוֹן, הֲרֵי שָׁנִינוּ, כְּשֶׁבָּרָא הַקָּדוֹשׁ בָּרוּךְ הוּא אֶת הָעוֹלָם, חָקַק בַּחֲקִיקוֹתָיו שֶׁל סוֹדוֹת הָאֱמוּנָה תּוֹךְ קְלִפּוֹת בְּסוֹדוֹת עֶלְיוֹנִים, וְחָקַק לְמַעְלָה וְחָקַק לְמַטָּה, וְהַכֹּל בְּסוֹד אֶחָד, בְּסוֹד גִּלּוּפֵי הַשֵּׁם הַקָּדוֹשׁ יהו\"ה, שֶׁשּׁוֹלֵט בְּאוֹתִיּוֹתָיו מַעְלָה וּמַטָּה, וּבְסוֹד זֶה נִתְקְנוּ הָעוֹלָמוֹת - הָעוֹלָם הָעֶלְיוֹן וְהָעוֹלָם הַתַּחְתּוֹן.</p>\n<p>הָעוֹלָם הָעֶלְיוֹן נִתְקַן בַּסּוֹד שֶׁל אוֹת י', נְקֻדָּה עֶלְיוֹנָה רִאשׁוֹנָה שֶׁיָּצְאָה מִתּוֹךְ הַנִּסְתָּר וְהַגָּנוּז שֶׁלֹּא יָדוּעַ, וְלֹא עוֹמֵד לְהִוָּדַע וְלֹא נוֹדָע כְּלָל, עֲלִיָּה שֶׁל סוֹד הָאֵין סוֹף, וּמִתּוֹךְ סֵתֶר זֶה מֵאִיר אוֹר אֶחָד דַּקִּיק וְנִסְתָּר, כּוֹלֵל בְּתוֹכוֹ כְּלַל כָּל הָאוֹרוֹת. וּבְאוֹתוֹ אוֹר נִסְתָּר הִכָּה בּוֹ מִי שֶׁלֹּא הִכָּה, הֵאִיר בּוֹ מִי שֶׁלֹּא הֵאִיר, וְאָז יָצָא אוֹר אֶחָד שֶׁהוּא עִדּוּן לְעִדּוּן, לְהִשְׁתַּעֲשֵׁעַ, לִגְנֹז אוֹר דַּקִּיק וְנִסְתָּר בְּתוֹךְ אוֹתוֹ הָאוֹר.</p>\n<p>וְאוֹתוֹ אוֹר שֶׁהוּא עִדּוּן לְעִדּוּן, נִסְתָּר, הִתְקַיְּמוּ (נרקמו) וְנִתְקְנוּ בוֹ שִׁשָּׁה רִשּׁוּמִים שֶׁלֹּא יְדוּעִים, פְּרָט לְאוֹתוֹ אוֹר דַּקִּיק כְּשֶׁנִּכְנָס לְהִגָּנֵז עִדּוּן בְּעִדּוּן, אוֹר בְּאוֹר.</p>\n<p>וְהָאוֹר הַזֶּה שֶׁיּוֹצֵא מִתּוֹךְ הָאוֹר הַדַּקִּיק, הוּא מַפְחִיד וְאֵימְתָנִי וְתַקִּיף יוֹתֵר, וְזֶה הִתְפַּשֵּׁט וְנַעֲשָׂה עוֹלָם אֶחָד שֶׁמֵּאִיר לְכָל הָעוֹלָמוֹת, עוֹלָם נִסְתָּר שֶׁלֹּא יָדוּעַ כְּלָל, וּבְתוֹכוֹ דָרִים שֵׁשׁ רִבּוֹא אֶלֶף שֶׁל אוֹתָם דַּיָּרִים וַחֲיָלוֹת וּמַחֲנוֹת הָעֶלְיוֹנוֹת.</p>\n<p>וְכֵיוָן שֶׁהוֹצִיא אוֹתָם וְנִתְקְנוּ כְאֶחָד, אָז הוּא חִבּוּר אֶחָד, וְהֵם סוֹד שֶׁל אוֹת וָי\"ו שֶׁהִתְחַבְּרָה בְּאוֹתוֹ עוֹלָם נִסְתָּר, וְאָז כָּתוּב כִּי יַעֲקֹב בָּחַר לוֹ יָהּ. כְּשֶׁיּוֹצֵא וָי\"ו וְנִתְקָן מִתּוֹךְ יָ\"הּ, אָז יִשְׂרָאֵל לִסְגֻלָּתוֹ.</p>\n<p>לִשְאָר בְּנֵי הָעוֹלָם לֹא נִתְּנָה רְשׁוּת לַעֲלוֹת כָּךְ, אֶלָּא רַק לִסְגֻלָּתוֹ, מָקוֹם שֶׁנּוֹטֵל וְכוֹנֵס הַכֹּל, וְזוֹהִי דַּרְגָּה לְמַטָּה, וּמִתּוֹךְ זֶה נוֹטְלִים לְמַעְלָה בְּסֵתֶר הָרָצוֹן, אֲבָל לֹא בְגִלּוּי כְּמוֹ שֶׁנָּטַל יַעֲקֹב. זֶהוּ שֶׁכָּתוּב וְיִקְחוּ לִי תְּרוּמָה.</p>"],[9522011693,"<p>וְיִקְחוּ לִי תְּרוּמָה. רַבִּי יְהוּדָה פָּתַח, (תהליםלא) מָה רַב טוּבְךְ אֲשֶׁר צָפַנְתָּ לִּירֵאֶיךְ פָּעַלְתָּ לַחוֹסִים בָּךְ נֶגֶד בְּנֵי אָדָם. פָּסוּק זֶה פֵּרְשׁוּהוּ וְנִתְבָּאֵר, אֲבָל סוֹד זֶה הֲרֵי בֵּאֲרוֹ הַמְּנוֹרָה הַקְּדוֹשָׁה בְּתוֹךְ סוֹדוֹת עֶלְיוֹנִים.</p>\n<p>דַּרְגָּה עֶלְיוֹנָה, שֶׁהוּא סוֹד שֶׁל עוֹלָם עֶלְיוֹן, נִקְרֵאת מִ\"י. דַּרְגָּה תַחְתּוֹנָה, שֶׁהוּא סוֹד שֶׁל עוֹלָם עֶלְיוֹן, נִקְרֵאת מָ\"ה. וְשָׁנִינוּ, אַל תִּקְרֵי מָ\"ה אֶלָּא מֵאָה, כִּי כָּל הַדְּרָגוֹת הָעֶלְיוֹנוֹת בִּשְׁלֵמוּתָם הֵם כָּאן.</p>\n<p>עוֹד, לָמָּה נִקְרֵאת מָ\"ה? אֶלָּא אַף עַל גַּב שֶׁמְּשִׁיכוּת עֶלְיוֹנָה נִמְשְׁכָה, לֹא הִתְגַּלְּתָה עַד שֶׁנִּשְׁלָם כָּאן, שֶׁהוּא מְקוֹם סוֹף כָּל הַדְּרָגוֹת, סוֹף שֶׁל הַמְשָׁכַת הַכֹּל, וְעוֹמֵד בְּהִתְגַּלּוּת. וְאַף עַל גַּב שֶׁגָּלוּי יוֹתֵר מֵהַכֹּל, עוֹמֵד לַשְּׁאֵלָה מָ\"ה. מָה רָאִיתָ? מַה יָּדַעְתָּ? כְּמוֹ שֶׁנֶּאֱמַר (דברים ד) כִּי לֹא רְאִיתֶם כָּל תְּמוּנָה.</p>\n<p>וְלָכֵן, \"מָה\" רַב טוּבְךְ - זֶהוּ יְסוֹד הָעוֹלָם שֶׁנִּקְרָא רַב טוּב, כְּמוֹ שֶׁנֶּאֱמַר (ישעיה סג) וְרַב טוּב לְבֵית יִשְׂרָאֵל, כִּי זֶהוּ רַב טוּב. אוֹר הָרִאשׁוֹן, נִקְרָא טוֹב סְתָם, וְכָאן כְּלוּלִים זָכָר וּנְקֵבָה כְּאֶחָד. אֲשֶׁר צָפַנְתָּ - שֶׁהֲרֵי נִגְנַז, כְּמוֹ שֶׁהָאוֹר הָרִאשׁוֹן שֶׁנִּגְזַר וְנִסְתַּר. פָּעַלְתָּ - שֶׁכָּאן הִיא אֻמָּנוּת הַכֹּל, אֻמָּנוּת שֶׁל כָּל הָעוֹלָם, אֻמָּנוּת שֶׁל נְשָׁמוֹת וְרוּחוֹת.</p>\n<p>בְּסוֹד זֶה עָשָׂה הַקָּדוֹשׁ בָּרוּךְ הוּא אֻמָּנוּת שֶׁל כָּל הָעוֹלָם, וְסוֹד זֶה (בראשית א) בְּרֵאשִׁית בָּרָא אֱלֹהִים אֵת הַשָּׁמַיִם וְאֵת הָאָרֶץ. בְּסוֹד זֶה נַעֲשָׂה וְנִבְנָה הַמִּשְׁכָּן, שֶׁהוּא בַּדְּיוֹקָן שֶׁל הָעוֹלָם הָעֶלְיוֹן וּבִדְיוֹקַן הָעוֹלָם הַתַּחְתּוֹן. זֶהוּ שֶׁכָּתוּב וְיִקְחוּ לִי תְּרוּמָה. לִי תְּרוּמָה - שְׁתֵּי דְרָגוֹת שֶׁהֵן אַחַת, שֶׁמִּתְחַבְּרוֹת כְּאֶחָד.</p>"],[9522011694,"<p>וְיִקְחוּ לִי תְּרוּמָה וְגוֹ'. רַבִּי שִׁמְעוֹן וְרַבִּי אֶלְעָזָר וְרַבִּי אַבָּא וְרַבִּי יוֹסֵי הָיוּ יוֹשְׁבִים יוֹם אֶחָד תַּחַת הָאִילָנוֹת בְּבִקְעָה לְיַד יָם גִּינוֹסַר. אָמַר רַבִּי שִׁמְעוֹן, כַּמָּה נָאֶה צֵל זֶה שֶׁמְּכַסֶּה עָלֵינוּ מִתּוֹךְ הָאִילָנוֹת, וְאָנוּ צְרִיכִים לְעַטֵּר מָקוֹם זֶה בְּדִבְרֵי תוֹרָה.</p>\n<p>פָּתַח רַבִּי שִׁמְעוֹן וְאָמַר, (שיר ג) אַפִּרְיוֹן עָשָׂה לוֹ הַמֶּלֶךְ שְׁלֹמֹה מֵעֲצֵי הַלְּבָנוֹן. פָּסוּק זֶה הֲרֵי בֵּאַרְנוּהוּ וְנִתְבָּאֵר, אֲבָל אַפִּרְיוֹן - זֶה הֵיכָל שֶׁלְּמַטָּה, שֶׁהוּא כְּמוֹ הַהֵיכָל הָעֶלְיוֹן, וְהַקָּדוֹשׁ בָּרוּךְ הוּא קָרָא לוֹ גַּן עֵדֶן, שֶׁהוּא נָטַע אוֹתוֹ לַהֲנָאָתוֹ, וְכִסּוּפוֹ הוּא לְהִשְׁתַּעֲשֵׁעַ בּוֹ תּוֹךְ אוֹתָן נִשְׁמוֹת הַצַּדִּיקִים, שֶׁשָּׁם כֻּלָּם עוֹמְדִים וּרְשׁוּמִים בְּתוֹכוֹ. אוֹתָן נְשָׁמוֹת שֶׁאֵין לָהֶן גּוּף בָּעוֹלָם הַזֶּה, כֻּלָּן עוֹלוֹת וּמִתְעַטְּרוֹת שָׁם, וְיֵשׁ לָהֶן מְקוֹמוֹת לִרְאוֹת, לְהִתְעַנֵּג תּוֹךְ עֹנֶג עֶלְיוֹן שֶׁנִּקְרָא נֹעַם ה', וְשָׁם מִתְמַלְּאִים מִכָּל הַכִּסּוּפִים שֶׁל נַהֲרוֹת אֲפַרְסְמוֹן זַךְ.</p>\n<p>אֲפַרְסְמוֹן - זֶהוּ הֵיכָל הָעֶלְיוֹן טָמִיר גָּנוּז. אַפִּרְיוֹן - זֶהוּ הֵיכָל שֶׁלְּמַטָּה, שֶׁאֵין בּוֹ סֶמֶךְ עַד שֶׁנִּסְמָךְ (שגמשך) מִתּוֹךְ הֵיכָל הָעֶלְיוֹן. וְלָכֵן אוֹת סָמֶ\"ךְ נִסְתֶּרֶת בְּכָל צְדָדֶיהָ, כְּמוֹ זֶה אוֹת ס (מ\"ם) סְתוּמָה.</p>\n<p>מַה בֵּין זֶה לָזֶה? אֶלָּא בְּשָׁעָה שֶׁנִּסְתָּר וְנִגְנָז בְּתוֹכוֹ תּוֹךְ (נקדה) אוֹר עֶלְיוֹן לְמַעְלָה, אָז הִיא עוֹמֶדֶת בַּדְּיוֹקָן (הזה) שֶׁל אוֹת סָמֶ\"ךְ נִסְתָּר בְּתוֹכוֹ, וְנִגְנָז בּוֹ לַעֲלוֹת לְמַעְלָה. וּבְשָׁעָה שֶׁחוֹזֶרֶת וְיוֹשֶׁבֶת רְבוּצָה עַל הַבָּנִים לְמַטָּה לְהֵינִיק אוֹתָם, אָז הִיא עוֹמֶדֶת בַּדְּיוֹקָן שֶׁל אוֹת ם רְבוּצָה נִסְתֶּרֶת לְתוֹךְ אַרְבַּעַת צִדְדֵי הָעוֹלָם.</p>\n<p>וְעַל כָּךְ זֶהוּ אֲפַרְסְמוֹן, וְזֶהוּ אַפִּרְיוֹן. וּבִמְקוֹם שְׁתֵּי אוֹתִיּוֹת ס\"מ עוֹמֶדֶת י' בְּסוֹד הַבְּרִית (סוד הברית שגגנז בתוכו), שֶׁהוּא עָתִיד לָקַחַת הַכֹּל, סוֹד שֶׁל אוֹתָן מֵאָה בְרָכוֹת, שִׁשִּׁים וְאַרְבָּעִים. שִׁשִּׁים כְּנֶגֶד שִׁשָּׁה צְדָדִים שֶׁיּוֹצְאִים מֵהָאוֹת ס', וְאַרְבָּעִים כְּנֶגֶד אַרְבַּעַת צִדְדֵי הָעוֹלָם, וְהַכֹּל מַשְׁלִימִים לְמֵאָה. וְאוֹת יוֹ\"ד מַשְׁלִימָה לַסּוֹד שֶׁל מֵאָה, כְּמוֹ שֶׁלְּמַעְלָה. וְלָכֵן זֶה אֲפַרְסְמוֹן, וְזֶה אַפִּרְיוֹן.</p>\n<p>אוֹתָם הַנְּהָרוֹת יוֹצְאִים מֵהָאֲפַרְסְמוֹן הַזֶּה, וּנְשָׁמוֹת עֶלְיוֹנוֹת, שֶׁאֵין לָהֶן גּוּף בָּעוֹלָם הַזֶּה, יוֹנְקוֹת מֵאוֹתוֹ הָאוֹר שֶׁיּוֹצֵא מֵאוֹתָם נַהֲרוֹת אֲפַרְסְמוֹן זַךְ, וּמִתְעַנְּגוֹת בָּעִנּוּג הָעֶלְיוֹן הַזֶּה. וּנְשָׁמוֹת (שעולות ויורדות) שֶׁיֵּשׁ לָהֶן גּוּף בָּעוֹלָם הַזֶּה, עוֹלוֹת וְיוֹנְקוֹת מֵאוֹתוֹ הָאוֹר שֶׁל הָאַפִּרְיוֹן הַזֶּה וְיוֹרְדוֹת, וְאֵלּוּ נוֹתְנוֹת וְנוֹטְלוֹת. נוֹתְנוֹת רֵיחַ מֵאוֹתָם מַעֲשִׂים כְּשֵׁרִים שֶׁמִּשְׁתַּדְּלִים בָּהֶם בְּאוֹתוֹ הָעוֹלָם, וְנוֹטְלוֹת מֵאוֹתוֹ הָרֵיחַ שֶׁנִּשְׁאָר בַּגָּן, כְּמוֹ שֶׁנֶּאֱמַר (בראשית כז) כְּרֵיחַ שָׂדֶה אֲשֶׁר בֵּרֲכוֹ ה'. הָרֵיחַ שֶׁנִּשְׁאָר בּוֹ בְּאוֹתוֹ הַשָּׂדֶה. וְכֻלָּם עוֹמְדִים בְּאוֹתוֹ הַגָּן. אֵלּוּ מִתְעַנְּגִים לְמַעְלָה, וְאֵלּוּ מִתְעַנְּגִים לְמַטָּה.</p>\n<p>עָשָׂה לוֹ הַמֶּלֶךְ שְׁלֹמֹה - עָשָׂה לוֹ, לְעַצְמוֹ. וְאִם תֹּאמַר, הֲרֵי נִשְׁמוֹת הַצַּדִּיקִים מִשְׁתַּעַשְׁעוֹת בּוֹ, וְאַתָּה אוֹמֵר עָשָׂה לוֹ? כָּךְ זֶה וַדַּאי, מִשּׁוּם שֶׁהָאַפִּרְיוֹן הַזֶּה וְכָל אוֹתָן נִשְׁמוֹת הַצַּדִּיקִים, בְּכֻלָּם עוֹמֵד הַקָּדוֹשׁ בָּרוּךְ הוּא לְהִשְׁתַּעֲשֵׁעַ בָּהֶן. הַמֶּלֶךְ שְׁלֹמֹה - הַמֶּלֶךְ שֶׁהַשָּׁלוֹם שֶׁלּוֹ, וְזֶהוּ מֶלֶךְ הָעֶלְיוֹן. (והריבארוה) הַמֶּלֶךְ סְתָם, זֶה מֶלֶךְ הַמָּשִׁיחַ. זֶה עוֹלַם הַזָּכָר, וְזֶה עוֹלַם הַנְּקֵבָה. מֵעֲצֵי הַלְּבָנוֹן - אוֹתָם אִילָנוֹת נְטוּעִים שֶׁעָקַר אוֹתָם הַקָּדוֹשׁ בָּרוּךְ הוּא וְשָׁתַל אוֹתָם בְּמָקוֹם אַחֵר, וְאֵלּוּ נִקְרָאִים אַרְזֵי הַלְּבָנוֹן, כְּמוֹ שֶׁנֶּאֱמַר (תהלים קד) אַרְזֵי לְבָנוֹן אֲשֶׁר נָטָע. וְלֹא נִבְנָה הָאַפִּרְיוֹן הַזֶּה וְלֹא נִתְקַן אֶלָּא בָהֶם.</p>"],[9522011695,"<p>עוֹד מֵעֲצֵי הַלְּבָנוֹן - אֵלּוּ שֵׁשֶׁת יְמֵי בְרֵאשִׁית שֶׁכָּל יוֹם וָיוֹם מְסַדֵּר אֶת הָאַפִּרְיוֹן הַזֶּה סִדּוּר שֶׁנִּרְאֶה לוֹ. סִדּוּר רִאשׁוֹן: שׁוֹפֵעַ מִצַּד יָמִין, הָאוֹר הָרִאשׁוֹן שֶׁנִּגְנַז, וְנִטַּל מִצַּד יָמִין, וְנִכְנַס בָּאַפִּרְיוֹן הַזֶּה עַל יְדֵי יְסוֹד אֶחָד וְעוֹשֶׂה בּוֹ שִׁמּוּשׁ. אַחַר כָּךְ מוֹצִיא אוֹתוֹ הָאַפִּרְיוֹן דְּיוֹקָן אֶחָד כְּמוֹ הָאוֹר הַזֶּה, וְזֶהוּ סוֹד הַכָּתוּב (בראשיתא) יְהִי אוֹר וַיְהִי אוֹר. כֵּיוָן שֶׁאָמַר יְהִי אוֹר, לָמָּה כָּתוּב וַיְהִי אוֹר? לֹא הִצְטָרֵךְ הַפָּסוּק לִכְתֹּב אֶלָּא וַיְהִי כֵן. מַהוּ וַיְהִי אוֹר? אֶלָּא שֶׁאוֹתוֹ אוֹר הוֹצִיא אוֹר אַחֵר שֶׁנִּרְאָה לוֹ, וְזֶהוּ יוֹם רִאשׁוֹן מֵאוֹתָם עֲצֵי הַלְּבָנוֹן.</p>\n<p>סִדּוּר שֵׁנִי: שׁוֹפֵעַ מִצַּד שְׂמֹאל, פְּרִישׁוּת הַמַּיִם, בְּשֶׁפַע שֶׁל אֵשׁ תַּקִּיפָה, וְנִטָּל מִצַּד שְׂמֹאל, וְנִכְנָס בָּאַפִּרְיוֹן הַזֶּה וְעוֹשֶׂה בּוֹ שִׁמּוּשׁ, וּמַפְרִיד בֵּין מַיִם שֶׁבְּצַר יָמִין לְבֵין מַיִם (שבצד שמאל). אַחַר כָּךְ מוֹצִיא אוֹתוֹ אַפִּרְיוֹן דְּיוֹקָן אֶחָד כְּמוֹ שֶׁלּוֹ, וְזֶהוּ סוֹד הַכָּתוּב, בֵּין הַמַּיִם אֲשֶׁר מִתַּחַת לָרָקִיעַ וּבֵין הַמַּיִם אֲשֶׁר מֵעַל לָרָקִיעַ וַיְהִי כֵן. וְזֶהוּ יוֹם שֵׁנִי מֵאוֹתָם עֲצֵי הַלְּבָנוֹן.</p>\n<p>סִדּוּר שְׁלִישִׁי: שׁוֹפֵעַ מִצַּד הָאֶמְצַע, וּמִצַּד יָמִין, (ומצד שמאל) יוֹם אֶחָד שְׁלִישִׁי שֶׁעוֹשֶׂה שָׁלוֹם בָּעוֹלָם. וּמִשָּׁם נִמְשָׁכִים פֵּרוֹת לַכֹּל, וְזֶה עוֹשֶׂה שִׁמּוּשׁ בָּאַפִּרְיוֹן הַזֶּה, וּמוֹצִיא מִין לְמִינוֹ. מִין לְמַעֲשִׂים רַבִּים, מִין שֶׁנִּרְאֶה לוֹ, וְכָל הַדְּשָׁאִים וְהָעֲשָׂבִים וְהָאִילָנוֹת בְּכַמָּה חֲיָלוֹת. וְנִשְׁאָר דְּיוֹקְנוֹ שָׁם, וְאוֹתוֹ אַפִּרְיוֹן מוֹצִיא מִין כְּאוֹתוֹ גָוֶן מַמָּשׁ, וְזֶהוּ יוֹם שְׁלִישִׁי שֶׁנִּכְלָל מִשְּׁנֵי צְדָדִים מֵאוֹתָם עֲצֵי הַלְּבָנוֹן.</p>\n<p>סִדּוּר רְבִיעִי: שׁוֹפֵעַ וּמֵאִיר אוֹר הַשֶּׁמֶשׁ לְהָאִיר לָאַפִּרְיוֹן הַזֶּה תּוֹךְ הַחֹשֶׁךְ שֶׁלּוֹ, וְנִכְנָס בּוֹ לְהָאִיר, וְלֹא עוֹשֶׂה בּוֹ שִׁמּוּשׁ. עַד יוֹם חֲמִישִׁי שֶׁמּוֹצִיא אוֹתוֹ אַפִּרְיוֹן שִׁמּוּשׁ שֶׁל אוֹר שֶׁנִּכְנַס בּוֹ בְּיוֹם רְבִיעִי, וּמוֹצִיא אוֹתוֹ אַפִּרְיוֹן בְּאוֹתוֹ גָוֶן מַמָּשׁ שֶׁל אוֹתוֹ אוֹר, וְזֶהוּ יוֹם רְבִיעִי אֶחָד מֵאוֹתָם עֲצֵי הַלְּבָנוֹן.</p>\n<p>סִדּוּר חֲמִישִׁי: שׁוֹפַעַת מְשִׁיכָה אַחַת שֶׁל רַחַשׁ הַמַּיִם, וְעוֹשֶׂה שִׁמּוּשׁ לְהוֹצִיא אוֹתוֹ אוֹר שֶׁל סִדּוּר יוֹם רְבִיעִי, וְעוֹשֶׂה בָּאַפִּרְיוֹן הַזֶּה שִׁמּוּשׁ, וּמוֹצִיא מִינִים לְמִינוֹ, אוֹתָם הַנִּרְאִים בְּאוֹתוֹ גָוֶן מַמָּשׁ. וְיוֹם זֶה שִׁמֵּשׁ אוֹתוֹ שִׁמּוּשׁ יוֹתֵר מִכָּל שְׁאָר הַיָּמִים, וְהַכֹּל תָּלוּי עַד יוֹם הַשִּׁשִּׁי, שֶׁהוֹצִיא הָאַפִּרְיוֹן כָּל מַה שֶּׁהָיָה גָּנוּז בּוֹ, שֶׁכָּתוּב תּוֹצֵא הָאָרֶץ נֶפֶשׁ חַיָּה לְמִינָהּ וְגוֹ'. וְזֶהוּ הַיּוֹם הַחֲמִישִׁי, אֶחָד מֵאוֹתָם עֲצֵי הַלְּבָנוֹן.</p>\n<p>סִדּוּר שִׁשִּׁי - זֶהוּ יוֹם שֶׁהִתְקִין אֶת כָּל הָאַפִּרְיוֹן הַזֶּה, וְאֵין לוֹ תִּקּוּן וְאֵין לוֹ תֹּקֶף פְּרָט לַיּוֹם הַזֶּה. כְּשֶׁבָּא הַיּוֹם הַזֶּה, נִתְקָן הָאַפִּרְיוֹן הַזֶּה בְּכַמָּה רוּחוֹת, בְּכַמָּה נְשָׁמוֹת, בְּכַמָּה עוֹלָמוֹת יְפוֹת מַרְאֶה. אוֹתָן שֶׁנִּרְאוֹת לָשֶׁבֶת בְּהֵיכַל הַמֶּלֶךְ. אַף הוּא נִתְקָן בִּיפִי כָּל שְׁאָר הַיָּמִים שֶׁהָיוּ בַּתְּחִלָּה, וּמַתְקִין אוֹתָם בִּתְשׁוּקָה אַחַת, בְּרָצוֹן, בְּשִׂמְחָה, תִּקּוּן עֶלְיוֹן וְתַחְתּוֹן.</p>\n<p>וְאָז מִתְקַדֵּשׁ הָאַפִּרְיוֹן בִּקְדֻשּׁוֹת עֶלְיוֹנוֹת וּמִתְעַטֵּר בְּעַטְרוֹתָיו, עַד שֶׁעוֹלֶה בַּעֲלִיָּה שֶׁל עֲטָרָה שֶׁל מְנוּחָה, וְנִקְרָא שֵׁם עֶלְיוֹן, שֵׁם קָדוֹשׁ, שֶׁהוּא שַׁבָּת. מְנוּחַת הַכֹּל, תְּשׁוּקַת הַכֹּל, דְּבֵקוּת הַכֹּל, שֶׁלְּמַעְלָה וּלְמַטָּה כְּאֶחָד. וְאָז כָּתוּב, (שיר השירים ג) אַפִּרְיוֹן עָשָׂה לוֹ הַמֶּלֶךְ שְׁלֹמֹה מֵעֲצֵי הַלְּבָנוֹן.</p>\n<p>אָמַר רַבִּי שִׁמְעוֹן, מִי שֶׁזּוֹכֶה לְאוֹתוֹ אַפִּרְיוֹן, זוֹכֶה בַכֹּל, זוֹכֶה לָשֶׁבֶת בִּמְנוּחָה בַּצֵּל שֶׁל הַקָּדוֹשׁ בָּרוּךְ הוּא, כְּמוֹ שֶׁנֶּאֱמַר (שיר השירים ד) בְּצִלּוֹ חִמַּדְתִּי וְיָשַׁבְתִּי. וְכָעֵת שֶׁיָּשַׁבְנוּ בַּצֵּל שֶׁל הַמְּנוּחָה הַזּוֹ, יֵשׁ לָנוּ לְהִסְתַּכֵּל שֶׁלֹּא יָשַׁבְנוּ אֶלָּא בְּצֵל הַקָּדוֹשׁ בָּרוּךְ הוּא בְּתוֹךְ אוֹתוֹ הָאַפִּרְיוֹן, וְיֵשׁ לָנוּ לְעַטֵּר אֶת הַמָּקוֹם הַזֶה בַּעֲטָרוֹת עֶלְיוֹנוֹת עַד שֶׁיִּתְעוֹרְרוּ הָאִילָנוֹת שֶׁל אוֹתוֹ הָאַפִּרְיוֹן לָבא עָלֵינוּ בְּצֵל אַחֵר.</p>"],[9522011696,"<p>פָּתַח רַבִּי שִׁמְעוֹן בָּרֹאשׁ וְאָמַר, וְיִקְחוּ לִי תְּרוּמָה מֵאֵת כָּל אִישׁ אֲשֶׁר יִדְּבֶנּוּ לִבּוֹ תִּקְחוּ אֶת תְּרוּמָתִי. וְיִקְחוּ לִי, מִי שֶׁרוֹצֶה לְהִשְׁתַּדֵּל בְּמִצְוָה וּלְהִשְׁתַּדֵּל בַּקָּדוֹשׁ בָּרוּךְ הוּא, צָרִיךְ שֶׁלֹּא יִשְׁתַּדֵּל בּוֹ בְּרֵיקָנוּת וּבְחִנָּם, אֶלָּא צָרִיךְ הָאָדָם לְהִשְׁתַּדֵּל בּוֹ כָּרָאוּי כְּפִי כֹחוֹ. וַהֲרֵי בֵּאַרְנוּ דָבָר זֶה בְּכַמָּה מְקוֹמוֹת, יָאֶה לָאָדָם לָשֵׂאת אוֹתָהּ הִשְׁתַּדְּלוּת שֶׁל הַקָּדוֹשׁ בָּרוּךְ הוּא, כְּמוֹ שֶׁנֶּאֱמַר (דברים טז) אִישׁ כְּמַתְּנַת יָדוֹ וְגוֹ'.</p>\n<p>וְאִם תֹּאמַר, הֲרֵי כָּתוּב (ישעיה נה) לְכוּ שִׁבְרוּ וֶאֱכֹלוּ וּלְכוּ שִׁבְרוּ בְּלוֹא כֶסֶף וּבְלוֹא מְחִיר יַיִן וְחָלָב, שֶׁהֲרֵי הוּא בְּחִנָּם, (והשתדלות בלא כסף) וְזוֹ הִשְׁתַּדְּלוּת לַקָּדוֹשׁ-בָּרוּךְ-הוּא? אֶלָּא הִשְׁתַּדְּלוּת שֶׁל הַתּוֹרָה - כָּל מִי שֶׁרוֹצֶה לִזְכּוֹת בָּהּ. הִשְׁתַּדְּלוּת כְּדֵי לָדַעַת אֶת הַקָּדוֹשׁ בָּרוּךְ הוּא - כָּל מִי שֶׁרוֹצֶה, זוֹכֶה בּוֹ בְּלִי שָׂכָר כְּלָל. אֲבָל הִשְׁתַּדְּלוּת בַּקָּדוֹשׁ בָּרוּךְ הוּא שֶׁעוֹמֶדֶת בְּמַעֲשֶׂה, אָסוּר לָקַחַת אוֹתָהּ לְחִנָּם וּבְרֵיקָנוּת, כִּי אֵינֶנּוּ זוֹכֶה כָּךְ בְּאוֹתוֹ מַעֲשֶׂה כְּלָל לְהַמְשִׁיךְ עָלָיו רוּחַ הַקֹּדֶשׁ, אֶלָּא רַק בְּשָׂכָר שָׁלֵם.</p>\n<p>בְּסֵפֶר הַכְּשָׁפִים שֶׁלִּמֵּד אַשְׁמְדַאי לִשְׁלֹמֹה הַמֶּלֶךְ - כָּל מִי שֶׁרוֹצֶה לְהִשְׁתַּדֵּל לְהַעֲבִיר מִמֶּנּוּ רוּחַ טֻמְאָה וְלִכְפּוֹת רוּחַ אַחֶרֶת, אוֹתוֹ הַמַּעֲשֶׂה שֶׁרוֹצֶה לְהִשְׁתַּדֵּל בּוֹ, צָרִיךְ לִקְנוֹת אוֹתוֹ בְּשָׂכָר מֻשְׁלָם בְּכָל מַה שֶּׁיִּרְצוּ מִמֶּנּוּ, בֵּין קָטָן בֵּין גָּדוֹל, מִשּׁוּם שֶׁרוּחַ הַטֻּמְאָה מִזְדַּמֶּנֶת תָּמִיד בְּחִנָּם וּבְרֵיקָנוּת, וְנִמְכֶּרֶת בְּלִי שָׂכָר, וְאוֹנֶסֶת בְּנֵי אָדָם לִשְׁרוֹת עֲלֵיהֶם, וּמְפַתָּה אוֹתָם לָדוּר עִמָּם. בְּכַמָּה פִתּוּיִים, בְּכַמָּה דְרָכִים, מַסְטָה אוֹתָם לָשִׂים דִּיּוּרָהּ עִמָּם.</p>\n<p>וְרוּחַ הַקֹּדֶשׁ אֵינָהּ כָּךְ, אֶלָּא בְּשָׂכָר שָׁלֵם, וּבְהִשְׁתַּדְּלוּת רַבָּה וּגְדוֹלָה, וּבְטִהוּר עַצְמוֹ וּבְטִהוּר מִשְׁכָּנוֹ, וּבִרְצוֹן לִבּוֹ וְנַפְשׁוֹ. וְהַלְוַאי שֶׁיָּכוֹל לְהַרְוִיחַ אוֹתוֹ שֶׁיָּשִׂים מְדוֹרוֹ עִמּוֹ, וְעִם כָּל זֶה שֶׁיֵּלֵךְ בְּדֶרֶךְ יָשָׁר, שֶׁלֹּא יִסְטֶה יָמִינָה וּשְׂמֹאלָה, וְאִם לֹא - מִיָּד מִסְתַּלֵּק מִמֶּנּוּ וּמִתְרַחֵק מִמֶּנּוּ, וְלֹא יוּכַל לְהַרְוִיחַ אוֹתוֹ כְּבַתְּחִלָּה.</p>\n<p>וְעַל זֶה כָּתוּב וְיִקְחוּ לִי תְּרוּמָה מֵאֵת כָּל אִישׁ, מֵאוֹתוֹ שֶׁנִּקְרָא אִישׁ, שֶׁמִּתְגַּבֵּר עַל יִצְרוֹ. וְכָל מִי שֶׁמִּתְגַּבֵּר עַל יִצְרוֹ נִקְרָא אִישׁ. אֲשֶׁר יִדְּבֶנּוּ לִבּוֹ, מַה זֶּה אֲשֶׁר יִדְּבֶנּוּ לִבּוֹ? אֶלָּא שֶׁיִּתְרַצֶּה בּוֹ הַקָּדוֹשׁ בָּרוּךְ הוּא, כְּמוֹ שֶׁנֶּאֱמַר (תהלים נז) לְךְ אָמַר לִבִּי. צוּר לְבָבִי. וְטוֹב לֵב. וַיִּיטַב לִבּוֹ. אֶת כֻּלָּם אָמַר בַּקָּדוֹשׁ-בָּרוּךְ-הוּא. אַף כָּאן - אֲשֶׁר יִדְּבֶנּוּ לִבּוֹ, מִמֶּנּוּ תִּקְחוּ אֶת תְּרוּמָתִי, שֶׁהֲרֵי שָׁם נִמְצָא וְלֹא בְמָקוֹם אַחֵר.</p>\n<p>וּמִנַּיִן יוֹדְעִים שֶׁהַקָּדוֹשׁ בָּרוּךְ הוּא מִתְרַצֶּה בּוֹ וְשָׂם בּוֹ אֶת מְדוֹרוֹ? כְּשֶׁרוֹאִים שֶׁרְצוֹן אוֹתוֹ הָאִישׁ (בשמחה וברצון הלב) לִרְדֹּף וּלְהִשְׁתַּדֵּל אַחַר הַקָּדוֹשׁ בָּרוּךְ הוּא בְּלִבּוֹ וְנַפְשׁוֹ וּרְצוֹנוֹ, וַדַּאי אָז שָׁם יוֹדְעִים שֶׁהַשְּׁכִינָה שׁוֹרָה בּוֹ, וְאָז צְרִיכִים לִקְנוֹת אֶת אוֹתוֹ הָאִישׁ בְּכֶסֶף שָׁלֵם, (ולהשתדל אחריו) לְהִתְחַבֵּר עִמּוֹ וְלִלְמֹד מִמֶּנּוּ. וְעַל זֶה הָרִאשׁוֹנִים הָיוּ אוֹמְרִים, וּקְנֵה לְךְ חָבֵר - בְּשָׂכָר שָׁלֵם יֵשׁ לִקְנוֹת אוֹתוֹ, כְּדֵי לִזְכּוֹת בַּשְּׁכִינָה. עַד כָּאן צָרִיךְ לִרְדֹּף אַחַר הַצַּדִּיק וְלִקְנוֹת אוֹתוֹ.</p>\n<p>אַף כָּךְ אוֹתוֹ הַצַּדִּיק צָרִיךְ לִרְדֹּף אַחַר הָרָשָׁע וְלִקְנוֹתוֹ בְּשָׂכָר שָׁלֵם, כְּדֵי שֶׁיַּעֲבִיר מִמֶּנּוּ אוֹתָהּ זֻהֲמָה וְיִכְפֶּה אֶת הַצַּד הָאַחֵר וְיַעֲשֶׂה לְנַפְשׁוֹ, כְּדֵי שֶׁיֵּחָשֵׁב עָלָיו כְּאִלּוּ הוּא בָּרָא אוֹתוֹ. וְזֶהוּ הַשֶּׁבַח שֶׁיִּתְעַלֶּה בּוֹ הַקָּדוֹשׁ בָּרוּךְ הוּא יוֹתֵר מִכָּל שֶׁבַח אַחֵר, וַעֲלִיָּה זוֹ יוֹתֵר מֵהַכֹּל. מָה הַטַּעַם? כִּי הוּא גָּרַם לִכְפּוֹת אֶת הַצַּד הָאַחֵר וּלְהַעֲלוֹת כְּבוֹד הַקָּדוֹשׁ בָּרוּךְ הוּא, וְעַל זֶה כָּתוּב בְּאַהֲרֹן, (מלאכי ב) ורבים השיב מעון. וכתוב (שם) בריתי היתה אתו.</p>\n<p>בֹּא וּרְאֵה, כָּל מִי שֶׁאוֹחֵז בְּיַד הָרָשָׁע (ושב אליו) וּמִשְׁתַּדֵּל בּוֹ לַעֲזב דֶּרֶךְ רָעָה, הוּא עוֹלֶה בְּשָׁלֹשׁ עֲלִיּוֹת מַה שֶּׁלֹּא עוֹלֶה כָּךְ שׁוּם אִישׁ אַחֵר: גּוֹרֵם לִכְפּוֹת אֶת הַצַּד הָאַחֵר., גּוֹרֵם שֶׁמִּתְעַלֶּה הַקָּדוֹשׁ בָּרוּךְ הוּא בִּכְבוֹדוֹ., וְגוֹרֵם לְהַעֲמִיד כָּל הָעוֹלָם בְּקִיּוּמוֹ לְמַעְלָה וּלְמַטָּה. וְעַל הָאִישׁ הַזֶּה כָּתוּב, בְּרִיתִי הָיְתָה אִתּוֹ הַחַיִּים וְהַשָּׁלוֹם. וְזוֹכֶה לִרְאוֹת בָּנִים לְבָנָיו, וְזוֹכֶה בָּעוֹלָם הַזֶּה וְזוֹכֶה לָעוֹלָם הַבָּא. כָּל בַּעֲלֵי הַדִּינִים לֹא יְכוֹלִים לָדוּן אוֹתוֹ בָּעוֹלָם הַזֶּה וּבָעוֹלָם הַבָּא. נִכְנָס בִּשְׁנֵים עָשָׂר שְׁעָרִים, וְאֵין מִי שֶׁיִּמְחֶה בְיָדוֹ. וְעַל זֶה כָּתוּב, (תהלים קיב) גִּבּוֹר בָּאָרֶץ יִהְיֶה זַרְעוֹ דּוֹר יְשָׁרִים יְבֹרָךְ. הוֹן וָעֹשֶׁר בְּבֵיתוֹ וְצִדְקָתוֹ עֹמֶדֶת לָעַד. זָרַח בַּחֹשֶׁךְ אוֹר לַיְשָׁרִים וְגוֹ'.</p>"],[9522011697,"<p>בַּגֹּרֶן - חֶדֶר הָעֶלְיוֹן, עוֹמְדִים שְׁלֹשָׁה (צדדי) גְוָנִים, וְהֵם לוֹהֲטִים בְּתוֹךְ שַׁלְהֶבֶת אַחַת, וְאוֹתָהּ הַשַּׁלְהֶבֶת יוֹצֵאת מִצַּד הַדָּרוֹם, שֶׁהוּא יָמִין. וְאוֹתָם גְּוָנִים נִפְרָדִים לִשְׁלֹשָׁה צְדָדִים. אֶחָד עוֹלֶה לְמַעְלָה, וְאֶחָד יוֹרֵד לְמַטָּה, וְאֶחָד שֶׁנִּרְאֶה וְנִגְנָז בְּשָׁעָה שֶׁהַשֶּׁמֶשׁ מְאִירָה.</p>\n<p>גָּוֶן אֶחָד, אוֹתוֹ שֶׁעוֹלֶה לְמַעְלָה, יוֹצֵא, וְאוֹתוֹ גָוֶן הוּא גָּוֶן לָבָן יוֹתֵר מִלֹּבֶן אַחֵר. וְנִכְנָס בְּאוֹתָהּ שַׁלְהֶבֶת וְנִצְבָּע מְעַט, וְלֹא נִצְבָּע, וְעוֹמֵד אוֹתוֹ גָוֶן לְמַעְלָה עַל רֹאשׁ אוֹתוֹ הַגֹּרֶן. וּבְשָׁעָה שֶׁיִּשְׂרָאֵל נִכְנָסִים לְבֵית הַכְּנֶסֶת וּמִתְפַּלְלִים תְּפִלּוֹתֵיהֶם, כְּשֶׁמַּגִּיעִים לְגָאַל יִשְׂרָאֵל וְסוֹמְכִים גְּאֻלָּה לִתְפִלָּה, אָז אוֹתוֹ גָוֶן לָבָן עוֹלֶה עַל רֹאשׁ הַגֹּרֶן וְנַעֲשֶׂה לוֹ כֶּתֶר (של קיום).</p>\n<p>וְהַכָּרוֹז יוֹצֵא וְאוֹמֵר: אַשְׁרֵיכֶם הָעָם הַקָּדוֹשׁ שֶׁעוֹשִׂים טוֹב לִפְנֵי הַקָּדוֹשׁ בָּרוּךְ הוּא. וְסוֹד זֶה - (ישעיה לח) וְהַטּוֹב בְּעֵינֶיךְ עָשִׂיתִי, שֶׁסּוֹמֵךְ גְּאֻלָּה לִתְפִלָּה. מִשּׁוּם שֶׁבַּשָּׁעָה הַזּוֹ שֶׁמַּגִּיעִים לִתְהִלּוֹת לְאֵל עֶלְיוֹן, שֶׁעוֹלֶה הַגָּוֶן הַזֶּה עַל רֹאשׁ אוֹתוֹ הַגֹּרֶן, מִתְעוֹרֵר הַצַּדִּיק לְהִתְחַבֵּר בְּמָקוֹם שֶׁצָּרִיךְ בְּאַהֲבָה וַחֲבִיבוּת, בְּחֶדְוָה וּבְרָצוֹן. וְכָל הָאֵיבָרִים כֻּלָּם מִתְחַבְּרִים בִּתְשׁוּקָה אַחַת אֵלֶּה בְּאֵלֶּה, עֶלְיוֹנִים בְּתַחְתּוֹנִים, וְכָל הַמְּנוֹרוֹת מְאִירוֹת וְלוֹהֲטוֹת, וְכֻלָּם עוֹמְדִים בְּחִבּוּר אֶחָד בַּצַּדִּיק הַזֶּה שֶׁנִּקְרָא טוֹב, כְּמוֹ שֶׁנֶּאֱמַר (ישעיה ג) אִמְרוּ צַדִּיק כִּי טוֹב, וְזֶה מְחַבֵּר אֶת כֻּלָּם בְּחִבּוּר אֶחָד. אָז הַכֹּל בְּלַחַשׁ לְמַעְלָה וּלְמַטָּה בִּנְשִׁיקוֹת שֶׁל רָצוֹן, וְהַדָּבָר עוֹמֵד בְּחִבּוּר שֶׁל בֵּית הַגֹּרֶן.</p>\n<p>כֵּיוָן שֶׁמַּגִּיעִים לָשִׂים שָׁלוֹם, אָז עוֹשֶׂה שִׁמּוּשׁ אוֹתוֹ נָהָר שֶׁיּוֹצֵא מֵעֵדֶן בַּגֹּרֶן הַזֶּה, וְאָז צְרִיכִים כֻּלָּם לָצֵאת מִלִּפְנֵי הַמֶּלֶךְ, וְלֹא צָרִיךְ אִישׁ וְלֹא אַחֵר לְהִמָּצֵא שָׁם וְלֹא לְבַקֵּשׁ בַּקָּשׁוֹת, אֶלָּא צָרִיךְ לִנְפֹּל עַל הַפָּנִים נְפִילַת אַפַּיִם. מָה הַטַּעַם? מִשּׁוּם שֶׁאוֹתָהּ שָׁעָה הִיא שָׁעָה שֶׁל שִׁמּוּשׁ, וְצָרִיךְ כָּל אִישׁ לְהִתְבַּיֵּשׁ מִלִּפְנֵי רִבּוֹנוֹ וּלְכַסּוֹת פָּנָיו בְּבוּשָׁה גְדוֹלָה, וּלְהַכְלִיל אֶת נַפְשׁוֹ בְּאוֹתוֹ שִׁמּוּשׁ שֶׁל הַנְּפָשׁוֹת, שֶׁנִּכְלָל אוֹתוֹ הַגֹּרֶן מִלְמַעְלָה וּמִלְּמַטָּה בִּנְפָשׁוֹת וְרוּחוֹת. אָז גָּוֶן אַחֵר שֶׁיּוֹרֵד לְמַטָּה עוֹמֵד וְאוֹחֵז בְּשִׁפּוּלֵי הַגֹּרֶן הַזֶּה.</p>\n<p>וְהַכָּרוֹז יוֹצֵא וְקוֹרֵא וְאוֹמֵר: עֶלְיוֹנִים וְתַחְתּוֹנִים, הָעִידוּ עֵדוּת, מִיהוּ שֶׁעוֹשֶׂה נְפָשׁוֹת וּמְזַכֶּה אֶת הָרְשָׁעִים? אוֹתוֹ שֶׁעֲטֶרֶת (שגראה לעטר אותו בעטרת) מַלְכוּת עַל רֹאשׁוֹ, אוֹתוֹ שֶׁרָאוּי לְהִכָּנֵס עַתָּה לִפְנֵי הַמֶּלֶךְ וְהַמַּלְכָּה, שֶׁהֲרֵי הַמֶּלֶךְ וְהַמַּלְכָּה שׁוֹאֲלִים עָלָיו.</p>\n<p>אָז מִזְדַּמְּנִים שְׁנֵי עֵדִים מֵאוֹתָם עֵינֵי ה' שֶׁמְּשׁוֹטְטוֹת בְּכָל הָעוֹלָם, וְעוֹמְדִים אַחַר הַפַּרְגּוֹד וּמְעִידִים עֵדוּת זוֹ, וְאוֹמְרִים: הֲרֵינוּ מְעִידִים עַל פְּלוֹנִי בֶּן פְּלוֹנִי. אַשְׁרֵי חֶלְקוֹ, שֶׁהֲרֵי אָבִיו יִזָּכֵר בִּגְלָלוֹ לְטוֹב. זֶהוּ עוֹשֶׂה נְפָשׁוֹת לְמַטָּה, נַפְשׁוֹת הָרְשָׁעִים שֶׁהָיוּ מֵהַצַּד הָאַחֵר. אָז מִתְיַקֵּר הַקָּדוֹשׁ בָּרוּךְ הוּא בְּחֶדְוָה שְׁלֵמָה.</p>\n<p>בְּאוֹתָהּ הַשָּׁעָה מִזְדַּמֵּן מְמֻנֶּה אֶחָד, שֶׁהוּא גִּזְבָּר עַל דְּיוֹקְנְאוֹת הַצַּדִּיקִים, בְּסוֹד שֶׁל שִׁמּוּשׁ הָאוֹתִיּוֹת שֶׁנִּקְרָא בְּסוֹד יְהוֹדִי\"עָם, בְּכֶתֶר שֶׁל שִׁמּוּשׁ הַשֵּׁם הַקָּדוֹשׁ. וְרוֹמֵז הַקָּדוֹשׁ בָּרוּךְ הוּא לְאוֹתוֹ מְמֻנֶּה, וּמֵבִיא אֶת דְּיוֹקַן אוֹתוֹ הָאִישׁ שֶׁעוֹשֶׂה נַפְשׁוֹת הָרְשָׁעִים וּמַעֲמִיד אוֹתוֹ לִפְנֵי הַמֶּלֶךְ וְהַמַּלְכָּה.</p>\n<p>וַאֲנִי מֵעִיד עָלַי שָׁמַיִם וָאָרֶץ, שֶׁבְּאוֹתָהּ שָׁעָה מוֹסְרִים לוֹ אוֹתוֹ הַדְּיוֹקָן, שֶׁהֲרֵי אֵין לְךְ כָּל צַדִּיק בָּעוֹלָם הַזֶּה שֶׁלֹּא חָקוּק דְּיוֹקְנוֹ לְמַעְלָה תַּחַת יַד אוֹתוֹ הַמְמֻנֶּה, וּמוֹסְרִים בְּיָדוֹ שִׁבְעִים מַפְתְּחוֹת שֶׁל כָּל גִּנְזֵי רִבּוֹנוֹ בָּהֶם. אָז הַמֶּלֶךְ מְבָרֵךְ אֶת אוֹתוֹ הַדְּיוֹקָן בְּכָל הַבְּרָכוֹת שֶׁבֵּרַךְ אֶת אַבְרָהָם כְּשֵׁעָשָׂה אֶת נַפְשׁוֹת הָרְשָׁעִים.</p>\n<p>וְהַקָֹּדוֹשׁ בָּרוּךָ הוּא רוֹמֵז לְאַרְבָּעָה מַחֲנוֹת עֶלְיוֹנִים, וְנוֹטְלִים אֶת אוֹתוֹ הַדְּיוֹקָן וְהוֹלְכִים עִמּוֹ, וְהוּא נִכְנָס לְשִׁבְעִים עוֹלָמוֹת גְּנוּזִים שֶׁלֹּא זָכָה בָהֶם אִישׁ אַחֵר, פְּרָט לְאוֹתָם גְּנָזִים לְאוֹתָם שֶׁעוֹשִׂים אֶת נַפְשׁוֹת הָרְשָׁעִים. וְאִלְמָלֵא הָיוּ יוֹדְעִים בְּנֵי אָדָם כַּמָּה תוֹעֶלֶת וּזְכוּת (גורמיםלצדיקים) וְזוֹכִים בִּגְלָלָם כְּשֶׁמְּזַכִּים אוֹתָם, הָיוּ הוֹלְכִים אַחֲרֵיהֶם וְרוֹדְפִים אוֹתָם כְּמִי שֶׁרוֹדֵף אַחַר הַחַיִּים.</p>\n<p>הֶעָנִי מְזַכֶּה אֶת בְּנֵי הָאָדָם בְּכַמָּה טוֹבוֹת, בְּכַמָּה גְנָזִים עֶלְיוֹנִים, וְלֹא כְּמִי שֶׁמְּזַכֶּה אֶת הָרְשָׁעִים. מַה בֵּין זֶה לָזֶה? אֶלָּא מִי שֶׁמִּשְׁתַּדֵּל אַחַר הֶעָנִי, הוּא מַשְׁלִים חַיִּים לְנַפְשׁוֹ וְגוֹרֵם לוֹ לְהִתְקַיֵּם, וְזוֹכֶה בִּגְלָלוֹ לְכַמָּה טוֹבוֹת לְאוֹתוֹ הָעוֹלָם. וּמִי שֶׁמִּשְׁתַּדֵּל אַחַר הָרָשָׁע, הוּא מַשְׁלִים יוֹתֵר. עוֹשֶׂה לַצַּד הָאַחֵר שֶׁל אֱלֹהִים אֲחֵרִים שֶׁיִּתְכּוֹפֵף וְלֹא יִשְׁלֹט, וּמַעֲבִיר אוֹתוֹ מִשִּׁלְטוֹנוֹ. עוֹשֶׂה שֶׁמִּתְעַלֶּה הַקָּדוֹשׁ בָּרוּךְ הוּא עַל כִּסֵּא כְבוֹדוֹ. עוֹשֶׂה לְאוֹתוֹ הָרָשָׁע נֶפֶשׁ אַחֶרֶת. אַשְׁרֵי חֶלְקוֹ.</p>\n<p>גָּוֶן אַחֵר שֶׁנִּרְאֶה וְלֹא נִרְאֶה, בְּשָׁעָה שֶׁמַּגִּיעִים יִשְׂרָאֵל לְסֵדֶר הַקְּדֻשָּׁה, אָז הַגָּוֶן הַגָּנוּז הַזֶּה, וְיוֹצֵא, מִשּׁוּם שֶׁהִיא הַקְּדֻשָּׁה שֶׁמְּקַדְּשִׁים יִשְׂרָאֵל יוֹתֵר עַל מַלְאָכִים הָעֶלְיוֹנִים, שֶׁהֵם חֲבֵרִים עִמָּם. וְהַגָּוֶן הַזֶּה מֵאִיר וְנִרְאֶה בְּשָׁעָה שֶׁיִּשְׂרָאֵל מְקַדְּשִׁים הַקְּדֻשָּׁה הַזּוֹ, (שהרי מסימים ישראל עד שלא ישגיחו וכו') עַד שֶׁמְּסַיְּמִים יִשְׂרָאֵל, כְּדֵי שֶׁלֹּא יַשְׁגִּיחוּ הַמַּלְאָכִים הָעֶלְיוֹנִים וְיַעֲנִישׁוּ אוֹתָם לְמַעְלָה, וְלֹא יְקַטְרְגוּ עֲלֵיהֶם.</p>\n<p>עֶלְיוֹנִים וְתַחְתּוֹנִים הַקְשִׁיבוּ, מִיהוּ גַּס רוּחַ בְּדִבְרֵי תוֹרָה, מִיהוּ שֶׁכָּל דְּבָרָיו לְהִתְגַּבֵּהַּ בְּדִבְרֵי תוֹרָה, מִשּׁוּם שֶׁשָּׁנִינוּ, שֶׁהָאָדָם צָרִיךְ לִהְיוֹת שָׁפָל בָּעוֹלָם הַזֶּה בְּדִבְרֵי תוֹרָה, שֶׁהֲרֵי אֵין גַּבְהוּת בַּתּוֹרָה אֶלָּא בָּעוֹלָם הַבָּא.</p>\n<p>בִּקְדֻשָּׁה זוֹ צָרִיךְ לְהִשָּׁמֵר וְלִגְנֹז אוֹתָהּ בֵּינֵינוּ כְּדֵי שֶׁנִּתְקַדֵּשׁ בְּתוֹךְ הַקְּדֻשָּׁה בָּרֹאשׁ וּבַסּוֹף יוֹתֵר מֵאוֹתָן קְדֻשּׁוֹת שֶׁאוֹמְרִים עִמָּנוּ מַלְאָכִים עֶלְיוֹנִים. הַקְּדֻשָּׁה שֶׁאָנוּ מְקַדְּשִׁים בַּשֶּׁבַח שֶׁאָנוּ מְשַׁבְּחִים לַמַּלְאָכִים הָעֶלְיוֹנִים. וּמִשּׁוּם שֶׁבַח זֶה מַרְשִׁים לָנוּ לְהִכָּנֵס לְתוֹךְ הַשְּׁעָרִים הָעֶלְיוֹנִים, וְעַל זֶה אָנוּ אוֹמְרִים קְדֻשָּׁה זוֹ בִּלְשׁוֹן הַקֹּדֶשׁ וּמַשְׁאִירִים אוֹתָנוּ בְּאַהֲבָה לְהִכָּנֵס לַשְּׁעָרִים שֶׁלְּמַעְלָה, מִתּוֹךְ שֶׁאָנוּ מְשַׁבְּחִים אוֹתָם בַּסִּדּוּר שֶׁלָּהֶם (שלנו), וְלָכֵן אָנוּ נוֹטְלִים יוֹתֵר קְדֻשּׁוֹת, וְנִכְנָסִים לַשְּׁעָרִים הָעֶלְיוֹנִים.</p>\n<p>וְאִם תֹּאמַר, זוֹהִי רַמָּאוּת - לֹא כָּךְ! אֶלָּא הַמַּלְאָכִים הָעֶלְיוֹנִים הֵם יוֹתֵר קְדוֹשִׁים מֵאִתָּנוּ, וְהֵם נוֹטְלִים יוֹתֵר קְדֻשָּׁה, וְאִלְמָלֵא שֶׁאָנוּ נוֹטְלִים וּמוֹשְׁכִים עָלֵינוּ הַקְּדֻשּׁוֹת הַלָּלוּ, לֹא נוּכַל לִהְיוֹת חֲבֵרִים עִמָּם, וּכְבוֹד הַקָּדוֹשׁ בָּרוּךְ הוּא לֹא יִשְׁתַּלֵּם לְמַעְלָה וּלְמַטָּה בִּזְמַן אֶחָד, וְעַל זֶה אָנוּ מִשְׁתַּדְּלִים לִהְיוֹת עִמָּם חֲבֵרִים, וְיִתְעַלֶּה כְּבוֹד הַקָּדוֹשׁ בָּרוּךְ הוּא לְמַעְלָה וּלְמַטָּה בִּזְמַן אֶחָד.</p>\n<p>הַקְּדֻשָּׁה שֶׁבַּסּוֹף הִיא תַּרְגּוּם, כְּמוֹ שֶׁבֵּאַרְנוּ, וְזֶה אֲפִלּוּ יָחִיד יוּכַל לוֹמַר אוֹתָהּ, אוֹתָם דִּבְרֵי הַתַּרְגּוּם. אֲבָל דִּבְרֵי לְשׁוֹן הַקֹּדֶשׁ שֶׁל הַקְּדֻשָּׁה אֵינָם אֶלָּא בַּעֲשָׂרָה, כִּי הַשְּׁכִינָה מִתְחַבֶּרֶת עִם לְשׁוֹן הַקֹּדֶשׁ, וּלְכָל קְדֻשָּׁה שֶׁהַשְּׁכִינָה בָּאָה, אֵין זֶה אֶלָּא בַּעֲשָׂרָה, שֶׁכָּתוּב (ויקרא כב) וְנִקְדַּשְׁתִּי בְּתוֹךְ בְּנֵי יִשְׂרָאֵל וְגוֹ'. בְּנֵי יִשְׂרָאֵל הֵם לְשׁוֹן הַקֹּדֶשׁ וַדַּאי, וְלֹא שְׁאָר עַמִּים שֶׁיֵּשׁ לָהֶם לָשׁוֹן אַחֶרֶת.</p>\n<p>וְאִם תֹּאמַר, הֲרֵי הַקְּדֻשָּׁה שֶׁל הַקַּדִּישׁ, שֶׁהִיא תַּרְגּוּם, לָמָּה אֵינָהּ בְּיָחִיד? בֹּא וּרְאֵה, קְדֻשָּׁה זוֹ אֵינָהּ כִּשְׁאָר הַקְּדֻשּׁוֹת שֶׁהֵם מְשַׁלְּשִׁים. אֲבָל קְדֻשָּׁה זוֹ הִיא עוֹלָה בְּכָל הַצְּדָדִים, לְמַעְלָה וּלְמַטָּה וּלְכָל צִדְדֵי הָאֱמוּנָה, וְשׁוֹבֶרֶת מַנְעוּלִים וְחוֹתָמוֹת שֶׁל בַּרְזֶל וּקְלִפּוֹת רָעוֹת (וזהו השבח שמתעלהבו כבוד הקדושברוך הוא יותר משבח אחר. והתעלות זו יתרה מהכל, מה הטעם, ' משום שהוא גורם להרפות את הצד האחר ולהעבירו) לְהַעֲלוֹת אֶת כְּבוֹד הַקָּדוֹשׁ בָּרוּךְ הוּא עַל הַכֹּל, וְאָנוּ רוֹצִים לוֹמַר אוֹתָהּ בַּלָּשׁוֹן שֶׁל הַצַּד הָאַחֵר וּלְהָשִׁיב בְּכֹחַ חָזָק: אָמֵן יְהֵא שְׁמֵיהּ רַבָּא מְבָרַךְ, כְּדֵי שֶׁיִּשְׁתַּבֵּר כֹּחוֹ שֶׁל הַצַּד הָאַחֵר, וְיִתְעַלֶּה הַקָּדוֹשׁ בָּרוּךְ הוּא בִּכְבוֹדוֹ עַל הַכֹּל. וּכְשֶׁנִּשְׁבָּר בִּקְדֻשָּׁה זוֹ כֹּחוֹ שֶׁל הַצַּד הָאַחֵר, הַקָּדוֹשׁ בָּרוּךְ הוּא מִתְעַלֶּה בִּכְבוֹדוֹ, וְנִזְכָּר לְבָנָיו, וְנִזְכָּר לִשְׁמוֹ. וּמִשּׁוּם שֶׁהַקָּדוֹשׁ בָּרוּךְ הוּא מִתְעַלֶּה בִּכְבוֹדוֹ בַּקְּדֻשָּׁה הַזּוֹ, אֵינָהּ אֶלָּא בַּעֲשָׂרָה.</p>\n<p>וּבְלָשון זוֹ עַל כָּרְחוֹ שֶׁל הַצַּד הָאַחֵר הוּא נִכְפֶּה, וְנִשְׁבָּר כֹּחוֹ, וּמִתְעַלֶּה כְּבוֹד הַקָּדוֹשׁ בָּרוּךְ הוּא וְשׁוֹבֵר מַנְעוּלִים וְחוֹתָמוֹת וְשַׁלְשְׁלָאוֹת חֲזָקוֹת וּקְלִפּוֹת רָעוֹת, וְנִזְכָּר הַקָּדוֹשׁ בָּרוּךְ הוּא אֶת שְׁמוֹ וְאֶת בָּנָיו. אַשְׁרֵיהֶם הָעָם הַקָּדוֹשׁ שֶׁהַקָּדוֹשׁ בָּרוּךְ הוּא נָתַן לָהֶם תּוֹרָה קְדוֹשָׁה לִזְכּוֹת בָּהּ לָעוֹלָם הַבָּא.</p>\n<p>אָמַר רַבִּי שִׁמְעוֹן לַחֲבֵרִים, אַשְׁרֵיכֶם לָעוֹלָם הַבָּא, וְכֵיוָן שֶׁהִתְחַלְנוּ בִדְבָרִים שֶׁל כֶּתֶר הַמַּלְכוּת הָעֶלְיוֹנָה, אוֹמֵר אֲנִי בִּשְׁבִילְכֶם (בתוככם), וְהַקָּדוֹשׁ בָּרוּךְ הוּא יִתֵּן לָכֶם שָׂכָר בְּאוֹתוֹ הָעוֹלָם. וְאוֹתוֹ הֶבֶל פִּיכֶם יִתְעַלֶּה לְמַעְלָה כְּאִלּוּ אַתֶּם הַמְעוֹרְרִים אֶת הַדְּבָרִים הַלָּלוּ.</p>"],[9522011698,"<p>פָּתַח וְאָמַר, וְזאת הַתְּרוּמָה אֲשֶׁר תִּקְחוּ מֵאִתָּם זָהָב וָכֶסֶף וּנְחֹשֶׁת. פָּסוּק זֶה הוּא לְצַד עֶלְיוֹן, וְהוּא לְצַד תַּחְתּוֹן. הוּא לְצַד עֶלְיוֹן - בְּצַד הַקְּדֻשָּׁה, וְהוּא לְצַד תַּחְתּוֹן - בַּצַּד הָאַחֵר. בּא וּרְאֵה, כְּשֶׁבָּרָא הַקָּדוֹשׁ בָּרוּךְ הוּא אֶת הָעוֹלָם, הִתְחִיל לִבְרֹא מִצַּד הַכֶּסֶף, שֶׁהוּא לְיָמִין, מִשּׁוּם שֶׁאוֹתוֹ כֶסֶף הָיָה מִלְמַעְלָה. וּבְמַעֲשֵׂה הַמִּשְׁכָּן, שֶׁהוּא כְּמוֹ שֶׁלּוֹ, הִתְחִיל מִצַּד שְׂמֹאל וְאַחַר כָּךְ מִצַּד יָמִין, מִשּׁוּם שֶׁהַמִּשְׁכָּן הָיָה מִצַּד שְׂמֹאל, וְלָכֵן הִתְחִיל כָּאן מִצַּד מִשְּׂמֹאל, וְשָׁם מִצַּד יָמִין, וְזאת הַתְּרוּמָה וְגוֹ'.</p>"],[9522011699,"<p>וְכָתוּב (תהלים נה) עֶרֶב וָבֹקֶר וְצָהֳרַיִם וְגוֹ'. פָּסוּק זֶה פֵּרְשׁוּהוּ וְנִתְבָּאֵר, אֲבָל כָּאן עִדָּן וְעִדָּנִים הוּא שֶׁל תְּפִלַּת כָּל הַיּוֹם, וְהַחֲבֵרִים הִתְעוֹרְרוּ בִּשְׁלֹשֶׁת הַזְּמַנִּים הַלָּלוּ. עֶרֶב זוֹהִי אַסְפַּקְלַרְיָה שֶׁלֹּא מְאִירָה, וּבֹקֶר זוֹהִי אַסְפַּקְלַרְיָה הַמְּאִירָה, וְצָהֳרַיִם - (אין זה מקום שגקרא חשך, אלא הוא מקום שעומד בין זה לזה, אבל הזמן של תפלת מנחה) מָקוֹם שֶׁהוּא נִקְרָא חֹשֶׁךְ, שֶׁאָחוּז בָּעֶרֶב וְעוֹמֵד זֶה עִם זֶה.</p>\n<p>וּמַה שֶּׁנֶּאֱמַר צָהֳרַיִם, שֶׁהוּא תֹקֶף חֹזֶק הַשֶּׁמֶשׁ, הוּא נָקַט בְּלָשׁוֹן מְעֻלָּה. וְכָךְ הִיא הַדֶּרֶךְ - לְאִישׁ שָׁחֹר קוֹרְאִים לוֹ לָבָן, וְנָקַט לָשׁוֹן מְעֻלָּה, וְלִפְעָמִים קוֹרְאִים לְלָבָן שָׁחֹר, שֶׁכָּתוּב (במדבר יב) כִּי אִשָּׁה כֻשִׁית לָקָח. (עמוס ט) הֲלוֹא כִבְנֵי כֻשִׁיִּים אַתֶּם לִי וְגוֹ'.</p>\n<p>עָרֶב זֶה - תְּפִלַּת עַרְבִית. וּמִשּׁוּם שֶׁבָּעֶרֶב הַזֶּה מִתְעָרֵב הַצַּד הָאַחֵר שֶׁמַּחֲשִׁיךְ אֶת אוֹרוֹ וְשׁוֹלֵט בַּלַּיְלָה, שָׂמוּ לוֹ רְשׁוּת, וְאֵין לוֹ זְמַן קָבוּעַ. אֵמוּרִים וּפְרָדִים מִתְאַכְּלִים בַּזְּמַן הַזֶּה, וּמִכָּאן נִזּוֹנִים כַּמָּה קְבוּצוֹת שֶׁל שָׂרִים שֶׁיּוֹצְאִים וְשׁוֹלְטִים בַּלַּיְלָה.</p>\n<p>וְאִם תֹּאמַר, אִם כָּךְ, הֲרֵי שָׁנִינוּ שֶׁכָּל אוֹתָם בַּעֲלֵי הַצַּד הָאַחֵר שֶׁל רוּחַ הַטֻּמְאָה לֹא שׁוֹלְטִים בָּאָרֶץ הַקְּדוֹשָׁה, וַהֲרֵי מְעוֹרְרִים אוֹתָם יִשְׂרָאֵל בָּזֶה, וְאָסוּר לְעוֹרְרָם לִשְׁרוֹת עַל הָאָרֶץ הַקְּדוֹשָׁה.</p>\n<p>אֶלָּא בַּלַּיְלָה אוֹתוֹ הֶעָשָׁן עוֹלֶה, וְלֹא עוֹלֶה כְּמוֹ שֶׁבְּקָרְבָּן אַחֵר, שֶׁהָיָה הֶעָשָׁן עוֹלֶה בְּדֶרֶךְ יָשָׁר, וְכָאן הָיָה עוֹלֶה אוֹתוֹ עָשָׁן לְנֶקֶב אֶחָד שֶׁל הַצָּפוֹן, שֶׁשָּׁם כָּל מְדוֹרִים שֶׁל רוּחוֹת רָעוֹת. וְכֵיוָן שֶׁאוֹתוֹ עָשָׁן עוֹלֶה וּמְעַקֵּם דֶּרֶךְ לְאוֹתוֹ צַד, כֻּלָּם הָיוּ נִזּוֹנִים וְעוֹמְדִים וְנִכְנָסִים לִמְקוֹמָם, וְלֹא הָיוּ יוֹצְאִים וְשׁוֹלְטִים בָּעוֹלָם.</p>\n<p>מְמֻנֶּה אֶחָד עוֹמֵד לְאוֹתוֹ הַצַּד שֶׁל אוֹתוֹ נֶקֶב שֶׁבַּצָּפוֹן, בְּכָל אוֹתָם קְבוּצוֹת שֶׁל שָׂרִים, וּשְׁמוֹ סַנְגִירְיָ\"א, וּבְשָׁעָה שֶׁאוֹתוֹ עָשָׁן מְעַקֵּם דַּרְכּוֹ וְעוֹלֶה, הַמְמֻנֶּה הַזֶּה וְשִׁשִּׁים אֶלֶף רִבּוֹא מַחֲנוֹת אֲחֵרוֹת, כֻּלָּם מִתְעַתְּדִים לְקַבְּלוֹ וּלְהִזּוֹן מִמֶּנּוּ, וְעוֹמְדִים בְּאוֹתוֹ נֶקֶב, וְנִכְנָסִים בְּפֶתַח אֶחָד שֶׁנִּקְרָא קֶרִי, וְזֶהוּ סוֹד הַכָּתוּב (ויקראכו) וְאִם תֵּלְכוּ עִמִּי קֶרִי וְגוֹ'. וְכָתוּב, וְהָלַכְתִּי עִמָּכֶם בַּחֲמַת קֶרִי. בְּאוֹתוֹ רֹגֶז הַיּוֹצֵא מֵהַפֶּתַח שֶׁל קֶרִי.</p>\n<p>וְאֵלּוּ הֵם שֶׁמְּשׁוֹטְטִים בַּלַּיְלָה, וּבְשָׁעָה שֶׁהַנְּשָׁמוֹת יוֹצְאוֹת לַעֲלוֹת לְהֵרָאוֹת לְמַעְלָה, הֵם יוֹצְאִים וּמְקַטְרְגִים בָּהֶם, וְלֹא יְכוֹלִים לַעֲלוֹת וּלְהֵרָאוֹת לְמַעְלָה, פְּרָט לְאוֹתָם חֲסִידִים קְדוֹשִׁים עֶלְיוֹנִים שֶׁהֵם בּוֹקְעִים רְקִיעִים וַאֲוִירִים וְעוֹלִים, וּקְבוּצוֹת הַשָּׂרִים הַלָּלוּ יוֹצְאִים וּמוֹדִיעִים דְּבָרִים כּוֹזְבִים לִבְנֵי אָדָם, וְנִרְאִים לָהֶם בִּדְמֻיּוֹת אֲחֵרוֹת, וְצוֹחֲקִים עֲלֵיהֶם, עַד שֶׁשּׁוֹפְכִים זֶרַע, וְנִקְרָאִים בַּעֲלֵי קֶרִי, מִשּׁוּם שֶׁאוֹתָם שֶׁיּוֹצְאִים מִפֶּתַח הַקֶּרִי גָּרְמוּ לָהֶם.</p>\n<p>וּבְשָׁעָה שֶׁמִּתְאַכְּלִים אֵמוּרִים וּפְדָרִים, אוֹתוֹ עָשָׁן הָיָה מַרְוֶה אוֹתָם וְזָן אוֹתָם. כְּפִי כְבוֹדָם כָּךְ מְזוֹנָם מַה שֶּׁרָאוּי לָהֶם. וּבָזֶה לֹא יָצְאוּ וְלֹא מְשׁוֹטְטִים בָּאָרֶץ הַקְּדוֹשָׁה.</p>\n<p>עָרֶב, כְּמוֹ שֶׁנֶּאֱמַר (שמות יב) וְגַם עֵרֶב רַב עָלָה אִתָּם. שֶׁכָּל אוֹתָן קְבוּצוֹת שָׂרִים מִתְעָרְבִים בְּשִׁלְטוֹן הַלַּיְלָה, וְלָכֵן לֹא שָׂמוּ אֶת תְּפִלַּת עַרְבִית חוֹבָה, שֶׁאֵין מִי שֶׁיָּכוֹל לְתַקְּנָהּ כְּמוֹ יַעֲקֹב, שֶׁהוּא הָיָה בַּעַל (מטהר) הַמִּשְׁכָּן וּמְתַקֵּן אוֹתוֹ כָּרָאוּי.</p>\n<p>וְאַף עַל גַּב שֶׁהִיא רְשׁוּת, תְּפִלָּה זוֹ הִיא כְּדֵי לְהָגֵן עָלֵינוּ מִתּוֹךְ פַּחַד בַּלֵּילוֹת, מִתּוֹךְ פַּחַד שֶׁל כַּמָּה צְדָדִים שֶׁל הַגֵּיהִנֹּם, שֶׁהֲרֵי בְּאוֹתָהּ שָׁעָה טוֹרְדִים אֶת הָרְשָׁעִים בַּגֵּיהִנֹּם עַל כָּל אֶחָד שְׁנַיִם מֵאֲשֶׁר בַּיּוֹם. וְלָכֵן מַקְדִּימִים יִשְׂרָאֵל לוֹמַר \"וְהוּא רַחוּם\", שֶׁהוּא מִשּׁוּם פַּחַד הַגֵּיהִנֹּם. וְלֹא דִין אַחֵר אָסוּר לְעוֹרְרוֹ, שֶׁנִּרְאֶה שֶׁהֲרֵי אֵין לוֹ רְשׁוּת לְשַׁבָּת לְהַעֲבִיר אֶת הַדִּין מֵהָעוֹלָם.</p>\n<p>וּפַחַד שֶׁל קִטְרוּג הַנְּשָׁמוֹת, כְּשֶׁרוֹצוֹת לַעֲלוֹת לְמַעְלָה כְּדֵי לְהֵרָאוֹת לִפְנֵי רִבּוֹנָם. וְלָכֵן אָנוּ מַקְדִּימִים \"שׁוֹמֵר אֶת עַמּוֹ יִשְׂרָאֵל לָעַד אָמֵן\". פַּחַד שֶׁל כַּמָּה מַזִּיקִים וְקִטְרוּגִים שֶׁנִּמְצָאִים בַּלַּיְלָה, וְיֵשׁ לָהֶם רְשׁוּת לְהַזִּיק לְמִי שֶׁיּוֹצֵא הַחוּצָה מִשַּׁעַר בֵּיתוֹ, וְלָכֵן אָנוּ מַקְדִּימִים \"וּשְׁמֹר צֵאתֵנוּ וּבֹאֵנוּ\".</p>\n<p>וְעַל כָּל זֶה, מִתּוֹךְ פַּחַד שֶׁל כָּל זֶה אָנוּ מַפְקִידִים הַגּוּפוֹת, הָרוּחוֹת וְהַנְּשָׁמוֹת לַמַּלְכוּת הָעֶלְיוֹנָה, שֶׁשִּׁלְטוֹן הַכֹּל בְּיָדֶיהָ, וְעַל זֶה תְּפִלַּת עַרְבִית בְּכָל לַיְלָה וְלַיְלָה. עַתָּה שֶׁקָרְבָּנוֹת וּמִזְבְּחוֹת לֹא נִמְצְאוּ, אָנוּ עוֹשִׂים כָּל הַתִּקּוּנִים שֶׁאָנוּ עוֹשִׂים עַל הַסּוֹד הַזֶּה.</p>\n<p>בַּחֲצוֹת הַלַּיְלָה, כְּשֶׁמִּתְעוֹרֶרֶת רוּחַ צָפוֹן, מַכָּה בְּכָל אוֹתָם מְדוֹרֵי הָרוּחוֹת הָרָעוֹת, וְשׁוֹבֵר אֶחָד (סלע חזק) אֶת הַצַּד הָאַחֵר, וְנִכְנָס וּמְשׁוֹטֵט לְמַעְלָה וָמַטָּה, וְכָל אוֹתָן קְבוּצוֹת שֶׁל מְחַבְּלִים נִכְנָסוֹת לִמְקוֹמָן, וְנִשְׁבָּר כֹּחָן וְלֹא שׁוֹלְטוֹת. וְאָז הַקָּדוֹשׁ בָּרוּךְ הוּא נִכְנָס לְהִשְׁתַּעֲשֵׁעַ עִם הַצַּדִּיקִים בְּגַן עֵדֶן, וַהֲרֵי נִתְבָּאֵר.</p>\n<p>כְּשֶׁבָּא הַבֹּקֶר, אוֹר הַנֵּר שֶׁשָּׁלַט בַּלַּיְלָה נִגְנַז מִלִּפְנֵי אוֹר הַיּוֹם, וְאָז הַבֹּקֶר שׁוֹלֵט, וּמָעֳבָר שִׁלְטוֹנוֹ שֶׁל הָעֶרֶב. (ואז) הַבֹּקֶר הַזֶּה הוּא בֹּקֶר שֶׁל אוֹר רִאשׁוֹן, הַבּקֶר הַזֶּה מַשְׁלִים טוֹב לְכָל הָעוֹלָמִים. מִמֶּנּוּ נִזּוֹנִים עֶלְיוֹנִים וְתַחְתּוֹנִים. זֶה מַשְׁקֶה אֶת הַגָּן. זוֹהִי שְׁמִירָה שֶׁל כָּל הָעוֹלָם.</p>\n<p>כָּאן הַסּוֹד לְיוֹדְעֵי מִדִּין: מִי שֶׁרוֹצֶה לָצֵאת לַדֶּרֶךְ, יָקוּם בַּנֹּגַהּ, וְיַשְׁגִּיחַ בְּהִתְבּוֹנְנוּת לְפִי שָׁעָה לְצַד מִזְרָח, וְיִרְאֶה כְּמַרְאֵה אוֹתִיּוֹת שֶׁמַּכּוֹת בָּרָקִיעַ, זוֹ עוֹלָה וְזוֹ יוֹרֶדֶת, וְאֵלֶּה הֵם הִתְנוֹצְצוּת הָאוֹתִיּוֹת שֶׁנִּבְרְאוּ בָהֶם שָׁמַיִם וָאָרֶץ.</p>\n<p>אִם הוּא יוֹדֵעַ בְּסוֹד אוֹתָן הָאוֹתִיּוֹת, שֶׁהֵם סוֹד הַשֵּׁם הַקָּדוֹשׁ שֶׁל אַרְבָּעִים וּשְׁתַּיִם אוֹתִיּוֹת, וְיַזְכִּירֵן כָּרָאוּי בִּרְצוֹן הַלֵּב, יִרְאֶה תּוֹךְ אוֹר הַנֹּגַהּ שֶׁל הָרָקִיעַ שֵׁשׁ יוֹדִי\"ם, שָׁלֹשׁ לְצַד יָמִין וְשָׁלֹשׁ לְצַד שְׂמֹאל, וְשָׁלֹשׁ וָוִי\"ם שֶׁעוֹלוֹת וְיוֹרְדוֹת וְנוֹצְצוֹת בָּרָקִיעַ. וְהֵן הָאוֹתִיּוֹת שֶׁל בִּרְכַּת כֹּהֲנִים, וְאָז יִתְפַּלֵּל תְּפִלָּתוֹ וְיֵצֵא לַדֶּרֶךְ, וַדַּאי שְׁכִינָה מַקְדִּימָה עִמּוֹ. אַשְׁרֵי חֶלְקוֹ.</p>\n<p>כְּשֶׁבָּא הַבּקֶר הַזֶּה, עַמּוּד אֶחָד נָעוּץ בְּצַד דָּרוֹם לְתוֹךְ מְתִיחַת הָרָקִיעַ שֶׁעַל גַּבֵּי הַגָּן, חוּץ מֵאוֹתוֹ עַמּוּד שֶׁנָּעוּץ בְּאֶמְצַע הַגָּן. וְעַמּוּד זֶה מֵאִיר בְּאוֹר שֶׁל שְׁלֹשָׁה גְוָנִים מְרֻקָּם בְּאַרְגָּמָן. בְּאוֹתוֹ הָעַמּוּד קַיָּם עָנָף אֶחָד, וּבְאוֹתוֹ עָנָף נִזְדַּמְּנוּ שָׁלֹשׁ צִפֳּרִים, מִתְעוֹרְרוֹת צִפְצוּף לְשַׁבֵּחַ.</p>"],[9522011700,"<p>פָּתַח אֶחָד וְאָמַר, (תהלים קיג) הַלְלוּיָהּ הַלְלוּ עַבְדֵי ה' הַלְלוּ אֶת שֵׁם ה'. פּוֹתֵחַ הַשֵּׁנִי וְאוֹמֵר, יְהִי שֵׁם ה' מְבֹרָךְ מֵעַתָּה וְעַד עוֹלָם. פּוֹתֵחַ הַשְּׁלִישִׁי וְאוֹמֵר, מִמִּזְרַח שֶׁמֶשׁ עַד מְבוֹאוֹ מְהֻלָּל שֵׁם ה'. אָז הַכָּרוֹז מַקְדִּים וְקוֹרֵא, הִזְדַּמְּנוּ קְדוֹשִׁים עֶלְיוֹנִים, אוֹתָם הַמְשַׁבְּחִים אֶת רִבּוֹנָם הִתְתַּקְּנוּ לְשֶׁבַח הַיּוֹם. וְאָז נִפְרָדִים הַיּוֹם מֵהַלַּיְלָה. אַשְׁרֵי חֶלְקוֹ שֶׁל מִי שֶׁקָּם בַּבּקֶר מִתּוֹךְ תִּשְׁבַּחְתָּהּ שֶׁל תּוֹרָה שֶׁלָּמַד בַּלַּיְלָה, בְּאוֹתוֹ זְמַן שֶׁל תְּפִלַּת הַבֹּקֶר.</p>\n<p>כָּתוּב, (ישעיה כא) אָמַר שֹׁמֵר אָתָא בקֶר וְגַם לָיְלָה אִם תִּבְעָיוּן בְּעָיוּ שֻׁבוּ אֵתָיוּ. פָּסוּק זֶה פֵּרְשׁוּהוּ עַל גָּלוּת יִשְׂרָאֵל שֶׁיּוֹשְׁבִים בְּתוֹךְ בְּנֵי שֵׂעִיר, וְיִשְׂרָאֵל אוֹמְרִים לַקָּדוֹשׁ- בָּרוּךְ-הוּא: שֹׁמֵר מַה מִלַּיְלָה - מַה יִּהְיֶה עָלֵינוּ מֵהַגָּלוּת הַזּוֹ שֶׁדּוֹמָה לְחֶשְׁכַת הַלַּיְלָה?. מַה כָּתוּב? אָמַר שֹׁמֵר. זֶה הַקָּדוֹשׁ בָּרוּךְ הוּא. אָתָא בֹקֶר - כְּבָר הֶאַרְתִּי לְךְ בְּגָלוּת מִצְרַיִם, וְהֶעֱלֵיתִי אֶתְכֶם וְקֵרַבְתִּיכֶם לַעֲבוֹדָתִי, וְנָתַתִּי לָכֶם תּוֹרָה כְּדֵי שֶׁתִּזְכּוּ לְחַיֵּי עוֹלָם. עֲזַבְתֶּם תּוֹרָתִי, וְגַם לָיְלָה - הִכְנַסְתִּיכֶם לְגָלוּת (בבל והעליתיכם. עזבתם תורתי כמקדם, והכנסתי אתכם לגלות) כְּמִקֹּדֶם. אִם תִּבְעָיוּן בְּעָיוּ - כְּמוֹ שֶׁנֶּאֱמַר (שם לד) דִּרְשׁוּ מֵעַל סֵפֶר ה' וּקְרָאוּ, וְשָׁם תִּמְצְאוּ בַּמֶּה תְּלוּיָה גָּלוּתְכֶם וּגְאֻלַּתְכֶם. וּכְשֶׁתִּבְעָיוּן בָּהּ, הִיא תֹּאמַר וְתַכְרִיז לִפְנֵיכֶם: שֻׁבוּ אֵתָיוּ. שׁוּבוּ בִּתְשׁוּבָה שְׁלֵמָה, וּמִיָּד אֵתָיוּ, וְקִרְבוּ אֵלַי. (ובסוד הפסוק הזה)</p>\n<p>וּבְפָסוּק זֶה כָּתוּב, מַשָּׂא דּוּמָה. וְסוֹד זֶה בְּשֵׁשׁ דְּרָגוֹת שֶׁל נְבוּאָה (בחמש דרכים) נֶאֱמַר לַנְּבִיאִים: בְּמַחֲזֶ\"ה. בְּחָזוֹ\"ן. בְּחִזָּיוֹ\"ן. בְּחָזוּ\"ת. בְּדָבָ\"ר. בְּמַשָּׂ\"א. וְכָל הֶחָמֵשׁ כֻּלָּן כְּמִי שֶׁרוֹאֶה אַחַר הַכֹּתֶל אוֹתוֹ הָאוֹר שֶׁמֵּאִיר, וּמֵהֶם כְּמִי שֶׁרוֹאֶה אוֹר הַשֶּׁמֶשׁ מִתּוֹךְ עֲשָׁשִׁית. אֲבָל מַשָּׂא הֱוֵי כַּאֲשֶׁר מַגִּיעַ אוֹתוֹ אוֹר בְּטֹרַח רַב וּמַטְרִיחַ עָלָיו דְּבָרָיו, שֶׁלֹּא יָכוֹל לְהִתְגַּלּוֹת לוֹ, כְּמוֹ שֶׁנֶּאֱמַר, (במדבר יא) לָשׂוּם אֶת מַשָּׂא כָּל הָעָם הַזֶּה עָלָי. וּמִשּׁוּם זֶה מַשָּׂא.</p>\n<p>וְכָאן מַשָּׂא דּוּמָה - טֹרַח רַב שֶׁלֹּא יָכוֹל לְהִתְגַּלּוֹת, וְהִיא נְבוּאָה בְּלַחַשׁ וְעוֹמֶדֶת בְּלַחַשׁ. אֵלַי קֹרֵא מִשֵּׂעִיר - כָּאן לֹא הִתְגַּלָּה מִי אָמַר \"אֵלַי קֹרֵא מִשֵּׂעִיר\", אִם הַקָּדוֹשׁ בָּרוּךְ הוּא אִם נָבִיא נֶאֱמָן. אֲבָל נְבוּאָה זוֹ וַדַּאי עוֹמֶדֶת בְּלַחַשׁ תּוֹךְ סוֹד הָאֱמוּנָה הָעֶלְיוֹנָה, וּמִתּוֹךְ סוֹד נִסְתָּר אָמַר הַנָּבִיא הַנֶּאֱמָן שֶׁלּוֹ הָיָה קוֹרֵא קוֹל בְּסוֹד הָאֱמוּנָה, וְאָמַר אֵלַי קֹרֵא מִשֵּׂעִיר, כְּמוֹ שֶׁנֶּאֱמַר (דברים לג) וְזָרַח מִשֵּׂעִיר לָמוֹ, וְלֹא כָתוּב וְזָרַח לְשֵׂעִיר, מִשּׁוּם שֶׁסּוֹד הָאֱמוּנָה כָּךְ הוּא, דְּרָגוֹת מִתּוֹךְ דְּרָגוֹת, אֵלֶּה פְּנִימִיִּים מֵאֵלֶּה, קְלִפָּה בְּתוֹךְ קְלִפָּה, וּמֹחַ בְּתוֹךְ מֹחַ.</p>\n<p>וַהֲרֵי בֵּאַרְנוּ, שֶׁכָּתוּב (יחזקאל א) וְהִנֵּה רוּחַ סְעָרָה בָּאָה מִן הַצָּפוֹן - הֲרֵי דַּרְגָּה אַחַת. עָנָן גָּדוֹל - הֲרֵי דַּרְגָּה אַחֶרֶת. וְאֵשׁ מִתְלַקַּחַת - הֲרֵי דַּרְגָּה שְׁלִישִׁית. וְנֹגַהּ לוֹ סָבִיב - דַּרְגָּה רְבִיעִית. וְאַחַר כָּךְ, וּמִתּוֹכָהּ כְּעֵין הַחַשְׁמַל. וְאַחַר כָּךְ, וּמִתּוֹכָהּ דְּמוּת אַרְבַּע חַיּוֹת. הֲרֵי דְּרָגוֹת בְּתוֹךְ מַדְרֵגוֹת (דרגות).</p>\n<p>אַף כָּאן, כְּשֶׁהִתְגַּלָּה הַקָּדוֹשׁ בָּרוּךְ הוּא לְיִשְׂרָאֵל, לֹא הִתְגַּלָּה אֶלָּא מִתּוֹךְ דְּרָגוֹת הַלָּלוּ. מִסִּינַי בָּא - דַּרְגָּה שֶׁהָיְתָה יוֹתֵר נִסְתֶּרֶת, וְאַחַר כָּךְ הִצְטָרְכָה לְהִתְגַּלּוֹת. וְאָמַר וְזָרַח מִשֵּׂעִיר - הֲרֵי דַּרְגָּה אַחֶרֶת שֶׁהִיא יוֹתֵר בְּגִלּוּי, קְלִפָּה שֶׁשּׁוֹרָה עַל גַּבֵּי הַמֹּחַ. וְאַחַר כָּךְ, הוֹפִיעַ מֵהַר פָּארָן - הֲרֵי דַּרְגָּה אַחֶרֶת. וְאַחַר כָּךְ, וְאָתָה מֵרִבֲבֹת קֹדֶשׁ - זֶהוּ שֶׁבַח שֶׁל הַכֹּל. שֶׁאַף עַל גַּב שֶׁהִתְגַּלָּה מִכָּל הַדְּרָגוֹת הַלָּלוּ, מֵאוֹתוֹ מָקוֹם שֶׁהוּא עִקַּר הַכֹּל, הִתְחִיל לְהִתְגַּלּוֹת מִמֶּנּוּ. מֵאֵיזֶה מָקוֹם הוּא? הוּא מֵרִבֲבֹת קֹדֶשׁ, אוֹתָן דְּרָגוֹת עֶלְיוֹנוֹת לְמַעְלָה. (למעלה) אַף כָּאן אֵלַי קֹרֵא מִשֵּׂעִיר - מֵאוֹתָהּ דַּרְגָּה שֶׁאָמַרְנוּ שֶׁנִּדְבְּקָה לְמַעְלָה.</p>\n<p>שׂמֵר מַה מִּלַּיְלָה שֹׁמֵר מַה מִּלֵּיל. שׁוֹמֵר זֶה מטטרו\"ן (שומר ישראל), וְכָתוּב (משלי כז) וְֹשמֵר אֲדנָיו יְכֻבָּד, וְזֶה הַסּוֹד שֶׁשּׁוֹלֵט בַּלַּיְלָה. מַה מִּלַּיְלָה שֹׁמֵר מַה מִּלֵּיל, מַה בֵּין זֶה לָזֶה? אֶלָּא הַכֹּל אֶחָד, אֲבָל בַּחֵלֶק הַזֶּה שׁוֹלֵט הַצַּד הָאַחֵר, וּבַחֵלֶק הַזֶּה לֹא שׁוֹלֵט כְּלָל. לֵיל צָרִיךְ לִשְׁמִירָה, שֶׁכָּתוּב (שמות יב) לֵיל שִׁמֻּרִים הוּא, וְעַל זֶה חָסֵר ה', וְזֶהוּ כְּשֶׁנִּכְנָס הַלַּיְלָה עַד שֶׁנֶּחֱלָק. מֵחֲצוֹת הַלַּיְלָה וָהָלְאָה שׁוֹלֵט לַיְלָה בְּה', שֶׁכָּתוּב וַיְהִי בַּחֲצִי הַלַּיְלָה. הוּא הַלַּיְלָה הַזֶּה. (תהלים קלט) וְלַיְלָה כַּיּוֹם יָאִיר וְגוֹ'. וּמִשּׁוּם כָּךְ, שֹׁמֵר מַה מִּלַּיְלָה שֹׁמֵר מַה מִּלֵּיל.</p>\n<p>אָמַר שֹׁמֵר. מָצָאנוּ בְּסִפְרוֹ שֶׁל אָדָם, מַה בֵּין וַיֹּאמֶר לְאָמַר? וַיֹּאמֶר לְמַעְלָה, וְאָמַר לְמַטָּה. וְאֶל מֹשֶׁה אָמַר - מִי אָמַר? אָמַר שֹׁמֵר, זֶה מטטרו\"ן. אָתָא בֹקֶר - זוֹ תְּפִלַּת שַׁחֲרִית שֶׁהִיא שִׁלְטוֹנוֹ שֶׁל הַיּוֹם, אוֹתוֹ שֶׁשּׁוֹלֵט עַל הַלַּיְלָה. וְאִם תֹּאמַר שֶׁהוּא בָּא לְבַדּוֹ וְנִפְרַד הַזָּכָר מֵהַנְּקֵבָה, הֲרֵי כָּתוּב וְגַם לָיְלָה - שְׁנֵיהֶם כְּאֶחָד, וְלֹא נִפְרָדִים זֶה מִזֶּה לְעוֹלָמִים. וְקוֹל זֶה קוֹרֵא בַּמִּלִּים הָאֵלֶּה: אָתָא בֹקֶר וְגַם לָיִלָה, שְׁנֵיהֶם מְזֻמָּנִים אֲלֵיכֶם.</p>\n<p>מִכָּאןֹ וָהָלְאָה, אִם תִּבְעָיוּן בְּעָיוּ. אִם תְּבַקְשׁוּ בַּקָּשַׁתְכֶם בִּתְפִלָּה לִפְנֵי הַמֶּלֶךְ הַקָּדוֹשׁ - בְּעָיוּ, הִתְפַּלְלוּ וּבַקְּשׁוּ בַּקָּשַׁתְכֶם וְשׁוּבוּ לְרִבּוֹנְכֶם. אֵתָיוּ - כְּמִי שֶׁעָתִיד לְקַבֵּל אֶת בָּנָיו וּלְרַחֵם עֲלֵיהֶם. אַף כָּךְ הַקָּדוֹשׁ בָּרוּךְ הוּא, בֹּקֶר וְגַם לַיְלָה קָרָא וְאָמַר אֵתָיוּ. אַשְׁרֵי הָעָם הַקָּדוֹשׁ שֶׁרִבּוֹנָם מְבַקֵּשׁ עֲלֵיהֶם וְקוֹרֵא לָהֶם לְקָרְבָם אֵלָיו.</p>\n<p>וְאָז הָעָם הַקָּדוֹשׁ רוֹצִים לְהִתְחַבֵּר וּלְהִכָּנֵס לְבֵית הַכְּנֶסֶת, וְכָל מִי שֶׁמַּקְדִּים בָּרִאשׁוֹנָה, מִתְחַבֵּר עִם הַשְּׁכִינָה בְּחִבּוּר אֶחָד. בּא וּרְאֵה, אוֹתוֹ רִאשׁוֹן שֶׁנִּמְצָא בְּבֵית הַכְּנֶסֶת (ומאריך בבית הכנסת) - אַשְׁרֵי חֶלְקוֹ, שֶׁהוּא עוֹמֵד בְּדַרְגַּת צַדִּיק עִם הַשְּׁכִינָה. וְזֶהוּ סוֹד (משלי ח) וּמְשַׁחֲרַי יִמְצָאֻנְנִי. זֶה עוֹלֶה בְּמַעֲלָה עֶלְיוֹנָה. וְאִם תֹּאמַר, הֲרֵי שָׁנִינוּ, בְּשָׁעָה שֶׁהַקָּדוֹשׁ בָּרוּךְ הוּא בָּא לְבֵית הַכְּנֶסֶת וְלֹא מוֹצֵא שָׁם עֲשָׂרָה, מִיָּד כּוֹעֵס. וְאַתָּה אָמַרְתָּ, שֶׁאוֹתוֹ אֶחָד שֶׁמַּקְדִּים, מִתְחַבֵּר בַּשְּׁכִינָה וְעוֹמֵד בְּדַרְגַּת צַדִּיק?!</p>\n<p>אֶלָּא, לְמֶלֶךְ שֶׁשָּׁלַח לְכָל בְּנֵי הָעִיר שֶׁיִּמָּצְאוּ עִמּוֹ בְּיוֹם פְּלוֹנִי בְּמָקוֹם פְּלוֹנִי. עַד שֶׁהָיוּ מְזַמְּנִים אֶת עַצְמָם אוֹתָם בְּנֵי הָעִיר, הִקְדִּים אֶחָד וּבָא אֶל אוֹתוֹ מָקוֹם. בֵּינְתַיִם בָּא הַמֶּלֶךְ וּמָצָא אֶת אוֹתוֹ אִישׁ שֶׁהִקְדִּים לָבֹא לְשָׁם. אָמַר לוֹ, אַיֵּה הֵם פְּלוֹנִים בְּנֵי הָעִיר? אָמַר לוֹ, מוֹרִי, אֲנִי הִקְדַּמְתִּי מֵהֶם, וַהֲרֵי הֵם בָּאִים אַחֲרַי לִפְקֻדַּת הַמֶּלֶךְ. וְאָז הוּטַב בְּעֵינֵי הַמֶּלֶךְ, וְיוֹשֵׁב שָׁם עִמּוֹ וּמְדַבֵּר עִמּוֹ, וְנַעֲשֶׂה אֲהוּב הַמֶּלֶךְ. בֵּינְתַיִם בָּאוּ כָּל הָעָם, וְהִתְפַּיֵּס עִמָּם הַמֶּלֶךְ וְשָׁלַח אוֹתָם לְשָׁלוֹם. אֲבָל אִם אוֹתָם בְּנֵי הָעִיר לֹא בָאִים, וְאֶחָד לֹא מַקְדִּים לְדַבֵּר לִפְנֵי הַמֶּלֶךְ לְהֵרָאוֹת בִּשְׁבִילָם שֶׁהֲרֵי כֻּלָּם יָבאוּ, מִיָּד כּוֹעֵס וְרוֹגֵז הַמֶּלֶךְ.</p>\n<p>אַף כָּאן, כֵּיוָן שֶׁאֶחָד הִקְדִּים וְנִמְצָא בְּבֵית הַכְּנֶסֶת, וּשְׁכִינָה בָּאָה וּמוֹצֵאת אוֹתוֹ, אָז נֶחְשָׁב כְּאִלּוּ כֻּלָּם נִמְצְאוּ שָׁם, שֶׁהֲרֵי זֶה הֶאֱרִיךְ לָהֶם שָׁם. מִיָּד מִתְחַבֶּרֶת עִמּוֹ שְׁכִינָה וְיוֹשְׁבִים בְּזִוּוּג אֶחָד, וְנוֹדָע עִמָּהּ, וּמוֹשִׁיבָה אוֹתוֹ בְּדַרְגַּת צַדִּיק. וְאִם אֶחָד לֹא מַקְדִּים וְלֹא נִמְצָא שָׁם, מַה כָּתוּב? (ישעיה נ) מַדּוּעַ בָּאתִי וְאֵין אִישׁ. לֹא כָתוּב וְאֵין עֲשָׂרָה, אֶלָּא וְאֵין אִישׁ, לְהִתְחַבֵּר עִמִּי לִהְיוֹת אֵלַי, כְּמוֹ שֶׁנֶּאֱמַר אִישׁ הָאֱלֹהִים, לִהְיוֹת בְּדַרְגַּת צַדִּיק.</p>\n<p>וְלֹא עוֹד, אֶלָּא שֶׁנּוֹדָע עִמָּהּ, וְשׁוֹאֶלֶת עָלָיו אִם יוֹם אֶחָד לֹא בָא, כְּמוֹ שֶׁבֵּאַרְנוּ, שֶׁכָּתוּב (שם) מִי בָכֶם יְרֵא ה' שֹׁמֵעַ בְּקוֹל עַבְדּוֹ. וַהֲרֵי הִתְעוֹרַרְנוּ בָּזֶה שֶׁכָּתוּב, אֵלַי קֹרֵא מִשֵּׂעִיר, שֶׁהֲרֵי דַּרְגָּה אַחַר דַּרְגָּה וְדַרְגָּה תּוֹךְ דַּרְגָּה אוֹתוֹ שׁוֹמֵר קוֹרֵא בְחַיִל בְּכָל יוֹם וָיוֹם. וְזֶהוּ שֹׁמֵעַ בְּקוֹל עַבְדּוֹ. עַבְדּוֹ זֶה מטטרו\"ן. וְלָכֵן אַשְׁרֵי הַמַּקְדִּים לְבֵית הַכְּנֶסֶת, לַעֲלוֹת לְאוֹתָהּ דַּרְגָּה עֶלְיוֹנָה שֶׁאָמַרְנוּ.</p>\n<p>כְּשֶׁבָּא הַבֹּקֶר וְהַצִּבּוּר נִמְצָאִים בְּבֵית הַכְּנֶסֶת, צְרִיכִים לְהִמָּצֵא בְּשִׁירוֹת וְתִשְׁבָּחוֹת שֶׁל דָּוִד. וַהֲרֵי בֵּאַרְנוּ, שֶׁסִּדּוּר הוּא לְעוֹרֵר אַהֲבָה לְמַעְלָה וּלְמַטָּה, לְתַקֵּן תִּקּוּנִים וּלְעוֹרֵר שִׂמְחָה, שֶׁהֲרֵי בִּשְׁבִיל זֶה הַלְוִיִּם מִתְעוֹרְרִים לְעוֹרֵר אַהֲבָה וְשִׂמְחָה לְמַעְלָה בְּאוֹתָם שִׁירוֹת וְתִשְׁבָּחוֹת.</p>\n<p>וּמִי שֶׁמְּדַבֵּר בְּבֵית הַכְּנֶסֶת בְּדִבְרֵי חֹל - אוֹי לוֹ! שֶׁמַּרְאֶה פֵרוּד. אוֹי לוֹ! שֶׁגּוֹרֵעַ אֶת הָאֱמוּנָה. אוֹי לוֹ! שֶׁאֵין חֵלֶק בֵּאלֹהֵי יִשְׂרָאֵל. שֶׁמַּרְאֶה שֶׁהֲרֵי אֵין (לו) אֱלוֹהַּ וְאֵינוֹ נִמְצָא שָׁם (ואין לו חלק בו) וְלֹא פוֹחֵד מִמֶּנּוּ, וּמַנְהִיג קָלוֹן בַּתִּקּוּן (בחזק) הָעֶלְיוֹן שֶׁלְּמַעְלָה.</p>\n<p>שֶׁהֲרֵי בְּשָׁעָה שֶׁיִּשְׂרָאֵל מְסַדְּרִים בְּבֵית הַכְּנֶסֶת סִדּוּר שֶׁל שִׁירוֹת וְתִשְׁבָּחוֹת וְסִדּוּר הַתְּפִלָּה, אָז מִתְכַּנְּסִים שָׁלֹשׁ מַחֲנוֹת שֶׁל מַלְאָכִים עֶלְיוֹנִים. מַחֲנֶה אֶחָד הֵם מַלְאָכִים קְדוֹשִׁים (עליונים) שֶׁמְּשַׁבְּחִים אֶת הַקָּדוֹשׁ בָּרוּךְ הוּא בַּיּוֹם, מִשּׁוּם שֶׁיֵּשׁ אֲחֵרִים שֶׁמְּשַׁבְּחִים אֶת הַקָּדוֹשׁ בָּרוּךְ הוּא בַּלַּיְלָה. וַאֲחֵרִים (ואלה) הֵם שֶׁמְּשַׁבְּחִים אֶת הַקָּדוֹשׁ בָּרוּךְ הוּא וְאוֹמְרִים שִׁירוֹת וְתִשְׁבָּחוֹת עִם יִשְׂרָאֵל בַּיּוֹם.</p>\n<p>מַחֲנֶה שֵׁנִי הֵם מַלְאָכִים קְדוֹשִׁים שֶׁנִּמְצָאִים בְּכָל קְדֻשָּׁה וּקְדֻשָּׁה שֶׁל יִשְׂרָאֵל, וּמְקַדְּשִׁים לְמַטָּה. וּבַשִּׁלְטוֹן שֶׁלָּהֶם, כָּל אוֹתָם שֶׁמִּתְעוֹרְרִים בְּכָל אוֹתָם רְקִיעִים (היכלות) בְּאוֹתָהּ תְּפִלָּה שֶׁל יִשְׂרָאֵל (שמישב). מַחֲנֶה שְׁלִישִׁי הֵם עֲלָמוֹת עֶלְיוֹנוֹת, שֶׁמִּתְתַּקְּנוֹת עִם הַגְּבִירָה, וּמְתַקְּנוֹת אוֹתָהּ לְהַכְנִיסָהּ לִפְנֵי הַמֶּלֶךְ, וְאֵלֶּה הֵם הַמַּחֲנוֹת הָעֶלְיוֹנִים עַל כֻּלָּם.</p>\n<p>וְכֻלָּם מִתְתַּקְּנִים בַּסִּדּוּר שֶׁיִּשְׂרָאֵל מִתְתַּקְּנִים לְמַטָּה, בְּאוֹתָם שִׁירוֹת וְתִשְׁבָּחוֹת וּבְאוֹתָהּ תְּפִלָּה שֶׁמִּתְפַּלְלִים יִשְׂרָאֵל. כֵּיוָן שֶׁמִּזְדַּמְּנִים שְׁלֹשֶׁת הַמַּחֲנוֹת הַלָּלוּ, אָז יִשְׂרָאֵל פּוֹתְחִים בְּשִׁירָה וּמְזַמְּרִים לִפְנֵי רִבּוֹנָם. וְאוֹתוֹ מַחֲנֶה אֶחָד, שֶׁמְּמֻנֶּה לְשַׁבֵּחַ אֶת רִבּוֹנָם בַּיּוֹם, מִזְדַּמְּנִים עֲלֵיהֶם וּמְזַמְּרִים עִמָּם כְּאֶחָד בְּאוֹתָם הַשְּׁבָחִים שֶׁל דָּוִד הַמֶּלֶךְ, וַהֲרֵי בֵּאַרְנוּ אֶת הַדְּבָרִים.</p>\n<p>בְּאוֹתוֹ זְמַן שֶׁמְּסַיְּמִים יִשְׂרָאֵל אֶת הַשְּׁבָחִים שֶׁל אוֹתָן תִּשְׁבָּחוֹת שֶׁל דָּוִד, אָז הַתִּשְׁבַּחַת שֶׁל שִׁירַת הַיָּם כְּמוֹ שֶׁבֵּאַרְנוּ. וְאִם תֹּאמַר, הֲרֵי הַתִּשְׁבַּחַת הַ את לָמָּה מְתֻקֶּנֶת אַחֲרוֹנָה אַחַר שִׁבְחֵי דָוִד, וַהֲרֵי תּוֹרָה שֶׁבִּכְתָב קוֹדֶמֶת לַתּוֹרָה שֶׁבְּעַל פֶּה, וְקוֹדֶמֶת לַנְּבִיאִים, וְקוֹדֶמֶת לַכְּתוּבִים, וּכְמוֹ שֶׁקּוֹדֶמֶת - כָּךְ צָרִיךְ לְהַקְדִּים (בשירה) ?</p>\n<p>אֶלָּא מִתּוֹךְ שֶׁכְּנֶסֶת יִשְׂרָאֵל לֹא מְתֻקֶּנֶת אֶלָּא מִתּוֹרָה שֶׁבִּכְתָב, מִשּׁוּם כָּךְ צָרִיךְ לוֹמַר אוֹתָהּ בְּרֵאשִׁית תִּקּוּנֶיהָ, וְזוֹ הַתִּשְׁבַּחַת הַמְעֻלָּה מִכָּל שְׁאָר הַתִּשְׁבָּחוֹת שֶׁבָּעוֹלָם. וְהִיא לֹא הִתְתַּקְּנָה מִכֻּלָּן כְּמוֹ שֶׁהִתְתַּקְּנָה מֵהַתִּשְׁבַּחַת הַזּוֹ, וְלָכֵן הִיא סְמוּכָה לִתְפִלַּת מִיֹּשֶׁב, כְּמוֹ שֶׁבֵּאַרְנוּ.</p>\n<p>בְּאוֹתָהּ שָׁעָה כְּשֶׁנֶּאֱמֶרֶת שִׁירַת הַיָּם, מִתְעַטֶּרֶת כְּנֶסֶת יִשְׂרָאֵל בְּאוֹתוֹ כֶתֶר שֶׁעָתִיד הַקָּדוֹשׁ בָּרוּךְ הוּא לְעַטֵּר אֶת מֶלֶךְ הַמָּשִׁיחַ, וְאוֹתוֹ כֶתֶר גָּלוּף וְחָקוּק בְּשֵׁמוֹת קְדוֹשִׁים, כְּמוֹ שֶׁהִתְעַטֵּר הַקָּדוֹשׁ בָּרוּךְ הוּא אוֹתוֹ יוֹם שֶׁעָבְרוּ יִשְׂרָאֵל אֶת הַיָּם וְהִטְבִּיעַ אֶת כָּל מַחֲנוֹת פַּרְעֹה וּפָרָשָׁיו. וּמִשּׁוּם כָּךְ צָרִיךְ אָדָם לָשִׂים רְצוֹנוֹ בַּשִּׁירָה הַזּוֹ. וְכָל מִי שֶׁזּוֹכֶה לָהּ בָּעוֹלָם הַזֶּה, זוֹכֶה לִרְאוֹת אֶת מֶלֶךְ הַמָּשִׁיחַ בְּתִקּוּנֵי אוֹתוֹ הַכֶּתֶר וּבַחֲגִירַת כְּלֵי זֵינוֹ, וְזוֹכֶה לְשַׁבֵּחַ שִׁירָה זוֹ שָׁם, וַהֲרֵי בֵּאַרְנוּ אֶת הַדְּבָרִים.</p>\n<p>כֵּיוָן שֶׁמַּגִּיעַ אָדָם לְיִשְׁתַּבַּח, נוֹטֵל הַקָּדוֹשׁ בָּרוּךְ הוּא אוֹתוֹ הַכֶּתֶר וְשָׂם אוֹתוֹ לְפָנָיו, וּכְנֶסֶת יִשְׂרָאֵל מַתְחִילָה לְהִתְתַּקֵּן לָבֹא לִפְנֵי הַמֶּלֶךְ הָעֶלְיוֹן, וְצָרִיךְ לִכְלֹל אוֹתָהּ בִּשְׁלֹשׁ עֶשְׂרֵה מִדּוֹת הָרַחֲמִים הָעֶלְיוֹנוֹת שֶׁמֵּהֶן מִתְבָּרֶכֶת, וְהֵם שְׁלֹשָׁה עָשָׂר בְּשָׂמִים עֶלְיוֹנִים, כְּמוֹ שֶׁנֶּאֱמַר (שיר השירים ד) נֵרְדְּ וְכַרְכֹּם קָנֶה וְקִנָּמוֹן וְגוֹ', וְכָאן הֵם: שִׁיר, וּשְׁבָחָה, הַלֵּל, וְזִמְרָה, עֹז, וּמֶמְשָׁלָה, נֶצַח, גְּדֻלָּה, גְּבוּרָה, וְתִפְאֶרֶת, קְדֻשָּׁה. הֲרֵי שְׁנֵים עָשָׂר. אַחַר כָּךְ לְחַבְּרָהּ עִמָּם וְלוֹמַר וּמַלְכוּת, וְהָיוּ שְׁלֹשָׁה עָשָׂר, מִשּׁוּם שֶׁהִיא מִתְבָּרֶכֶת מֵהֶם.</p>\n<p>וְלָכֵן צָרִיךְ בְּשָׁעָה שֶׁנִּכְלֶלֶת בֵּינֵיהֶם, לָשִׂים בָּזֶה לֵב וְרָצוֹן וְלֹא לְדַבֵּר כְּלָל, שֶׁלֹּא לְהַפְסִיק בֵּינֵיהֶם, וְאִם מַפְסִיק בֵּינֵיהֶם, יוֹצֵאת שַׁלְהֶבֶת אַחַת מִתַּחַת כַּנְפֵי הַכְּרוּבִים, וְקוֹרֵאת בְּחַיִל וְאוֹמֶרֶת: פְּלוֹנִי שֶׁהִפְסִיק אֶת גֵּאוּת הַקָּדוֹשׁ בָּרוּךְ הוּא, יִתְכַּלֶּה וְיִפָּסֵק, שֶׁלֹּא יִרְאֶה גֵאוּת הַמֶּלֶךְ הַקָּדוֹשׁ, כְּמוֹ שֶׁנֶּאֱמַר (ישעיהכו) וּבַל יִרְאֶה גֵּאוּת ה', מִשּׁוּם שֶׁשְּׁלֹשָׁה עָשָׂר הָאֵלֶּה הֵם גֵּאוּת ה'.</p>\n<p>מִכָּאן וָהָלְאָה - אֵל הַהוֹדָאוֹת כוּ'. זֶה הַמֶּלֶךְ הָעֶלְיוֹן שֶׁהַשָּׁלוֹם כֻּלּוֹ שֶׁלּוֹ, כְּמוֹ שֶׁנֶּאֱמַר, שִׁיר הַשִּׁירִים אֲשֶׁר לִשְׁלֹמֹה, לַמֶּלֶךְ שֶׁהַשָּׁלוֹם שֶׁלּוֹ. מִשּׁוּם שֶׁכָּל הַשְּׁבָחִים הַלָּלוּ הֵם אֶל כְּנֶסֶת יִשְׂרָאֵל כְּשֶׁמִּשְׁתַּבַּחַת בַּמַּחֲנֶה שֶׁלְּמַטָּה, כְּמוֹ שֶׁנֶּאֱמַר, שִׁיר הַשִּׁירִים אֲשֶׁר לִשְׁלֹמֹה, לַמֶּלֶךְ שֶׁהַשָּׁלוֹם שֶׁלּוֹ. מִשָּׁם וָהָלְאָה - יוֹצֵר אוֹר וּבוֹרֵא חֹשֶׁךְ עֹשֶׂה שָׁלוֹם וּבוֹרֵא אֶת הַכֹּל. וַהֲרֵי הִתְעוֹרַרְנוּ בָזֶה, וְהִתְעוֹרְרוּ הַחֲבֵרִים שֶׁאֵלֶּה הֵם תִּקּוּנֵי הָעוֹלָם הָעֶלְיוֹן (אל אדון).</p>\n<p>אֵ\"ל בָּ\"רוּךְ - תִּקּוּנֵי הָעוֹלָם הַתַּחְתּוֹן, שֶׁהֵם כ\"ב אוֹתִיּוֹת קְטַנּוֹת, מִשּׁוּם שֶׁיֵּשׁ אוֹתִיּוֹת גְּדוֹלוֹת וְאוֹתִיּוֹת קְטַנּוֹת. הָאוֹתִיּוֹת הַקְּטַנּוֹת מֵהָעוֹלָם הַתַּחְתּוֹן, וְאוֹתִיּוֹת גְּדוֹלוֹת מֵאוֹתוֹ עוֹלָם הַבָּא.</p>\n<p>בַּכֹּל הֵן גְּדוֹלוֹת. הֵן גְּדוֹלוֹת בְּעַצְמָן. כַּאֲשֶׁר (לא) בָּאוֹת יְחִידוֹת הֵן גְּדוֹלוֹת (זכר ונקבה פשוטים). שֶׁכַּאֲשֶׁר הֵן לֹא פְשׁוּטוֹת יוֹתֵר, הֵן בָּאוֹת כָּל אוֹת וְאוֹת בַּמֶּרְכָּבָה הָרְאוּיָה לָהּ, כְּמוֹ שֶׁבַח שֶׁל הַשַּׁבָּת שֶׁהֵם אוֹתִיּוֹת שֶׁל שֶׁבַח: אֵל אָדוֹן עַל כָּל הַמַּעֲשִׂים, בָּרוּךְ וּמְבֹרָךְ בְּפִי כָּל נְשָׁמָה. אֵלּוּ אוֹתִיּוֹת בְּחָמֵשׁ חָמֵשׁ תֵּבוֹת, שֶׁהֵן חֲמִשִּׁים שְׁעָרִים שֶׁל הָעוֹלָם הַבָּא.</p>\n<p>שְׁתֵּי אוֹתִיּוֹת אֲחֵרוֹת שֶׁבַּסּוֹף - ש\"ת. הֵן בְּשֵׁשׁ שֵׁשׁ תֵּבוֹת, שֶׁהֵם שֵׁשֶׁת צִדְדֵי הָעוֹלָם הַבָּא, וְיוֹצְאוֹת מִשָּׁם כְּמוֹ: שֶׁבַח יִתְּנוּ לוֹ כָּל צְבָא מָרוֹם. תִּפְאֶרֶת וּגְדֻלָּה שְׂרָפִים וְאוֹפַנִּים וְחַיּוֹת הַקֹּדֶשׁ.</p>\n<p>אֵלּוּ שְׁתֵּי אוֹתִיּוֹת בְּשֵׁשׁ שֵׁשׁ. שְׁתֵּי אוֹתִיּוֹת רִאשׁוֹנוֹת בְּחָמֵשׁ חָמֵשׁ. כָּל שְׁאָר הָאוֹתִיּוֹת שֶׁבָּאֶמְצַע, כֻּלָּן בְּאַרְבַּע אַרְבַּע, מִשּׁוּם שֶׁהֵן בְּסוֹד הַמֶּרְכָּבָה הָעֶלְיוֹנָה, שֶׁהֵן אוֹתִיּוֹת רִאשׁוֹנוֹת וְאוֹתָן שֶׁבַּסּוֹף, הֵן שְׁלֵמוּת כ\"ב הָאוֹתִיּוֹת, מִשּׁוּם שֶׁיֵּשׁ בָּהֶן כ\"ב תֵּבוֹת כְּנֶגֶד כ\"ב הָאוֹתִיּוֹת הָעֶלְיוֹנוֹת. נִשְׁאֲרוּ שְׁמוֹנֶה עֶשְׂרֵה אוֹתִיּוֹת אֲחֵרוֹת שֶׁעוֹלוֹת בְּמַרְכְּבוֹתֵיהֶן לְאַרְבַּע אַרְבַּע, לְשִׁבְעִים וּשְׁתַּיִם תֵּבוֹת, שֶׁהֵן סוֹד הַשֵּׁם הַמְפֹרָשׁ, חֲקִיקָה קְדוֹשָׁה שֶׁל שִׁבְעִים וּשְׁתַּיִם אוֹתִיּוֹת שֶׁהַקָּדוֹשׁ בָּרוּךְ הוּא מִתְעַטֵּר בָּהֶן, וְהַשֵּׁם הַזֶּה מְעַטֵּר אֶת כְּנֶסֶת יִשְׂרָאֵל, וְעוֹלָה בְּסוֹד זֶה לְהִתְעַטֵּר בָּהֶם תּוֹךְ הַשְּׁלִיחוּת (של אדונו) שֶׁל הַשְּׁכִינָה.</p>\n<p>וְסִימָנְךָ שֶׁל אֵלּוּ הָאוֹתִיּוֹת שֶׁמִּתְעַטְּרוֹת בְּשֶׁבַח עֶלְיוֹן - זֶה רִאשׁוֹנוֹת וְסוֹפִיּוֹת, שֶׁעוֹלוֹת בְּעַטְרוֹתֵיהֶן אוֹתָן א\"ת ב\"ש: אָלֶ\"ף בְּחָמֵשׁ. תָּי\"ו בְּשֵׁשׁ. בֵּי\"ת בְּחָמֵשׁ. שִׁי\"ן בְּשֵׁשׁ. וּמִשּׁוּם כָּךְ הַסּוֹד שֶׁל א\"ת ב\"ש כְּלָל שֶׁל כ\"ב אוֹתִיּוֹת, שֶׁהֵן עֲטָרָה שֶׁל שְׁלֹשִׁים וּשְׁנַיִם שְׁבִילִים.</p>\n<p>וְסִימָן שֶׁל אוֹתָן אוֹתִיּוֹת אֲחֵרוֹת שֶׁעוֹלוֹת בְּמַרְכְּבוֹתֵיהֶן - ג\"ר. מַתְחִיל בְּגִימֶ\"ל וְסִיֵּם בְּרֵי\"שׁ, וְכֻלָּן סוֹד הַמֶּרְכָּבָה הַקְּדוֹשָׁה. א\"ת ב\"ש - סוֹד הַשֵּׁם הַקָּדוֹשׁ. ג\"ר - סוֹד הַמֶּרְכָּבָה הַקְּדוֹשָׁה שֶׁעוֹלָה לְשִׁבְעִים וּשְׁתַּיִם, וְנַעֲשֶׂה מֵהֶם שֵׁם קָדוֹשׁ לְעַטֵּר אֶת כְּנֶסֶת יִשְׂרָאֵל מִתּוֹךְ הַמֶּרְכָּבָה הָעֶלְיוֹנָה. (שכתוב (תהלים מח) כשמך אלהים כן תהלתך).</p>\n<p>וְלָכֵן אוֹתוֹ שֵׁם שֶׁל ע\"ב כָּלוּל בְּסוֹד הָאָבוֹת, יָמִין וּשְׂמֹאל וְאֶמְצַע. וְהִיא מִתְעַטֶּרֶת בָּהֶם לִהְיוֹת שֵׁם קָדוֹשׁ, וְלֹא שֵׁם עֶלְיוֹן כְּאוֹתָם שֵׁמוֹת עֶלְיוֹנִים שֶׁל הָעוֹלָם הָעֶלְיוֹן, שֶׁנֶּאֱחָזִים לְמַעְלָה לְמַעְלָה. וְאַף עַל גַּב שֶׁזֶּהוּ שֵׁם עֶלְיוֹן, אֲבָל הַסּוֹד שֶׁלּוֹ דָּוִד הַמֶּלֶךְ שֶׁמִּתְעַטֵּר בָּאָבוֹת.</p>\n<p>הַשֵּׁם שֶׁל מ\"ב אוֹתִיּוֹת - הַסּוֹד שֶׁלּוֹ הָאָבוֹת, שֶׁמִּתְעַטְּרִים בָּעוֹלָם הָעֶלְיוֹן. וְהָעוֹלָם הָעֶלְיוֹן בְּמַה שֶּׁלְּמַעְלָה. (ועולה הסוד שלמעלה למעלה, עד שמתעטר באין סוף) וְלָכֵן עוֹלֶה וְלֹא יוֹרֵד, וּמִתְעַטֵּר בְּתוֹךְ הַמַּחֲשָׁבָה הָעֶלְיוֹנָה. אַשְׁרֵי חֶלְקוֹ שֶׁל מִי שֶׁמַּכִּיר אוֹתוֹ וְנִזְהָר בּוֹ.</p>\n<p>הַשֵּׁם שֶׁל ע\"ב אוֹתִיּוֹת - דָּוִד הַמִּתְעַטֵּר בָּאָבוֹת, וְסוֹדוֹ עוֹלֶה וְיוֹרֵד כְּמוֹ זֶה מצפ\"ץ, (מצפ\"ץ) שֵׁם שֶׁל שְׁלֹשׁ עֶשְׂרֵה מִדּוֹת הָרַחֲמִים. הֵם שְׁתֵּים עֶשְׂרֵה, סוֹד הַמֶּרְכָּבָה הַקְּדוֹשָׁה שֶׁיּוֹצְאִים מֵאֶחָד שֶׁשּׁוֹרֶה עֲלֵיהֶם, וְלָכֵן (עולה ויורד, וכלם עולים ויורדים חוץ מזה השם של מ\"ב שעולה ולא יורד, ועל זה) הַשֵּׁם שֶׁל שִׁבְעִים וּשְׁתַּיִם עוֹלֶה וְיוֹרֵד. עוֹלֶה מִצַּד זֶה וְיוֹרֵד מִצַּד זֶה. הַשֵּׁם שֶׁל שְׁלֹשׁ עֶשְׂרֵה מִדּוֹת עוֹלֶה מִצַּד זֶה וְיוֹרֵד מִצַּד זֶה. וְאוֹתוֹ שֶׁיּוֹרֵד, כְּדֵי לִמְשֹׁךְ טוֹב לְמַטָּה. וְעַל זֶה, א\"ת ב\"ש ג\"ר ד\"ק ה\"ץ ו\"פ ז\"ע ח\"ס ט\"ן י\"ם כ\"ל. הָאוֹתִיּוֹת הָרִאשׁוֹנוֹת עוֹלוֹת בַּחֶשְׁבּוֹן, וְאוֹתִיּוֹת אֲחֵרוֹת יוֹרְדוֹת בַּחֶשְׁבּוֹן, כְּדֵי לִמְשֹׁךְ אֶת הַטּוֹב שֶׁלְּמַעְלָה לְמַטָּה.</p>\n<p>הַשֵּׁם שֶׁל אַרְבָּעִים וּשְׁתַּיִם הוּא מִתְעַטֵּר לַמֶּרְכָּבָה הָעֶלְיוֹנָה. הַשֵּׁם שֶׁל שִׁבְעִים וּשְׁתַּיִם מִתְעַטֵּר לַמֶּרְכָּבָה הַתַּחְתּוֹנָה. אַשְׁרֵי חֶלְקוֹ שֶׁל מִי שֶׁמִּשְׁתַּדֵּל לְהַכִּיר אֶת רִבּוֹנוֹ. אַשְׁרָיו בָּעוֹלָם הַזֶּה וּבָעוֹלָם הַבָּא.</p>\n<p>וְלָכֵן תִּשְׁבַּחְתָּהּ שֶׁל שַׁבָּת שֶׁמְּשַׁבַּחַת אֶת הַמֶּלֶךְ שֶׁהַשָּׁלוֹם שֶׁלּוֹ, מְשַׁבַּחַת בָּאוֹתִיּוֹת שֶׁל שִׁבְעִים וּשְׁתַּיִם וּבְעֶשְׂרִים וּשְׁתַּיִם תֵּבוֹת, הַסּוֹד שֶׁל עֶשְׂרִים וּשְׁתַּיִם אוֹתִיּוֹת, כְּדֵי שֶׁתִּתְעַטֵּר בּוֹ לַעֲלוֹת לְמַעְלָה בַּתִּשְׁבַּחַת הַזּוֹ. וְלָכֵן אֵל אָדוֹן - תִּשְׁבַּחַת הָעוֹלָם הַבָּא הוּא, וּפְרִיחַת (וקשירת) הַמֶּרְכָּבָה הַקְּדוֹשָׁה הָעֶלְיוֹנָה שֶׁמִּתְעַטֶּרֶת לַעֲלוֹת לְמַעְלָה, וּפְרִיחַת כְּנֶסֶת יִשְׂרָאֵל שֶׁמִּתְעַטֶּרֶת לַעֲלוֹת בְּתוֹךְ הַמֶּרְכָּבָה הָעֶלְיוֹנָה.</p>\n<p>א\"ת ב\"ש עוֹלִים וְיוֹרְדִים, כְּמוֹ שֶׁנִּתְבָּאֵר. א\"ל ב\"ם עוֹלִים וְלֹא יוֹרְדִים, וְסִימָנְךְ - זוֹ שַׁבָּ\"ת לְבַדָּהּ. וזוֹ שַׁבָּת וְיוֹם הַכִּפּוּרִים, שֶׁעוֹלֶה הַסּוֹד לְמַעְלָה לְמַעְלָה, עַד שֶׁהַכֹּל מִתְעַטֵּר בָּאֵין סוֹף.</p>\n<p>אֵל בָּרוּךְ - זֶה סִדּוּר שֶׁל אוֹתִיּוֹת קְטַנּוֹת וְתִקּוּנֵי כְּנֶסֶת יִשְׂרָאֵל בְּכָל יוֹם בַּתְּפִלָּה. וּמִשּׁוּם שֶׁאוֹתָן אוֹתִיּוֹת קְטַנּוֹת, אֵין רֶוַח בֵּינֵיהֶן, וְהֵן תִּקּוּנֵי הָעוֹלָמוֹת שֶׁבָּאוֹת עִם הַגְּבִירָה לַמֶּלֶךְ הָעֶלְיוֹן.</p>\n<p>קְדֻשָּׁה זוֹ שֶׁמְּקַדְּשִׁים הַמַּלְאָכִים הָעֶלְיוֹנִים אֵינָהּ בְּיָחִיד, וַהֲרֵי בֵּאַרְנוּ, כָּל קְדֻשָּׁה שֶׁהִיא בִּלְשׁוֹן הַקֹּדֶשׁ, אָסוּר לְיָחִיד לְאָמְרָהּ. תַּרְגּוּם - לְעוֹלָם בְּיָחִיד, וְלֹא בְרַבִּים. וְהַיָּחִיד הוּא תִּקּוּן שֶׁלּוֹ וַדַּאי, וְלֹא רַבִּים. וְסִימָן לְסוֹד זֶה - שְׁנַיִם מִקְרָא וְאֶחָד תַּרְגּוּם. שְׁנַיִם זֶה לְשׁוֹן רַבִּים, שֶׁוַּדַּאי קְדֻשָּׁה שֶׁל לְשׁוֹן הַקֹּדֶשׁ אֲסוּרָה בְּיָחִיד. קְדֻשַּׁת תַּרְגּוּם אֲסוּרָה בָּרַבִּים, אֶלָּא בְּיָחִיד לְעוֹלָם. אֶחָד תַּרְגּוּם שָׁנִינוּ, וְלֹא שְׁנַיִם וְלֹא יוֹתֵר. הַתַּרְגּוּם בָּא לְמַעֵט, וְכָךְ צָרִיךְ. לְשׁוֹן הַקֹּדֶשׁ בָּא לְרִבּוּי, וְכָךְ צָרִיךְ, שֶׁמַּעֲלִים בַּקֹּדֶשׁ וְלֹא מוֹרִידִים. וּבַתַּרְגּוּם מוֹרִידִים וְלֹא מַעֲלִים. שָׁנִינוּ אֶחָד, וְלֹא יוֹתֵר, וְלֹא מַעֲלִים כְּלָל.</p>\n<p>הַקְּדֻשָּׁה הַזּוֹ - הַקְּדֻשָּׁה שֶׁהִתְקַדְּשָׁה הַשְּׁכִינָה, וְכָל אוֹתָן מַרְכְּבוֹתֶיהָ לְהִתְתַּקֵּן אֶל הַמֶּלֶךְ הָעֶלְיוֹן. וּמִשּׁוּם שֶׁהִיא קְדֻשַּׁת הָעוֹלָם הַתַּחְתּוֹן, הִיא מְיֻשָּׁב וְלֹא בַּעֲמִידָה. קְדֻשָּׁה אַחֶרֶת שֶׁל חֲזָרַת הַתְּפִלָּה הִיא קְדֻשָּׁה שֶׁל הָעוֹלָם הָעֶלְיוֹן, וְלָכֵן הִיא בַּעֲמִידָה, כְּדֵי לְהַמְשִׁיכָהּ לְמַטָּה, וְכָל דִּבְרֵי הָעוֹלָם הָעֶלְיוֹן הֵם בַּעֲמִידָה וְלֹא מְיֻשָּׁב.</p>\n<p>וּבְכָל הַקְּדֻשּׁוֹת הַלָּלוּ יִשְׂרָאֵל מִתְקַדְּשִׁים בָּהֶם לְמַטָּה, וְלָכֵן יִשְׂרָאֵל מִתְקַדְּשִׁים בִּקְדֻשַּׁת הַמֶּרְכָּבָה הַתַּחְתּוֹנָה מְיֻשָּׁב, וּבִקְדֻשַּׁת הַמֶּרְכָּבָה הָעֶלְיוֹנָה מְעֻמָּד. קְדֻשָּׁה אַחֶרֶת הִיא תּוֹסֶפֶת קְדֻשָּׁה, וְלָכֵן הִיא אַחַר הַתְּפִלָּה. וּמִשּׁוּם שֶׁהִיא תּוֹסֶפֶת קְדֻשָּׁה עַל קְדֻשּׁוֹת אֲחֵרוֹת, הִיא אַחַר הַתְּפִלָּה. וּמִשּׁוּם שֶׁכָּל אֶחָד וְאֶחָד צָרִיךְ לִמְשֹׁךְ עָלָיו מֵאוֹתָהּ תּוֹסֶפֶת, נִתְקָן לְכָל יָחִיד וְיָחִיד קְדֻשַּׁת תַּרְגּוּם.</p>\n<p>וְאִם תֹּאמַר, הֲרֵי יֵשׁ בָּהּ קְדֻשַּׁת לְשׁוֹן הַקֹּדֶשׁ - אוֹתָהּ לְצִבּוּר, לְהִתְקַדֵּשׁ כֻּלָּם בִּכְלָל בְּאוֹתָהּ תּוֹסֶפֶת קְדֻשָּׁה. וּמִשּׁוּם שֶׁלְּיָחִיד אֵין רְשׁוּת לְאָמְרָהּ בִּלְשׁוֹן הַקֹּדֶשׁ וּלְהִתְקַדֵּשׁ יְחִידִי, הִתְקִינוּהָ בִּלְשׁוֹן תַּרְגּוּם, וְהִיא בְּיָחִיד, לְהִתְקַדֵּשׁ כָּל אֶחָד וְאֶחָד בְּאוֹתָהּ תּוֹסֶפֶת לְהַמְשִׁיךְ עָלָיו יֶתֶר קְדֻשָּׁה. אַשְׁרֵי חֶלְקָם שֶׁל יִשְׂרָאֵל שֶׁמִּתְקַדְּשִׁים בִּקְדֻשּׁוֹת עֶלְיוֹנוֹת, מִשּׁוּם שֶׁהֵם דְּבֵקִים לְמַעְלָה, שֶׁכָּתוּב (דברים ד) וְאַתֶּם הַדְּבֵקִים בַּה' אֱלֹהֵיכֶם חַיִּים כֻּלְּכֶם הַיּוֹם.</p>"],[9522011701,"<p>כָּתוּב, (מלכים ב ד) הִנֵּה נָא יָדַעְתִּי כִּי אִישׁ אֱלֹהִים קָדוֹשׁ הוּא עֹבֵר וְגוֹ'. וְכָתוּב, נַעֲשֶׂה נָּא עֲלִיַּת קִיר קְטַנָּה וְגוֹ'. בְּפָסוּק זֶה יֵשׁ סֶמֶךְ בְּעָלְמָא לְסִדּוּר הַתְּפִלָּה. הִנֵּה נָא יָדַעְתִּי - זֶהוּ הָרָצוֹן שֶׁצָּרִיךְ אָדָם לָשִׂים בְּתוֹכוֹ בַּתְּפִלָּה. כִּי אִישׁ אֱלֹהִים קָדוֹשׁ הוּא - זֶהוּ הָעוֹלָם הָעֶלְיוֹן, שֶׁיּוֹשֵׁב עַל כִּסֵּא כְבוֹדוֹ, וְכָל הַקְּדֻשּׁוֹת יוֹצְאוֹת מִמֶּנּוּ, וְהוּא מְקַדֵּשׁ אֶת כָּל הָעוֹלָמוֹת. עֹבֵר עָלֵינוּ תָּמִיד - מֵאוֹתָהּ קְדֻשָּׁה שֶׁהוּא מְקַדֵּשׁ אֶת כָּל הָעוֹלָמוֹת לְמַעְלָה, הוּא מְקַדֵּשׁ אוֹתָנוּ בָּעוֹלָם הַזֶּה. שֶׁהֲרֵי אֵין קְדֻשָּׁה לְמַעְלָה אֶלָּא אִם יֵשׁ קְדֻשָּׁה לְמַטָּה, כְּמוֹ שֶׁנֶּאֱמַר וְנִקְדַּשְׁתִּי בְּתוֹךְ בְּנֵי יִשְׂרָאֵל.</p>\n<p>וְהוֹאִיל וְכָךְ הוּא, נַעֲשֶׂה נָּא עֲלִיַּת קִיר קְטַנָּה. זֶהוּ סִדּוּר שֶׁל תִּקּוּן הַשְּׁכִינָה, שֶׁהִיא עֲלִיַּת קִיר, כְּמוֹ שֶׁנֶּאֱמַר (ישעיה לח) וַיַּסֵּב חִזְקִיָּהוּ פָּנָיו אֶל הַקִּיר. קְטַנָּה, מִשּׁוּם שֶׁהִיא קְטַנָּה, כְּמוֹ שֶׁנֶּאֱמַר (קהלת ט) עִיר קְטַנָּה. וְנָשִׂים לוֹ שָׁם - בַּתִּקּוּן הַזֶּה שֶׁאָנוּ מְתַקְּנִים, וּבַסִּדּוּר שֶׁלָּנוּ בְּשִׁירוֹת וְתִשְׁבָּחוֹת וּתְפִלָּה, (ובתקון זה) אָנוּ מְתַקְּנִים לוֹ, לִמְנוּחָתוֹ. מִטָּה וְשֻׁלְחָן וְכִסֵּא וּמְנוֹרָה - כָּל הָאַרְבָּעָה הַלָּלוּ הֵם בַּשְּׁכִינָה, וְהִיא (כלה) בְּכָל הַתִּקּוּנִים הַלָּלוּ מְתֻקָּנִים לָעוֹלָם הָעֶלְיוֹן בַּסִּדּוּר שֶׁאָנוּ מְסַדְּרִים.</p>\n<p>בַּסִּדּוּר שֶׁל תְּפִלַּת עַרְבִית וּבַתִּקּוּן שֶׁלּוֹ - הֲרֵי מִטָּה. בַּסִּדּוּר שֶׁל אוֹתָם קָרְבָּנוֹת וְעוֹלוֹת שֶׁאָנוּ מְסַדְּרִים בַּבֹּקֶר וְאוֹתָם שִׁירוֹת וְתִשְׁבָּחוֹת - הֲרֵי הַשֻּׁלְחָן. וּבְאוֹתוֹ סִדּוּר שֶׁל תְּפִלַּת מְיֻשָּׁב וּבַתִּקּוּן שֶׁל קְרִיאַת שְׁמַע בְּאוֹתוֹ יִחוּד שֶׁאָנוּ מְתַקְּנִים - הֲרֵי כִּסֵּא. בְּאוֹתוֹ סִדּוּר שֶׁל תְּפִלַּת מְעֻמָּד וּבְאוֹתָן קְדֻשּׁוֹת וְתוֹסֶפֶת קְדֻשָּׁה, וּבְרָכוֹת שֶׁאָנוּ מְסַדְּרִים (לה) - הֲרֵי מְנוֹרָה.</p>\n<p>אַשְׁרֵי הָאִישׁ שֶׁאֶת זֶה שָׂם בִּרְצוֹנוֹ לְהַשְׁלִים לְרִבּוֹנוֹ בְּכָל יוֹם וּלְתַקֵּן עֲלִיַּת קִיר קְטַנָּה זוֹ לְרִבּוֹנוֹ בַּתִּקּוּנִים הַלָּלוּ, אָז וַדַּאי שֶׁהַקָּדוֹשׁ בָּרוּךְ הוּא יִהְיֶה אוֹרְחוֹ בְּכָל יוֹם. אַשְׁרָיו בָּעוֹלָם הַזֶּה, וְאַשְׁרָיו בָּעוֹלָם הַבָּא. מִשּׁוּם שֶׁאֵלּוּ הָאַרְבָּעָה הֵם תִּקּוּנֵי הַשְּׁכִינָה לְהִתְתַּקֵּן לְבַעְלָהּ. בְּאַרְבָּעָה הַתִּקּוּנִים הַלָּלוּ הִיא מִתְתַּקֶּנֶת בְּיָפְיָהּ בְּשִׂמְחוֹתֶיהָ, בְּמַרְאֶיהָ, עַל יְדֵי הָעָם הַקָּדוֹשׁ כָּל יוֹם.</p>\n<p>הַמִּטָה נִתְּנָה לְיַעֲקֹב לְהִתְתַּקֵּן, וְלָכֵן יַעֲקֹב תִּקֵּן תְּפִלַּת עַרְבִית. שֻׁלְחָן תִּקֵּן דָּוִד הַמֶּלֶךְ בְּאוֹתָם שִׁירוֹת וְתִשְׁבָּחוֹת שֶׁתִּקֵּן, כְּמוֹ שֶׁנֶּאֱמַר (תהלים כג) תַּעֲרֹךְ לְפָנַי שֻׁלְחָן נֶגֶד צֹרְרָי. כִּסֵּא תִּקֵּן אַבְרָהָם בְּהִתְקַשְּׁרוּתוֹ, שֶׁעָשָׂה טוֹב וּשְׁלֵמוּת הַנְּשָׁמוֹת לְכָל בְּנֵי הָעוֹלָם, וְאֵין תִּקּוּן הַכִּסֵּא אֶלָּא בַּחֶסֶד שֶׁל אַבְרָהָם, כְּמוֹ שֶׁנֶּאֱמַר (ישעיה טז) וְהוּכַן בְּחֶסֶד כִּסֵּא.</p>\n<p>הַמְּנוֹרָה תִּקֵּן יִצְחָק, שֶׁקִּדֵּשׁ שֵׁם הַקָּדוֹשׁ בָּרוּךְ הוּא לְעֵינֵי כָּל הָעוֹלָם, וְהֵאִיר אֶת אוֹר הַמְּנוֹרָה הָעֶלְיוֹנָה בְּאוֹתָהּ קְדֻשָּׁה. לָכֵן צְרִיכִים הָעָם הַקָּדוֹשׁ לוֹמַר תָּמִיד וְלָשִׂים רְצוֹנָם לְסַדֵּר לָעוֹלָם הָעֶלְיוֹן, שֶׁהוּא בַּעַל הַבַּיִת, אִישׁ הָאֱלֹהִים, מִטָּה וְשֻׁלְחָן וְכִסֵּא וּמְנוֹרָה, לִהְיוֹת שְׁלֵמוּת בְּכָל יוֹם מַעְלָה וּמַטָּה.</p>"],[9522011702,"<p>בְּשָׁעָה שֶׁיִּשְׂרָאֵל מְיַחֲדִים אֶת הַיִּחוּד שֶׁל סוֹד שְׁמַע יִשְׂרָאֵל בְּרָצוֹן שָׁלֵם, אָז יוֹצֵא מִתּוֹךְ סֵתֶר שֶׁל הָעוֹלָם הָעֶלְיוֹן אוֹר אֶחָד, וְאוֹתוֹ אוֹר מַכֶּה לְתוֹךְ הַנִּיצוֹץ הַקָּשֶׁה וּמִתְחַלֵּק לְשִׁבְעִים אוֹרוֹת, וְאוֹתָם שִׁבְעִים אוֹרוֹת בְּשִׁבְעִים עַנְפֵי עֵץ הַחַיִּים.</p>\n<p>אָז אוֹתוֹ אִילָן מַעֲלֶה רֵיחוֹת וּבְשָׂמִים, וְכָל אִילָנוֹת גַּן עֵדֶן, כֻּלָּם מַעֲלִים רֵיחוֹת וּמְשַׁבְּחִים אֶת רִבּוֹנָם, שֶׁהֲרֵי אָז מְתֻקֶּנֶת הַגְּבִירָה לְהִכָּנֵס לַחֻפָּה עִם בַּעְלָהּ. כָּל אוֹתָם אֵיבָרִים עֶלְיוֹנִים, כֻּלָּם מִתְחַבְּרִים בִּתְשׁוּקָה אַחַת וּבְרָצוֹן אֶחָד לִהְיוֹת אֶחָד בְּלִי פֵרוּד כְּלָל. וְאָז בַּעְלָהּ מִתְתַּקֵּן אֵלֶיהָ לְהַכְנִיסָהּ לַחֻפָּה בְּיִחוּד אֶחָד לְהִתְיַחֵד עִם הַגְּבִירָה.</p>\n<p>וְלָכֵן אָנוּ מְעוֹרְרִים אוֹתוֹ וְאוֹמְרִים (דבריםי) שְׁמַע יִשְׂרָאֵל. תַּקְּנִי עַצְמֵךְ, הֲרֵי בַּעְלֵךְ יָבא אֵלַיִךְ בְּתִקּוּנָיו מְזֻמָּן כְּנֶגְדֵּךְ. ה' אֱלֹהֵינוּ ה' אֶחָד, בְּיִחוּד אֶחָד, בְּרָצוֹן אֶחָד, בְּלִי פֵרוּד, שֶׁכָּל אוֹתָם הָאֵיבָרִים נַעֲשִׂים אֶחָד, וְנִכְנָסִים בְּאֶחָד בִּתְשׁוּקָה.</p>\n<p>כֵּיוָן שֶׁאוֹמְרִים יִשְׂרָאֵל \"ה' אֶחָד\" בְּהִתְעוֹרְרוּת שִׁשָּׁה צְדָדִים, אָז כָּל אוֹתָם שֵׁשֶׁת הַצְּדָדִים נַעֲשִׂים אֶחָד וְנִכְנָסִים בִּתְשׁוּקָה אַחַת, וְסוֹד זֶה ו' אֶחָד, פְּשִׁיטוּת בִּלְבַדּוֹ בְּלִי דְבְקוּת אַחֶרֶת אֵלָיו, אֶלָּא הוּא לְבַדּוֹ פָּשׁוּט מִכֹּל, וְהוּא אֶחָד.</p>\n<p>בְּאוֹתָהּ שָׁעָה הַגְּבִירָה מִתְתַּקֶּנֶת וּמִתְקַשֶּׁטֶת, וְשַׁמָּשֶׁיהָ מַכְנִיסִים אוֹתָהּ בְּלַחַשׁ רַב אֶל בַּעְלָהּ, וְאוֹמְרִים: בָּרוּךְ שֵׁם כְּבוֹד מַלְכוּתוֹ לְעוֹלָם וָעֶד. זֶהוּ בְּלַחַשׁ, שֶׁכָּךְ צָרִיךְ לְהַכְנִיסָהּ לְבַעְלָהּ. אַשְׁרֵי הָעָם שֶׁיּוֹדְעִים אֶת זֶה וּמְסַדְּרִים סִדּוּר עֶלְיוֹן שֶׁל הָאֱמוּנָה.</p>\n<p>בְּאוֹתָהּ שָׁעָה שֶׁמִּתְחַבְּרִים הַבַּעַל וְהַגְּבִירָה כְּאֶחָד, אָז הַכָּרוֹז יוֹצֵא מִצַּד הַדָּרוֹם, מִתְעוֹרְרִים חֲיָלוֹת וּמַחֲנוֹת שֶׁמְּגַלִּים אַהֲבָה לְרִבּוֹנָם.</p>\n<p>אָז מִתְעוֹרֵר מְמֻנֶּה אֶחָד עֶלְיוֹן, שֶׁשְּׁמוֹ בּוּאֵ\"ל, גְּדוֹל הַמַּחֲנוֹת, וּבְיָדוֹ אַרְבָּעָה מַפְתְּחוֹת שֶׁנּוֹטֵל מֵאַרְבַּעַת צִדְדֵי הָעוֹלָם. וּמַפְתֵּחַ אֶחָד נִרְשָׁם בָּאוֹת י', וּמַפְתֵּחַ אַחֵר נִרְשָׁם בָּאוֹת ה', וּמַפְתֵּחַ אֶחָד נִרְשָׁם בָּאוֹת ו', (וּמפתּח אחר נרשָם בָּאות ה') וּמַנִּיחִים אוֹתוֹ תַּחַת עֵץ הַחַיִּים. וְאוֹתָם שְׁלֹשָׁה מַפְתְּחוֹת שֶׁנִּרְשְׁמוּ בִּשְׁלֹשׁ הָאוֹתִיּוֹת הַלָּלוּ נַעֲשִׂים אֶחָד. כֵּיוָן שֶׁנַּעֲשִׂים אֶחָד, אוֹתוֹ הַמַּפְתֵּחַ הָאַחֵר עוֹלֶה וְעוֹמֵד וּמִתְחַבֵּר בְּאוֹתוֹ אַחֵר שֶׁהוּא כְּלַל הַשָּׁלֹשׁ, וְכָל אוֹתָם מַחֲנוֹת וַחֲיָלוֹת נִכְנָסִים לְאוֹתָם שְׁנֵי הַמַּפְתְּחוֹת לְתוֹךְ הַגָּן, וְכֻלָּם מְיַחֲדִים כְּמוֹ שֶׁלְּמַטָּה.</p>\n<p>יְהֹוָ\"ה - זֶה רֹשֶׁם שֶׁל הָאוֹת י', הָרֹאשׁ הָעֶלְיוֹן שֶׁבַּשֵּׁם הַקָּדוֹשׁ. אֱלֹהֵינוּ - זֶהוּ סוֹד שֶׁל רֹשֶׁם הָאוֹת ה' הָעֶלְיוֹנָה, הָאוֹת הַשְּׁנִיָּה שֶׁבַּשֵּׁם הַקָּדוֹשׁ. יְהֹוָ\"ה - זוֹ מְשִׁיכָה שֶׁנִּמְשֶׁכֶת לְמַטָּה בְּסוֹד הָרֹשֶׁם שֶׁל הָאוֹת ו', שֶׁהֵן שְׁתַּיִם, וְהָאוֹתִיּוֹת נִמְשָׁכוֹת לִהְיוֹת בַּמָּקוֹם הַזֶּה, וְהוּא אֶחָד. כָּל הַשָּׁלֹשׁ הַלָּלוּ הֵן אֶחָד בְּיִחוּד אֶחָד.</p>\n<p>כֵּיוָן שֶׁכָּל זֶה נַעֲשֶׂה אֶחָד בְּיִחוּד אֶחָד, וְנִשְׁאָר הַכֹּל בַּסּוֹד שֶׁל אוֹת ו' שָׁלֵם, מֵרֹאשׁ הַמַּעְיָן וּמֵהַהֵיכָל הַפְּנִימִי, וְיוֹרֵשׁ אֶת הָאַבָּא וְהָאִמָּא, אָז מַכְנִיסִים אֶת הַגְּבִירָה עִמּוֹ, שֶׁהֲרֵי עַכְשָׁו הוּא שָׁלֵם בְּכָל הַטּוּב הָעֶלְיוֹן, וְיָכוֹל לְהָזִין אוֹתָהּ וְלָתֵת לָהּ מָזוֹן וְסִפּוּק כָּרָאוּי. וְכָל אוֹתָם הָאֵיבָרִים שֶׁלּוֹ כֻּלָּם אֶחָד. וְאָז מַכְנִיסִים אוֹתָהּ אֵלָיו בְּלַחַשׁ. לָמָּה בְּלַחַשׁ? כְּדֵי שֶׁלֹּא יִתְעָרֵב זָר בְּאוֹתָהּ שִׂמְחָה, כְּמוֹ שֶׁנֶּאֱמַר (משלי יד) וּבְשִׂמְחָתוֹ לֹא יִתְעָרַב זָר.</p>\n<p>כֵּיוָן שֶׁהוּא מִתְיַחֵד לְמַעְלָה בְּשִׁשָּׁה צְדָדִים, אַף כָּךְ הִיא מִתְיַחֶדֶת לְמַטָּה בְּשִׁשָּׁה צְדָדִים אֲחֵרִים, כְּדֵי לִהְיוֹת אֶחָד לְמַעְלָה וְאֶחָד לְמַטָּה, כְּמוֹ שֶׁנֶּאֱמַר (זכריה ד) יִהְיֶה ה' אֶחָד וּשְׁמוֹ אֶחָד. אֶחָד לְמַעְלָה בְּשִׁשָּׁה צְדָדִים - שֶׁכָּתוּב (דברים ו) שְׁמַע יִשְׂרָאֵל ה' אֱלֹהֵינוּ ה' אֶחָד. הֲרֵי שֵׁשׁ תֵּבוֹת כְּנֶגֶד שִׁשָּׁה צְדָדִים. אֶחָד לְמַטָּה בְּשִׁשָּׁה צְדָדִים - (זהו שכתוב) בָּרוּךְ שֵׁם כְּבוֹד מַלְכוּתוֹ לְעוֹלָם וָעֶד. הֲרֵי שִׁשָּׁה צְדָדִים אֲחֵרִים בְּשֵׁשׁ תֵּבוֹת. ה' אֶחָד - לְמַעְלָה. וּשְׁמוֹ אֶחָד - לְמַטָּה.</p>\n<p>וְאִם תֹּאמַר, הֲרֵי כָּתוּב אֶחָד לְמַעְלָה, וּלְמַטָּה לֹא כָתוּב אֶחָד. וָעֶד הוּא אֶחָד בְּחִלּוּפֵי אוֹתִיּוֹת. אוֹתִיּוֹת הַזָּכָר לֹא מִתְחַלְּפוֹת, אוֹתִיּוֹת הַנְּקֵבָה מִתְחַלְּפוֹת, שֶׁהֲרֵי שֶׁבַח הַזָּכָר עַל הַנְּקֵבָה. וּכְדֵי שֶׁלֹּא תִשְׁלֹט עַיִן הָרָע אָנוּ מַחֲלִיפִים אוֹתִיּוֹת שֶׁלֹּא אוֹמְרִים אֶחָד בְּגָלוּי, וְלֶעָתִיד לָבֹא כְּשֶׁתַּעֲבֹר עַיִן הָרָע מִן הָעוֹלָם וְלֹא תִשְׁלֹט (אצלה), אָז יִקָּרֵא אֶחָד בְּגָלוּי. מִשּׁוּם שֶׁעַכְשָׁו, כְּשֶׁאוֹתוֹ הַצַּד הָאַחֵר נִדְבָּק עִמָּהּ, אֵינָהּ אֶחָד, אֶלָּא שֶׁאָנוּ מְיַחֲדִים אוֹתָהּ בְּלַחַשׁ בְּסוֹד הָאוֹתִיּוֹת הָאֲחֵרוֹת, וְאוֹמְרִים וָעֶד.</p>\n<p>אֲבָל לֶעָתִיד לָבֹא שֶׁיִּפָּרֵד אוֹתוֹ הַצַּד מִמֶּנָּה וְיָעֳבַר מֵהָעוֹלָם, אָז יִקָּרֵא אֶחָד וַדַּאי, שֶׁלֹּא יִהְיֶה עִמָּהּ שֻׁתָּפוּת וּדְבֵקוּת אַחֶרֶת, כְּמוֹ שֶׁנֶּאֱמַר (זכריה יד) בַּיּוֹם הַהוּא יִהְיֶה ה' אֶחָד וּשְׁמוֹ אֶחָד, בְּגָלוּי בְּפֵרוּשׁ, וְלֹא בְּלַחַשׁ וְלֹא בְּסוֹד.</p>\n<p>וְלָכֵן אָנוּ מְיַחֲדִים אוֹתָהּ מֵאוֹתוֹ הַצַּד הָאַחֵר, כְּמִי שֶׁמַּזְמִין אַחֵר לִהְיוֹת עֵד שֶׁלּוֹ, מִשּׁוּם שֶׁזֶּהוּ הָעֵד שֶׁלָּנוּ, וְהַצַּד הָאַחֵר אֵינוֹ עֵד אֵלֵינוּ. וְאָז הִיא נִפְרֶדֶת מֵאוֹתוֹ הַצַּד. כֵּיוָן שֶׁבָּאָה, אָנוּ מַכְנִיסִים אוֹתָהּ לַחֻפָּה אֶל בַּעְלָהּ, הַמֶּלֶךְ הָעֶלְיוֹן, בְּכָל רָצוֹן וִכַוָּנַת הַלֵּב, וְלָכֵן הוּא אֶחָד.</p>\n<p>בְּשָׁעָֹה שֶׁהִיא בָּאָה עִם עַלְמוֹתֶיהָ וְרוֹצָה לְהִפָּרֵד מֵהַצַּד הָאַחֵר, לֹא בָאָה אֶלָּא כְּמִי שֶׁמִּזְדַּמֶּנֶת לִרְאוֹת אֶת כְּבוֹד הַמֶּלֶךְ וְלֹא יוֹתֵר, וְכָךְ מַכְרִיזִים שֶׁיִּזְדַּמְּנוּ לִרְאוֹת בִּכְבוֹד הַמֶּלֶךְ, כְּמוֹ שֶׁנֶּאֱמַר (שיר השירים ג) צְאֶינָה וּרְאֶינָה בְּנוֹת צִיּוֹן בַּמֶּלֶךְ שְׁלֹמֹה. צְאוּ לִרְאוֹת בִּכְבוֹד הַמֶּלֶךְ אָז הַצַּד הָאַחֵר לֹא נוֹחַ לוֹ לִרְאוֹת, וְנִפְרָד מִמֶּנָּה. כֵּיוָן שֶׁבָּאָה, כָּל אוֹתָם שַׁמָּשֶׁיהָ מַכְנִיסִים אוֹתָהּ לַחֻפָּה עִם הַמֶּלֶךְ הָעֶלְיוֹן בְּלַחַשׁ, בְּסוֹד. שֶׁאִלְמָלֵא לֹא כָּךְ, לֹא יִפָּרֵד מִמֶּנָּה אוֹתוֹ הַצַּד הָאַחֵר וְתִתְעָרֵב הַשִּׂמְחָה. אֲבָל לֶעָתִיד לָבא, כְּשֶׁיִּפָּרֵד מִמֶּנָּה אוֹתוֹ הַצַּד הָאַחֵר, אָז בַּיּוֹם הַהוּא יִהְיֶה ה' אֶחָד וּשְׁמוֹ אֶחָד.</p>\n<p>כֵּיוָן שֶׁנִּכְנֶסֶת לַחֻפָּה וְהִיא עִם הַמֶּלֶךְ הָעֶלְיוֹן, אָז אָנוּ מְעוֹרְרִים שִׂמְחָה שֶׁל יָמִין וּשְׂמֹאל, כְּמוֹ שֶׁנֶּאֱמַר (דברים ו) וְאָהַבְתָּ אֶת ה' אֱלֹהֶיךְ בְּכָל לְבָבְךְ וְגוֹ', וְהָיָה אִם שָׁמוֹעַ וְגוֹ', בְּלִי פַחַד כְּלָל, שֶׁהֲרֵי הַצַּד הָאַחֵר לֹא יִתְקָרֵב לְשָׁם וְאֵין לוֹ רְשׁוּת.</p>\n<p>הַכַּלָּה, כָּל זְמַן שֶׁרוֹצִים לְהַכְנִיסָהּ לַמֶּלֶךְ לְשִׂמְחַת הַשִּׁמּוּשׁ, צָרִיךְ בְּלַחַשׁ בְּסוֹד, כְּדֵי שֶׁלֹּא יִמָּצֵא בְּרַגְלֵי (אדם שמגלה) צְעָדֶיהָ, רֶמֶז שֶׁל הַצַּד הָרָע וְלֹא יִדְבַּק עִמָּהּ, וְלֹא יִמָּצִאוּ בַּבָּנִים רֶמֶז שֶׁל פְּסוּל כְּלָל.</p>\n<p>וְכָךָֹ אָמַר יַעֲקֹב לְבָנָיו, שֶׁמָּא חַס וְשָׁלוֹם אֵרַע פְּסוּל (בזרעי או) בְּמִטָּתִי. אָז הֵם אָמְרוּ, כְּמוֹ שֶׁאֵין בְּלִבְּךְ אֶלָּא אֶחָד, כָּךְ וְכוּ', אֵין לָנוּ דְּבֵקוּת בַּצַּד הָאַחֵר כְּלָל. שֶׁהֲרֵי פָּרוּשׁ הָיָה מִמִּטָּתְךְ, וְאָנוּ בְּיִחוּד לַמֶּלֶךְ הָעֶלְיוֹן וְאֵין לָנוּ כְּלָל דְּבֵקוּת בַּצַּד הָאַחֵר, שֶׁהֲרֵי בִּפְרֵדָה מֵהַצַּד הָאַחֵר (היינוברצון) הָיָה הָרָצוֹן וְהַמַּחֲשָׁבָה שֶׁלָּנוּ.</p>\n<p>כֵּיוָן שֶׁיָּדַע שֶׁהַצַּד הָאַחֵר, לֹא נִדְבַּק שָׁם כְּלָל, אָז נִכְנְסָה הָאִשָּׁה לְבַעְלָהּ בְּלַחַשׁ, בְּסוֹד הַיִּחוּד שֶׁל שִׁשָּׁה צְדָדִים. פָּתַח וְאָמַר, בָּרוּךְ שֵׁם כְּבוֹד מַלְכוּתוֹ לְעוֹלָם וָעֶד, שֶׁהֲרֵי הִיא בְּסוֹד שֶׁל אֶחָד, בְּעַלְמוֹתֶיהָ, בְּלִי עִרְבּוּב כְּלָל, וְלֹא שֻׁתָּפוּת שֶׁל הַצַּד הָאַחֵר.</p>\n<p>וּבֹא רְאֵה, בְּאוֹתָהּ שָׁעָה הָיוּ יַעֲקֹב וּבָנָיו בִּדְיוֹקָן עֶלְיוֹן לְמַטָּה עִם הַשְּׁכִינָה. יַעֲקֹב הָיָה בְּסוֹד שֶׁל שִׁשָּׁה צְדָדִים שֶׁל הָעוֹלָם הָעֶלְיוֹן בְּסוֹד אֶחָד. בָּנָיו הָיוּ בִּדְיוֹקָן שֶׁל שִׁשָּׁה צְדָדִים שֶׁל הָעוֹלָם הַתַּחְתּוֹן. וְהוּא רָצָה לְגַלּוֹת לָהֶם אוֹתוֹ קֵץ, כְּמוֹ שֶׁבֵּאַרְנוּ, שֶׁיֵּשׁ קֵץ וְיֵשׁ קֵץ, יֵשׁ קֵץ הַיָּמִין וְיֵשׁ קֵץ הַיָּמִים. קֵץ הַיָּמִין - זוֹ הַמַּלְכוּת הַקְּדוֹשָׁה, סוֹד הָאֱמוּנָה, סוֹד מַלְכוּת הַשָּׁמַיִם. קֵץ הַיָּמִים - זֶה סוֹד שֶׁל מַלְכוּת הָרְשָׁעָה, סוֹד שֶׁל הַצַּד הָאַחֵר שֶׁנִּקְרָא קֵץ כָּל בָּשָׂר, וַהֲרֵי בֵּאַרְנוּ.</p>\n<p>כֵּיוָן שֶׁרָאָה שֶׁהִסְתַּלְּקָה שְׁכִינָה מִמֶּנּוּ וְכוּ', הֵם אָמְרוּ: כְּמוֹ שֶׁאֵין בְּלִבְּךְ אֶלָּא אֶחָד, שֶׁאַתָּה בַּסּוֹד שֶׁל הָעוֹלָם הָעֶלְיוֹן וְהוּא אֶחָד - אַף אָנוּ, שֶׁאָנוּ בַּסּוֹד שֶׁל הָעוֹלָם הַתַּחְתּוֹן, הוּא אֶחָד. וְלָכֵן נִזְכְּרוּ שְׁנֵי לְבָבוֹת, סוֹד שֶׁל הָעוֹלָם הָעֶלְיוֹן, שֶׁהוּא הַלֵּב שֶׁל יַעֲקֹב, וְהַסּוֹד שֶׁל הָעוֹלָם הַתַּחְתּוֹן, שֶׁהוּא הַלֵּב שֶׁל בָּנָיו. אָז הִכְנִיס אוֹתָהּ בְּלַחַשׁ.</p>\n<p>וּכְמוֹ שֶׁהֵם הִתְיַחֲדוּ - הַסּוֹד שֶׁל הָעוֹלָם הָעֶלְיוֹן בְּאֶחָד, וְהַסּוֹד שֶׁל הָעוֹלָם הַתַּחְתּוֹן בְּאֶחָד, אַף כָּךְ אָנוּ צְרִיכִים לְיַחֵד אֶת הָעוֹלָם הָעֶלְיוֹן בְּאֶחָד וּלְיַחֵד אֶת הָעוֹלָם הַתַּחְתּוֹן בְּסוֹד שֶׁל אֶחָד. זֶה בְּשִׁשָּׁה צְדָדִים, וְזֶה בְּשִׁשָּׁה צְדָדִים. וְלָכֵן שֵׁשׁ תֵּבוֹת כָּאן בְּסוֹד שֶׁל שִׁשָּׁה צְדָדִים. וְשֵׁשׁ תֵּבוֹת כָּאן בְּסוֹד שֶׁל שִׁשָּׁה צְדָדִים, (זכריה יד) ה' אֶחָד וּשְׁמוֹ אֶחָד. אַשְׁרֵי גּוֹרָלוֹ וְחֶלְקוֹ שֶׁל מִי שֶׁשָּׂם רְצוֹנוֹ לָזֶה בָּעוֹלָם הַזָּה וּבָעוֹלָם הַבָּא.</p>\n<p>רַב הַמְנוּנָא סָבָא אָמַר כָּךְ, הִתְעוֹרְרוּת זוֹ שֶׁל הַיִּחוּד יָפָה הִיא, שֶׁסּוֹד בֵּרוּר הַדָּבָר הֲרֵי בֵּאַרְנוּ, וְהַדְּבָרִים הַלָּלוּ עֲתִידִים לְהִתְעַתֵּד לִפְנֵי עַתִּיק הַיָּמִים בְּלִי בוּשָׁה כְּלָל.</p>\n<p>מִצְוָה לִלְמֹד תּוֹרָה בְּכָל יוֹם, שֶׁהִיא סוֹד הָאֱמוּנָה הָעֶלְיוֹנָה לָדַעַת דַּרְכֵי הַקָּדוֹשׁ בָּרוּךְ הוּא. שֶׁכָּל מִי שֶׁמִּשְׁתַּדֵּל בַּתּוֹרָה, זוֹכֶה בָּעוֹלָם הַזֶּה וְזוֹכֶה בָּעוֹלָם הַבָּא וְנִצּוֹל מִכָּל הַמְקַטְרְגִים הָרָעִים, מִשּׁוּם שֶׁהַתּוֹרָה הִיא סוֹד הָאֱמוּנָה, שֶׁמִּי שֶׁמִּתְעַסֵּק בָּהּ, מִתְעַסֵּק בָּאֱמוּנָה הָעֶלְיוֹנָה, וְהַקָּדוֹשׁ בָּרוּךְ הוּא מַשְׁרֶה שְׁכִינָתוֹ בְתוֹכוֹ שֶׁלֹּא תָזוּז מִמֶּנּוּ.</p>\n<p>מִי שֶׁיּוֹדֵעַ דְּבַר תּוֹרָה, צָרִיךְ לִרְדֹּף אַחֲרָיו וְלִלְמֹד דָּבָר זֶה מִמֶּנּוּ, לְקַיֵּם אֶת סוֹד הַכָּתוּב, מֵאֵת כָּל אִישׁ אֲשֶׁר יִדְּבֶנּוּ לִבּוֹ תִּקְחוּ אֶת תְּרוּמָתִי. הַתּוֹרָה הִיא עֵץ הַחַיִּים לָתֵת חַיִּים לַכֹּל. מִי שֶׁמִּתְחַזֵּק בַּתּוֹרָה, מִתְחַזֵּק בְּעֵץ הַחַיִּים, כְּמוֹ שֶׁנֶּאֱמַר (משלי ג) עֵץ חַיִּים הִיא לַמַּחֲזִיקִים בָּהּ.</p>\n<p>וְכַמָּה סוֹדוֹת עֶלְיוֹנִים בֵּאַרְנוּ בְּמִי שֶׁמִּשְׁתַּדֵּל בַּתּוֹרָה, שֶׁזּוֹכֶה לְהִקָּשֵׁר בַּתּוֹרָה שֶׁלְּמַעְלָה. בָּעוֹלָם הַזֶּה אֵינוֹ שׁוֹכֵךְ, וְאֵינוֹ שׁוֹכֵךְ בָּעוֹלָם הַבָּא, וַאֲפִלּוּ בַּקֶּבֶר שִׂפְתוֹתָיו מְרַחֲשׁוֹת בַּתּוֹרָה, כְּמוֹ שֶׁנֶּאֱמַר דּוֹבֵב שִׂפְתֵי יְשֵׁנִים.</p>"],[9522011703,"<p>פָּתַח וְאָמַר, וְיִקְחוּ לִי תְּרוּמָה. כָּאן הוּא יִחוּד בִּכְלָל אֶחָד. מַעְלָה וּמַטָּה. לֹא כָתוּב וְיִקְחוּ תְרוּמָה, אֶלָּא וְיִקְחוּ לִי תְּרוּמָה, מַעְלָה וּמַטָּה, בְּלִי פֵרוּד כְּלָל.</p>\n<p>מֵאֵת כָּל אִישׁ אֲשֶׁר יִדְּבֶנּוּ לִבּוֹ תִּקְחוּ אֶת תְּרוּמָתִי. פָּסוּק זֶה כָּךְ צָרִיךְ לוֹמַר אוֹתוֹ: כָּל אִישׁ אֲשֶׁר יִדְּבֶנּוּ לִבּוֹ. מַה זֶּה מֵאֵת כָּל אִישׁ? אֶלָּא סוֹד יֵשׁ כָּאן לְאוֹתָם בַּעֲלֵי מִדּוֹת. אַשְׁרֵיהֶם הַצַּדִּיקִים שֶׁיּוֹדְעִים לָשִׂים אֶת רְצוֹן לִבָּם לַמֶּלֶךְ הָעֶלְיוֹן הַקָּדוֹשׁ, וְכָל רְצוֹן לִבָּם אֵינוֹ לָעוֹלָם הַזֶּה, וְלַתַּאֲוָה הַבְּטֵלָה שֶׁלּוֹ. אֶלָּא יוֹדְעִים וּמִשְׁתַּדְּלִים לָשִׂים רְצוֹנָם וּלְהִדָּבֵק לְמַעְלָה, כְּדֵי לִמְשֹׁךְ רָצוֹן (שלהם) שֶׁל רִבּוֹנָם אֲלֵיהֶם מִמַּעְלָה לְמַטָּה.</p>\n<p>וּמֵאֵיזְהִ מָקוֹם נוֹטְלִים אוֹתוֹ רְצוֹן רִבּוֹנָם לִמְשֹׁךְ אוֹתוֹ אֲלֵיהֶם? הֵם נוֹטְלִים מִמָּקוֹם אֶחָד עֶלְיוֹן וְקָדוֹשׁ שֶׁמִּמֶּנּוּ יוֹצְאִים כָּל הָרְצוֹנוֹת הַקְּדוֹשִׁים. וּמִי הוּא? כָּל אִישׁ. זֶה צַדִּיק שֶׁנִּקְרָא כֹּל, כְּמוֹ שֶׁנֶּאֱמַר (קהלת ה) וְיִתְרוֹן אֶרֶץ בַּכֹּל הִיא. (תהלים קיט) עַל כֵּן כָּל פִּקּוּדֵי כֹל יִשָּׁרְתִּי. אִישׁ - כְּמוֹ שֶׁנֶּאֱמַר אִישׁ צַדִּיק. זֶהוּ צַדִּיק (כל איש) בַּעַל הַבַּיִת שֶׁרְצוֹנוֹ תָּמִיד לַגְּבִירָה, כְּמוֹ בַּעַל שֶׁאוֹהֵב אֶת אִשְׁתּוֹ תָּמִיד. יִדְּבֶנּוּ לִבּוֹ - הוּא אוֹהֵב אוֹתָהּ, וְלִבּוֹ, שֶׁהִיא הַגְּבִירָה שֶׁלּוֹ, יִדְּבֶנּוּ לְהִדָּבֵק בָּהּ.</p>\n<p>וְאַף עַל גַּב שֶׁאַהֲבָה רַבָּה זֶה עִם זֶה, שֶׁלֹּא נִפְרָדִים לְעוֹלָמִים, מֵאוֹתוֹ כָּל אִישׁ, בַּעַל הַבַּיִת, בַּעַל הַגְּבִירָה, מִמֶּנּוּ תִּקְחוּ אֶת תְּרוּמָתִי. דֶּרֶךְ הָעוֹלָם, מִי שֶׁרוֹצֶה לָקַחַת אִשְׁתּוֹ שֶׁל אָדָם מִמֶּנּוּ, הוּא מַקְפִּיד וְלֹא עוֹזֵב אוֹתָהּ. אֲבָל הַקָּדוֹשׁ בָּרוּךְ הוּא לֹא כָּךְ. כָּתוּב וְזֹאת הַתְּרוּמָה - זוֹ כְּנֶסֶת יִשְׂרָאֵל. אַף עַל גַּב שֶׁכָּל אַהֲבָתָהּ אֵלָיו וְאַהֲבָתוֹ אֵלֶיהָ, מִמֶּנּוּ נוֹטְלִים אוֹתָהּ לְהַשְׁרוֹתָהּ בֵּינֵיהֶם, מֵאוֹתוֹ מָקוֹם עֶלְיוֹן, שֶׁכָּל הָאַהֲבָה שֶׁל אִשָּׁה וּבַעְלָהּ שׁוֹרָה, מִשָּׁם תִּקְחוּ אֶת תְּרוּמָתִי. אַשְׁרֵי חֶלְקָם שֶׁל יִשְׂרָאֵל, וְאַשְׁרֵי כֻּלָּם שֶׁזָּכוּ לָזֶה.</p>\n<p>וְזֹאת הַתְּרוּמָה אֲשֶׁר תִּקְחוּ מֵאִתָּם. וְאִם תֹּאמַר, אִם כָּךְ, אֲשֶׁר תִּקְחוּ מֵאִתּוֹ הָיָה צָרִיךְ לִהְיוֹת! מַה זֶּה מֵאִתָּם? מֵאֵת שְׁנֵי הַשֵּׁמוֹת (הדרגות) הַלָּלוּ.</p>\n<p>עוֹד אָמַר רַב יֵיבָא סָבָא, מֵאִתָּם - מֵאֵת ם', שֶׁהוּא סוֹד הָעוֹלָם הָעֶלְיוֹן, מְקוֹם מְדוֹרוֹ שֶׁל הַצַּדִּיק הַזֶּה שֶׁמִּתְעַטֵּר מֵהָאוֹת ם', וּמִשָּׁם נוֹטֵל חַיִּים לְהָזִין אֶת כָּל הָעוֹלָמוֹת. וְהַכֹּל דָּבָר אֶחָד, הַסּוֹד שֶׁנִּתָּן לַחֲכָמִים. אַשְׁרֵי חֶלְקָם.</p>\n<p>שֶׁאַף עַל גַּב שֶׁהֵם נוֹטְלִים אוֹתָהּ, (כאן) לֹא יְכוֹלִים לִטֹּל אוֹתָהּ אֶלָּא רַק בִּרְשׁוּת בַּעְלָהּ וּבִרְצוֹנוֹ, וְלַעֲשׂוֹת עֲבוֹדָה שֶׁל אַהֲבָה אֵלָיו, וְאָז בְּאַהֲבָתוֹ תִּקְחוּ אֶת תְּרוּמָתִי. וְכָל זֶה בְּאוֹתָן הָעֲבוֹדוֹת שֶׁל הַתְּפִלָּה, וְתִקּוּן וְסִדּוּר שֶׁיִּשְׂרָאֵל מְסַדְּרִים בְּכָל יוֹם. דָּבָר אַחֵר מֵאִתָּם - מֵהַכְּלָל שֶׁל שִׁשָּׁה צְדָדִים הָעֶלְיוֹנִים, וְהַכֹּל אֶחָד.</p>\n<p>(ד\"א) מֵאִתָּם - מֵאוֹתָם זְמַנִּים וְשַׁבָּתוֹת, וְהַכֹּל סוֹד אֶחָד. זָהָב וָכֶסֶף וּנְחֹשֶׁת וּתְכֵלֶת וְאַרְגָּמָן וְתוֹלַעַת שָׁנִי. זָהָב - בַּסּוֹד שֶׁל יוֹם רֹאשׁ הַשָּׁנָה, שֶׁהוּא יוֹם שֶׁל זָהָב, יוֹם הַדִּין, וְשׁוֹלֵט אוֹתוֹ הַצַּד, כְּמוֹ שֶׁנֶּאֱמַר (איוב לז) מִצָּפוֹן זָהָב יֶאֱתֶה. וָכֶסֶף - זֶה יוֹם הַכִּפּוּרִים, שֶׁמִּתְלַבְּנִים חֲטָאֵיהֶם שֶׁל יִשְׂרָאֵל כְּמוֹ שֶׁלֶג, כְּמוֹ שֶׁנֶּאֱמַר (ישעיה א) אִם יִהְיוּ חֲטָאֵיכֶם כַּשָּׁנִים כַּשֶּׁלֶג יַלְבִּינוּ. וְכָתוּב (ויקרא טז) כִּי בַיּוֹם הַזֶּה יְכַפֵּר עֲלֵיכֶם לְטַהֵר אֶתְכֶם.</p>\n<p>וּנְחֹשֶׁת - יְמֵי קָרְבְּנוֹת הֶחָג, שֶׁהֵם מַרְכְּבוֹת הָעַמִּים עוֹבְדֵי כוֹכָבִים וּמַזָּלוֹת, וְהֵם נִקְרָאִים סוֹד שֶׁל הָרֵי נְחֹשֶׁת, וְלָכֵן מִתְמַעֲטִים בְּכָל יוֹם וְהוֹלְכִים. וּתְכֵלֶת - זֶה פֶּסַח, הַשִּׁלְטוֹן שֶׁל סוֹד הָאֱמוּנָה, הַסּוֹד שֶׁל צֶבַע הַתְּכֵלֶת. וּמִשּׁוּם שֶׁהִיא תְּכֵלֶת, לֹא שׁוֹלֶטֶת, עַד שֶׁמַּשְׁמִידָה וְהוֹרֶגֶת כָּל בְּכוֹרוֹת מִצְרַיִם, כְּמוֹ שֶׁנֶּאֱמַר (שמותיב) וְעָבַר ה' לִנְגֹּף אֶת מִצְרַיִם. וְלָכֵן כָּל הַגְּוָנִים טוֹבִים בַּחֲלוֹם, חוּץ מִתְּכֵלֶת.</p>\n<p>וְאַרְגָּמָן - זֶה שָׁבוּעוֹת, סוֹד הָאַרְגָּמָן, שֶׁתּוֹרָה שֶׁבִּכְתָב שֶׁנִּתְּנָה בּוֹ כְּלוּלָה מִשְּׁנֵי צְדָדִים - מִיָּמִין וּמִשְּׂמֹאל, כְּמוֹ שֶׁנֶּאֱמַר (דברים לב) מִימִינוֹ אֵשׁ דָּת לָמוֹ, וְזֶהוּ אַרְגָּמָן. וְתוֹלַעַת שָׁנִי - זֶהוּ ט\"ו בְּאָב, שֶׁבְּנוֹת יִשְׂרָאֵל הָיוּ יוֹצְאוֹת בִּכְלֵי מֵילָת, כְּמוֹ שֶׁנֶּאֱמַר (איכה ד) הָאֱמֻנִים עֲלֵי תוֹלָע.</p>\n<p>עֵד כָּאן שִׁשָּׁה צְדָדִים. מִכָּאן וָהָלְאָה הַסּוֹד שֶׁל עֲשֶׂרֶת יְמֵי תְשׁוּבָה. וְשֵׁשׁ. וְעִזִּים. וְעֹרֹת אֵילִם מְאָדָּמִים. וְעֹרֹת תְּחָשִׁים. וַעֲצֵי שִׁטִּים. וְשֶׁמֶן לַמָּאֹר. וּבְשָׂמִים לְשֶׁמֶן הַמִּשְׁחָה וְלִקְטֹרֶת הַסַּמִּים. וְאַבְנֵי שּהַם. וְאַבְנֵי מִלּוּאִים. עַד כָּאן תִּשְׁעָה, כְּנֶגֶד תִּשְׁעָה יָמִים, וְיוֹם הַכִּפּוּרִים מַשְׁלִים לַעֲשָׂרָה.</p>\n<p>וּמִכָּל אֵלֶּה אָנוּ נוֹטְלִים תְּרוּמַת ה' בְּכָל זְמַן וּזְמַן, כְּדֵי לְהַשְׁרוֹת עָלֵינוּ. בְּרֹאשׁ הַשָּׁנָה אָנוּ נוֹטְלִים תְּרוּמַת ה', וְהוּא סוֹד שֶׁל רֹאשׁ הַשָּׁנָה, שֶׁבָּא מִצַּד הַזָּהָב. בְּיוֹם הַכִּפּוּרִים אָנוּ נוֹטְלִים אוֹתָהּ, וְהִיא יוֹם הַכִּפּוּרִים שֶׁיּוֹרֶשֶׁת הַבַּת אֶת הָאֵם. בְּסֻכּוֹת אָנוּ נוֹטְלִים אוֹתָהּ, וְהִיא סֻכָּה, סוֹכֶכֶת וּמְגִנָּה עָלֵינוּ, וְכָתוּב (במדבר כט) בַּיּוֹם הַשְּׁמִינִי עֲצֶרֶת תִּהְיֶה לָכֶם, וְזוֹהִי תְּרוּמַת ה'.</p>\n<p>בְּפֶסַח אַף כָּךְ אָנוּ נוֹטְלִים אוֹתָהּ, וְהִיא פֶּסַח. וַהֲרֵי בֵּאַרְנוּ, סוֹד הַגָּוֶן שֶׁל אוֹר הַתְּכֵלֶת. בְּשָׁבוּעוֹת אָנוּ נוֹטְלִים אוֹתָהּ, וְהִיא שְׁתֵּי הַלֶּחֶם, וְכָתוּב (שמות כ) וַיְדַבֵּר אֱלֹהִים אֵת כָּל הַדְּבָרִים הָאֵלֶּה לֵאמֹר. וְאָנוּ נוֹטְלִים מִתּוֹרָה שֶׁבִּכְתָב תּוֹרָה שֶׁבְּעַל פֶּה. חֲמִשָּׁה עָשָׂר בְּאָב, הוּא עָמַד בְּשִׂמְחָה עַל בְּנוֹת יִשְׂרָאֵל. כָּל שְׁאָר הַיָּמִים הֵם לַתִּקּוּן שֶׁלָּהּ, וְלָכֵן כָּתוּב אֲשֶׁר תִּקְחוּ מֵאִתָּם.</p>"],[9522011704,"<p>כְּמוֹ שֶׁהֵם מִתְיַחֲדִים לְמַעְלָה בְּאֶחָד, אַף כָּךְ הִיא מִתְיַחֶדֶת לְמַטָּה בְּסוֹד שֶׁל אֶחָד, לִהְיוֹת עִמָּם לְמַעְלָה אֶחָד כְּנֶגֶד אֶחָד. הַקָּדוֹשׁ בָּרוּךְ הוּא אֶחָד לְמַעְלָה לֹא יוֹשֵׁב עַל כִּסֵּא כְבוֹדוֹ, עַד שֶׁנַּעֲשֵׂית בְּסוֹד שֶׁל אֶחָד כְּמוֹ שֶׁלּוֹ, לִהְיוֹת אֶחָד בְּאֶחָד. וַהֲרֵי בֵּאַרְנוּ הַסּוֹד שֶׁל ה' אֶחָד וּשְׁמוֹ אֶחָד.</p>\n<p>סוֹד הַשַּׁבָּת, הִיא שַׁבָּת שֶׁנֶּאֱחֶזֶת בְּסוֹד שֶׁל אֶחָ\"ד, לְהַשְׁרוֹת עָלֶיהָ הַסּוֹד שֶׁל אֶחָד. תְּפִלַּת עֶרֶב שַׁבָּת, שֶׁהֲרֵי אָז מִתְיַחֵד כִּסֵּא הַכָּבוֹד הַקָּדוֹשׁ בְּסוֹד שֶׁל אֶחָד, וּמִתְתַּקֶּנֶת שֶׁיִּשְׁרֶה עָלֶיהָ הַמֶּלֶךְ הַקָּדוֹשׁ הָעֶלְיוֹן.</p>\n<p>כְּשֶׁנִּכְנֶסֶת הַשַּׁבָּת, הִיא מִתְיַחֶדֶת וְנִפְרֶדֶת מֵהַצַּד הָאַחֵר, וְכָל הַדִּינִים מָעֳבָרִים מִמֶּנָּה, וְהִיא נִשְׁאֶרֶת בְּיִחוּד שֶׁל אוֹר קָדוֹשׁ, וּמִתְעַטֶּרֶת בְּכַמָּה עֲטָרוֹת לַמֶּלֶךְ הַקָּדוֹשׁ, וְכָל שַׁלִּיטֵי הָרֹגֶז וּבַעֲלֵי הַדִּין כֻּלָּם בּוֹרְחִים, (ומעברים ממנה) וְאֵין שִׁלְטוֹן אַחֵר בְּכָל הָעוֹלָמוֹת.</p>\n<p>וּפָנֶיהָ מְאִירִים בְּאוֹר עֶלְיוֹן, וּמִתְעַטֶּרֶת לְמַטָּה בָּעָם הַקָּדוֹשׁ, וְכֻלָּם מִתְעַטְּרִים בִּנְשָׁמוֹת חֲדָשׁוֹת. אָז רֵאשִׁית הַתְּפִלָּה, לְבָרֵךְ אוֹתָהּ בְּשִׂמְחָה, בְּפָנִים מְאִירוֹת, וְלוֹמַר בָּרְכוּ אֶת ה' הַמְבֹרָךְ. אֶת ה' דַּוְקָא, כְּדֵי לִפְתֹּחַ לָהּ בִּבְרָכָה.</p>\n<p>וְאָסוּר לָעָם הַקָּדוֹשׁ לִפְתֹּחַ אֵלֶיהָ בְּפָסוּק שֶׁל דִּין, כְּמוֹ וְהוּא רַחוּם וְגוֹ', מִשּׁוּם שֶׁהֲרֵי נִפְרְדָה מֵהַצַּד הָאַחֵר, וְכָל בַּעֲלֵי הַדִּינִים נִפְרְדוּ וְהָעָבְרוּ מִמֶּנָּה. וּמִי שֶׁמְּעוֹרֵר אֶת זֶה לְמַטָּה, גּוֹרֵם לְעוֹרֵר כָּךְ לְמַעְלָה, וְהַכִּסֵּא הַקָּדוֹשׁ לֹא יָכוֹל לְהִתְעַטֵּר בַּעֲטֶרֶת קְדֻשָּׁה. שֶׁכָּל זְמַן שֶׁמִּתְעוֹרְרִים לְמַטָּה אוֹתָם בַּעֲלֵי הַדִּין שֶׁהָיוּ מָעֳבָרִים וְהָיוּ הוֹלְכִים לְהִתְחַבֵּא בְּתוֹךְ הַנֶּקֶב שֶׁל הֶעָפָר שֶׁל הַתְּהוֹם הַגָּדוֹל, כֻּלָּם שָׁבִים לִשְׁרוֹת בִּמְקוֹמָם, וְהַמָּקוֹם הַקָּדוֹשׁ מִתְרַחֵק (ונדחק) בָּהֶם מִלִּהְיוֹת בִּמְנוּחָה.</p>\n<p>וְאַל תֹּאמַר שֶׁזֶּהוּ לְבַדּוֹ, אֶלָּא שֶׁאֵין הִתְעוֹרְרוּת לְמַעְלָה לְהִתְעוֹרֵר עַד שֶׁיִּשְׂרָאֵל מְעוֹרְרִים לְמַטָּה, כְּפִי שֶׁבֵּאַרְנוּ, שֶׁכָּתוּב (תהלים פא) בַּכֶּסֶה לְיוֹם חַגֵּנוּ. לֹא כָתוּב לְיוֹם חַג, אֶלָּא לְיוֹם חַגֵּנוּ. וְלָכֵן אָסוּר לָעָם הַקָּדוֹשׁ, שֶׁמִּתְעַטְּרִים בַּעֲטָרוֹת קְדוֹשׁוֹת שֶׁל נְשָׁמוֹת כְּדֵי לְעוֹרֵר מְנוּחָה, שֶׁהֵם יְעוֹרְרוּ דִין, אֶלָּא כֻּלָּם בְּרָצוֹן וְאַהֲבָה רַבָּה, שֶׁיְּעוֹרְרוּ בְרָכוֹת מַעְלָה וּמַטָּה כְּאֶחָד.</p>"],[9522011705,"<p>בָּרְכוּ אֶת ה' - דַּוְקָא אֶת, כְּמוֹ שֶׁאָמַרְנוּ, זוֹ שַׁבָּת שֶׁל עֶרֶב שַׁבָּת. בָּרוּךְ ה' הַמְבֹרָךְ - זוֹ יְצִיאַת הַבְּרָכוֹת מִמְּקוֹר הַחַיִּים, וּמָקוֹם שֶׁמִּמֶּנּוּ יוֹצֵאת כָּל הַהַשְׁקָאָה לְהַשְׁקוֹת אֶת הַכֹּל. וּמִשּׁוּם שֶׁהוּא הַמָּקוֹר בְּסוֹד שֶׁל אוֹת הַבְּרִית, קוֹרְאִים לוֹ הַמְבֹרָךְ, הוּא נְבִיעַת הַבְּאֵר. כֵּיוָן שֶׁמַּגִּיעִים לְשָׁם, הֲרֵי הַבְּאֵר וַדַּאי מִתְמַלֵּאת, שֶׁאֵין פּוֹסְקִים מֵימָיו לְעוֹלָמִים.</p>\n<p>וְלָכֵן לֹא אוֹמְרִים בָּרוּךְ אֶת ה' הַמְבֹרָךְ, אֶלָּא בָּרוּךְ ה'. שֶׁאִלְמָלֵא לֹא מַגִּיעָה לְשָׁם נְבִיעָה מֵהַמָּקוֹר הָעֶלְיוֹן, לֹא מִתְמַלֵּאת הַבְּאֵר כְּלָל, וְעַל זֶה הַמְבֹרָךְ. לָמָּה הוּא הַמְבֹרָךְ? מִשּׁוּם שֶׁהוּא מַשְׁלִים וּמַשְׁקֶה לְעוֹלָם וָעֶד. עוֹלָם וָעֶד זוֹהִי שַׁבָּת שֶׁל עֶרֶב שַׁבָּת, וְאָנוּ תּוֹקְעִים בְּרָכוֹת בְּמָקוֹם שֶׁנִּקְרָא מְבֹרָךְ. וְכֵיוָן שֶׁמַּגִּיעִים לְשָׁם, כֻּלָּם לְעוֹלָם וָעֶד. וְזֶהוּ בָּרוּךְ ה' הַמְבֹרָךְ. עַד כָּאן הִגִּיעוּ בְרָכוֹת מֵהָעוֹלָם הָעֶלְיוֹן, וְכֻלָּם לְעוֹלָם וָעֶד, לְהִתְבָּרֵךְ וְלִהְיוֹת מֻשְׁקֶה וְלִהְיוֹת שָׁלֵם כָּרָאוּי, מָלֵא מִכָּל הַצְּדָדִים.</p>\n<p>בָּרוּךָ - זֶהוּ הַמָּקוֹר הָעֶלְיוֹן שֶׁכָּל הַבְּרָכוֹת יוֹצְאוֹת מִמֶּנּוּ. וּכְשֶׁהַלְּבָנָה נִשְׁלֶמֶת, קוֹרְאִים אוֹתָהּ כָּךְ לַתַּחְתּוֹנִים, אֲבָל בָּרוּךְ מָקוֹר הָעֶלְיוֹן, כְּפִי שֶׁאָמַרְנוּ. ה' - זֶה אֶמְצָעִי שֶׁל כָּל הַצְּדָדִים הָעֶלְיוֹנִים. הַמְבֹרָךְ - זֶה שְׁלוֹם הַבַּיִת, נְבִיעַת הַבְּאֵר, לְהַשְׁלִים וּלְהַשְׁקוֹת הַכֹּל. לְעוֹלָם וָעֶד - זֶה הָעוֹלָם הַתַּחְתּוֹן שֶׁצָּרִיךְ לְהתְבָּרֵךְ. וְשֶׁמֶן וּמִשְׁחָה שֶׁל בָּרוּךְ ה' וְהַמְבֹרָךְ, הַכֹּל הוּא לְעוֹלָם וָעֶד. (מברך, כמו שנאמר (בראשית מט) בן פרת)</p>\n<p>וְלָכֵן הַבְּרָכָה הַזּוֹ צְרִיכִים כָּל הָעָם לְבָרֵךְ, וּבְעֶרֶב שַׁבָּת, בִּרְצוֹן הַלֵּב וּבְשִׂמְחָה צָרִיךְ לְהַתְחִיל בַּתְּחִלָּה בַּבְּרָכָה הַזּוֹ, שֶׁתִּתְבָּרֵךְ הַשַּׁבָּת הַזּוֹ שֶׁל עֶרֶב שַׁבָּת (בלילה) מֵהָעָם הַקָּדוֹשׁ כָּרָאוּי בַּבְּרָכָה הַזּוֹ.</p>\n<p>(ברכו) כְּשֶׁמַּתְחִילִים יִשְׂרָאֵל לְבָרֵךְ, קוֹל הוֹלֵךְ בְּכָל הָרְקִיעִים, שֶׁמִּתְקַדְּשִׁים בִּקְדֻשַּׁת עֶרֶב הַשַּׁבָּת: אַשְׁרֵיכֶם הָעָם הַקָּדוֹשׁ שֶׁאַתֶּם מְבָרְכִים וּמְקַדְּשִׁים לְמַטָּה כְּדֵי שֶׁיִּתְבָּרְכוּ וְיִתְקַדְּשׁוּ לְמַעְלָה כַּמָּה מַחֲנוֹת עֶלְיוֹנִים קְדוֹשִׁים. אַשְׁרֵיהֶם בָּעוֹלָם הַזֶּה, וְאַשְׁרֵיהֶם בָּעוֹלָם הַבָּא. וְלֹא מְבָרְכִים יִשְׂרָאֵל אֶת הַבְּרָכָה הַזּוֹ, עַד שֶׁמִּתְעַטְּרִים בַּעֲטָרוֹת שֶׁל נְשָׁמוֹת קְדוֹשׁוֹת, כְּפִי שֶׁאָמַרְנוּ. אַשְׁרֵי הָעָם שֶׁזָּכוּ לָהֶם בָּעוֹלָם הַזֶּה, לְזַכּוֹתָם לָעוֹלָם הַבָּא.</p>\n<p>בְּלַיְלָה זֶה שִׁמּוּשׁ שֶׁל הַחֲכָמִים בְּאֵלּוּ הַנְּשָׁמוֹת הַקְּדוֹשׁוֹת שֶׁמִּתְעַטְּרוֹת בָּהֶם, וְאַף עַל גַּב שֶׁהֲרֵי בֵּאַרְנוּ וְהַכֹּל אֶחָד. וּבְכָל מָקוֹם שֶׁתִּמְצָא לַחֲכָמִים בַּדָּבָר הַזֶּה בְּצַד זֶה, וְלִפְעָמִים בְּצַד זֶה - הַכֹּל הוּא אֶחָד, וּדְבָרִים הַלָּלוּ הֲרֵי כְּבָר בֵּאַרְנוּ. אֲבָל בַּפַּעַם הַזּוֹ שֶׁכֻּלָּם מִתְעַטְּרִים בִּנְשָׁמוֹת וְרוּחוֹת חֲדָשׁוֹת יְתֵרוֹת קְדוֹשׁוֹת, אָז הוּא הַזְּמַן שֶׁל הַשִּׁמּוּשׁ שֶׁלָּהֶם, כְּדֵי שֶׁיִּהְיֶה שֶׁפַע לְאוֹתוֹ שִׁמּוּשׁ (תשמיש) בְּשֶׁפַע שֶׁל קְדֻשָּׁה בִּמְנוּחָה עֶלְיוֹנָה, וְיֵצְאוּ בְנֵיהֶם קְדוֹשִׁים כָּרָאוּי.</p>\n<p>סוֹד זֶה נִתָּן לַחֲכָמִים. בְּשָׁעָה שֶׁנֶּחֱלָק הַלַּיְלָה, בַּלַּיְלָה הַזֶּה הַקָּדוֹשׁ בָּרוּךְ הוּא רוֹצֶה לְהִכָּנֵס לַגָּן שֶׁלְּמַעְלָה. וְסוֹד זֶה, בִּימֵי הַחֹל הַקָּדוֹשׁ בָּרוּךְ הוּא נִכְנָס לְגַן עֵדֶן שֶׁלְּמַטָּה לְהִשְׁתַּעֲשֵׁעַ עִם הַצַּדִּיקִים שֶׁשּׁוֹרִים שָׁם, וּבְשַׁבָּת, בְּאוֹתוֹ לֵיל שַׁבָּת, הַקָּדוֹשׁ בָּרוּךְ הוּא נִכְנָס לַגָּן שֶׁלְּמַעְלָה, בְּסוֹד הַמָּקוֹר הָעֶלְיוֹן.</p>\n<p>מִשּׁוּם שֶׁבִּימֵי הַחֹל כָּל נִשְׁמוֹת הַצַּדִּיקִים כֻּלָּן שׁוֹרוֹת בַּגָּן שֶׁבָּאָרֶץ, וּכְשֶׁמִּתְקַדֵּשׁ הַיּוֹם בְּעֶרֶב הַשַּׁבָּת, כָּל אוֹתָם מַחֲנוֹת שֶׁל מַלְאָכִים קְדוֹשִׁים שֶׁמְּמֻנִּים בְּתוֹךְ הַגָּן שֶׁלְּמַטָּה, כֻּלָּם מַעֲלִים אֶת אוֹתָן נְשָׁמוֹת שֶׁשּׁוֹרוֹת בְּתוֹךְ הַגָּן שֶׁלְּמַטָּה, לְהַכְנִיס לְאוֹתוֹ הָרָקִיעַ שֶׁעוֹמֵד עַל הַגָּן, וּמִשָּׁם מִזְדַּמְּנוֹת מֶרְכָּבוֹת קְדוֹשׁוֹת שֶׁסּוֹבְבוֹת אֶת כִּסֵּא הַכָּבוֹד שֶׁל הַמֶּלֶךְ, וּמַעֲלִים אוֹתָם אֶת כָּל אוֹתָן נְשָׁמוֹת לַגָּן שֶׁלְּמַעְלָה.</p>\n<p>כֵּיוָן שֶׁהָרוּחוֹת הַלָּלוּ עוֹלוֹת, אָז רוּחוֹת קְדוֹשׁוֹת אֲחֵרוֹת יוֹרְדוֹת לְהִתְעַטֵּר בָּהֶם הָעָם הַקָּדוֹשׁ. אֵלּוּ עוֹלוֹת וְאֵלּוּ יוֹרְדוֹת.</p>\n<p>וְאִם תֹּאמַר, הֲרֵי הַגָּן שֶׁבָּאָרֶץ בְּיוֹם הַשַּׁבָּת יוֹשֵׁב בְּרֵיקָנוּת בְּלִי נִשְׁמוֹת צַדִּיקִים - לֹא כָּךְ, אֶלָּא נְשָׁמוֹת הוֹלְכוֹת וּנְשָׁמוֹת בָּאוֹת, נְשָׁמוֹת עוֹלוֹת וּנְשָׁמוֹת יוֹרְדוֹת. נְשָׁמוֹת הוֹלְכוֹת מִתּוֹךְ הַגָּן, וּנְשָׁמוֹת בָּאוֹת לְתוֹךְ הַגָּן. כָּל אוֹתָן נִשְׁמוֹת הַצַּדִּיקִים שֶׁמִּתְלַבְּנוֹת בִּימוֹת הַחֹל, וְטֶרֶם שֶׁנִּכְנְסוּ לְתוֹךְ הַגָּן, בְּשָׁעָה שֶׁאֵלּוּ יוֹצְאוֹת - אֵלּוּ נִכְנָסוֹת, וְהַגָּן לֹא נִשְׁאָר רֵיק, בְּסוֹד לֶחֶם הַפָּנִים בְּיוֹם הִלָּקְחוֹ.</p>\n<p>וְאִם תֹּאמַר, כְּשֶׁחוֹזְרִים בִּימוֹת הַחֹל, בַּמֶּה (כמה) נִמְשָׁכִים הַמְּקוֹמוֹת לָאֹרֶךְ וְלָרֹחַב וְלָרוּם בַּגָּן, וְלֹא נוֹדָע? כְּמוֹ סוֹד אֶרֶץ הַצְּבִי, שֶׁהָיְתָה נִמְשֶׁכֶת לְכָל הַצְּדָדִים וְלֹא נוֹדָע. כְּמוֹ הַצְּבִי, שֶׁכָּל מַה שֶּׁגָּדֵל, עוֹרוֹ גָדֵל לְכָל צַד וְלֹא נִכָּר. וְיֵשׁ כַּמָּה נְשָׁמוֹת, שֶׁכֵּיוָן שֶׁעוֹלוֹת, שׁוּב לֹא יוֹרְדוֹת.</p>\n<p>נְשָׁמוֹת עוֹלוֹת וּנְשָׁמוֹת יוֹרְדוֹת לְהִתְעַטֵּר בָּהֶן הָעָם הַקָּדוֹשׁ. וּבְעֶרֶב שַׁבָּת הוּא גִּלְגּוּל הַנְּשָׁמוֹת, אֵלּוּ הוֹלְכוֹת וְאֵלּוּ בָּאוֹת, אֵלּוּ עוֹלוֹת וְאֵלּוּ יוֹרְדוֹת. מִי רָאָה כַּמָּה מֶרְכָּבוֹת קְדוֹשׁוֹת שֶׁמְּשׁוֹטְטוֹת לְכָאן וּלְכָאן. כֻּלָּן בְּשִׂמְחָה, כֻּלָּן בְּרָצוֹן בְּאֵלּוּ הַנְּשָׁמוֹת לְעַטֵּר אֶת הָעָם הַקָּדוֹשׁ, לְעַטֵּר לְכַמָּה צַדִּיקִים, גַּן הָעֵדֶן שֶׁלְּמַטָּה, עַד שָׁעָה שֶׁהַכָּרוֹז עוֹמֵד וְקוֹרֵא: מְקֻדָּשׁ מְקֻדָּשׁ. אָז נִמְצֵאת מְנוּחָה וְשׁוֹכֵךְ הַכֹּל. וְכָל רִשְׁעֵי הַגֵּיהִנֹּם שׁוֹכְכִים בִּמְקוֹמָם וְיֵשׁ לָהֶם מְנוּחָה. וְכָל הַנְּשָׁמוֹת מִתְעַטְּרוֹת, אֵלּוּ לְמַעְלָה וְאֵלּוּ לְמַטָּה. אַשְׁרֵי הָעָם שֶׁזֶּה חֶלְקָם.</p>\n<p>בַּחֲצוֹת לֵיל שַׁבָּת, כְּשֶׁהַחֲכָמִים מִתְעוֹרְרִים לְתַשְׁמִישָׁם, אוֹתָהּ רוּחַ עֶלְיוֹנָה שֶׁמִּתְעַטְּרִים בָּהּ כְּשֶׁמִּתְקַדֵּשׁ הַיּוֹם, בְּשָׁעָה שֶׁהֵם יְשֵׁנִים בְּמִטּוֹתֵיהֶם, וְהַנְּשָׁמוֹת הָאֲחֵרוֹת שֶׁלָּהֶם רוֹצוֹת לַעֲלוֹת לִרְאוֹת בִּכְבוֹד הַמֶּלֶךְ, אָז אוֹתָהּ רוּחַ עֶלְיוֹנָה שֶׁיּוֹרֶדֶת בְּעֶרֶב שַׁבָּת, נוֹטֶלֶת אוֹתָהּ נְשָׁמָה, וְעוֹלִים לְמַעְלָה, וְרוֹחֶצֶת נְשָׁמָה אַחֶרֶת בַּבְּשָׂמִים שֶׁל גַּן הָעֵדֶן, וְשָׁם רוֹאָה מַה שֶּׁרוֹאָה.</p>\n<p>וּכְשֶׁיּוֹרֶדֶת לִשְׁרוֹת בִּמְקוֹמָהּ בַּחֲצוֹת הַלַּיְלָה, אוֹתָהּ נְשָׁמָה שָׁבָה לִמְקוֹמָהּ, וּצְרִיכִים אוֹתָם הַחֲכָמִים לוֹמַר פָּסוּק אֶחָד שֶׁל הִתְעוֹרְרוּת שֶׁל אוֹתָהּ רוּחַ עֶלְיוֹנָה קְדוֹשָׁה שֶׁל עֲטֶרֶת הַשַּׁבָּת, כְּמוֹ (ישעיה סא) רוּחַ ה' אֱלֹהִים עָלָי יַעַן מָשַׁח ה' אוֹתִי לְבַשֵּׂר עֲנָוִים וְגוֹ'. (יחזקאל א) בְּלֶכְתָּם יֵלֵכוּ וּבְעָמְדָם יַעֲמֹדוּ וּבְהִנָּשְׂאָם מֵעַל הָאָרֶץ וְגוֹ', אֶל אֲשֶׁר יִהְיֶה שָּׁמָּה הָרוּחַ לָלֶכֶת יֵלֵכוּ וְגוֹ'. מִשּׁוּם שֶׁמִּתְעַטְּרוֹת בְּאוֹתָהּ רוּחַ בְּהִתְעוֹרְרוּתָם לְשִׂמְחַת הַתַּשְׁמִישׁ, וְיִהְיֶה שֶׁפַע שֶׁל אוֹתָהּ רוּחַ עֶלְיוֹנָה שֶׁל הַשַּׁבָּת בְּאוֹתוֹ תַּשְׁמִישׁ מִצְוָה.</p>\n<p>רַב הַמְנוּנָא סָבָא, כְּשֶׁהָיָה עוֹלֶה מֵהַנָּהָר בְּעֶרֶב שַׁבָּת, הָיָה יוֹשֵׁב רֶגַע אֶחָד וּמֵרִים עֵינָיו, וְהָיָה שָׂמֵחַ וְהָיָה אוֹמֵר שֶׁהָיָה יוֹשֵׁב לִרְאוֹת אֶת שִׂמְחַת הַמַּלְאָכִים הָעֶלְיוֹנִים, אֵלֶּה עוֹלִים וְאֵלֶּה יוֹרְדִים. וּבְכָל עֶרֶב שַׁבָּת יוֹשֵׁב אָדָם בְּעוֹלַם הַנְּשָׁמוֹת. אַשְׁרֵי מִי שֶׁיּוֹדֵעַ בְּסוֹד רִבּוֹנוֹ.</p>"],[9522011706,"<p>כְּשֶׁמֵּאִיר הַיּוֹם בְּיוֹם שַׁבָּת, עֲלִיַּת הַשִּׂמְחָה עוֹלָה בְּכָל הָעוֹלָמוֹת בִּמְנוּחָה בְּשִׂמְחָה. אָז (תהלים יט) הַשָּׁמַיִם מְסַפְּרִים כְּבוֹד אֵל וּמַעֲשֵׂה יָדָיו מַגִּיד הָרָקִיעַ. מִי הַשָּׁמַיִם? אֵלּוּ שָׁמַיִם שֶׁהַשֵּׁם הָעֶלְיוֹן נִרְאֶה בָהֶם, שֶׁהַשֵּׁם הַקָּדוֹשׁ רָשׁוּם בָּהֶם.</p>\n<p>מְסַפְּרִים - מַה הֵם מְסַפְּרִים? אִם תֹּאמַר כְּמִי שֶׁמְּדַבֵּר סִפּוּר דְּבָרִים - לֹא כָּךְ. אֶלָּא שֶׁמְּאִירִים וְנוֹצְצִים בְּהִתְנוֹצְצוּת שֶׁל אוֹר עֶלְיוֹן וְעוֹלִים בַּשֵּׁם שֶׁכּוֹלֵל בְּאוֹר שֶׁל שְׁלֵמוּת עֶלְיוֹנָה.</p>\n<p>וּמַה הוּא הַסִּפּוּר? שֶׁנּוֹצְצִים בְּאוֹר שֶׁל שְׁלֵמוּת הַסֵּפֶר הָעֶלְיוֹן. וְלָכֵן עוֹלִים בְּשֵׁם שָׁלֵם, וּמְאִירִים בְּאוֹר שָׁלֵם, וְנוֹצְצִים בְּהִתְנוֹצְצוּת שְׁלֵמָה. הֵם נוֹצְצִים וּמְאִירִים בְּעַצְמָם מִתּוֹךְ אוֹר שֶׁל הִתְנוֹצְצוּת הַסֵּפֶר הָעֶלְיוֹן, וְנוֹצְצִים וּמְאִירִים לְכָל צַד וְצַד (לכל כבוד וכבוד) שֶׁנִּדְבָּקִים בּוֹ. שֶׁהֲרֵי מֵהֶם, מֵאוֹתָהּ סַפִּירִיּוּת וְאוֹר מְאִירָה כָּל טַבַּעַת וְטַבַּעַת וְנוֹצֶצֶת בְּהִתְנוֹצְצוּת, מִשּׁוּם שֶׁבַּיּוֹם הַזֶּה מִתְעַטְּרִים הַשָּׁמַיִם וְעוֹלִים בַּשֵּׁם הַקָּדוֹשׁ יוֹתֵר מִבִּשְׁאָר הַיָּמִים.</p>\n<p>וּמַעָשֵׂה יָדָיו - אוֹתוֹ הַטַּל הָעֶלְיוֹן שֶׁמֵּאִיר מִכָּל הַצְּדָדִים הַגְּנוּזִים, שֶׁהוּא מַעֲשֵׂה יָדָיו, וְתִקּוּנוֹ - שֶׁמִּתְתַּקֵּן בַּיּוֹם הַזֶּה מִכָּל שְׁאָר הַיָּמִים.</p>\n<p>מַגִּיד הָרָקִיעַ - מַה מַּגִּיד? מוֹשֵׁךְ וְשׁוֹפֵעַ לְמַטָּה מֵרֹאשׁ הַמֶּלֶךְ, מָלֵא מִכָּל צְדָדָיו. הָרָקִיעַ - אוֹתוֹ הָרָקִיעַ שֶׁהוּא מַבּוּעַ הַבְּאֵר, וְזֶהוּ אוֹתוֹ נָהָר שֶׁיּוֹצֵא מֵעֵדֶן, וְזֶהוּ שֶׁשּׁוֹפֵעַ וּמוֹשֵׁךְ לְמַטָּה שֶׁפַע שֶׁל טַל עֶלְיוֹן שֶׁמֵּאִיר וְנוֹצֵץ בְּהִתְנוֹצְצוּת מִכָּל הַצְּדָדִים. וְהָרָקִיעַ הַזֶּה מַשְׁפִּיעַ לוֹ בִּמְשִׁיכָה שֶׁל אַהֲבָה וּתְשׁוּקָה לְהַשְׁקוֹת הַשְׁקָאַת הַשִּׂמְחָה לְעֶרֶב שַׁבָּת.</p>\n<p>וּכְשֶׁשּׁוֹפֵעַ וּמוֹשֵׁךְ אוֹתוֹ הַטַּל שֶׁל הַבְּדלַח, הַכֹּל (שופע) מָלֵא וְשָׁלֵם בְּאוֹתִיּוֹתָיו הַקְּדוֹשׁוֹת בְּכָל אוֹתָם שְׁבִילִים קְדוֹשִׁים. כֵּיוָן שֶׁהַכֹּל מִתְחַבֵּר בּוֹ, נַעֲשֶׂה בּוֹ דֶּרֶךְ לְהַשְׁקוֹת וּלְבָרֵךְ לְמַטָּה.</p>\n<p>יוֹם לְיוֹם - יוֹם לְיוֹם וְטַבַּעַת לְטַבַּעַת. עַכְשָׁו מְדַבֵּר הַכָּתוּב בְּדֶרֶךְ פְּרָט אֵיךְ הַשָּׁמַיִם מְסַפְּרִים וּמְתַקְּנִים בְּסַפִּירִיּוּת וּבְהִתְנוֹצְצוּת עֶלְיוֹנָה לַכָּבוֹד הַזֶּה, וְאֵיךְ שׁוֹפֵעַ וּמוֹשֵׁךְ אוֹתוֹ הָרָקִיעַ שֶׁפַע שֶׁל טַל עֶלְיוֹן. וְאוֹמֵר, יוֹם לְיוֹם יַבִּיעַ אֹמֶר. יוֹם לְיוֹם וְדַרְגָּה לְדַרְגָּה, יְחַוֶּה (אוחז) לְהִכָּלֵל זֶה בָּזֶה וּלְהָאִיר זֶה מִזֶּה מֵאוֹתָהּ סַפִּירִיּוּת שֶׁנּוֹצְצִים וּמְאִירִים הַשָּׁמַיִם לַכָּבוֹד הַזֶּה. יַבִּיעַ - כְּמוֹ שֶׁנֶּאֱמַר מַבָּע אִתְעָבֵד וְגוֹ'. מְמַהֲרִים לְהָאִיר זֶה מִזֶּה וּלְהִתְנוֹצֵץ זֶה מִזֶּה מֵאוֹתוֹ סַפִּירִיּוּת וְהִתְנוֹצְצוּת.</p>\n<p>אֹמֶ\"ר - כְּלָל שֶׁל הָאוֹתִיּוֹת וְהַשְּׁבִילִים שֶׁיּוֹצְאִים מֵאָב וָאֵם, וְאוֹתוֹ רֹאשׁ שֶׁיּוֹצֵא מֵהֶם, שֶׁהוּא בֵּן בְּכוֹר. אָלֶף - אַבָּא. וּכְשֶׁהוּא עוֹלֶה וְיוֹרֵד, מִתְחַבֶּרֶת מ' עִם א', וְהִיא אֵם. ר' - רֹאשׁ הַבְּכוֹר. כְּשֶׁמִּתְחַבְּרוֹת כָּל הָאוֹתִיּוֹת - אֹמֶר. זֶה אוֹר שֶׁל אָב וָאֵם וְהַבֵּן הַבְּכוֹר, וּמְאִירִים זֶה בָּזֶה בְּחִבּוּר אֶחָד. שׁוֹלֵט בְּיוֹם הַשַּׁבָּת. וְלָכֵן הַכֹּל נִכְלָל זֶה בָּזֶה, כְּדֵי לִהְיוֹת אֶחָד. וְלָכֵן מְמַהֲרִים זֶה בָּזֶה אוֹתוֹ אֹמֶר, שַׁלִּיט עֶלְיוֹן, לִהְיוֹת הַכֹּל אֶחָד.</p>\n<p>וּכְשֶׁכָּל זֶה נִשְׁפָּע וְנִמְשָׁךְ לָרָקִיעַ הַזֶּה, אָז הוּא מַשְׁקֶה וּמֵאִיר לְמַטָּה, לִכְבוֹד אֵל הַזֶּה, לַעֲשׂוֹת תּוֹלָדוֹת בִּדְיוֹקַן אוֹתָם הַשָּׁמַיִם שֶׁמְּאִירִים לְאוֹתוֹ כְּבוֹד אֵל. (וזהו שכתוב)</p>\n<p>וְלַיְלָה לְּלַיְלָה יְחַוֶּה דָּעַת - מַרְכְּבוֹתֶיהָ (זו לזו) שֶׁהֵן גּוּף הַכִּסֵּא, וְכֻלָּן נִקְרָאוֹת לֵילוֹת, כְּמוֹ שֶׁנֶּאֱמַר (תהליםטז) אַף לֵילוֹת יִסְּרוּנִי כִלְיוֹתָי. מֶרְכָּבָה עֶלְיוֹנָה נִקְרֵאת יָמִים, יוֹם לְיוֹם. מֶרְכָּבָה תַּחְתּוֹנָה נִקְרֵאת לֵילוֹת, לַיְלָה לְּלַיְלָה.</p>\n<p>יְחַוֶּה דָּעַת. יְחַוֶּה - יְחַיֶּה. יְחַיֶּה תוֹלָדוֹת, שֶׁהֵם (בהם) שָׁמַיִם. וְאִם תֹּאמַר, יְחַוֶּה לֹא יְחַיֶּה - בֹּא וּרְאֵה, כָּתוּב (בראשית ג) וַיִּקְרָא הָאָדָם שֵׁם אִשְׁתּוֹ חַוָּה, כִּי הִיא הָיְתָה אֵם כָּל חַי. חַוָּה וְחַיָּה בְּמִלָה אַחַת עוֹלִים. וְעַל שֶׁהִסְתַּלְּקָה (זה הסתלקה) י' וְנִכְנְסָה ו', שֶׁהוּא כָּרָאוּי, שֶׁהֲרֵי ו' הוּא חַיִּים וַדַּאי, וְעַל זֶה חַוָּה וְחַיָּה, י' (קטגה נוטלת) נוֹטֶלֶת חַיִּים מִו'. אַף כָּאן יְחַוֶּה - יְחַיֶּה.</p>\n<p>דָּעַת - זֶהוּ סוֹד הַשָּׁמַיִם. מַה שָּׁמַיִם שִׁשָּׁה צְדָדִים, אַף כָּאן שִׁשָּׁה צְדָדִים בְּאוֹתָן תּוֹלָדוֹת שֶׁיְּחַיֶּה כְּמוֹ שֶׁלּוֹ. וְלָכֵן יוֹם לְיוֹם נִכְלָל בְּדַרְגָּה עֶלְיוֹנָה - אֹמֶ\"ר. וְלַיְלָה לְּלַיְלָה - בְּסוֹד שֶׁל הַזָּכָר שֶׁמֵּאִיר לָהּ, שֶׁהוּא שְׁמוֹ (שמים), דַּעַת.</p>\n<p>וּמִשּׁוּם שֶׁאֹמֶר הַזֶּה הוּא סוֹד עֶלְיוֹן, וְלֹא כִשְׁאָר הָאֲמִירוֹת, חָזַר עָלָיו הַפָּסוּק וְאָמַר, אֵין אֹמֶר וְאֵין דְּבָרִים, כִּשְׁאָר אֲמִירוֹת הָעוֹלָם. אֶלָּא הָאֹמֶר הַזֶּה הוּא סוֹד עֶלְיוֹן בִּדְרָגוֹת עֶלְיוֹנוֹת, שֶׁאֵין שָׁם אֲמִירוֹת וּדְבָרִים, וְלֹא נִשְׁמְעוּ כִּשְׁאָר הַדְּרָגוֹת שֶׁהֵן סוֹד הָאֱמוּנָה, שֶׁהֵן קוֹל שֶׁנִּשְׁמָע. אֲבָל אֵלֶּה לֹא נִשְׁמְעוּ לְעוֹלָמִים, וְזֶהוּ שֶׁכָּתוּב בְּלִי נִשְׁמָע קוֹלָם.</p>\n<p>אֲבָל בְּכָל הָאָרֶץ יָצָא קַוָּם, אַף עַל גַּב שֶׁהֵם נִסְתָּרִים עֶלְיוֹנִים שֶׁלֹּא נוֹדְעוּ לְעוֹלָמִים, הַשֶּׁפַע וְהַמְּשִׁיכָה שֶׁלָּהֶם נִמְשָׁךְ וְשׁוֹפֵעַ לְמַטָּה. וּמִשּׁוּם אוֹתָהּ מְשִׁיכָה יֵשׁ לָנוּ אֱמוּנָה שְׁלֵמָה בָּעוֹלָם הַזֶּה, וְכָל בְּנֵי הָעוֹלָם מְדַבְּרִים סוֹד אֱמוּנוֹת הַקָּדוֹשׁ בָּרוּךְ הוּא בְּאוֹתָן דְּרָגוֹת כְּאִלּוּ נִתְגַּלּוּ וְלֹא הָיוּ נִסְתָּרִים וּגְנוּזִים. וְזֶהוּ וּבִקְצֵה תֵבֵל מִלֵּיהֶם - מֵרֹאשׁ הָעוֹלָם עַד סוֹף הָעוֹלָם מְדַבְּרִים אוֹתָם חַכְמֵי הַלֵּב בְּאוֹתָן דְּרָגוֹת גְּנוּזוֹת, אַף עַל גַּב שֶׁלֹּא נוֹדְעוּ.</p>\n<p>אֲבָל בַּמָּה הֵם נוֹדָעִים? מִשּׁוּם שֶׁלַּשֶּׁמֶשׁ שָׂם אֹהֶל בָּהֶם. מִשּׁוּם הַשֶּׁמֶשׁ הַקְּדוֹשָׁה, שֶׁהִיא מִשְׁכָּן מֵאוֹתָן דְּרָגוֹת עֶלְיוֹנוֹת קְדוֹשׁוֹת, וְהוּא אוֹר שֶׁנּוֹטֵל כָּל הָאוֹרוֹת הַגְּנוּזִים וְאוֹתָהּ מְשִׁיכָה שֶׁלָּהֶם, וּבִגְלָלוֹ נִרְאֵית הָאֱמוּנָה בְּכָל הָעוֹלָם.</p>\n<p>מִי שֶׁנּוֹטֵל אֶת הַשֶּׁמֶשׁ, כְּמִי שֶׁנּוֹטֵל אֶת כָּל הַדְּרָגוֹת, מִשּׁוּם שֶׁהַשֶּׁמֶשׁ הוּא אֹהֶל שֶׁנִּכְלָל בָּהֶם וְנוֹטֵל הַכֹּל, וְהוּא מֵאִיר לְכָל אוֹתָם הַגְּוָנִים שֶׁל הָאוֹרוֹת שֶׁלְּמַטָּה. וְלָכֵן וְהוּא כְּחָתָן יֹצֵא מֵחֻפָּתוֹ - בְּאוֹר וְהִתְנוֹצְצוּת שֶׁל כָּל הָאוֹרוֹת הַגְּנוּזִים. שֶׁכֻּלָּם בִּתְשׁוּקָה, בְּרָצוֹן שָׁלֵם, נוֹתְנִים לוֹ רְצוֹנָם וְאוֹרָם, כְּמוֹ שֶׁלְּחָתָן יֵשׁ רָצוֹן וּתְשׁוּקָה שֶׁל הַכַּלָּה (של כלם) לָתֵת לָהּ אוֹצָרוֹת וּמַתָּנוֹת, וְלָכֵן וְהוּא כְּחָתָן יֹצֵא מֵחֻפָּתוֹ.</p>\n<p>מִי זוֹ חֻפָּתוֹ? זֶה עֵדֶן. וְסוֹד זֶה - (בראשית ב) וְנָהָר יֹצֵא מֵעֵדֶן. עֵדֶן זוֹהִי חֻפָּה שֶׁמְּכַסָּה עַל הַכֹּל. יָשִׂישׂ כְּגִבּוֹר. יָשִׂישׂ - מִצַּד שֶׁל אוֹר רִאשׁוֹן שֶׁלֹּא נִמְצָא בּוֹ דִּין כְּלָל. כְּגִבּוֹר - מִצַּד הַגְּבוּרָה. וְאַף עַל פִּי שֶׁגְּבוּרָה הִיא דִין שָׁלֵם, כָּתוּב כְּגִבּוֹר, וְלֹא גִבּוֹר. מִשּׁוּם שֶׁמַּמְתִּיק דִּין בְּחֶסֶד וְנוֹטֵל הַכֹּל כְּאֶחָד, בִּתְשׁוּקָה וְרָצוֹן שָׁלֵם. וְכָל זֶה - לָרוּץ אֹרַח, כְּמוֹ שֶׁנֶּאֱמַר (ישעיה מג) הַנּוֹתֵן בַּיָּם דָּרֶךְ, לְהַשְׁקוֹת וּלְהַשְׁלִים אֶת אוֹר הַלְּבָנָה בְּכָל הַצְּדָדִים, וְלִפְתֹּחַ בָּהּ דֶּרֶךְ לְהָאִיר לְמַטָּה.</p>\n<p>מִקְצֵה הַשָּׁמַיִם מוֹצָאוֹ - מִסּוֹף אֵלּוּ הַשָּׁמַיִם הָעֶלְיוֹנִים שֶׁאָמַרְנוּ הוּא מוֹצִיא, מִשּׁוּם שֶׁבְּסִיּוּם הַגּוּף הוּא מוֹצִיא, וּבְאוֹתוֹ מָקוֹם נִכָּר בֵּין הַזָּכָר לַנְּקֵבָה. וְזֶהוּ שֶׁכָּתוּב (דבריםד) וּלְמִקְצֵה הַשָּׁמַיִם וְעַד קְצֵה הַשָּׁמָיִם. קְצֵה הַשָּׁמַיִם - זֶה הָעוֹלָם הָעֶלְיוֹן. וּלְמִקְצֵה הַשָּׁמַיִם - זֶה (המלך ש) הַשָּׁלוֹם שֶׁלּוֹ. כְּמוֹ שֶׁזֶּה נוֹטֵל אֶת כָּל הָאוֹרוֹת וְכֻלָּם בּוֹ, אַף זֶה כָּךְ, נוֹטֵל כָּל הָאוֹרוֹת וִהוּא יוֹצֵא מִקְצֵה הַשָּׁמַיִם.</p>\n<p>וּתְקֹוּפָתוֹ - שֶׁסּוֹבֵב (שהלבנה) בְּכָל אוֹתָם הַצְּדָדִים (הספירות) הַקְּדוֹשִׁים שֶׁרְאוּיִים לְהָאִיר וְלִהְיוֹת מֻשְׁקִים וּלְהִתְנוֹצֵץ מִמֶּנּוּ. וְאֵין נִסְתָּר - אֵין מִי שֶׁמְּכֻסֶּה מֵאוֹתוֹ הָאוֹר, שֶׁהֲרֵי לְכֻלָּם הוּא מֵאִיר בִּכְלָל אֶחָד, לְכָל אֶחָד וְאֶחָד כָּרָאוּי לוֹ.</p>\n<p>וּכְשֶׁכֻּלָּם נִשְׁלָמִים וּמְאִירִים מִתּוֹךְ הַשֶּׁמֶשׁ, אָז הַלְּבָנָה מִתְעַטֶּרֶת כְּמוֹ הָאֵם הָעֶלְיוֹנָה, שְׁלֵמָה בַּחֲמִשִּׁים שְׁעָרִים, וְזֶהוּ שֶׁכָּתוּב תּוֹרַת ה' תְּמִימָה, שֶׁהֲרֵי אָז הִיא (שלמה) תְּמִימָה מִכָּל הַצְּדָדִים, בְּסוֹד שֶׁל חָמֵשׁ דְּרָגוֹת, כְּמוֹ הָאֵם הָעֶלְיוֹנָה, שֶׁהֵם חָמֵשׁ, סוֹד שֶׁל חֲמִשִּׁים.</p>\n<p>וְלָכֵן הִיא בָּאָה בְּחָמֵשׁ חָמֵשׁ תֵּבוֹת, כְּדֵי לְהַשְׁלִים לַסּוֹד שֶׁל חֲמִשִּׁים. תּוֹרַת ה' תְּמִימָה מְשִׁיבַת נָפֶשׁ - הֲרֵי חָמֵשׁ. עֵדוּת ה' נֶאֱמָנָה מַחְכִּימַת פֶּתִי - הֲרֵי חָמֵשׁ. פִּקּוּדֵי ה' יְשָׁרִים מְשַׂמְּחֵי לֵב - הֲרֵי חָמֵשׁ. מִצְוַת ה' בָּרָה מְאִירַת עֵינָיִם - הֲרֵי חָמֵשׁ. יִרְאַת ה' טְהוֹרָה עוֹמֶדֶת לָעַד - הֲרֵי חָמֵשׁ. מִשְׁפְּטֵי ה' אֱמֶת צָדְקוּ יַחְדָּו - הֲרֵי חָמֵשׁ. וְכֻלָּם בָּאִים בְּחָמֵשׁ חָמֵשׁ, לְהִכָּלֵל כְּמוֹ הָאֵם הָעֶלְיוֹנָה.</p>\n<p>וְלָכֵן, יְהֹוָ\"ה יְהֹוָ\"ה שֵׁשׁ פְּעָמִים, כְּנֶגֶשׁ שֵׁשֶׁת הַצְּדָדִים הָעֶלְיוֹנִים שֶׁהֵם סוֹד הַשֵּׁם הָעֶלְיוֹן (השמים העליונים), וְעַל זֶה הַלְּבָנָה מִתְמַלֵּאת וְנִשְׁלֶמֶת בְּסִדּוּר עֶלְיוֹן כָּרָאוּי, וְזֶהוּ בְּיוֹם הַשַּׁבָּת, שֶׁהַכֹּל נִשְׁלָם כָּרָאוּי בְּסוֹד הַשַּׁבָּת מַעְלָה וּמַטָּה.</p>\n<p>וְלָכֵן בַּיּוֹם הַזֶּה נוֹסָף אוֹר בַּכֹּל, כְּמוֹ שֶׁאָמַרְנוּ. הַשָּׁמַיִם נוֹטְלִים מִמְּקוֹר הַחַיִּים בָּרִאשׁוֹנָה, וְהֵם מְאִירִים וּמְתַקְנִים אֶת הַכָּבוֹד הָעֶלְיוֹן מִסּוֹד הַסֵּפֶר הָעֶלְיוֹן - הָאָב שֶׁל הַכֹּל. וּמִסּוֹד הַסֵּפֶר - הָאֵם הָעֶלְיוֹנָה. וְהוּא מִסּוֹד הַסִּפּוּר. וְלָכֵן מְסַפְּרִים, כְּמוֹ שֶׁאָמַרְנוּ, בְּסוֹד שְׁלֹשֶׁת הַשֵּׁמוֹת הַלָּלוּ, שֶׁשּׁוֹלְטִים בְּיוֹם הַשַּׁבָּת עַל כָּל שְׁאָר הַיָּמִים.</p>\n<p>וְלָכֵן הַתִּשְׁבַּחַת הַזּוֹ אָמַר דָּוִד בְּרוּחַ הַקֹּדֶשׁ עַל הָאוֹר וְהִתְנוֹצְצוּת וְשִׁלְטוֹן (ושלמות) שֶׁל יוֹם הַשַּׁבָּת עַל כָּל שְׁאָר הַיָּמִים (ותקונה שגתקנת ביום זה מכל שאר הימים) בִּשְׁבִיל סוֹד הַשֵּׁם הָעֶלְיוֹן שֶׁמֵּאִיר בְּאוֹר, וְנוֹצֵץ בְּהִתְנוֹצְצוּת, וְנִשְׁתַּלֵּם בִּשְׁלֵמוּת מַעְלָה וּמַטָּה. וְאָז תּוֹרַת ה' תְּמִימָה, שַׁבָּת שֶׁל עֶרֶב שַׁבָּת (סוד של שמור כבוד לילה, שהיא תורת ה' תמימה, תורה שבעל פה, משה קבל תורה מסיני. והרי התעוררו על התורה שבעל פה, שאלו תורה שבכתב, הריכתובויצומשהאתהלויםוגו'לקוח את ספר התורה. וזה ראוי ללוים לזה שאוחז בשמש, והמלך שבא ממגו משה מאיר לישראל ארבעים שנה שמשביום, ותורת ה'זהערב שבת) בִּסוֹד אֶחָד, כְּמוֹ שֶׁאָמַרְנוּ.</p>"],[9522011707,"<p>וְתִקְֹּנוּ (אנשי כנסת הגדולה הסדור של השבח) הַחֲבֵרִים רֵאשִׁית הַתִּשְׁבָּחוֹת מֵאוֹתָן תִּשְׁבָּחוֹת שֶׁל דָּוִד מִסּוֹד זֶה הַשָּׁמַיִם, שֶׁנּוֹטֵל בָּרֹאשׁ וּמֵאִיר לְכָל הַשְּׁאָר. וְאַחַר כָּךְ אוֹתוֹ נָהָר שֶׁיּוֹצֵא מֵעֵדֶן, וְזֶהוּ סוֹד (תהלים לג) רַנְּנוּ צַדִּיקִים בַּה'. מִשּׁוּם שֶׁהַנָּהָר הַזֶּה כּוֹנֵס וְנוֹטֵל הַכֹּל מִסּוֹד הַשָּׁמַיִם בְּסוֹד עֶלְיוֹן, וּמְקוֹר הַחַיִּים, הַכֹּל כָּרָאוּי בְּיוֹם זֶה. וְהַשֶּׁמֶשׁ מְתַקֵּן לְהָאִיר כָּרָאוּי בַּיּוֹם הַזֶּה.</p>"],[9522011708,"<p>וְאַחַר כָּךְ הַלְּבָנָה שֶׁנִּפְרֶדֶת מֵהַצַּד הָאַחֵר בַּיּוֹם הַזֶּה כְּדֵי לִהְיוֹת מְאִירָה מִן הַשֶּׁמֶשׁ, וְזֶהוּ לְדָוִד בְּשַׁנּוֹתוֹ אֶת טַעְמוֹ וְגוֹ'. וְאַחַר שֶׁנִּפְרֶדֶת מִמֶּנּוּ, הֲרֵי מִתְחַבֶּרֶת בַּשֶּׁמֶשׁ, וְתִשְׁבַּחַת זוֹ בְּעֶשְׂרִים וּשְׁתַּיִם אוֹתִיּוֹת שֶׁמַּכְנִיס בָּהּ הַשֶּׁמֶשׁ בַּלְּבָנָה. וְתִשְׁבַּחַת זוֹ פְּרֵדַת הַלְּבָנָה מִן הַצַּד הָאַחֵר, וְתִשְׁבַּחַת שֶׁל עֶשְׂרִים וּשְׁתַּיִם אוֹתִיּוֹת בְּאוֹר הַשֶּׁמֶשׁ.</p>"],[9522011709,"<p>וְאַחַר כָּךְ הִתְחַבְּרוּת וַעֲלִיַּת הַגְּבִירָה לְבַעְלָהּ, וְזוֹהִי (שםצ) תְּפִלָּה לְמֹשֶׁה אִישׁ הָאֱלֹהִים. הִתְחַבְּרוּת וְהִתְדַּבְּקוּת אִשָּׁה בְּבַעְלָהּ, לִפְרֹשׂ יָמִין וּשְׂמֹאל לְקַבֵּל אוֹתָהּ וְלִהְיוֹת כְּאֶחָד בְּחִבּוּר אֶחָד. (להיות אחד בסוד אחד. וכל אלו שמים מספרים להם ומתקנים אותם. מכאן והלאה תשבחות אחרות של שמחה ותשוקה שלמה. אבל אלו אותם תקון השלמות העליונה בסוד של השם הקדוש כראוי ותשבחות אלו, התקינו בתקון של שבת, שהוא עולה ומתעטר בעטרותיו כראוי, ועולים בסוד השם הקדוש להיות אחד בסוד של כבוד אל של השמים מספרים לו וזוהרים לו כמו שאמרנו).</p>"],[9522011710,"<p>וְזְהִוּ מִזְמוֹר שִׁירוּ לַה' שִׁיר חָדָשׁ. הַתִּשְׁבַּחַת הַזּוֹ הֲרֵי בֵּאַרְנוּהָ. אַף עַל גַּב שֶׁהִתְעוֹרַרְנוּ בָּהּ, הִתְעוֹרְרוּת הַחֲבֵרִים שֶׁהִתְעוֹרְרוּ, יָפֶה הוּא, שֶׁהַפָּרוֹת הַלָּלוּ עָלוֹת, כְּשֶׁהָיוּ נוֹשְׂאוֹת אֶת הָאָרוֹן, הִתְעוֹרְרוּ בַּתִּשְׁבַּחַת הַזּוֹ, כְּמוֹ שֶׁנֶּאֱמַר (שמואל א ו) וַיִּשַּׁרְנָה הַפָּרוֹת בַּדֶּרֶךְ. וְאֵיזוֹ שִׁירָה הָיוּ אוֹמְרוֹת? מִזְמוֹר שִׁירוּ לַה' שִׁיר חָדָשׁ כִּי נִפְלָאוֹת עָשָׂה. הַסּוֹד הַזֶּה הוּא כְּמוֹ שֶׁלְּמַעְלָה. בְּשָׁעָה שֶׁאוֹתָן חַיּוֹת נוֹשְׂאוֹת אֶת (הארון) הַכִּסֵּא לְהָרִים אוֹתוֹ לְמַעְלָה, הֵן אוֹמְרוֹת תִּשְׁבַּחַת זוֹ.</p>\n<p>וְאִם תֹּאמַר, לָמָּה כָּתוּב כָּאן חָדָשׁ, וַהֲרֵי תָּמִיד אוֹמְרִים תִּשְׁבַּחַת זוֹ? אֶלָּא וַדַּאי שֶׁהוּא חָדָשׁ, וְחָדָשׁ לֹא נִקְרָא אֶלָּא בְּהִתְחַדְּשׁוּת הַלְּבָנָה כְּשֶׁנְּאוֹרָה מֵהַשֶּׁמֶשׁ, אָז הוּא חָדָשׁ, וְזֶהוּ שִׁיר חָדָשׁ. הוֹשִׁיעָה לּוֹ יְמִינוֹ וּזְרוֹעַ קָדְשׁוֹ, הֲרֵי הִתְעוֹרְרוּת שֶׁל יָמִין וּשְׂמֹאל לְקַבֵּל אוֹתָהּ.</p>\n<p>וְתִשְׁבַּחַת זוֹ, כְּשֶׁנּוֹשְׂאוֹת הָאָרוֹן, מְשַׁבְּחוֹת אוֹתָהּ כְּשֶׁעוֹלוֹת לְבֵית שֶׁמֶשׁ, כְּמוֹ שֶׁעֲגָלוֹת עוֹלוֹת לְבֵית שֶׁמֶשׁ, וְהַכֹּל עוֹלִים בְּסוֹד אֶחָד, מִשּׁוּם שֶׁבְּשַׁבָּת הִיא עֲלִיַּת הַכִּסֵּא לַעֲלוֹת לְמַעְלָה. הַתִּקּוּן שֶׁל הַתִּשְׁבַּחַת הַזּוֹ בְּשַׁבָּת. כָּל הַתִּשְׁבָּחוֹת הַלָּלוּ תִּקְּנוּ לְשַׁבָּת, לְשַׁבֵּחַ אוֹתוֹ הָעָם הַיָּחִיד בָּעוֹלָם.</p>"],[9522011711,"<p>מִזְמוֹר שִׁיר לְיוֹם הַשַּׁבָּת (תהלים צב). הַתִּשְׁבַּחַת הַזּוֹ אָדָם הָרִאשׁוֹן אָמַר אוֹתָהּ בְּשָׁעָה שֶׁגֹּרַשׁ מִגַּן עֵדֶן, וּבָאָה שַׁבָּת וְהֵגֵנָּה עָלָיו. וּבֵאֲרוּהָ הַחֲבֵרִים, אֶת הַתִּשְׁבַּחַת הַזּוֹ מְשַׁבֵּחַ הָעוֹלָם הַתַּחְתּוֹן אֶת הָעוֹלָם הָעֶלְיוֹן, יוֹם (שהכל בו) שֶׁהוּא כֻּלּוֹ שַׁבָּת, הַמֶּלֶךְ שֶׁהַשָּׁלוֹם שֶׁלּוֹ. וְזֶהוּ מִזְמוֹר שִׁיר, וְלֹא כָתוּב מִי אָמַר אוֹתוֹ, כְּמוֹ שֶׁבֵּאַרְנוּ.</p>\n<p>לְיוֹם הַשַּׁבָּת - הַיּוֹם הָעֶלְיוֹן, הַשַּׁבָּת הָעֶלְיוֹנָה. זוֹ שַׁבָּת וְזוֹ שַׁבָּת. מַה בֵּין זֶה לָזֶה? אֶלָּא שַׁבָּת סְתָם זוֹ שַׁבָּת שֶׁל עֶרֶב שַׁבָּת. יוֹם הַשַּׁבָּת זוֹ שַׁבָּת שֶׁלְּמַעְלָה. זֶה יוֹם וְזֶה לַיְלָה. (שמות לא) וְשָׁמְרוּ בְנֵי יִשְׂרָאֵל אֶת הַשַּׁבָּת - הֲרֵי לַיְלָה, סוֹד שֶׁל נְקֵבָה. (שם כ) זָכוֹר אֶת יוֹם הַשַּׁבָּת - הֲרֵי יוֹם, סוֹד שֶׁל זָכָר. וְלָכֵן מִזְמוֹר שִׁיר לְיוֹם הַשַּׁבָּת.</p>\n<p>וּמָצָאנוּ בְּכַמָּה מְקוֹמוֹת, שֶׁהָעוֹלָם הַתַּחְתּוֹן עוֹלֶה בַשֵּׁם וּבָא סְתָם, כְּמוֹ זֶה - וַיִּקְרָא אֶל מֹשֶׁה, וּכְמוֹ (שמות כד) וְאֶל מֹשֶׁה אָמַר עֲלֵה אֶל ה'. כֻּלָּם שֵׁם נִסְתָּר וְלֹא עוֹלֶה בּוֹ, (אלא) (והכל) מִשּׁוּם שֶׁיֵּשׁ בּוֹ דַּרְגָּה עֶלְיוֹנָה, וְאֶל הַדַּרְגָּה הָעֶלְיוֹנָה הוּא לֹא עוֹלֶה בַשֵּׁם. אוֹר הַמְּנוֹרָה לֹא עוֹלֶה בַּיּוֹם בְּאוֹר הַשֶּׁמֶשׁ, וְעַל זֶה לֹא עוֹלֶה בַשֵּׁם. וְכָל אֵלֶּה תִּשְׁבְּחוֹת הַשַּׁבָּת, שֶׁהִיא כְּבוֹד (יום השבת, שהיא תשבחת) הַיּוֹם, הִיא תִּשְׁבַּחַת עֶלְיוֹנָה עַל כָּל שְׁאָר הַיָּמִים. (וכל אלו התשבחות התקינו בתקון של שבת, שהיא עולה להתעטר בעטרות עליונות, מקומות קדושים על כל שאר הימים).</p>"],[9522011712,"<p>נִשְׁמַת כָּל חַי, הֲרֵי הַחֲבֵרִים עוֹרְרוּ בוֹ דִּבְרֵי אֱמֶת. אֲבָל יֵשׁ לָנוּ לְהַזְכִּיר, הַנְּשָׁמָה הַזּוֹ שֶׁפּוֹרַחַת מֵאוֹתוֹ חַי הָעוֹלָמִים. וּמִשּׁוּם שֶׁהִיא שֶׁלּוֹ, שֶׁמִּמֶּנּוּ יוֹצְאוֹת כָּל הַבְּרָכוֹת וְשׁוֹרוֹת בּוֹ, וְהוּא מַשְׁקֶה וּמְבָרֵךְ לְמַטָּה, הַנְּשָׁמָה הַזּוֹ שֶׁיּוֹצֵאת מִמֶּנּוּ יֵשׁ רְשׁוּת לְבָרֵךְ אֶת הַמָּקוֹם הַזֶּה.</p>\n<p>וְלָכֵן פּוֹרְחוֹת הַנְּשָׁמוֹת מֵאוֹתוֹ חַי בְּעֶרֶב שַׁבָּת, אוֹתָן נְשָׁמוֹת שֶׁפּוֹרְחוֹת, מַמָּשׁ מְבָרְכוֹת מָקוֹם זֶה שֶׁנִּקְרָא שֵׁם מִלְּמַטָּה. וְאוֹתוֹ מָקוֹם שֶׁיּוֹצְאוֹת מִמֶּנּוּ, מְבָרֵךְ אוֹתוֹ לְמַעְלָה, וְשֵׁם זֶה מְקַבֵּל בְּרָכוֹת מִמַּטָּה וּמִמַּעְלָה, וְנִכְלֶלֶת מִכָּל הַצְּדָדִים.</p>\n<p>בִּימֵי הַחֹל הִיא מְקַבֶּלֶת בְּרָכוֹת מִשְּׁאָר הַנְּשָׁמוֹת שֶׁמְּבָרְכוֹת אוֹתָהּ מִלְּמַטָּה בְּיוֹם הַשַּׁבָּת, הִיא מְקַבֶּלֶת בְּרָכוֹת מֵאוֹתָן נְשָׁמוֹת עֶלְיוֹנוֹת שֶׁמְּבָרְכוֹת אוֹתָהּ בְּאַרְבָּעִים וְחָמֵשׁ תֵּבוֹת כְּחֶשְׁבּוֹן מ\"ה. (מגשמת כל חי עד והאחרונים) (ובסוד של חמשים תבות, כחשבון מ\"י) כְּמוֹ שֶׁבֵּאַרְנוּ בְּסוֹד מ\"ה וּבְסוֹד מ\"י. זֶה הָעוֹלָם הָעֶלְיוֹן, וְזֶה הָעוֹלָם הַתַּחְתּוֹן. נִשְׁמַת כָּל חַי (עד והאחרונים) - מ\"ה. וּמִן וְאִלּוּ פִינוּ מָלֵא שִׁירָה עַד וּמִלְּפָנִים - עוֹלָה הַתִּשְׁבַּחַת הָאַחֶרֶת חֲמִשִּׁים תֵּבוֹת. וְאַף עַל גַּב שֶׁלֹּא עוֹמֵד הַדָּבָר בַּחֶשְׁבּוֹן, עוֹלֶה הַחֶשְׁבּוֹן סוֹד מ\"י, וּמִשָּׁם וָהָלְאָה עוֹלָה הַתִּשְׁבַּחַת הָאַחֶרֶת לְחֶשְׁבּוֹן (מ\"ה) מֵאָה תֵבוֹת, תַּשְׁלוּמִים שֶׁל הַכֹּל, וּמֶרְכָּבָה אַחַת עַל מַה שֶּׁשּׁוֹרֶה שֶׁהוּא תַּשְׁלוּם (אותו שלם עליון).</p>\n<p>וְכָל הַשֶּׁבַח הַזֶּה וְכָל הַדְּבָרִים הַלָּלוּ כֻּלָּם אֵיבָרִים יְדוּעִים בְּחֶשְׁבּוֹן לְתַשְׁלוּם שַׁבָּת וּלְהִשְׁתַּלֵּם מֵהֶם כָּרָאוּי. אַשְׁרֵי הָעָם שֶׁיּוֹדְעִים לְסַדֵּר אֶת שֶׁבַח רִבּוֹנָם כָּרָאוּי. מִכָּאן וָהָלְאָה סִדּוּר הַתְּפִלָּה כְּמוֹ שֶׁתֻּקַּן.</p>"],[9522011713,"<p>כָּתוּב (תהלים כב) וְאַתָּה ה' אַל תִּרְחָק אֱיָלוּתִי לְעֶזְרָתִי חוּשָׁה. דָּוִד הַמֶּלֶךְ אָמַר אֶת זֶה בְּשָׁעָה שֶׁהָיָה מְתַקֵּן וּמְסַדֵּר אֶת תִּשְׁבַּחַת הַמֶּלֶךְ כְּדֵי לְחַבֵּר אֶת הַשֶּׁמֶשׁ לַלְּבָנָה. כֵּיוָן שֶׁהָיָה מְתַקֵּן וּמְסַדֵּר אֶת שְׁבָחָיו לְהִתְחַבֵּר, אָמַר וְאַתָּה ה' אַל תִּרְחָק.</p>\n<p>וְאַתָּה ה' - סוֹד שֶׁל חֲבֵרוּת אַחַת בְּלִי פֵרוּד. אַל תִּרְחָק - כֵּיוָן שֶׁעָלְתָה לְהִתְחַבֵּר עִם בַּעְלָהּ, וְהַכֹּל בָּעוֹלָם הָעֶלְיוֹן, וּמִשָּׁם רוֹצָה לַעֲלוֹת לְאֵין סוֹף לְהִתְקַשֵּׁר הַכֹּל לְמַעְלָה לְמַעְלָה, וְלָכֵן אַל תִּרְחַק לְהִסִתַּלֵּק מֵאִתָּנוּ וְלַעֲזב אוֹתָנוּ.</p>\n<p>וְלָכֵןֹ בְּתוֹךְ סִדּוּר הַתִּשְׁבַּחַת צְרִיכִים יִשְׂרָאֵל לְהִכָּלֵל שָׁם וּלְהִדָּבֵק עִמָּם מִלְּמַטָּה, שֶׁאִלְמָלֵא יִרְצֶה לְהִתְעַלּוֹת הַכָּבוֹד הַזֶּה, הֲרֵי יִשְׂרָאֵל לְמַטָּה אֲחוּזִים בּוֹ וּמַחֲזִיקִים בּוֹ שֶׁלֹּא יַעֲזב אוֹתוֹ לְהִתְרַחֵק מֵהֶם. וְלָכֵן הַתְּפִלָּה בְּלַחַשׁ, כְּמִי שֶׁמְּדַבֵּר בְּסוֹד עִם הַמֶּלֶךְ. וּבְעוֹד שֶׁהוּא בְּסוֹד עִמּוֹ, לֹא מִתְרַחֶקֶת מִמֶּנּוּ כְּלָל.</p>\n<p>אֱיָלוּתִי - מָה אַיָּל וּצְבִי, בְּשָׁעָה שֶׁהוֹלְכִים וּמִתְרַחֲקִים, מִיָּד חוֹזְרִים לְאוֹתוֹ מָקוֹם שֶׁעָזְבוּ - אַף הַקָּדוֹשׁ בָּרוּךְ הוּא, אַף עַל גַּב שֶׁהִתְעַלָּה לְמַעְלָה לְמַעְלָה בְּאֵין סוֹף, מִיָּד חוֹזֵר לִמְקוֹמוֹ. מָה הַטַּעַם? מִשּׁוּם שֶׁיִּשְׂרָאֵל לְמַטָּה אֲחוּזִים בּוֹ, וְלֹא עוֹזְבִים אוֹתוֹ לִהְיוֹת נִשְׁכָּח וּלְהִתְרַחֵק מֵהֶם. וְלָכֵן, אֱיָלוּתִי לְעֶזְרָתִי חוּשָׁה.</p>\n<p>וּמִשּׁוּם כָּךְ צְרִיכִים לְהִתְאַחֵד עִם הַקָּדוֹשׁ בָּרוּךְ הוּא וְלֶאֱחֹז בּוֹ כְּמִי שֶׁמַּמְשִׁיךְ מִלְּמַעְלָה לְמַטָּה, שֶׁלֹּא יִשָּׁאֵר אִישׁ עָזוּב מִמֶּנּוּ אֲפִלּוּ שָׁעָה אַחַת. וְלָכֵן כְּשֶׁסּוֹמֵךְ גְּאֻלָּה לִתְפִלָּה, צָרִיךְ לֶאֱחֹז בּוֹ וּלְדַבֵּר עִמּוֹ בְּלַחַשׁ, בְּסוֹד, שֶׁלֹּא יִתְרַחֵק מֵעִמָּנוּ וְלֹא יֵעָזֵב מֵעִמָּנוּ, וְלָכֵן כָּתוּב (דברים ד) וְאַתֶּם הַדְּבֵקִים בַּה' אֱלֹהֵיכֶם חַיִּים כֻּלְּכֶם הַיּוֹם. (תהלים קמד) אַשְׁרֵי הָעָם שֶׁכָּכָה לּוֹ אַשְׁרֵי הָעָם שֶׁה' אֱלֹהָיו.</p>\n<p>בְּאוֹתָהּ שָׁעָה קָם רַבִּי שִׁמְעוֹן, וְהַחֲבֵרִים אַף כָּךְ קָמוּ וְהָלְכוּ. אָמַר רַבִּי אֶלְעָזָר לְרַבִּי שִׁמְעוֹן אָבִיו, אַבָּא, עַד כָּאן הָיִינוּ יוֹשְׁבִים בַּצֵּל שֶׁל עֵץ הַחַיִּים בְּגַן עֵדֶן. מִכָּאן וָהָלְאָה שֶׁאָנוּ הוֹלְכִים, צָרִיךְ לָנוּ לָלֶכֶת בְּדַרְכֵי הַשּׁוֹמְרִים אֶת הָעֵץ הַזֶּה. אַתָּה תַּתְחִיל בְּרֵאשִׁית לִפְתֹּחַ בַּדֶּרֶךְ.</p>"]]});
